//==================================================================================================.
//[機能] uint32_t データを Little Endian に変換する.
//==================================================================================================.
inline uint32_t ULtoLE( uint32_t data )
{
#ifdef _WINDOWS
	return data;
#else
#ifdef DEF_BIGENDIAN		// BIG_ENDIAN固有処理.
	return	(((data >>  0) & 0xff) << 24) + (((data >>  8) & 0xff) << 16) + (((data >> 16) & 0xff) <<  8) + (((data >> 24) & 0xff) <<  0);
#else
	return data;
#endif		// #ifdef DEF_BIGENDIAN		// BIG_ENDIAN固有処理.
#endif		// #ifdef _WINDOWS.
}

//==================================================================================================.
//[機能] short データを Little Endian に変換する.
//==================================================================================================.
inline short SStoLE( short data )
{
#ifdef _WINDOWS
	return data;
#else
#ifdef DEF_BIGENDIAN		// BIG_ENDIAN固有処理.
	return(short)((((data >>  0) & 0xff) << 8) + (((data >>  8) & 0xff) << 0));
#else
	return data;
#endif		// #ifdef DEF_BIGENDIAN		// BIG_ENDIAN固有処理.
#endif		// #ifdef _WINDOWS.
}

//==================================================================================================.
//[機能] uint32_t データを char型 4byteの Little Endian に変換する.
//[コメント] char型の Little Endian 保持領域は必ず 4byte用意する、かつ、.
//           データへは必ずuint32_t型の変数を設定してコールすること！.
//[履歴] 2008.04.09 Harada Donau対応.
//==================================================================================================.
inline void ULtoC4LE( char* pc_data, uint32_t data )
{
#ifdef _WINDOWS
	pc_data[0] = (data >> 24) & 0xff;
	pc_data[1] = (data >> 16) & 0xff;
	pc_data[2] = (data >>  8) & 0xff;
	pc_data[3] = (data >>  0) & 0xff;
#else
#ifdef DEF_BIGENDIAN		// BIG_ENDIAN固有処理.
	pc_data[0] = (char)(data >>  0 & 0xff);
	pc_data[1] = (char)(data >>  8 & 0xff);
	pc_data[2] = (char)(data >> 16 & 0xff);
	pc_data[3] = (char)(data >> 24 & 0xff);
#else
	pc_data[0] = (data >> 24) & 0xff;
	pc_data[1] = (data >> 16) & 0xff;
	pc_data[2] = (data >>  8) & 0xff;
	pc_data[3] = (data >>  0) & 0xff;
#endif		// #ifdef DEF_BIGENDIAN		// BIG_ENDIAN固有処理.
#endif		// #ifdef _WINDOWS.
}

//==================================================================================================.
//[機能] char型 4byteの Little Endian データを uint32_t に変換する.
//[コメント] char型の Little Endian 保持領域は必ず 4byte用意すること！.
//[履歴] 2008.04.09 Harada Donau対応.
//==================================================================================================.
inline uint32_t C4LEtoUL( char* pc_data )
{
#ifdef _WINDOWS
	return ((pc_data[0] << 24) & 0xff000000)
		 + ((pc_data[1] << 16) & 0x00ff0000)
		 + ((pc_data[2] <<  8) & 0x0000ff00)
		 + ((pc_data[3] <<  0) & 0x000000ff);
#else
#ifdef DEF_BIGENDIAN		// BIG_ENDIAN固有処理 
	return ((pc_data[0] <<  0) & 0x000000ff)
		 + ((pc_data[1] <<  8) & 0x0000ff00)
		 + ((pc_data[2] << 16) & 0x00ff0000)
		 + ((pc_data[3] << 24) & 0xff000000);
#else
	return ((pc_data[0] << 24) & 0xff000000)
		 + ((pc_data[1] << 16) & 0x00ff0000)
		 + ((pc_data[2] <<  8) & 0x0000ff00)
		 + ((pc_data[3] <<  0) & 0x000000ff);
#endif		// #ifdef DEF_BIGENDIAN		// BIG_ENDIAN固有処理 
#endif		// #ifdef _WINDOWS 
}

