//==================================================================================================
//[機能]ウォッチドックタイマーの起動 
//[戻り値]STATUS
//[履歴] 2004.04.08 Yamahata
//==================================================================================================
STATUS twainWatchDogStart(
				WDOG_ID wdId,		// ウォッチドックタイマーＩＤ 
				int32_t msTime,		// 遅延カウント（MS）
				FUNCPTR pRoutine,	// タイマールーチン 
				int parameter		// タイマールーチンパラメータ 
)
{
	register int32_t sl_Tick = (int32_t)SYSF_sysClkRateGet() * msTime / 1000;
	if( sl_Tick == 0L ) { sl_Tick = 1L; }
	++sl_Tick;
	return SYSF_wdStart( wdId, sl_Tick, pRoutine, parameter );
}

