//[機能]TimeOut時にコマンドを実行する 
//[履歴] 2004.04.08 Yamahata
//		 2013.03.25 ADS坪井  CQ.378831(Act_63702) NETS_TwainServiceをNETS_TwainServiceMsgに変更.
//==================================================================================================
static void PushScanTimeOutProc(
	int SocketFd		// ソケットディスクリプタ 
)
{
	NETS_TwainServiceMsg netsMsg;
	memset( &netsMsg, 0, sizeof(netsMsg) );
	netsMsg.messageType = TWNSERVICE_MSG_PUSH_TIMEOUT;
	netsMsg.closeSocketInfo.bl_CloseSocketReq = False;
	netsMsg.closeSocketInfo.bl_AllClose = False;
	netsMsg.closeSocketInfo.si_SocketFd = SocketFd;
	netsMsg.closeSocketInfo.si_KeepSocketFd = 0;
	SYSF_msgQSend(msg_Q_ID,(char*)&netsMsg,sizeof(NETS_TwainServiceMsg),NO_WAIT,MSG_PRI_NORMAL);
}
//==================================================================================================
//[機能]PushTimeOut時にコマンドを実行する 
//[履歴] 2005.01.21 Matsumoto 
//==================================================================================================
void PushScanTimeOutMsgProc(
	int SocketFd		// ソケットディスクリプタ 
)
{
NetTwainDebugTrace((char*)"#### PushScanTimeOutMsgProc() START! ####\n",0,0,0,0,0,0);
//	isPushScanTimeOutON = false;													// 2021/10/18 FPT-TrungHV7 [IT6_2.2][TAS000000010056] Delete.
	netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_NONE );	// クライアント情報のTWAINジョブ実行状態をジョブなし状態とする 
	netc_TwainClientMan.setState_CancelSync( SocketFd, NETE_CANCELSYNC_NONE );		// キャンセル同期状態を初期化する.		// 2.1c CQ519136 OSP1八代 2015.10.23.

	// ジョブインスタンスを取得しジョブの削除処理を実行する 
	APIC_Job* pc_Job = netc_TwainClientMan.getImageTransJobInstance( SocketFd );
	if ( pc_Job != NULL ) {
		pc_Job->lock();
// 2021/10/18 FPT-TrungHV7 [IT6_2.2][TAS000000010056] Start.
		//pc_Job->deleteInstance();
		pc_Job->deleteInstance();
//		pc_Job->req_cancelForTimeout(ans_cancel);
//		printf("#### PushScanTimeOutMsgProc() req_cancelForTimeout ####\n");
// 2021/10/18 FPT-TrungHV7 [IT6_2.2][TAS000000010056] End.
		pc_Job->unlock();
		netc_TwainClientMan.setPushTwain( SocketFd, False );		// PUSH Twain状態解除 
		netc_TwainClientMan.setImageTransJobInstance( SocketFd, NULL );
		netc_TwainClientMan.setScanDataFlag( SocketFd, False );
	}
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 Start.
	APIC_SystemStatus* pc_SystemStatus = NULL;
	pc_SystemStatus = APIC_SystemStatus::newInstance();
	pc_SystemStatus->lock();
	pc_SystemStatus->setSeparateScanForTwain( TYPE_SeparateScanForTwain_Off );
	pc_SystemStatus->setNextImageEnableForTwain( TYPE_NextImageEnableForTwain_NoExec );
	pc_SystemStatus->setTwainLock( TYPE_TwainLockNon, pc_Job );		// ロック無し 
	pc_SystemStatus->unlock();
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 End.

	// ウォッチドックタイマー動キャンセル＆削除 
	twainWatchDogCancel( wdog_ID_PushTwain );
	NetTwainDebugTrace((char*)"###  PushScanTimeOutMsgProc wdog_ID_PushTwain[%p] SocketFd[%d] ###\n",reinterpret_cast<intptr_t>(wdog_ID_PullTwain),SocketFd,0,0,0,0);		
	char pc_ReqData[32];
	strcpy( pc_ReqData, "\x1b*s20101r3V" );	// デバイスでタイムアウトが発生した。 
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4, True );
	}
}



