//==================================================================================================
//[機能]PullTimeOut時にコマンドを実行する 
//[履歴] 2005.01.21 Matsumoto 
//==================================================================================================
void PullScanTimeOutMsgProc(
	int SocketFd		// ソケットディスクリプタ 
)
{
NetTwainDebugTrace((char*)"#### PullScanTimeOutMsgProc() ! ####\n",0,0,0,0,0,0);
	netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_NONE );	// クライアント情報のTWAINジョブ実行状態をジョブなし状態とする 
	netc_TwainClientMan.setState_CancelSync( SocketFd, NETE_CANCELSYNC_NONE );		// キャンセル同期状態を初期化する.		// 2.1c CQ519136 OSP1八代 2015.10.23.

	// ジョブインスタンスを取得しジョブの削除処理を実行する 
	APIC_Job* pc_Job = netc_TwainClientMan.getImageTransJobInstance( SocketFd );
	if ( pc_Job != NULL ) {
		pc_Job->lock();
		pc_Job->deleteInstance();
		printf("#### PullScanTimeOutMsgProc() deleteInstance ####\n");
		pc_Job->unlock();
		APIC_SystemStatus* pc_SystemStatus = NULL;
		pc_SystemStatus = APIC_SystemStatus::newInstance();
		pc_SystemStatus->lock();
		pc_SystemStatus->setTwainLock( TYPE_TwainLockNon, pc_Job );		// ロック無し 
		pc_SystemStatus->unlock();
		netc_TwainClientMan.setImageTransJobInstance( SocketFd, NULL );
		netc_TwainClientMan.setScanDataFlag( SocketFd, False );
	}
	twainWatchDogCancel( wdog_ID_PullTwain );
	NetTwainDebugTrace((char*)"###  PullScanTimeOutMsgProc wdog_ID_PullTwain[%p] SocketFd[%d] ###\n",reinterpret_cast<intptr_t>(wdog_ID_PullTwain),SocketFd,0,0,0,0);			
}


