//[クラス]NETC_UserLoginResultNotifier 
//[内容]外部サーバーログイン結果を取得するためのクラス 
//[履歴] 2006.03.29 Matsumoto
//==================================================================================================
//==================================================================================================
//[機能]ログイン結果通知 
//[戻り値]void 
//[履歴]2006.03.29 Matsumoto 
//==================================================================================================
void NETC_UserLoginResultNotifier::notifyLoginResult(
	TYPE_UserResult	e_UserResult, 	// ログイン結果 
	APIC_User* 		pc_User			// ユーザオブジェクト 
)
{
NetTwainDebugTrace((char*)"#### NETC_UserLoginResultNotifier::notifyLoginResult() START! ####\n",0,0,0,0,0,0);
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( index );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_UserLogin* pc_UserLogin = (NETS_UserLogin*)malloc( sizeof(NETS_UserLogin) );
	if( pc_UserLogin == NULL ){
		errorLog_TwainService("pc_UserLogin_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	pc_UserLogin->index = index;
	pc_UserLogin->pc_User = pc_User;
	pc_UserLogin->e_Result = e_UserResult;
	netc_TwainService->setPacketData( NETE_TWAIN_USER_LOGIN,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
									  (void*)pc_UserLogin );
}
