//[クラス] NETC_KeyDeviceLoginResultNotifier.
//[内容] 統合管理装置2ログイン結果を取得するためのクラス.
//[履歴] 2010/12/21 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証.
//==================================================================================================.
//==================================================================================================.
//[機能] 統合管理装置2ログイン結果通知.
//[履歴] 2010/12/21 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証.
//==================================================================================================.
void NETC_KeyDeviceLoginResultNotifier::notifyLoginResult(
	TYPE_UserResultAdminMachineKM e_inUserResultAdminMachineKM,		// ログイン結果. 
	int32_t sl_AuthLabel												// 認証ラベル. 
)
{
NetTwainDebugTrace((char*)"#### NETC_KeyDeviceLoginResultNotifier::notifyLoginResult() START! ####\n",0,0,0,0,0,0);
NetTwainDebugTrace((char*)"#### NETC_KeyDeviceLoginResultNotifier() e_inUserResultAdminMachineKM = [%d] / sl_AuthLabel = [%ld] ####\n", e_inUserResultAdminMachineKM, sl_AuthLabel,0,0,0,0);
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( index );	// SocketFd取得.
	NETC_TwainService* netc_TwainService = NULL;						// インスタンス生成.
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_KeyDeviceLogin* pc_KeyDeviceLogin = ( NETS_KeyDeviceLogin* )malloc( sizeof( NETS_KeyDeviceLogin ) );
	if( pc_KeyDeviceLogin == NULL ){ 
		errorLog_TwainService("pc_KeyDeviceLogin malloc Error\n",0,0,0,0,0,0);
		return;
	}
	// 認証情報格納.
	pc_KeyDeviceLogin->index = index;
	pc_KeyDeviceLogin->sl_AuthLabel = sl_AuthLabel;
	pc_KeyDeviceLogin->e_Result = e_inUserResultAdminMachineKM;
	
	// ジョブ実行時のジョブチケット取得の場合.
	if( NULL != netc_TwainClientMan.getJobInstanceforJobTicket( si_SocketFd ) ) {
NetTwainDebugTrace((char*)"#### NETC_KeyDeviceLoginResultNotifier() Before Job_start!! ####\n", 0,0,0,0,0,0);
		// メッセージ送信処理(_setJobTicketProcへ).
		netc_TwainService->setPacketData( NETE_TWAIN_SET_JOBTICKET,
										  netc_TwainClientMan.getClientIndex( si_SocketFd ),
										  NULL,
										  0,
										  netc_TwainClientMan.getAppID( si_SocketFd ),
										  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
										  NULL,
										  (void*)pc_KeyDeviceLogin );
		
	// ログイン時のジョブチケット発行可否チェックの場合.
	} else {
NetTwainDebugTrace((char*)"#### NETC_KeyDeviceLoginResultNotifier() LOGIN!! ####\n",0,0,0,0,0,0);
		// メッセージ送信処理(_KeyDeviceLoginProcへ).
		netc_TwainService->setPacketData( NETE_TWAIN_KEYDEVICE_LOGIN,
										  netc_TwainClientMan.getClientIndex( si_SocketFd ),
										  NULL,
										  0,
										  netc_TwainClientMan.getAppID( si_SocketFd ),
										  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
										  NULL,
										  (void*)pc_KeyDeviceLogin );
	}
	
}
