//==================================================================================================.
//[機能] 管理装置ベンダー装置ログイン結果通知.
//[履歴] 2010/12/21 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証.
//==================================================================================================.
void _KeyDeviceLoginProc( NETS_KeyDeviceLogin* ps_KeyDeviceLogin )
{
	char sc_ReqData[32];
NetTwainDebugTrace((char*)"#### _KeyDeviceLoginProc() START! ####\n",0,0,0,0,0,0);
	NETS_KeyDeviceLogin s_KeyDeviceLogin;
	memcpy( &s_KeyDeviceLogin, ps_KeyDeviceLogin, sizeof( NETS_KeyDeviceLogin ) );
	free( ps_KeyDeviceLogin );
	int SocketFd = netc_TwainClientMan.getSocketFd( s_KeyDeviceLogin.index );	// 自分を管理しているテーブルのSocketFdを取得する.
NetTwainDebugTrace((char*)"#### _KeyDeviceLoginProc() s_KeyDeviceLogin.e_Result = [%d] ####\n",s_KeyDeviceLogin.e_Result,0,0,0,0,0);
	switch( s_KeyDeviceLogin.e_Result ) {
		case TYPE_UserResultAdminMachineKM_OK:			// 認証成功⇒アプリに成功を返す.
NetTwainDebugTrace((char*)"#### _KeyDeviceLoginProc()_Authentication Success ####\n",0,0,0,0,0,0);
		strcpy( sc_ReqData, "\x1b*s20123r1V" );													// 成功応答. 
		netc_TwainClientMan.setUserLogined( SocketFd, True );									// ログイン状態とする.
		netc_TwainClientMan.setActiveJobNotify( SocketFd, False );								// ActiveJob通知状態をクリアする.
			break;
		case TYPE_UserResultAdminMachineKM_NG: 			// 認証失敗.
NetTwainDebugTrace((char*)"#### _KeyDeviceLoginProc()_Authentication Failure Login Error ####\n",0,0,0,0,0,0);
			strcpy( sc_ReqData, "\x1b*s20123r0V" );												// 失敗応答.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);				// Access to the specified object is denied.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// エラー発生状態とする.
			break;
// 2011/02/09 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証 START.
		case TYPE_UserResultAdminMachineKM_Busy:		// 認証受付ビジー状態.
			strcpy( sc_ReqData, "\x1b*s20123r0V" );													// 失敗応答.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_AUTHENTICATION_NOT_ACCEPTED , __FILE__ ,__LINE__);	// Authentication Not Accepted.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );								// エラー発生状態とする.
			break;
		case TYPE_UserResultAdminMachineKM_TimeOut:		// タイムアウトによる認証NG.
			strcpy( sc_ReqData, "\x1b*s20123r0V" );												// 失敗応答.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_AUTHENTICATION_SERVER_ERROR , __FILE__ ,__LINE__);		// Authentication Server Error.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// エラー発生状態とする.
			break;
		case TYPE_UserResultAdminMachineKM_ParamError:	// パラメーター不正.
// 2011/02/09 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証 END.
		case TYPE_UserResultAdminMachineKM_Other:		// その他.
		default:										// 存在しない結果.
NetTwainDebugTrace((char*)"#### _KeyDeviceLoginProc()_Authentication Failure for unknown value Login Error ####\n",0,0,0,0,0,0);
			strcpy( sc_ReqData, "\x1b*s20123r0V" );												// 失敗応答.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);				// Access to the specified object is denied.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// エラー発生状態とする.
			break;
	}

	// 2014/09/08 [ZeusS][RQ-232][WP957]OPS1前田 Start.
	if( True == isbizhubRACheck( SocketFd ) ) {
		if ( memcmp( sc_ReqData, "\x1b*s20123r1V", strlen(sc_ReqData) ) == 0 ) {	// 一致した場合.
			setAuthResult( True , False , SocketFd );								//ログイン成功.
		} else {
			setAuthResult( False , False , SocketFd );								//ログイン失敗.
		}
	}
	// 2014/09/08 [ZeusS][RQ-232][WP957]OPS1前田 End.

	char* psc_RspData = (char*)malloc( strlen(sc_ReqData) );
	if( psc_RspData == NULL ) {
		errorLog_TwainService("psc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( psc_RspData, sc_ReqData, strlen(sc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, psc_RspData, (uint32_t)strlen( sc_ReqData ) );		// 送信データ保持領域に書き込む.
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

//==================================================================================================
//[機能]コールバック関数からコールされる関数 
//[履歴]2004.07.23 Matsumoto
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_GetJobSpec( int id, TYPC_JobSpec* pc_JobSpec, void* ptr, int32_t ret, NETE_TwainPacketType e_msgType )
{
NetTwainDebugTrace((char*)"#### ans_GetJobSpec() START! ####\n",0,0,0,0,0,0);
	netc_TwainClientMan.semLock();		// クライアントテーブルを参照・変更するためセマフォをロックする 
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_DocJobSpec* pc_DocJobSpec = (NETS_DocJobSpec*)malloc( sizeof(NETS_DocJobSpec) );
	if( pc_DocJobSpec == NULL ){
		errorLog_TwainService("pc_DocJobSpec_malloc Error\n",0,0,0,0,0,0);
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
		return;
	}
	pc_DocJobSpec->index = id;
	pc_DocJobSpec->pc_JobSpec = pc_JobSpec;
	pc_DocJobSpec->ptr = ptr;
	pc_DocJobSpec->ret = ret;
	netc_TwainService->setPacketData( e_msgType,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
									  (void*)pc_DocJobSpec );
	netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
}

