// 混在対応 iesato 
struct _PerPageData {
	int32_t sl_StartNum;				// ページ単位設定のStartNo 
	int32_t sl_EndNum;					// ページ単位設定のEndNo 
} PerPageData[TYPD_MaxPerPageSet];

//==================================================================================================
//[機能]TicketSettingの取得時の処理関数 
//[履歴]2004.07.23 Matsumoto
//[履歴]2008.02.26 mt_iwa   [管理No.353] FS-526における処理を追加 
//==================================================================================================
void _TicketSettingProc( NETS_DocJobSpec* pc_DocJobSpec )
{
NetTwainDebugTrace((char*)"#### _TicketSettingProc() START! ####\n",0,0,0,0,0,0);
	NETS_DocJobSpec s_DocJobSpec;
	memcpy( &s_DocJobSpec, pc_DocJobSpec, sizeof(NETS_DocJobSpec) );
	free( pc_DocJobSpec );
	int SocketFd = netc_TwainClientMan.getSocketFd( s_DocJobSpec.index );
	if ( SocketFd != -1 ) {
		char pc_ReqData[128];
		int returnLength = 0;
		// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
		if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2 ) { 		// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
		// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			if ( (s_DocJobSpec.pc_JobSpec == NULL) || (s_DocJobSpec.ret == -1) ) {		// 取得失敗 
NetTwainDebugTrace((char*)"### _TicketSettingProc_ERR_PARAMETER_ERROR ###\n",0,0,0,0,0,0);
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				strcpy( pc_ReqData, "\x1b*s311tN" );	// 取得失敗.
				// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				returnLength = strlen( pc_ReqData );
			} else {																	// データ取得成功 
				NETC_TwainDebug_ShowJobSpec("_TicketSettingProc",s_DocJobSpec.pc_JobSpec);
				TYPE_JobType e_JobType = s_DocJobSpec.pc_JobSpec->pc_Common->c_JobType.getJobType(); //20050411 arisawa - Fixed BugNo.36405.
				int32_t sl_NumOfCopies = s_DocJobSpec.pc_JobSpec->pc_Print->getNumOfCopies();									// 部数 
				TYPE_DuplexMode e_DuplexMode = s_DocJobSpec.pc_JobSpec->pc_Print->getDuplexMode();							// 両面 
				TYPE_BindDirection e_BindDirection = s_DocJobSpec.pc_JobSpec->pc_Print->c_BindDirection.getBindDirection();	// 用紙綴じ代 
				TYPE_SortMode e_SortMode = s_DocJobSpec.pc_JobSpec->pc_Print->c_SortMode.getSortMode();						// ソート 
				Bool bl_OffsetOn = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getOffsetOn();							// 仕分け 
				TYPE_StapleMode e_StapleMode = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getStapleMode();				// ステープル 
				TYPE_BindDirection e_StaplePosition = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getStaplePosition();	// ステープル位置 
				TYPE_StapleAngle e_StapleAngle = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getStapleAngle();			// ステープル針角度	// MinervaSBK 機器No18_[FS-537] A4L,LTL奥綴じ時の針角度選択ボタン追加 OPS1八代 2015.05.09.
				TYPE_FoldMode e_FoldMode = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getFoldMode();					// 紙折り 
				TYPE_FeedTray e_FeedTray = s_DocJobSpec.pc_JobSpec->pc_Print->c_PaperTray.getFeedTray();					// 給紙トレイ 
				TYPE_OutputTray e_OutputTray = s_DocJobSpec.pc_JobSpec->pc_Print->c_OutputTray.getOutputTray();				// 排紙トレイ 
				TYPE_FaceMode e_FaceMode = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getFaceMode();					// 排紙モード 
				TYPE_PunchMode e_PunchMode = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getPunchMode();					// パンチ 
				TYPE_BindDirection e_PunchPosition = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getPunchPosition();		// パンチ位置 
				TYPE_Nin1 e_Nin1 = s_DocJobSpec.pc_JobSpec->pc_Print->c_Nin1.getNin1();										// 1ページ/シート 
				Bool bl_BookletOn = s_DocJobSpec.pc_JobSpec->pc_Print->c_Nin1.getBookletOn();								// 週刊誌とじ.
				Bool bl_RepeatOn = s_DocJobSpec.pc_JobSpec->pc_Common->c_Repeat.getOn();										// リピートＯＮ.
				TYPE_RepeatTimes e_RepeatTimes = s_DocJobSpec.pc_JobSpec->pc_Common->c_Repeat.getRepeatTimes();				// リピート回数.
				Bool bl_WideOn = s_DocJobSpec.pc_JobSpec->pc_Print->c_PaperSize.b_WideOn; //ワイド紙指定. //20050319 arisawa - Fixed BugNo.35505.
				TYPE_WidePaperImagePosition e_WidePaperImagePosition = s_DocJobSpec.pc_JobSpec->pc_Print->c_PaperType.getWidePaperImagePosition(); //ワイド紙に対する画像位置指定.

				// 片面/両面/混在対応 
				Bool bl_PerPageSetOn = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getPerPageSetOn();					// ページ単位設定ＯＮ／ＯＦＦ取得 
NetTwainDebugTrace((char*)"### bl_PerPageSetOn[%d] ###\n", bl_PerPageSetOn,0,0,0,0,0);
				Bool bl_PerPageDuplexOn = False;																			// ページ単位設定情報に両面プリントモードＯＮ検出フラグ 
				unsigned char  uc_PerPageSetCount = 0;																		// ページ単位設定の指定数 
				unsigned short us_PerPageSetTotalNum = 0;																	// ページ単位設定されている全ページ数 
				if ( bl_PerPageSetOn == True ) {
					// ページ単位設定ありの場合 
					unsigned char i = 0;
					for ( i = 0; i < TYPD_MaxPerPageSet; i++){					// ページ単位のページ設定数を取得する領域クリア 
						PerPageData[i].sl_StartNum = 0;
						PerPageData[i].sl_EndNum = 0;
					}
					uc_PerPageSetCount = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getPerPageSetCount();	// ページ単位設定の指定数取得（1～TYPD_MaxPerPageSet） 
NetTwainDebugTrace((char*)"### uc_PerPageSetCount[%d] ###\n", uc_PerPageSetCount,0,0,0,0,0);
					for ( i = 0; i < uc_PerPageSetCount; i++){
						TYPC_PerPageSet c_PerPageSet = s_DocJobSpec.pc_JobSpec->pc_Print->c_Finishing.getPerPageSet((uchar)(i+1));		// ページ単位設定情報の位置（1～TYPD_MaxPerPageSet） 
						TYPE_DuplexMode e_PerPageDuplexMode = c_PerPageSet.e_DuplexMode;										// ページ単位設定情報の両面プリントモード 
						if ( e_PerPageDuplexMode == TYPE_DuplexModeOn ) {
							bl_PerPageDuplexOn = True;																			// 両面プリントモードＯＮ検出 
NetTwainDebugTrace((char*)"# c_PerPageSet.e_DuplexMode = TYPE_DuplexModeOn #\n", 0,0,0,0,0,0);
						}
NetTwainDebugTrace((char*)"[%d/%d]\n",i,uc_PerPageSetCount,0,0,0,0);
NetTwainDebugTrace((char*)"c_PerPageSet.e_DuplexMode = [%d]\n",c_PerPageSet.e_DuplexMode,0,0,0,0,0);
						// ページ単位設定されているページ数(範囲）を取得する 
						for( unsigned char j = 0; j < TYPD_MaxPageRange; j++ ) {
NetTwainDebugTrace((char*)"s_PageRange[%d] / sl_StartNo[%ld]\n",j,c_PerPageSet.s_PageRange[j].sl_StartNo,0,0,0,0);
NetTwainDebugTrace((char*)"s_PageRange[%d] / sl_EndNo[%ld]\n",j,c_PerPageSet.s_PageRange[j].sl_EndNo,0,0,0,0);
							if ( c_PerPageSet.s_PageRange[j].sl_StartNo > 0 && c_PerPageSet.s_PageRange[j].sl_EndNo > 0 ){		 // 値がセットされている
								PerPageData[i].sl_StartNum = c_PerPageSet.s_PageRange[j].sl_StartNo;
								PerPageData[i].sl_EndNum = c_PerPageSet.s_PageRange[j].sl_EndNo;
								us_PerPageSetTotalNum = (unsigned short)(us_PerPageSetTotalNum + PerPageData[i].sl_EndNum - PerPageData[i].sl_StartNum +1 );		// ページ単位設定ページ数取得 
NetTwainDebugTrace((char*)"sl_StartNum[%ld] / sl_EndNum[%ld]\n",PerPageData[i].sl_StartNum,PerPageData[i].sl_EndNum,0,0,0,0);
NetTwainDebugTrace((char*)"us_PerPageSetTotalNum[%ld]\n",us_PerPageSetTotalNum,0,0,0,0,0);
							}
							
						}
					}
				}

				TYPE_UniversalAddressType e_AddressType = s_DocJobSpec.pc_JobSpec->pc_Send->c_ComSend.getUniversalAddressType();	// 2007.07.04 Harada 追加 
				// ジョブタイプ // 2007.06.07 Harada 追加 
				switch( e_JobType ) {
					case TYPE_JobTypeCopy:					// コピー 
					case TYPE_JobTypeIntCopy:				// 割込コピー 
						netc_TwainClientMan.setDocumentMode( SocketFd, 1 );
						break;
					case TYPE_JobTypePrint:					// プリント 
					case TYPE_JobTypeSecurePrint:			// 機密文書プリント 
					case TYPE_JobTypePdl:					// ＰＤＬ（ＲＩＰ処理前） 
						netc_TwainClientMan.setDocumentMode( SocketFd, 2 );
						break;
					case TYPE_JobTypeScan:					// スキャン 
					case TYPE_JobTypeTwain:					// Ｔｗａｉｎ 
						netc_TwainClientMan.setDocumentMode( SocketFd, 3 );
						break;
					case TYPE_JobTypeFaxSendQuick:			// ＦＡＸ（クイックメモリ送信） 
					case TYPE_JobTypeFaxSendMemory:			// ＦＡＸ（メモリ送信） 
					case TYPE_JobTypeFaxSendTimer:			// ＦＡＸ(タイマ送信） 
					case TYPE_JobTypeFaxReceive:			// ＦＡＸ受信プリント 
					case TYPE_JobTypeFaxReceiveTimer:		// ＦＡＸ（タイマーポーリング受信） 
					case TYPE_JobTypeFaxReceivePolling:		// ＦＡＸ（ポーリング送信） 
						// 2007.07.04 Harada 追加 
						// ユニバーサルセンド宛先種別をチェックしてBox宛先が含まれている場合はモードをスキャンとする 
						// 実際は、Scan/faxモードからBox保存した場合は、TYPE_JobTypeFaxSendMemoryなので全てScanとしてもOKだが分けておく 
						if ( ( e_AddressType & TYPE_UniversalAddressTypeBox ) != 0 ) {
							netc_TwainClientMan.setDocumentMode( SocketFd, 3 );		// Scan 
NetTwainDebugTrace((char*)"!! sc_JobFunction = Scan \n", 0,0,0,0,0,0);
						} else {
							netc_TwainClientMan.setDocumentMode( SocketFd, 4 );		// FAX 
						}
						break;
					case TYPE_JobTypeIfaxReceive:			// ＩＦａｘ受信 
						netc_TwainClientMan.setDocumentMode( SocketFd, 5 );
						break;
					default:								// それ以外(暫定) 
						netc_TwainClientMan.setDocumentMode( SocketFd, 0 );
						break;
				}

				NETS_JobTicket nets_JobTicket;
				memset( &nets_JobTicket, 0, sizeof(NETS_JobTicket) );
				// 部数 
				nets_JobTicket.uc_NumOfCopies[0] = (unsigned char)(sl_NumOfCopies & 0x00ff);
				nets_JobTicket.uc_NumOfCopies[1] = (unsigned char)(sl_NumOfCopies & 0xff00) >> 8 ;
				// 両面 2005.07.11変更（両面-自動、混在対応） 
				if ( e_DuplexMode == TYPE_DuplexModeOff ) {											// 片面 
					nets_JobTicket.uc_DuplexMode = 1;
				} else if ( e_DuplexMode == TYPE_DuplexModeOn ) {									// 両面 
					if ( e_BindDirection == TYPE_BindDirectionLeft ) {			// 左綴じ 
						nets_JobTicket.uc_DuplexMode = 2;
					} else if ( e_BindDirection == TYPE_BindDirectionTop ) {	// 上綴じ 
						nets_JobTicket.uc_DuplexMode = 3;
					} else if ( e_BindDirection == TYPE_BindDirectionRight ) {	// 右綴じ 
						nets_JobTicket.uc_DuplexMode = 4;
					} else if ( e_BindDirection == TYPE_BindDirectionAuto ) {	// 自動 
						nets_JobTicket.uc_DuplexMode = 5;
					} else {													// それ以外 
						nets_JobTicket.uc_DuplexMode = 1;
					}
				} else {																			// 片/両ページ混在（e_DuplexMode = TYPE_DuplexModePageMix） 
					if ( bl_PerPageSetOn == False ){
						// ページ単位設定OFFの場合 
						if ( netc_TwainClientMan.getPrintFaceIndi_Single( SocketFd ) == True ) {				// Leafのプリント面指定が片面 
							// 片面である 
							nets_JobTicket.uc_DuplexMode = 1;							// 片面(両面OFF） 
						} else {		// プリント面指定が両面 
							// 両面である 
							if ( e_BindDirection == TYPE_BindDirectionLeft ) {			// 左綴じ 
								nets_JobTicket.uc_DuplexMode = 2;
							} else if ( e_BindDirection == TYPE_BindDirectionTop ) {	// 上綴じ 
								nets_JobTicket.uc_DuplexMode = 3;
							} else if ( e_BindDirection == TYPE_BindDirectionRight ) {	// 右綴じ 
								nets_JobTicket.uc_DuplexMode = 4;
							} else if ( e_BindDirection == TYPE_BindDirectionAuto ) {	// 自動 
								nets_JobTicket.uc_DuplexMode = 5;
							} else {													// それ以外 
								nets_JobTicket.uc_DuplexMode = 1;
							}
						}
					} else {
						// ページ単位設定ＯＮの場合 
						unsigned short us_PageNumOfOriginals = netc_TwainClientMan.getNumOfOriginals( SocketFd );		// ドキュメントの原稿枚数(全ページ数）取得 
NetTwainDebugTrace((char*)"us_PageNumOfOriginals = [%d]\n",us_PageNumOfOriginals,0,0,0,0,0);
						if ( netc_TwainClientMan.getPrintFaceIndi_Single(  SocketFd ) == False  ) {			// Leafのプリント面指定が両面 
							if ( bl_PerPageDuplexOn == False ) {					// ページ単位の両面プリントOFF(ページ単位が片面） 
								// 両面に片面のページ設定 
NetTwainDebugTrace((char*)"---[1]---\n", 0,0,0,0,0,0);
								if ( us_PerPageSetTotalNum < us_PageNumOfOriginals ) { 	// ページ単位設定ページ数 <  全ページ数 
									nets_JobTicket.uc_DuplexMode = 6;						// 片/両ページ混在 
								} else {												// ページ単位設定ページ数 =  全ページ数 
									nets_JobTicket.uc_DuplexMode = 1;						// 片面(両面OFF） 
								}
							} else {												// ページ単位の両面プリントON  
NetTwainDebugTrace((char*)"---[2]---\n", 0,0,0,0,0,0);
								// 両面に両面のページ設定 
								// 両面に対して両面のページ単位設定をおこなった場合は、【両面】とする。 
								// 一部に両面のページ単位設定をおこなって実際の印刷結果が片/両が混ざったようになっても、ユーザーが両面に設定したので【両面】 
								if ( e_BindDirection == TYPE_BindDirectionLeft ) {			// 左綴じ 
									nets_JobTicket.uc_DuplexMode = 2;
								} else if ( e_BindDirection == TYPE_BindDirectionTop ) {	// 上綴じ 
									nets_JobTicket.uc_DuplexMode = 3;
								} else if ( e_BindDirection == TYPE_BindDirectionRight ) {	// 右綴じ 
									nets_JobTicket.uc_DuplexMode = 4;
								} else if ( e_BindDirection == TYPE_BindDirectionAuto ) {	// 自動 
									nets_JobTicket.uc_DuplexMode = 5;
								} else {													// それ以外 
									nets_JobTicket.uc_DuplexMode = 2;
								}
							}
						} else {																							// Leafのプリント面指定が片面 
NetTwainDebugTrace((char*)"---[3]---\n", 0,0,0,0,0,0);
							if ( bl_PerPageDuplexOn == False ) {					// ページ単位の両面プリントOFF 
								// ***  「印刷種類：片面」に、片面のページ単位指定の場合は【片面】 
NetTwainDebugTrace((char*)"---[4]---\n", 0,0,0,0,0,0);
								nets_JobTicket.uc_DuplexMode = 1;							// 片面(両面OFF） 
							} else {												// ページ単位の両面プリントON  
								// ***  「印刷種類：片面」に、両面のページ単位指定の場合は【混在】 
								if ( us_PerPageSetTotalNum < us_PageNumOfOriginals ) { 	// ページ単位設定ページ数 <  全ページ数 
NetTwainDebugTrace((char*)"---[5]---\n", 0,0,0,0,0,0);
									nets_JobTicket.uc_DuplexMode = 6;						// 片/両ページ混在 
								} else {												// ページ単位設定ページ数 =  全ページ数 
NetTwainDebugTrace((char*)"---[6]---\n", 0,0,0,0,0,0);
									// 両面である 
									if ( e_BindDirection == TYPE_BindDirectionLeft ) {			// 左綴じ 
										nets_JobTicket.uc_DuplexMode = 2;
									} else if ( e_BindDirection == TYPE_BindDirectionTop ) {	// 上綴じ 
										nets_JobTicket.uc_DuplexMode = 3;
									} else if ( e_BindDirection == TYPE_BindDirectionRight ) {	// 右綴じ 
										nets_JobTicket.uc_DuplexMode = 4;
									} else if ( e_BindDirection == TYPE_BindDirectionAuto ) {	// 自動 
										nets_JobTicket.uc_DuplexMode = 5;
									} else {													// それ以外 
										nets_JobTicket.uc_DuplexMode = 2;
									}
								}
							}
						} 
					}
				}
				// ソート 
				if ( e_SortMode == TYPE_SortModeSort ) {			// ソート 
					nets_JobTicket.uc_SortMode = 1;
				} else {											// ソート以外 
					nets_JobTicket.uc_SortMode = 2;
				}
				// 仕分け 
				if ( bl_OffsetOn == False ) {	// オフセットOFF 
					nets_JobTicket.uc_OffsetOn = 1;
				} else {						// オフセットON 
					nets_JobTicket.uc_OffsetOn = 2;
				}
				// ステープル 
				if ( e_StapleMode == TYPE_StapleModeNone ) {			// ステープルOFF 
					nets_JobTicket.uc_StapleMode = 1;
				} else if ( e_StapleMode == TYPE_StapleModeCorner ) {	// コーナーステープル(1点) 
					if ( e_StaplePosition == TYPE_BindDirectionRight ) {		// 右綴じ 
						nets_JobTicket.uc_StapleMode = 2;
					} else if ( e_StaplePosition == TYPE_BindDirectionLeft ) {	// 左綴じ 
						nets_JobTicket.uc_StapleMode = 3;
					// BugNo72515 Autoの場合に値をかえしてい  
					} else if ( e_StaplePosition == TYPE_BindDirectionAuto ) {	// Auto 
						nets_JobTicket.uc_StapleMode = 9;
					} else {													// それ以外 
						nets_JobTicket.uc_StapleMode = 1;
					}
				} else if ( e_StapleMode == TYPE_StapleModeSide ) {		// サイドステープル(2点) 
					if ( e_StaplePosition == TYPE_BindDirectionRight ) {		// 右綴じ 
						nets_JobTicket.uc_StapleMode = 4;
					} else if ( e_StaplePosition == TYPE_BindDirectionLeft ) {	// 左綴じ 
						nets_JobTicket.uc_StapleMode = 5;
					} else if ( e_StaplePosition == TYPE_BindDirectionTop ) {	// 上綴じ 
						nets_JobTicket.uc_StapleMode = 6;
					} else if ( e_StaplePosition == TYPE_BindDirectionAuto ) {	// Auto 
						nets_JobTicket.uc_StapleMode = 7;
					} else {													// それ以外 
						nets_JobTicket.uc_StapleMode = 1;
					}
				} else if ( e_StapleMode == TYPE_StapleModeCenter ) {	// センターステープル 
					if (NETC_Twain_isCenterStapleInFolds() == False){ //20050317 arisawa - Fixed BugNo.34864.
						//紙折り/綴じ/断裁メニューに中綴じを実装しない場合.
						nets_JobTicket.uc_StapleMode = 8;
					}
				}

				// MinervaSBK 機器No18_[FS-537] A4L,LTL奥綴じ時の針角度選択ボタン追加 OPS1八代 2015.05.09 START.
				// ステープル針角度.
				if( TYPE_StapleAngle_0 == e_StapleAngle ) {			// 1箇所(左0度：大サイズ用紙).
					nets_JobTicket.uc_StapleMode = 10;

					// ステープル針角度0度の場合は、必ず、コーナー1点、位置左となるはず.
					if( ( TYPE_StapleModeCorner != e_StapleMode ) || ( TYPE_BindDirectionLeft != e_StaplePosition ) ) {
NetTwainDebugTrace((char*)"StapleAngle_0 Illegal Convination!! Mode = %d, Position = %d \n", e_StapleMode,e_StaplePosition,0,0,0,0);
					}
				}
				// MinervaSBK 機器No18_[FS-537] A4L,LTL奥綴じ時の針角度選択ボタン追加 OPS1八代 2015.05.09 END.

				// 紙折り/綴じ/断裁 
// Rhein1は、中綴じと紙折りがセットなので、紙折りをNotSupportに変更 

				// ↓ mosel 折り対応 
				nets_JobTicket.uc_FoldMode = 0;
				switch ( e_FoldMode ) {
					case TYPE_FoldModeOff :					// OFF 
						nets_JobTicket.uc_FoldMode = 1;
						break;
					case TYPE_FoldModeCenterInner :			// 内中折り 
					case TYPE_FoldModeCenterOuter :			// 外中折り 
						nets_JobTicket.uc_FoldMode = 4;
						break;
					case TYPE_FoldModeZShaped :				// Ｚ折り	ＰＺ１０８／１０９のみ機能搭載 
						nets_JobTicket.uc_FoldMode = 5;
						break;
					case TYPE_FoldModeLetterIn :			// 内三つ折り(印字面が内側)	"巻き三つ折：ＦＳ２１０ｍとＭｉｒａｇｅに機能搭載" 
					case TYPE_FoldModeLetterOut :			// 内三つ折り(印字面が外側)	"巻き三つ折：ＦＳ２１０ｍとＭｉｒａｇｅに機能搭載" //20050404 arisawa - Fixed BugNo.35002.
						nets_JobTicket.uc_FoldMode = 10; 	 // 内三つ折り(印字方向指定なし)
						break;
					default:
						nets_JobTicket.uc_FoldMode = 1;
						break;
				}
				// ↑ mosel 折り対応 

				// 給紙トレイ 
				APIC_FeedTray* pc_FeedTray = APIC_FeedTray::newInstance();			// 給紙トレイ情報のインスタンスを取得する 
				pc_FeedTray->lock();

				switch ( e_FeedTray ) {						// 20101115 amiya 【Minerva】機器案件 外付けLCT START.
					case TYPE_FeedTray1:		// 第1トレイ.
						nets_JobTicket.uc_FeedTray = 2;
						break;
					case TYPE_FeedTray2:		// 第2トレイ.
						nets_JobTicket.uc_FeedTray = 3;
						break;
					case TYPE_FeedTray3:		// 第3トレイ.
						nets_JobTicket.uc_FeedTray = 4;
						break;
					case TYPE_FeedTray4:		// 第4トレイ.
						nets_JobTicket.uc_FeedTray = 5;
						break;
					case TYPE_FeedTray5:		// 第5トレイ.
						nets_JobTicket.uc_FeedTray = 7;
						break;
					case TYPE_FeedTrayManual:	// 手差しトレイ.
						nets_JobTicket.uc_FeedTray = 8;
						break;
					default:					// 無い場合は、第1トレイにする.
						nets_JobTicket.uc_FeedTray = 2;
						break;
				}											// 20101115 amiya 【Minerva】機器案件 外付けLCT END.

				pc_FeedTray->unlock();
				if ((e_JobType == TYPE_JobTypePrint) || (e_JobType == TYPE_JobTypeSecurePrint) ||
					(e_JobType == TYPE_JobTypeScan)){
					/*
					■Printの場合.
						給紙トレイ情報(PaperSource)はLeafに設定される(JobSpecには設定されない).
						PrintではPerPageSettingで混載トレイの指定が可能.
						Print時にLeaf情報を見て給紙トレイが決定される.
						⇒PerPageSettingの時は混載トレイなのでJobTicketはAPS.
						  PerPageSettingでない時はAPSではないが、取得できないのでAPSで返す(制限事項).
					■Scanの場合.
						給紙トレイ情報はAPS固定でLeafに設定される(JobSpecには設定されない).
						Print時にLeaf情報を見て給紙トレイが決定される(すべてAPS).
						⇒すべてAPSで出力されるのでJobTicketはAPS.
					*/
					nets_JobTicket.uc_FeedTray = NETE_TicketFeedTray_Auto;
				}
				// 排紙トレイ 
				APIC_PrinterSystem* pc_PrinterSystem = APIC_PrinterSystem::newInstance();
				pc_PrinterSystem->lock();
				Bool b_isExistFinisher = pc_PrinterSystem->isExistFinisher();				// フィニッシャ有無を取得する 
				TYPE_FinisherType e_FinisherType = pc_PrinterSystem->getFinisherType();		// フィニッシャタイプを取得する 
				Bool b_isOptionTray3 = pc_PrinterSystem->isOptionTray3();						// オプショントレイ装着情報の取得（CB_FNの場合は増設トレイが相当する） 
NetTwainDebugTrace((char*)" b_isOptionTray3 = [%d]\n",pc_PrinterSystem->isOptionTray3(),0,0,0,0,0);
				pc_PrinterSystem->unlock();
				APIC_CopyJobSetting* pc_CopyJobSetting = APIC_CopyJobSetting::newInstance();	
				pc_CopyJobSetting->lock();
				Bool b_AssignMailBin_Tray1 = pc_CopyJobSetting->getAssignMailBin_Tray1();		// Tray1（メイントレイ)のメールビン割り当て状態取得 
				Bool b_AssignMailBin_Tray2 = pc_CopyJobSetting->getAssignMailBin_Tray2();		// Tray2（増設ビン)のメールビン割り当て状態取得 
				pc_CopyJobSetting->unlock();
NetTwainDebugTrace((char*)" b_AssignMailBin_Tray1 = [%d]\n",b_AssignMailBin_Tray1,0,0,0,0,0);
NetTwainDebugTrace((char*)" b_AssignMailBin_Tray2 = [%d]\n",b_AssignMailBin_Tray2,0,0,0,0,0);
				if ( b_isExistFinisher == False ) {			// 排紙オプション非装着 
					nets_JobTicket.uc_OutputTray = 21;
				} else {									// 排紙オプション装着時
					switch( e_OutputTray )
					{
						case TYPE_OutputTrayMain:			// メイントレイ（Ｍ：エレベートトレイ）	基本定義として基本出力モード（ステイプル・パンチ・仕分け）で出力可能なトレイ 
							switch (e_FinisherType)
							{
								case TYPE_FinisherTypeFS504:			// ＦＳ５０４
								case TYPE_FinisherTypeFS602:			// ＦＳ６０２
								case TYPE_FinisherTypeFS505:			// ＦＳ５０５
								case TYPE_FinisherTypeFS506:			// ＦＳ５０６
								case TYPE_FinisherTypeFS601:			// ＦＳ６０１
								case TYPE_FinisherTypeFS517:			// ＦＳ５１７ 
								case TYPE_FinisherTypeFS518:			// ＦＳ５１８ 
								case TYPE_FinisherTypeFS608:			// ＦＳ６０８ 
								case TYPE_FinisherTypeFS526:			// ＦＳ５２６ 
								case TYPE_FinisherTypeFS527:			// ＦＳ５２７.
								case TYPE_FinisherTypeFS529:			// ＦＳ５２９.
								case TYPE_FinisherTypeFS533:			// ＦＳ５３３.		// 2010/10/22 amiya 【Minerva】<機器要望 M28> 新排紙OP対応.
								case TYPE_FinisherTypeFS534:			// ＦＳ５３４.		// 2010/10/22 amiya 【Minerva】<機器要望 M28> 新排紙OP対応.
								case TYPE_FinisherTypeFS535:			// ＦＳ５３５.		// 2010/10/22 amiya 【Minerva】<機器要望 M28> 新排紙OP対応.
								case TYPE_FinisherTypeFS536:			// ＦＳ５３６.		// [2015/03/23][MinervaSBK][制御構成変更No.14][OPS1前田]FS536追加対応.
								case TYPE_FinisherTypeFS537:			// ＦＳ５３７.		// [2015/03/23][MinervaSBK][制御構成変更No.15][OPS1前田]FS537追加対応.
								case TYPE_FinisherTypeFS539:			// ＦＳ５３９.		// 2018/10/25 FPT-LongVD2 【IT6_EagleH】【EagleH】 機器構成変更_No.5 Add.
								case TYPE_FinisherTypeFS540:			// ＦＳ５４０.		// 2018/10/25 FPT-LongVD2 【IT6_EagleH】【EagleH】 機器構成変更_No.5 Add.
								case TYPE_FinisherTypeFS542:			// ＦＳ５４２.		//2022/06/27 FPT-HaDV8 【IT6_2.3】 機器構成変更_No.2 Add.
									nets_JobTicket.uc_OutputTray = 15;			// メイントレイ(FS-XXX) 
									break;
								case TYPE_FinisherTypeCB:				// CB_FN 
									if ( b_AssignMailBin_Tray1 == True ) {		 // メールビン割り当てあり（Tray1：メイントレイ） 
										nets_JobTicket.uc_OutputTray = 29;			//メールビン5 
									} else  {
										nets_JobTicket.uc_OutputTray = 12;			//第1トレイ (FN-xx)(CB-FN) 
									}
									break;
								case TYPE_FinisherTypeJS:				// JobSeparator 
								case TYPE_FinisherTypeJS506:			// JS-506.			// 2010/10/22 amiya 【Minerva】<機器要望 M28> 新排紙OP対応.
									// JobSeparatorは上から第1トレイ、第2トレイの順 
									// 第1トレイがサブトレイ（Ｍ：第１トレイ）、第2トレイがメイントレイなので、ここでは第2トレイの値をセット 
										nets_JobTicket.uc_OutputTray = 23;			//第2トレイ 
									break;
								default:								// ＦＮ－Ｘ０、ＦＮ－Ｘ３の場合 
									nets_JobTicket.uc_OutputTray = 14;			// エレベータトレイ(FN-XX) 
									break;
							}
							break;
						case TYPE_OutputTraySub1:			// サブトレイ（Ｍ：第１トレイ）	メイントレイ以外のトレイ 
							switch (e_FinisherType)
							{
								case TYPE_FinisherTypeFS504:			// ＦＳ５０４
								case TYPE_FinisherTypeFS602:			// ＦＳ６０２
								case TYPE_FinisherTypeFS505:			// ＦＳ５０５
								case TYPE_FinisherTypeFS506:			// ＦＳ５０６
								case TYPE_FinisherTypeFS517:			// ＦＳ５１７ 
								case TYPE_FinisherTypeFS518:			// ＦＳ５１８ 
								case TYPE_FinisherTypeFS526:			// ＦＳ５２６ 
								case TYPE_FinisherTypeFS527:			// ＦＳ５２７.
								case TYPE_FinisherTypeFS534:			// ＦＳ５３４.		// 2010/10/22 amiya 【Minerva】<機器要望 M28> 新排紙OP対応.
								case TYPE_FinisherTypeFS535:			// ＦＳ５３５.		// 2010/10/22 amiya 【Minerva】<機器要望 M28> 新排紙OP対応.
								case TYPE_FinisherTypeFS536:			// ＦＳ５３６.		// [2015/03/23][MinervaSBK][制御構成変更No.14][OPS1前田]FS536追加対応.
								case TYPE_FinisherTypeFS537:			// ＦＳ５３７.		// [2015/03/23][MinervaSBK][制御構成変更No.15][OPS1前田]FS537追加対応.
								case TYPE_FinisherTypeFS539:			// ＦＳ５３９.		// 2018/10/25 FPT-LongVD2 【IT6_EagleH】【EagleH】 機器構成変更_No.5 Add.
								case TYPE_FinisherTypeFS540:			// ＦＳ５４０.		// 2018/10/25 FPT-LongVD2 【IT6_EagleH】【EagleH】 機器構成変更_No.5 Add.
									nets_JobTicket.uc_OutputTray = 16;			// サブトレイ(FS-XXX) 
									break;
								case TYPE_FinisherTypeCB:				// CB_FN 
									if ( b_isOptionTray3 == True ) {			// オプショントレイ有りの場合 
										nets_JobTicket.uc_OutputTray = 13;			//第3トレイ (CB-FN) 
									} else {
										nets_JobTicket.uc_OutputTray = 23;			//第2トレイ (CB-FN) 
									}
									break;
								case TYPE_FinisherTypeJS:				// JobSeparator 
									// JobSeparatorは上から第1トレイ、第2トレイの順 
									// 第1トレイがサブトレイ（Ｍ：第１トレイ）、第2トレイがメイントレイなので、ここでは第1トレイの値をセット 
										nets_JobTicket.uc_OutputTray = 12;			//第1トレイ 
									break;
								default:								// ＦＮ－Ｘ０、ＦＮ－Ｘ３の場合 
									nets_JobTicket.uc_OutputTray = 12;			// 第１トレイ(FN-XX) 
								break;
							}
							break;
						case TYPE_OutputTraySub2:			// サブトレイ（Ｍ：第３トレイ） 
							switch (e_FinisherType)
							{
								case TYPE_FinisherTypeFS504:			// ＦＳ５０４
								case TYPE_FinisherTypeFS602:			// ＦＳ６０２
								case TYPE_FinisherTypeFS505:			// ＦＳ５０５
								case TYPE_FinisherTypeFS506:			// ＦＳ５０６
								case TYPE_FinisherTypeFS517:			// ＦＳ５１７ 
								case TYPE_FinisherTypeFS518:			// ＦＳ５１８ 
									nets_JobTicket.uc_OutputTray = 16;			// サブトレイ(FS-XXX) 
									break;
								case TYPE_FinisherTypeCB:				// CB_FN 
									if ( b_AssignMailBin_Tray2 == True ) {		 // メールビン割り当てあり（Tray2：増設ビン） 
										nets_JobTicket.uc_OutputTray = 30;			//メールビン６(CB-FN) 
									} else {
										nets_JobTicket.uc_OutputTray = 23;			//第2トレイ (CB-FN) 
									}
									break;
								default:								// ＦＮ－Ｘ０、ＦＮ－Ｘ３の場合 
									nets_JobTicket.uc_OutputTray = 13;			// 第３トレイ(FN-XX) 
								break;
							}
							break;
						case TYPE_OutputTrayBooklet:		// ブックレットトレイ（Ｍ：サドルトレイ）	折った用紙を出力するトレイ（中折り/中綴じ、Z折り、袋折り、３つ折り） 
							nets_JobTicket.uc_OutputTray = 17;			// Bookletトレイ(FS-602,FN-X3) 
							break;
						case TYPE_OutputTrayProcess:		// フィニッシャ処理トレイ 
							// 処理トレイは最終的な排出先でないため、排出先が処理トレイの場合は、エレベートトレイとする。 
							// 処理トレイからはエレベートトレイに出力される。 
							nets_JobTicket.uc_OutputTray = 14;			// エレベータトレイ(FN-X3) 
							break;
						case TYPE_OutputTrayMailBin1:		// メールビン1 
							nets_JobTicket.uc_OutputTray = 25;
							break;
						case TYPE_OutputTrayMailBin2:		// メールビン2 
							nets_JobTicket.uc_OutputTray = 26;
							break;
						case TYPE_OutputTrayMailBin3:		// メールビン3 
							nets_JobTicket.uc_OutputTray = 27;
							break;
						case TYPE_OutputTrayMailBin4:		// メールビン4 
							nets_JobTicket.uc_OutputTray = 28;
							break;
						case TYPE_OutputTrayAuto:			// 自動判別  #40232対応 2005.08.01 iesato 
							nets_JobTicket.uc_OutputTray = 1;
							break;
						default:							// それ以外 
							nets_JobTicket.uc_OutputTray = 15;			// メイントレイ 
							break;
					}
				}
				// 排紙モード 
				if ( e_FaceMode == TYPE_FaceModeUp ) {			// フェイスアップ（印刷面を上にして出力） 
					nets_JobTicket.uc_FaceMode = 2;
				} else if ( e_FaceMode == TYPE_FaceModeDown ) {	// フェイスダウン (印刷面を下にして出力) 
					nets_JobTicket.uc_FaceMode = 1;
				}
				// ページ順--NotSupport 
				nets_JobTicket.uc_Page = 0;
				// パンチ 
				switch ( e_PunchMode ) {
					case TYPE_PunchModeNone:			// なし 
						nets_JobTicket.uc_PunchMode = 1;
						break;
					case TYPE_PunchMode2:				// 2穴 
						switch ( e_PunchPosition ) {
							case TYPE_BindDirectionAuto:
								nets_JobTicket.uc_PunchMode = 2;
								break;
							case TYPE_BindDirectionTop:
								nets_JobTicket.uc_PunchMode = 3;
								break;
							case TYPE_BindDirectionLeft:
								nets_JobTicket.uc_PunchMode = 4;
								break;
							case TYPE_BindDirectionRight:
								nets_JobTicket.uc_PunchMode = 5;
								break;
							default:
								nets_JobTicket.uc_PunchMode = 2;
								break;
						}
						break;
					case TYPE_PunchMode3:				// 3穴 
						switch ( e_PunchPosition ) {
							case TYPE_BindDirectionAuto:
								nets_JobTicket.uc_PunchMode = 6;
								break;
							case TYPE_BindDirectionTop:
								nets_JobTicket.uc_PunchMode = 7;
								break;
							case TYPE_BindDirectionLeft:
								nets_JobTicket.uc_PunchMode = 8;
								break;
							case TYPE_BindDirectionRight:
								nets_JobTicket.uc_PunchMode = 9;
								break;
							default:
								nets_JobTicket.uc_PunchMode = 6;
								break;
						}
						break;
					case TYPE_PunchMode4:
						switch ( e_PunchPosition ) {
							case TYPE_BindDirectionAuto:
								nets_JobTicket.uc_PunchMode = 10;
								break;
							case TYPE_BindDirectionTop:
								nets_JobTicket.uc_PunchMode = 11;
								break;
							case TYPE_BindDirectionLeft:
								nets_JobTicket.uc_PunchMode = 12;
								break;
							case TYPE_BindDirectionRight:
								nets_JobTicket.uc_PunchMode = 13;
								break;
							default:
								nets_JobTicket.uc_PunchMode = 10;
								break;
						}
						break;
					default:
						nets_JobTicket.uc_PunchMode = 1;
						break;
				}
				// 1ページ/シート--NotSupport  
				switch ( e_Nin1 ) {
					case TYPE_Nin1_1in1:
						nets_JobTicket.uc_Nin1 = 1;
						break;
					case TYPE_Nin1_2in1:
						nets_JobTicket.uc_Nin1 = 2;
						break;
					case TYPE_Nin1_4in1 : // ４ｉｎ１.
						nets_JobTicket.uc_Nin1 = 8;
						break;
					case TYPE_Nin1_8in1 : // ８ｉｎ１.
						nets_JobTicket.uc_Nin1 = 10;
						break;
					default:
						nets_JobTicket.uc_Nin1 = 1;
						break;
				}
				if (bl_RepeatOn){
					//リピートは後優先にする.
					switch (e_RepeatTimes){
						case TYPE_RepeatTimesAuto: // 自動.
							nets_JobTicket.uc_Nin1 = 0;		//IF仕様に定義無し 
							break;
						case TYPE_RepeatTimes2   : // ２個.
							nets_JobTicket.uc_Nin1 = 3;
							break;
						case TYPE_RepeatTimes4   : // ４個.
							nets_JobTicket.uc_Nin1 = 9;
							break;
						case TYPE_RepeatTimes8   : // ８個.
							nets_JobTicket.uc_Nin1 = 11;
							break;
						default:
							break;
					}
				}
				// Booklet 
				// Bookletは、オフ、左開き、右開き。上開きはできない。 
				nets_JobTicket.uc_PageShot = 1; //OFF 
				if (bl_BookletOn){
					switch (e_BindDirection){
						case TYPE_BindDirectionRight: // 右綴じ.
							nets_JobTicket.uc_PageShot = 3; //右開き.（右綴じは右開き） 
							break;
						case TYPE_BindDirectionLeft : // 左綴じ.
							nets_JobTicket.uc_PageShot = 2; //左開き.（左綴じは左開き） 
							break;
					default:
							nets_JobTicket.uc_PageShot = 2; //左開き
							break;
					}
				}
				// PrintPosition--NotSupport 
				nets_JobTicket.uc_PrintPosition = 0;
				if (NETC_Twain_isPrintPositionSupportedSystem() && bl_WideOn){ //20050319 arisawa - Fixed BugNo.35505.
					switch (e_WidePaperImagePosition){
						case TYPE_WidePaperImagePositionTop   :// 先端 
							nets_JobTicket.uc_PrintPosition = ( e_FaceMode == TYPE_FaceModeUp ) ? (unsigned char)1 : (unsigned char)3; //FaceUp:左,FaceDown:右.
							break;
						case TYPE_WidePaperImagePositionCenter:// 中央 
							nets_JobTicket.uc_PrintPosition = (unsigned char)2;
							break;
						case TYPE_WidePaperImagePositionBottom:// 後端 
							nets_JobTicket.uc_PrintPosition = ( e_FaceMode == TYPE_FaceModeUp ) ? (unsigned char)3 : (unsigned char)1; //FaceUp:右,FaceDown:左.
							break;
					}
				}
				// タンデムプリント--NotSupport 
				nets_JobTicket.uc_TumdemPrint = 0;
				// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				// カラー (4 固定).
				nets_JobTicket.uc_ColorMode = 4;
				// 応答データ作成.
				int si_tempLength = sprintf( pc_ReqData, "\x1b*s311t%dW", sizeof(NETS_JobTicket) );
				// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				memcpy( &pc_ReqData[si_tempLength], (char*)&nets_JobTicket, sizeof(NETS_JobTicket) );
				returnLength = si_tempLength + sizeof(NETS_JobTicket);
			}
		} else {
			return;
		}
		char* pc_RspData = (char*)malloc( returnLength );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, returnLength );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)returnLength );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// RREQを受けている 
			// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2 ) { 		// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
			// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
			} else {
				free( pc_RspData );
			}
		}

		netc_TwainClientMan.setHddAccessEndWait( SocketFd );

	}
}
//==================================================================================================
//[機能]コールバック関数からコールされる関数 
//[履歴]2004.11.27 Iesato
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_GetJobStatus( int id, TYPC_JobStatus* pc_JobStatusDoc, void* ptr, int32_t ret )
{
NetTwainDebugTrace((char*)"#### ans_GetJobStatus() START! ####\n",0,0,0,0,0,0);
	netc_TwainClientMan.semLock();		// クライアントテーブルを参照・変更するためセマフォをロックする 
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_DocJobStatus* pc_DocJobStatus = (NETS_DocJobStatus*)malloc( sizeof(NETS_DocJobStatus) );
	if( pc_DocJobStatus == NULL ){
		errorLog_TwainService("pc_DocJobStatus_malloc Error\n",0,0,0,0,0,0);
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
		return;
	}
	pc_DocJobStatus->index = id;
	pc_DocJobStatus->pc_JobStatusDoc = pc_JobStatusDoc;
	pc_DocJobStatus->ptr = ptr;
	pc_DocJobStatus->ret = ret;
	netc_TwainService->setPacketData( NETE_TWAIN_GET_JOB_STATUS,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
									  (void*)pc_DocJobStatus );
	netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
}

