//==================================================================================================
//[機能]コールバック関数からコールされる関数 
//[履歴]2004.08.17 Matsumoto
//      2005.09.21 int32_t ret 追加
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_GetDocInstance( int id, DOCC_CompositeDoc* pc_CompositeDoc, void* ptr, int32_t ret )
{
NetTwainDebugTrace((char*)"#### ans_GetDocInstance() START! ####\n",0,0,0,0,0,0);
	netc_TwainClientMan.semLock();		// クライアントテーブルを参照・変更するためセマフォをロックする 
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_CompositeDoc* pc_CompositeDocMsg = (NETS_CompositeDoc*)malloc( sizeof(NETS_CompositeDoc) );
	if( pc_CompositeDocMsg == NULL ){
		errorLog_TwainService("pc_CompositeDocMsg_malloc Error\n",0,0,0,0,0,0);
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
		return;
	}
	pc_CompositeDocMsg->index = id;
	pc_CompositeDocMsg->pc_CompositeDoc = pc_CompositeDoc;
	pc_CompositeDocMsg->ptr = ptr;
	netc_TwainService->setPacketData( NETE_TWAIN_DOC_INSTANCE,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
									  (void*)pc_CompositeDocMsg );
	netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
}
