//==================================================================================================
//[機能]JobStatus取得時の処理関数 
//[履歴]2004.11.27 Iesato
//==================================================================================================
void _GetJobStatus( NETS_DocJobStatus* pc_DocJobStatus )
{
NetTwainDebugTrace((char*)"#### _GetJobStatus() START! ####\n",0,0,0,0,0,0);
	NETS_DocJobStatus s_DocJobStatus;
	memcpy( &s_DocJobStatus, pc_DocJobStatus, sizeof(NETS_DocJobStatus) );
	free( pc_DocJobStatus );
	int SocketFd = netc_TwainClientMan.getSocketFd( s_DocJobStatus.index );
	if ( SocketFd != -1 ) {
		Bool isRsp = False;
		char pc_ReqData[32];
		if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_PRINT_DOC ) { 		// WDATコマンドがSCL_PRINT_DOCである 
			if ( (s_DocJobStatus.pc_JobStatusDoc == NULL) || (s_DocJobStatus.ret == -1) ) {		// 取得失敗 
NetTwainDebugTrace((char*)"### _GetJobStatus_ERR_PARAMETER_ERROR ###\n",0,0,0,0,0,0);
				isRsp = True;
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				strcpy( pc_ReqData, "\x1b*s34520r0V" );	// 設定失敗 
			} else {
				// ドキュメントのJobStatusから原稿枚数を取得し保持する。
				netc_TwainClientMan.setNumOfOriginals( SocketFd, s_DocJobStatus.pc_JobStatusDoc->getNumOfOriginals() );	// 原稿枚数を取得する 
NetTwainDebugTrace((char*)" [_GetJobStatus]setNumOfOriginals= [%d]\n", s_DocJobStatus.pc_JobStatusDoc->getNumOfOriginals(),0,0,0,0,0);
				netc_TwainClientMan.setTransactionID( SocketFd, s_DocJobStatus.pc_JobStatusDoc->getTransactionID() ,netc_TwainClientMan.getTransactionIndex( SocketFd ) );	// トランザクションIDをセット. 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴.
NetTwainDebugTrace((char*)" [_GetJobStatus]TransactionID= [%d]\n", s_DocJobStatus.pc_JobStatusDoc->getTransactionID(),0,0,0,0,0);
				// ドキュメントのJobSpecを取得する 
				// パラメータに基づいてチケットの編集をおこなう 
				APIC_Doc* pc_Doc  = APIC_Doc::newInstance();
				// 監査ログ対応 
				pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );								// ログ用IF No 登録.

				pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );
				if(netc_TwainClientMan.getDocumentID( SocketFd ) == NULL){
					errorLog_TwainService("getDocumentID NULL!!!\n",0,0,0,0,0,0);
					return;
				}
				int32_t sl_DocID[10];
				memset( &sl_DocID[0], 0, sizeof(int32_t)*10 );
				memcpy( &sl_DocID[0], netc_TwainClientMan.getDocumentID( SocketFd ), sizeof(int32_t)*10 );
				pc_Doc->setDocId( sl_DocID[0] );	// インスタンスに Doc ID を登録(保持)する 
				int clientindex = netc_TwainClientMan.getClientIndex( SocketFd );
// ▼ START ▼ 2013/01/29 S12-r_mori CQ377544 (mul)【UV-00877】PC-FAX送信3回線とFAX受信1回線、HDDTwainの5次元を繰り返し行うとE301が発生する.
				if ( (0 <= clientindex) && (clientindex < SUPPORTED_CLIENT_NUM) ) {
					Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
					APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
					Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
					APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
					(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
					int32_t ret = pc_Doc->req_GetJobSpec(	pc_UserGet, netc_TwainClientMan.getLoginedBoxPassword( SocketFd ), netc_TwainClientMan.getJobSpec( SocketFd ), ans_PrintDocTbl[clientindex], pc_TrackGet );
					if ( ret != APID_DocapiMethodOk ) {
NetTwainDebugTrace((char*)"### _GetJobStatus_ERR_PARAMETER_ERROR  APID_DocapiMethodOk != req_GetJobSpec() ###\n",0,0,0,0,0,0);
						isRsp = True;
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
						strcpy( pc_ReqData, "\x1b*s34520r0V" );	// 設定失敗 
					}
				}else{
NetTwainDebugTrace((char*)"### _GetJobStatus  clientindex invalid [%d] ###\n",clientindex,0,0,0,0,0);
				}
// ▲  END  ▲ 2013/01/29 S12-r_mori CQ377544 (mul)【UV-00877】PC-FAX送信3回線とFAX受信1回線、HDDTwainの5次元を繰り返し行うとE301が発生する.
				pc_Doc->deleteInstance();
			}
		// ↓片/両/混在 対応
		// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
		} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2 ) { 	// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
		// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			if ( (s_DocJobStatus.pc_JobStatusDoc == NULL) || (s_DocJobStatus.ret == -1) ) {		// 取得失敗 
NetTwainDebugTrace((char*)"### _GetJobStatus_ERR_PARAMETER_ERROR ###\n",0,0,0,0,0,0);
				isRsp = True;
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				strcpy( pc_ReqData, "\x1b*s311tN" );	// 設定失敗.
				// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			} else {
				// ドキュメントのJobStatusから原稿枚数を取得し保持する。
				netc_TwainClientMan.setNumOfOriginals( SocketFd, s_DocJobStatus.pc_JobStatusDoc->getNumOfOriginals() );	// 原稿枚数を取得する 
NetTwainDebugTrace((char*)" [_GetJobStatus]setNumOfOriginals= [%d]\n", s_DocJobStatus.pc_JobStatusDoc->getNumOfOriginals(),0,0,0,0,0);

				// DocIDからCompositedDocインスタンスのアドレスを取得する 
NetTwainDebugTrace((char*)"### req_getInstance ###\n", 0,0,0,0,0,0);
				if(netc_TwainClientMan.getDocumentID( SocketFd ) == NULL){
					errorLog_TwainService("getDocumentID NULL!!!\n",0,0,0,0,0,0);
					return;
				}
				int clientindex = netc_TwainClientMan.getClientIndex( SocketFd );
// ▼ START ▼ 2013/01/29 S12-r_mori CQ377544 (mul)【UV-00877】PC-FAX送信3回線とFAX受信1回線、HDDTwainの5次元を繰り返し行うとE301が発生する.
				if ( (0 <= clientindex) && (clientindex < SUPPORTED_CLIENT_NUM) ) {
					int32_t sl_DocID[10];
					memset( &sl_DocID[0], 0, sizeof(int32_t)*10 );
					memcpy( &sl_DocID[0], netc_TwainClientMan.getDocumentID( SocketFd ), sizeof(int32_t)*10 );
					// 2012/11/15 amiya CQ375074 【市場問題(FQ-ISDP-1200313)】PSBOでBOXにアクセスするとジョブの自動削除機能が動作しない.
					// req_getInstance()の第7引数をFalseにすると、最終アクセス時刻を変更しなくなる.
					// 第4-6引数は、デフォルト引数と同じ値をセットする.
					int32_t result = DOCC_CompositeDoc::req_getInstance( sl_DocID[0], netc_TwainClientMan.getLoginedBoxNo( SocketFd ), ans_GetDocInstanceTbl[clientindex], NULL, False, 0, False );
					if ( !( result == DOCD_RetRamExist || result == DOCD_RetFileExist ) ) {
NetTwainDebugTrace((char*)"### _GetJobStatus_ERR_PARAMETER_ERROR  (DOCD_RetRamExist || DOCD_RetFileExist) != DOCC_CompositeDoc::req_getInstance() ###\n",0,0,0,0,0,0);
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
						// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
						strcpy( pc_ReqData, "\x1b*s311tN" );	// 設定失敗.
						// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
NetTwainDebugTrace((char*)"### req_getInstance NG. ###\n", 0,0,0,0,0,0);
					}
				}else{
NetTwainDebugTrace((char*)"### _GetJobStatus  clientindex invalid [%d] ###\n",clientindex,0,0,0,0,0);
					return;
				}
// ▲  END  ▲ 2013/01/29 S12-r_mori CQ377544 (mul)【UV-00877】PC-FAX送信3回線とFAX受信1回線、HDDTwainの5次元を繰り返し行うとE301が発生する.
			}
		// ↑片/両/混在 対応
				// 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴 START.
		} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4 || 
					netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5 ||
					netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6		//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata.


					){ 	// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_4である CQNo327801 2010/05/24 okabe 変更.
NetTwainDebugTrace((char*)"### req_GetJobStatus Call!!! %d times ###\n",(int)netc_TwainClientMan.getTransactionIndex( SocketFd ) + 1,0,0,0,0,0);
			if( (s_DocJobStatus.pc_JobStatusDoc == NULL) || (s_DocJobStatus.ret == -1) ) {			// 取得失敗.
NetTwainDebugTrace((char*)"### _GetJobStatus_ERR_PARAMETER_ERROR ###\n",0,0,0,0,0,0);
				isRsp = True;
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
				strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗 
			} else {
				netc_TwainClientMan.setTransactionID( SocketFd, s_DocJobStatus.pc_JobStatusDoc->getTransactionID() , netc_TwainClientMan.getTransactionIndex( SocketFd ) );	// トランザクションIDをセット.

				int si_index = netc_TwainClientMan.getClientIndex( SocketFd );
				APIC_Doc* pc_Doc  = APIC_Doc::newInstance();
				pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );							// ログ用IF No 登録.
				pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );
				int32_t sl_DocID[NETD_MAX_BIND_LENGTH];
				memset( &sl_DocID[0], 0, sizeof(int32_t)*NETD_MAX_BIND_LENGTH );
				memcpy( &sl_DocID[0], netc_TwainClientMan.getDocumentID( SocketFd ), sizeof(int32_t)*NETD_MAX_BIND_LENGTH );
NetTwainDebugTrace((char*)"### Get TransactionID = [%d] / DocID = [%d] ###\n", s_DocJobStatus.pc_JobStatusDoc->getTransactionID(), sl_DocID[ netc_TwainClientMan.getTransactionIndex( SocketFd )],0,0,0,0);
				netc_TwainClientMan.setTransactionIndex( SocketFd , (short)(netc_TwainClientMan.getTransactionIndex( SocketFd ) + 1) );		// インデックスをインクリメント.
				pc_Doc->setDocId( sl_DocID[ netc_TwainClientMan.getTransactionIndex( SocketFd ) ] );

				// ドキュメントIDがまだ残っているかつインデックスが10以下である.
				if( ( sl_DocID[ netc_TwainClientMan.getTransactionIndex( SocketFd ) ] != 0 ) && ( netc_TwainClientMan.getTransactionIndex( SocketFd ) < NETD_MAX_BIND_LENGTH ) ){
NetTwainDebugTrace((char*)"### sl_DocID= [%d]  / index = [%d] ###\n",(int)sl_DocID[netc_TwainClientMan.getTransactionIndex( SocketFd )],netc_TwainClientMan.getTransactionIndex( SocketFd ),0,0,0,0);
					int32_t sl_ret = pc_Doc->req_GetJobStatus( netc_TwainClientMan.getJobStatusDoc( SocketFd ) , ans_GetJobStatusTbl[si_index] );
					pc_Doc->deleteInstance();
					if( sl_ret != APID_DocapiMethodOk ){
NetTwainDebugTrace((char*)"### req_GetJobStatus Error!!! return = [%d] ###\n",(int)sl_ret,0,0,0,0,0);
						isRsp = True;
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
						strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					}
				} else {
					pc_Doc->setDocId( sl_DocID[0] );										// ドキュメントIDをセットし直す.
					Bool bl_UserLogined = False;
					APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
					Bool bl_TrackLogined = False;
					APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
					(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
					int32_t sl_ret = pc_Doc->req_GetJobSpec( pc_UserGet, netc_TwainClientMan.getLoginedBoxPassword( SocketFd ), netc_TwainClientMan.getJobSpec( SocketFd ), ans_GetImageTbl[si_index], pc_TrackGet );
					if( sl_ret != APID_DocapiMethodOk ) {
NetTwainDebugTrace((char*)"### _GetJobStatus_ERR_PARAMETER_ERROR  APID_DocapiMethodOk != [%d] ###\n",(int)sl_ret,0,0,0,0,0);
						isRsp = True;
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
						strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					}
					pc_Doc->deleteInstance();
				}
			}
		// ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応 2013/03/07 OPS1八代 START.
		} else if ( ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_DELETE_DOC )  	// WDATコマンドがSCL_DELETE_DOCである.
				 ||	( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_DELETE_DOC2 ) ) 	// WDATコマンドがSCL_DELETE_DOC2である.
		{
		// ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応 2013/03/07 OPS1八代 END.
			if( (s_DocJobStatus.pc_JobStatusDoc == NULL) || (s_DocJobStatus.ret == -1) ) {		// 取得失敗.
NetTwainDebugTrace((char*)"### _GetJobStatus_ERR_PARAMETER_ERROR ###\n",0,0,0,0,0,0);
				isRsp = True;
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
				strcpy( pc_ReqData, "\x1b*s21107r0V" );	// 設定失敗 
			} else {
				netc_TwainClientMan.setTransactionID( SocketFd, s_DocJobStatus.pc_JobStatusDoc->getTransactionID() , netc_TwainClientMan.getTransactionIndex( SocketFd ));	// トランザクションIDをセット.
NetTwainDebugTrace((char*)"###_GetJobStatus TransactionID= [%d]###\n", s_DocJobStatus.pc_JobStatusDoc->getTransactionID(),0,0,0,0,0);
				// ドキュメントのJobSpecを取得する.
				APIC_Box* pc_Box = APIC_Box::newInstance();
				pc_Box->setLogIFNo( JLGE_InspectLogIfTCPSocket );								// ログ用IF No 登録.
				pc_Box->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );

				int si_index = netc_TwainClientMan.getClientIndex( SocketFd );
// ▼ START ▼ 2013/01/29 S12-r_mori CQ377544 (mul)【UV-00877】PC-FAX送信3回線とFAX受信1回線、HDDTwainの5次元を繰り返し行うとE301が発生する.
				if ( (0 <= si_index) && (si_index < SUPPORTED_CLIENT_NUM) ) {
					Bool bl_UserLogined = False;
					APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
					Bool bl_TrackLogined = False;
					APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
					(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
					int32_t sl_ret = pc_Box->req_deleteDoc( pc_UserGet,												// 既存ユーザー.
														 netc_TwainClientMan.getLoginedBoxPassword( SocketFd ),		// 既存パスワード.
														 netc_TwainClientMan.getDeleteDocumentID( SocketFd ),		// 削除対象DocID.
														 ans_DeleteDocTable[si_index],								// コールバックアドレス.
														 APID_DefaultWatchDocID,									// 削除対象WatchDocID.
														 pc_TrackGet );												// 部門管理情報.
					if( sl_ret != APID_DocapiMethodOk ) {
NetTwainDebugTrace((char*)"### _GetJobStatus_ERR_PARAMETER_ERROR  APID_DocapiMethodOk != [%d] ###\n",(int)sl_ret,0,0,0,0,0);
						isRsp = True;
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
						strcpy( pc_ReqData, "\x1b*s21107r0V" );	// 設定失敗.
					}
				}else{
NetTwainDebugTrace((char*)"### _GetJobStatus  clientindex invalid [%d] ###\n",si_index,0,0,0,0,0);
					pc_Box->deleteInstance();	// MinervaBK2nd CQ379634(静的解析) ID12657 2013.05.28 OPS1八代.
					return;
				}
// ▲  END  ▲ 2013/01/29 S12-r_mori CQ377544 (mul)【UV-00877】PC-FAX送信3回線とFAX受信1回線、HDDTwainの5次元を繰り返し行うとE301が発生する.
				pc_Box->deleteInstance();
			}
		// 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴 END.
		} else {
			return;
		}
		if ( isRsp == True ) {
			char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
			if( pc_RspData == NULL ){
				errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
				return;
			}
			memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
			netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
			if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// RREQを受けている 
				// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				if ( (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_PRINT_DOC) 					// WDATコマンドがSCL_PRINT_DOCである.
				  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2)			// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
				  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4)		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_4である.	// 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴 追加.
				  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5)		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_5である.
				  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6)		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_6である.	//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata.
				// ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応 2013/03/07 OPS1八代 START.
				  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_DELETE_DOC) 					// WDATコマンドがSCL_DELETE_DOCである.				// 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴 追加.
				  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_DELETE_DOC2) ) 				// WDATコマンドがSCL_DELETE_DOC2である.
				// ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応 2013/03/07 OPS1八代 END.
				{
				// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
					netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				} else {
					free( pc_RspData );
				}
			}

			netc_TwainClientMan.setHddAccessEndWait( SocketFd );

		}
	}
}

//==================================================================================================
//[機能]コールバック関数からコールされる関数 
//[履歴]2004.12.25 Matsumoto 
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_startPrintDoc( int id, APIC_Job* pc_Job )
{
NetTwainDebugTrace((char*)"#### ans_startPrintDoc() START! ####\n",0,0,0,0,0,0);
	netc_TwainClientMan.semLock();			// クライアントテーブルを参照・変更するためセマフォをロックする 
	int SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_PRINT_DOC ) {
		char pc_ReqData[32];
		if ( pc_Job != NULL ) {		// ジョブ起動成功 
			// 一時保管した設定パラメータを取得する 
			// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			char cmdTemp[18] = {0,};
			// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			if(netc_TwainClientMan.getSetCmdParam( SocketFd ) == NULL){
				errorLog_TwainService("getSetCmdParam NULL!!!\n",0,0,0,0,0,0);
				netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
				return;
			}
			memcpy( cmdTemp, netc_TwainClientMan.getSetCmdParam( SocketFd ), sizeof(cmdTemp) );
			char sc_errInfo = netc_TwainClientMan.getPrintDocError( SocketFd );
			Bool isSaveError = False;
			if ( sc_errInfo >= 10 ) {
				isSaveError = True;
				sc_errInfo = (char)(sc_errInfo - 10);
			}
			if ( cmdTemp[16] == 0x01 ) {					// 通常印刷のみの場合 
NetTwainDebugTrace((char*)"### For normal printing only ###\n",0,0,0,0,0,0);
				if ( sc_errInfo == 1 ) {						// Device error 1 
NetTwainDebugTrace((char*)"### ans_startPrintDoc_ERR_DEVICE_ERROR1 ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);		// Error Client Error Info 	
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s34520r0V" );			// 失敗応答 
				} else if (sc_errInfo == 2 ) { 					// Job Registration Error 
NetTwainDebugTrace((char*)"### ans_startPrintDoc_ERR_SCAN_JOB_REGIST_ERROR ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 	
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s34520r0V" );			// 失敗応答 
				} else if (sc_errInfo == 3 ) { 					// Limit of Print Count 
NetTwainDebugTrace((char*)"### ans_startPrintDoc_ERR_LIMIT_OF_PRINT_COUNT ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_LIMIT_OF_PRINT_COUNT , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s34520r0V" );		// 失敗応答 
				} else {
					strcpy( pc_ReqData, "\x1b*s34520r1V" );		// 成功応答 
				}
			}
			if ( cmdTemp[16] == 0x05 ) {					// チケット保存 + 通常印刷のみの場合 
NetTwainDebugTrace((char*)"### For normal printing only and save tickets ###\n",0,0,0,0,0,0);
				if ( sc_errInfo == 1 ) {						// Device error 1 
NetTwainDebugTrace((char*)"### ans_startPrintDoc_ERR_DEVICE_ERROR1 ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);		// Error Client Error Info 	
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s34520r0V" );			// 失敗応答 
				} else if (sc_errInfo == 2 ) { 					// Job Registration Error 
NetTwainDebugTrace((char*)"### ans_startPrintDoc_ERR_SCAN_JOB_REGIST_ERROR ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 	
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s34520r0V" );			// 失敗応答 
				} else if (sc_errInfo == 3 ) { 					// Limit of Print Count 
NetTwainDebugTrace((char*)"### ans_startPrintDoc_ERR_LIMIT_OF_PRINT_COUNT ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_LIMIT_OF_PRINT_COUNT , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s34520r0V" );		// 失敗応答 
				} else if ( isSaveError == True ) { 			// 正常終了以外 
NetTwainDebugTrace((char*)"### ans_startPrintDoc_ERR_PARAMETER_ERROR ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s34520r0V" );		// 失敗応答 
				} else {
					strcpy( pc_ReqData, "\x1b*s34520r1V" );		// 成功応答 
				}
			}
		} else {					// ジョブ起動失敗 
NetTwainDebugTrace((char*)"### ans_startPrintDoc_ERR_SCAN_JOB_REGIST_ERROR ###\n",0,0,0,0,0,0);
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
			strcpy( pc_ReqData, "\x1b*s34520r0V" );		// 失敗応答 
		}
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// RREQを受けている 
			netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
	netc_TwainClientMan.semUnLock();		// クライアント管理情報のセマフォをアンロックする 
}

