void ans_RestoreImage( int id, void* ptr, int32_t result )
{
NetTwainDebugTrace((char*)"#### ans_RestoreImage() START! ####\n",0,0,0,0,0,0);
	netc_TwainClientMan.semLock();		// クライアントテーブルを参照・変更するためセマフォをロックする 
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_CompositeDocImage* pc_CompositeDocImage = (NETS_CompositeDocImage*)malloc( sizeof(NETS_CompositeDocImage) );
	if( pc_CompositeDocImage == NULL ){
		errorLog_TwainService("pc_CompositeDocImage_malloc Error\n",0,0,0,0,0,0);
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
		return;
	}
	pc_CompositeDocImage->index = id;
	pc_CompositeDocImage->ptr = ptr;
	pc_CompositeDocImage->result = result;
	// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
	if ( netc_TwainClientMan.getCommandID( si_SocketFd ) == SCL_GET_TICKET_SETTING_2 ) { 		// WDATコマンドがSCL_GET_TICKET_SETTING_2の場合.
NetTwainDebugTrace((char*)"### CommandID() == SCL_GET_TICKET_SETTING_2 ###\n",0,0,0,0,0,0);
	// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
		netc_TwainService->setPacketData( NETE_TWAIN_DOC_IMAGE_INFO2,
										  netc_TwainClientMan.getClientIndex( si_SocketFd ),
										  NULL,
										  0,
										  netc_TwainClientMan.getAppID( si_SocketFd ),
										  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
										  NULL,
										  (void*)pc_CompositeDocImage );
		netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
	} else if ( netc_TwainClientMan.getCommandID( si_SocketFd ) == SCL_GET_DOC_INFO_4 ) {
		netc_TwainService->setPacketData( NETE_TWAIN_DOC_IMAGE_INFO4,
										  netc_TwainClientMan.getClientIndex( si_SocketFd ),
										  NULL,
										  0,
										  netc_TwainClientMan.getAppID( si_SocketFd ),
										  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
										  NULL,
										  (void*)pc_CompositeDocImage );
		netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
	} else if ( netc_TwainClientMan.getCommandID( si_SocketFd ) == SCL_GET_DOC_INFO_5 ) {		// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
		netc_TwainService->setPacketData( NETE_TWAIN_DOC_IMAGE_INFO5,							// messageloopに回して_GetDocImageInfoProc5()へ回す.
										  netc_TwainClientMan.getClientIndex( si_SocketFd ),
										  NULL,
										  0,
										  netc_TwainClientMan.getAppID( si_SocketFd ),
										  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
										  NULL,
										  (void*)pc_CompositeDocImage );
		netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
	} else if ( netc_TwainClientMan.getCommandID( si_SocketFd ) == SCL_GET_DOC_INFO_6 ) {		// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
		netc_TwainService->setPacketData( NETE_TWAIN_DOC_IMAGE_INFO6,							// messageloopに回して_GetDocImageInfoProc5()へ回す.
										  netc_TwainClientMan.getClientIndex( si_SocketFd ),
										  NULL,
										  0,
										  netc_TwainClientMan.getAppID( si_SocketFd ),
										  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
										  NULL,
										  (void*)pc_CompositeDocImage );
		netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
	} else {
		// 2011/02/14 Coverity対応 どのケースにも該当しない場合、領域を解放する.
		free( pc_CompositeDocImage );
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
	}
}

