//[機能]DOCC_CompositeDoc取得時の処理関数 
//[履歴]2004.08.17 Matsumoto
//==================================================================================================
void _GetDocCompositeProc( NETS_CompositeDoc* pc_CompositeDocMsg )
{
NetTwainDebugTrace((char*)"#### _GetDocCompositeProc() START! ####\n",0,0,0,0,0,0);
	NETS_CompositeDoc s_CompositeDoc;
	memcpy( &s_CompositeDoc, pc_CompositeDocMsg, sizeof(NETS_CompositeDoc) );
	free( pc_CompositeDocMsg );
	NetTwainDebugTrace((char*)"### DocPtr = [%p] ###\n", reinterpret_cast<intptr_t>(s_CompositeDoc.pc_CompositeDoc),0,0,0,0,0);		
	Bool isError = False;
	int SocketFd = netc_TwainClientMan.getSocketFd( s_CompositeDoc.index );
	APIC_DocListTbl *pc_DocListTbl = netc_TwainClientMan.getDocListTbl( SocketFd );
	APIC_DocListInfo* pc_DocListInfo = netc_TwainClientMan.getDocListInfoList( SocketFd );
	if(pc_DocListInfo == NULL){
		errorLog_TwainService("pc_DocListInfo NULL!!!\n",0,0,0,0,0,0);
		return;
	}

	if ( s_CompositeDoc.pc_CompositeDoc == NULL){
		isError = True;
	} else if (s_CompositeDoc.pc_CompositeDoc->getDocPageIns() == NULL){
		errorLog_TwainService("s_CompositeDoc.pc_CompositeDoc->getDocPageIns() NULL!!!\n",0,0,0,0,0,0);
		return;
	} else if ( s_CompositeDoc.pc_CompositeDoc->getDocPageIns()->getFirstLeaf() == DOCD_RetNull ) {
		isError = True;
	} else if ( s_CompositeDoc.pc_CompositeDoc->getDocPageIns()->getFirstLeaf()->getImage() == DOCD_NULL ) {
		isError = True;
	}
	if ( isError == True ) {
		// NULLチェック(NULLが来た場合は機能を満足しない) 
NetTwainDebugTrace((char*)"# _GetDocCompositeProc_ERR_PARAMETER_ERROR1 #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
		char pc_ReqData[32];
		// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
		if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_DOC_INFO_4 ) {			// WDATコマンドがSCL_GET_DOC_INFO_4である.
			strcpy( pc_ReqData, "\x1b*s277tN" );	// 設定失敗.
		} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_DOC_INFO_5 ) {			// WDATコマンドがSCL_GET_DOC_INFO_5である.
			strcpy( pc_ReqData, "\x1b*s281tN" );	// 設定失敗.																			// 2010/3/8 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
		}else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_DOC_INFO_6 ) {			// WDATコマンドがSCL_GET_DOC_INFO_5である.
			strcpy( pc_ReqData, "\x1b*s283tN" );	// 設定失敗.																			// 2010/3/8 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
		} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2 ) {	// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
			strcpy( pc_ReqData, "\x1b*s311tN" );	// 設定失敗.
		}
		// << 2008.02.21 Tana [Donau] No.561 コピー時のWatermark対応.
		// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		pc_DocListInfo->pList->Lock();
		pc_DocListTbl = pc_DocListInfo->pList->findFirst();
		while (pc_DocListTbl != NULL) {
			pc_DocListInfo->pList->del(pc_DocListTbl);
			free( pc_DocListTbl );
			pc_DocListTbl = pc_DocListInfo->pList->findFirst();
		}
		pc_DocListInfo->pList->UnLock();
		netc_TwainClientMan.setDocListTbl( SocketFd, pc_DocListTbl );
		netc_TwainClientMan.setDocumentCreateCnt( SocketFd, 0 );
		DocListCreateSocketFd = 0;				// DocumentList作成中のクライアントのSocketFd 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// RREQを受けている 
			// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			// >> 2008.02.21 Tana [Donau] No.561 コピー時のWatermark対応.
			if ( (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_DOC_INFO_4)			// WDATコマンドがSCL_GET_DOC_INFO_4である.
			  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_DOC_INFO_5)			// WDATコマンドがSCL_GET_DOC_INFO_5である.	// 2010/3/8 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
			  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2) )	// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
			{
			// << 2008.02.21 Tana [Donau] No.561 コピー時のWatermark対応.
			// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
			} else {
				free( pc_RspData );
			}
		}

		netc_TwainClientMan.setHddAccessEndWait( SocketFd );

	} else {
		int32_t result = s_CompositeDoc.pc_CompositeDoc->getDocPageIns()->getFirstLeaf()->getImage()->req_restoreImage( IMGD_InfoRestoreReq, 0, NULL, ans_RestoreImageTbl[s_CompositeDoc.index], s_CompositeDoc.pc_CompositeDoc );
		if ( result != IMGD_ImgOk ) {		// エラーの場合 
NetTwainDebugTrace((char*)"# _GetDocCompositeProc_ERR_PARAMETER_ERROR2 #\n", 0,0,0,0,0,0);
			int SocketFd = netc_TwainClientMan.getSocketFd( s_CompositeDoc.index );
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
			char pc_ReqData[32];
			// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_DOC_INFO_4 ) {			// WDATコマンドがSCL_GET_DOC_INFO_4である.
				strcpy( pc_ReqData, "\x1b*s277tN" );	// 設定失敗.
			} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2 ) {	// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
				strcpy( pc_ReqData, "\x1b*s311tN" );	// 設定失敗.
			}
			// << 2008.02.21 Tana [Donau] No.561 コピー時のWatermark対応.
			// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
			if( pc_RspData == NULL ){
				errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
				return;
			}
			memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
			netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
			pc_DocListInfo->pList->Lock();
			pc_DocListTbl = pc_DocListInfo->pList->findFirst();
			while (pc_DocListTbl != NULL) {
				pc_DocListInfo->pList->del(pc_DocListTbl);
				free( pc_DocListTbl );
				pc_DocListTbl = pc_DocListInfo->pList->findFirst();
			}
			pc_DocListInfo->pList->UnLock();
			netc_TwainClientMan.setDocListTbl( SocketFd, pc_DocListTbl );
			netc_TwainClientMan.setDocumentCreateCnt( SocketFd, 0 );
			DocListCreateSocketFd = 0;				// DocumentList作成中のクライアントのSocketFd 
			if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// RREQを受けている 
				// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				// >> 2008.02.21 Tana [Donau] No.561 コピー時のWatermark対応.
				if ( (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_DOC_INFO_4)			// WDATコマンドがSCL_GET_DOC_INFO_4である.
				  || (netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2) )	// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
				{
				// << 2008.02.21 Tana [Donau] No.561 コピー時のWatermark対応.
				// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
					netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				} else {
					free( pc_RspData );
				}
			}

			netc_TwainClientMan.setHddAccessEndWait( SocketFd );

		}
	}
}

//==================================================================================================
//[機能]DocumentImage情報取得時の処理関数（Ticket Setting用) 
//[履歴]2005.02.15 Iesato
//==================================================================================================
void _GetDocImageInfo2Proc( NETS_CompositeDocImage* pc_CompositeDocImage )
{
NetTwainDebugTrace((char*)"#### _GetDocImageInfo2Proc() START! ####\n",0,0,0,0,0,0);
	NETS_CompositeDocImage s_CompositeDocImage;
	memcpy( &s_CompositeDocImage, pc_CompositeDocImage, sizeof(NETS_CompositeDocImage) );
	free( pc_CompositeDocImage );
	Bool isError = False;
	char pc_ReqData[32];
	int SocketFd = netc_TwainClientMan.getSocketFd( s_CompositeDocImage.index );
	DOCC_CompositeDoc* DocPtr = (DOCC_CompositeDoc*)s_CompositeDocImage.ptr;
	if ( s_CompositeDocImage.result == IMGD_ImgOk ) {		// 取得OKの場合 
		// プリント面指定は、プリント時の印刷種類の設定によってきまる。
		// プリント時にページ単位設定をしても、面指定の片面/両面が混ざることはないので 
		// 全ページ分チェックせずに、先頭ページのみチェックする 
		DOCC_Leaf* pc_Leaf = NULL;
		if(DocPtr->getDocPageIns() == NULL){
			errorLog_TwainService("DocPtr->getDocPageIns() NULL!!!\n",0,0,0,0,0,0);
			return;
		}
		pc_Leaf = DocPtr->getDocPageIns()->getLeafAt( 1 );						// 1ページ目のLeafのアドレスを取得する 
		if(pc_Leaf == NULL){
			errorLog_TwainService("pc_Leaf NULL!!!\n",0,0,0,0,0,0);
			return;
		}
		DOCE_PrintFaceIndi	ec_PrintFaceIndi = pc_Leaf->getPrintFaceIndi();		// Leaf情報からプリント面指定を取得する 
		if ( ec_PrintFaceIndi == DOCE_PrintFaceIndi_Single ){					// 片面の場合  
			netc_TwainClientMan.setPrintFaceIndi_Single( SocketFd, True );						// 面指定情報(True:片面）を保持する 
NetTwainDebugTrace((char*)"PrintFaceIndi_Single = True\n", 0,0,0,0,0,0);
		} else {
			netc_TwainClientMan.setPrintFaceIndi_Single( SocketFd, False );					// 面指定情報(False:両面）を保持する 
NetTwainDebugTrace((char*)"PrintFaceIndi_Single = False\n", 0,0,0,0,0,0);
		}
		DocPtr->deleteInstance();
		// ジョブスペックを取得するメソッドをコールする 
		APIC_Doc* pc_Doc = NULL;
		pc_Doc = APIC_Doc::newInstance();
		// 監査ログ対応 
		pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );								// ログ用IF No 登録.

		pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );
		int32_t sl_DocID[10];
		memset( &sl_DocID[0], 0, sizeof(int32_t)*10 );
		if(netc_TwainClientMan.getDocumentID( SocketFd ) == NULL){
			errorLog_TwainService("getDocumentID NULL!!!\n",0,0,0,0,0,0);
			return;
		}
		memcpy( &sl_DocID[0], netc_TwainClientMan.getDocumentID( SocketFd ), sizeof(int32_t)*10 );
		pc_Doc->setDocId( sl_DocID[0] );
		Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
		APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
		Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
		APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
		(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
NetTwainDebugTrace((char*)"### req_GetJobSpec ###\n", 0,0,0,0,0,0);
		int index = netc_TwainClientMan.getClientIndex( SocketFd );
// ▼ START ▼ 2013/01/29 S12-r_mori CQ377544 (mul)【UV-00877】PC-FAX送信3回線とFAX受信1回線、HDDTwainの5次元を繰り返し行うとE301が発生する.
		if ( (0 <= index) && (index < SUPPORTED_CLIENT_NUM) ) {
			int32_t ret = pc_Doc->req_GetJobSpec( pc_UserGet, netc_TwainClientMan.getLoginedBoxPassword( SocketFd ), netc_TwainClientMan.getJobSpec( SocketFd ), ans_TicketSettingTbl[index], pc_TrackGet );
			if ( ret != APID_DocapiMethodOk ) {	// 不正取得 
				isError = True;
			}
		}else{
NetTwainDebugTrace((char*)"### _GetDocImageInfo2Proc  clientindex invalid [%d] ###\n",index,0,0,0,0,0);
		}
// ▲  END  ▲ 2013/01/29 S12-r_mori CQ377544 (mul)【UV-00877】PC-FAX送信3回線とFAX受信1回線、HDDTwainの5次元を繰り返し行うとE301が発生する.
		pc_Doc->deleteInstance();
	} else {												// 取得NGの場合 
		NetTwainDebugTrace((char*)"### DocPtr = [%p] ###\n", reinterpret_cast<intptr_t>(DocPtr),0,0,0,0,0);		
		DocPtr->deleteInstance();
		isError = True;
	}
	if ( isError == True ) {
NetTwainDebugTrace((char*)"### _GetDocImageInfo2Proc_ERR_PARAMETER_ERROR ###\n",0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
		// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
		strcpy( pc_ReqData, "\x1b*s311tN" );	// 設定失敗.
		// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// RREQを受けている 
			// >> 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
			if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_TICKET_SETTING_2 ) { 		// WDATコマンドがSCL_GET_TICKET_SETTING_2である.
			// << 2008.02.05 Harada Donau対応 No.14 Box出力変更モード機能拡張対応.
				netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
			} else {
				free( pc_RspData );
			}
		}
		netc_TwainClientMan.setHddAccessEndWait( SocketFd );
	}
}
// 2005.07.11 iesato 片/両/混在対応 

//==================================================================================================
//[機能]HDDからのドキュメント取得ジョブを実行する 
//[戻り値]Bool ジョブ開始完了 
//[履歴]2004.04.13 Matsumoto 
//      2006.07.06 Iesato ユニバーサルセンド対応で、ジョブ登録時のジョブタイプを
//                        TYPE_JobTypeScan から TYPE_JobTypeFaxSendMemory に変更
//==================================================================================================
Bool _HDDDocumentAcquire(
	signed int SocketFd
)
{
NetTwainDebugTrace((char*)"#### _HDDDocumentAcquire() START! ####\n",0,0,0,0,0,0);
	// ジョブの登録＆起動をかける 
	APIC_Job* pc_Job = NULL;
	pc_Job = APIC_Job::newInstance( TYPE_JobTypeFaxSendMemory );		// 引数はTYPE_JobTypeFaxSendMemory（ユニバーサルセンド対応)  
	if ( pc_Job != NULL ) {	// ジョブインスタンス取得成功 
		// 転送用パラメータの初期化 
		netc_TwainClientMan.setImageTransSendedSize( SocketFd, 0 );
		netc_TwainClientMan.setImageTransDataAllSize( SocketFd, 0 );
		netc_TwainClientMan.setImageTransBandDataSize( SocketFd, 0 );
		netc_TwainClientMan.setImageTransBandSendedSize( SocketFd , 0 );
		netc_TwainClientMan.setImageTransRotateAngle( SocketFd, TYPE_ImageAngle0 );
		netc_TwainClientMan.setPixelsPerScan( SocketFd, 0 );
		netc_TwainClientMan.setBytesPerScan( SocketFd, 0 );
		netc_TwainClientMan.setNumberOfScanLines( SocketFd, 0 );
		netc_TwainClientMan.setHDDPageDataSize( SocketFd, 0 );
		netc_TwainClientMan.setTotalPages( SocketFd, 0 );
		netc_TwainClientMan.setSendedPages( SocketFd, 0 );
		netc_TwainClientMan.setImageTransEmptyRDATSend( SocketFd, False );
		netc_TwainClientMan.setEndObserverNotified( SocketFd, False );		// 2008.06.23 Harada BugNo.305231.
		netc_TwainClientMan.setImageTransJobInstance( SocketFd, pc_Job );
		netc_TwainClientMan.setErrorInfo( SocketFd, ERR_NOT_EXIST_ERROR );
		APIC_Doc* pc_Doc = NULL;
		pc_Doc = APIC_Doc::newInstance();
		if ( pc_Doc != NULL ) {
			pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );								// ログ用IF No 登録.
			pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );
			int32_t sl_DocID[10];
			memset( &sl_DocID[0], 0, sizeof(int32_t)*10 );
			if(netc_TwainClientMan.getDocumentID( SocketFd ) == NULL){
				errorLog_TwainService("getDocumentID NULL!!!\n",0,0,0,0,0,0);
				return False;
			}
			memcpy( &sl_DocID[0], netc_TwainClientMan.getDocumentID( SocketFd ), sizeof(int32_t)*10 );
			pc_Doc->setDocId( sl_DocID[0] );

			// ドキュメントのJobSpecの取得をはじめる 
			int index = netc_TwainClientMan.getClientIndex( SocketFd );
			if ( index != -1 ) {
// 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴 START.
				if( isForceMemoryReceiveBoxJournal( SocketFd ) && ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4 ) ){	// 機能が有効かつコマンドがSCL_SET_HDD_TWAIN_PARAM_4 CQNo327801 2010/05/24 okabe 変更.
NetTwainDebugTrace((char*)"### ForceMemoryReceiveBox && SoftSw No77 0x04 ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setTransactionIndex( SocketFd, 0 );								// トランザクション管理インデックス初期化.
					netc_TwainClientMan.setTransactionID( SocketFd, 0 , -1);							// トランザクションID.
					APIC_User* pc_User = netc_TwainClientMan.getApic_User( SocketFd );					// ログインユーザーインスタンス取得.
					int32_t sl_UserNo = 0;	//2013/10/11 【スケーラブルFUM】[CQ383174] 20万人対応. 
					if ( pc_User != NULL ){
						pc_User->lock();
						sl_UserNo = pc_User->getUserNo();
						pc_User->unlock();
					}
					// ログインユーザーがパブリックかつ任意の文字列が設定されていない場合はエラー.
					if( netc_TwainClientMan.getForceMemoryName( SocketFd ) == NULL ){
						errorLog_TwainService("getForceMemoryName Error\n",0,0,0,0,0,0);
						return False;
					}
					if( sl_UserNo == TYPD_IndexUserPublic && *netc_TwainClientMan.getForceMemoryName( SocketFd ) == '\0' ){
NetTwainDebugTrace((char*)"### sl_UserNo == TYPD_IndexUserPublic && ForceMemoryName NULL!!! ###\n",0,0,0,0,0,0);									// パブリック指定時のユーザー名が設定されていない.
						return False;
					} else {
						int32_t sl_ret = pc_Doc->req_GetJobStatus( netc_TwainClientMan.getJobStatusDoc( SocketFd ) , ans_GetJobStatusTbl[index] );
						pc_Doc->deleteInstance();
						if( sl_ret != APID_DocapiMethodOk ){
NetTwainDebugTrace((char*)"###req_GetJobStatus Error!!! return = [%d] ###\n",(int)sl_ret,0,0,0,0,0);
							return False;
						}
					}
// 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴 END.
				} else {
					// 従来通りの処理へ.
					Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
					APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
					Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
					APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
					(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
					int32_t ret = pc_Doc->req_GetJobSpec( pc_UserGet, netc_TwainClientMan.getLoginedBoxPassword( SocketFd ), netc_TwainClientMan.getJobSpec( SocketFd ), ans_GetImageTbl[index], pc_TrackGet );
					pc_Doc->deleteInstance();
					if( ret != APID_DocapiMethodOk ){
						return False;
					}
				}
			} else {
				pc_Doc->deleteInstance();
			}
		}
	} else {
NetTwainDebugTrace((char*)"### ERROR APIC_Job::newInstance() ###\n",0,0,0,0,0,0);
		return False;
	}
	return True;
}

//==================================================================================================
//[機能]コールバック関数からコールされる関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2004.12.25 Matsumoto 
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_startGetImageJob( int id, APIC_Job* pc_Job )
{
NetTwainDebugTrace((char*)"#### ans_startGetImageJob() START! ####\n",0,0,0,0,0,0);
NetTwainDebugTrace((char*)"#### ans_startGetImageJob() index = [%d] ! ####\n",(int)id,0,0,0,0,0);
	netc_TwainClientMan.semLock();			// クライアントテーブルを参照・変更するためセマフォをロックする 
	int SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	short CmdID = netc_TwainClientMan.getCommandID( SocketFd );
	if ( CmdID == SCL_GET_PAGE_SIZE   			// WDATコマンドがSCL_GET_PAGE_SIZEである 
	  || CmdID == SCL_SET_HDD_TWAIN_PARAM_4		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_4である.
	  || CmdID == SCL_SET_HDD_TWAIN_PARAM_5		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_5である. 				// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
	  || CmdID == SCL_SET_HDD_TWAIN_PARAM_6		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_6である. 				//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata.
	  || CmdID == SCL_GET_SCAN_PAGE_DATA ) {	// WDATコマンドがSCL_GET_SCAN_PAGE_DATAである.
		char pc_ReqData[32];
// Amur_WBS No. 675 UV案件 対応 2008/07/16 平谷 str.
		memset(pc_ReqData, 0x0, sizeof( pc_ReqData ));
// Amur_WBS No. 675 UV案件 対応 2008/07/16 平谷 end.
		if ( pc_Job == NULL ) {		// ジョブ起動失敗 
NetTwainDebugTrace((char*)"### ans_startGetImageJob pc_Job is NULL ###\n", 0,0,0,0,0,0);
			Bool isRsp = True;
			switch ( CmdID ) {
				case SCL_GET_PAGE_SIZE:
NetTwainDebugTrace((char*)"### ans_startGetImageJob_ERR_SCAN_JOB_REGIST_ERROR  SCL_GET_PAGE_SIZE ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21006dN" );	// 設定失敗 
					break;
// 2008.09.26 hiratani Amur_WBS No. 8 261 675 UV案件 新規実装 str.
				case SCL_SET_HDD_TWAIN_PARAM_4:
NetTwainDebugTrace((char*)"### ans_startGetImageJob_ERR_SCAN_JOB_REGIST_ERROR  SCL_SET_HDD_TWAIN_PARAM_4 ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					break;
// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya START.
				case SCL_SET_HDD_TWAIN_PARAM_5:
NetTwainDebugTrace((char*)"### ans_startGetImageJob_ERR_SCAN_JOB_REGIST_ERROR  SCL_SET_HDD_TWAIN_PARAM_5 ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info. 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status. 
					strcpy( pc_ReqData, "\x1b*s21119r0V" );	// 設定失敗. 
					break;
// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya END. 
//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start.
				case SCL_SET_HDD_TWAIN_PARAM_6:
NetTwainDebugTrace((char*)"### ans_startGetImageJob_ERR_SCAN_JOB_REGIST_ERROR  SCL_SET_HDD_TWAIN_PARAM_6 ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info. 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status. 
					strcpy( pc_ReqData, "\x1b*s21121r0V" );	// 設定失敗. 
					break;
//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata End.
				case SCL_GET_SCAN_PAGE_DATA:
NetTwainDebugTrace((char*)"### ans_startGetImageJob_ERR_SCAN_JOB_REGIST_ERROR  SCL_GET_SCAN_PAGE_DATA ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
					netc_TwainClientMan.setEmptySend( SocketFd, True );								// 空パケット送信待ち状態を設定する.
					netc_TwainClientMan.setImageTransPreError( SocketFd, True );					// ImageTrans PreError.
					break;
// 2008.09.26 hiratani Amur_WBS No. 8 261 675 UV案件 新規実装 end.
				default:
NetTwainDebugTrace((char*)"### ans_startGetImageJob::isRsp = False  ###\n",0,0,0,0,0,0);
					isRsp = False;
					break;
			}
			if ( isRsp == True ) {
// 2008.09.26 hiratani Amur_WBS No. 8 261 675 UV案件 新規実装 str.
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );	// 送信データ保持領域に書き込む.
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {	// RREQを受けている.
					if ( CmdID == SCL_GET_PAGE_SIZE   			// WDATコマンドがSCL_GET_PAGE_SIZEである.
					  || CmdID == SCL_SET_HDD_TWAIN_PARAM_4		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_4である. 
					  || CmdID == SCL_SET_HDD_TWAIN_PARAM_5		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_5である. 			// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
					  || CmdID == SCL_SET_HDD_TWAIN_PARAM_6 ) {	// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_6である. 			//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata.
						netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
					} else if ( CmdID == SCL_GET_SCAN_PAGE_DATA ) {	// WDATコマンドがSCL_GET_SCAN_PAGE_DATAである.
						// 空パケット送信の為何もしない.
						// bl_EmptySend == True( 空パケット送信待ち状態 )、bl_ImageTransPreError == True( ImageTrans PreError)の状態.
NetTwainDebugTrace((char*)"### ans_startGetImageJob_Send empty packet ###\n",0,0,0,0,0,0);
					} else {
						free( pc_RspData );
					}
				}
// 2008.09.26 hiratani Amur_WBS No. 8 261 675 UV案件 新規実装 end.
			}
			
//>> 2009.04.09 hiratani@TCP CQ317037.
			// ジョブインスタンスを取得しジョブの削除処理を実行する 
			APIC_Job* pc_TransJobInstance = netc_TwainClientMan.getImageTransJobInstance( SocketFd );
			if( NULL != pc_TransJobInstance ) {
				pc_TransJobInstance->lock();
				pc_TransJobInstance->deleteInstance();
				pc_TransJobInstance->unlock();
			}
//<< 2009.04.09 hiratani@TCP CQ317037.
			
			// デタッチする 
			if ( netc_TwainClientMan.getImageObserver( SocketFd ) != NULL ) {
				APIC_NetScanIfaxTxImage* pc_NetScanIfaxTxImage = NULL;
				pc_NetScanIfaxTxImage = APIC_NetScanIfaxTxImage::newInstance();
				// >>デッドロック問題対応.
				netc_TwainClientMan.semUnLock();
				pc_NetScanIfaxTxImage->detachObserver( netc_TwainClientMan.getImageObserver( SocketFd ) );
				netc_TwainClientMan.semLock();
				// <<デッドロック問題対応.
				char temp[100];
				sprintf( temp, "pc_NetScanIfaxTxImage->detachObserver" );
				registNetTwainLog( temp );
				delete netc_TwainClientMan.getImageObserver( SocketFd );
				netc_TwainClientMan.setImageObserver( SocketFd, NULL );
			}
			
			//>> 2009.04.09 hiratani@TCP CQ317037.
			// 転送系の管理データをクリアする
			netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_NONE );	// ImageTrans ジョブ状態.
			netc_TwainClientMan.setImageTransJobInstance( SocketFd, NULL );					// ImageTrans ジョブインスタンス.
			netc_TwainClientMan.setImageTransSendedSize( SocketFd, 0 );						// ImageTrans 転送済み画像サイズ.
			netc_TwainClientMan.setImageTransDataAllSize( SocketFd, 0 );					// ImageTrans All Data Size.
			netc_TwainClientMan.setImageTransBandDataSize( SocketFd, 0 );					// ImageTrans Band Data Size.
			netc_TwainClientMan.setImageTransRotateAngle( SocketFd, TYPE_ImageAngle0 );		// ImageTrans バンド転送済み画像サイズ.
			netc_TwainClientMan.setHDDPageDataSize( SocketFd, 0 );							// HDD Twain ページデータサイズ.
			netc_TwainClientMan.setEndObserverNotified( SocketFd, False );					// Endオブザーバ通知済み状態.
			netc_TwainClientMan.setState_CancelSync( SocketFd, NETE_CANCELSYNC_NONE );		// キャンセル同期状態を初期化する.		// 2.1c CQ519136 OSP1八代 2015.10.23.
			//>> 2009.04.09 hiratani@TCP CQ317037.
		}
	}
	netc_TwainClientMan.semUnLock();		// クライアント管理情報のセマフォをアンロックする 
}

