NetTwainDebugTrace((char*)"### If there is matching ID ###\n",0,0,0,0,0,0);
							//	2011/02/14 Coverity対応 不要処理を削除 str
							// 2018/10/12 Kajitani Eagle [AR.1047714対応] Start.
							Bool b_Server = False;
							pc_UserAuthentication->lock();
							if ( TYPE_UserAuthenticationServer == pc_UserAuthentication->getUserAuthentication() )
							{
								b_Server = True;
							}
							pc_UserAuthentication->unlock();
							pc_User->lock();
							pc_User->getUserPassword( &checkPswd[0], b_Server );	// ユーザーパスワード情報を取得する 
							pc_User->unlock();
