//==================================================================================================
//[機能]req_start() のansの引数(ジョブポインタ)がNULLの場合にインスタンス削除処理関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2006.03.24 Iesato 
//==================================================================================================
void _JobDeleteInstance(
	int32_t* pl_Data	// クライアント管理インデックス番号 
)
{
NetTwainDebugTrace((char*)"### _JDeleteInstance() ###\n",0,0,0,0,0,0);
	if ( pl_Data != NULL )
	{
		int32_t sl_Index = *pl_Data;
		free( pl_Data );
		int SocketFd = netc_TwainClientMan.getSocketFd( (int)sl_Index );	// ソケットFDの取得(管理インデックスを指定して取得) 
NetTwainDebugTrace((char*)"SocketFd = [%d] ###\n", SocketFd,0,0,0,0,0);
		if ( SocketFd != -1 ){
			if ( netc_TwainClientMan.getImageTransJobInstance( SocketFd ) != NULL ) { // 保持しているインスタンスがNULLでない場合 
NetTwainDebugTrace((char*)"--- delete Instance start ---!!\n",0,0,0,0,0,0);
				netc_TwainClientMan.getImageTransJobInstance( SocketFd )->deleteInstance();		// インスタンス削除 
				netc_TwainClientMan.setImageTransJobInstance( SocketFd, NULL );					// // 保持しているインスタンスをクリアする 
				netc_TwainClientMan.setScanDataFlag( SocketFd, False );		// 画像転送中状態を解除する 
			}
		}
	}
}
//==================================================================================================
//[機能]コールバック関数からコールされる関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2004.12.25 Matsumoto 
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_startScanWindow( int id, APIC_Job* pc_Job )
{
NetTwainDebugTrace((char*)"### ans_startScanWindow() START! ###\n",0,0,0,0,0,0);
	netc_TwainClientMan.semLock();			// クライアントテーブルを参照・変更するためセマフォをロックする 
	int SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	// #54459対策 req_start() のansの引数(ジョブポインタ)がNULLの場合にインスタンス削除処理「_DeleteInstance()」を実行するために追加 
	if ( pc_Job == NULL ) {		// NULLの場合 
		NETC_TwainService* netc_TwainService = NULL;
		netc_TwainService = NETC_TwainService::newInstance();
		int32_t* pl_Data = (int32_t*)malloc(sizeof(int32_t));
		if( pl_Data == NULL ){
			errorLog_TwainService("pl_Data_malloc Error\n",0,0,0,0,0,0);
			netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
			return;
		}
		*pl_Data = (int32_t)id;
		netc_TwainService->setPacketData( NETE_TWAIN_JOB_DEL_INSTANCE,
										  netc_TwainClientMan.getClientIndex( SocketFd ),
										  NULL,
										  0,
										  netc_TwainClientMan.getAppID( SocketFd ),
										  netc_TwainClientMan.getTwainReceiverSlave( SocketFd ),
										  NULL,
										  (void*)pl_Data );
	}
	if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SCAN_WINDOW ) {
		char pc_ReqData[32];
		if ( pc_Job == NULL ) {		// ジョブ起動成功 
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
			strcpy( pc_ReqData, "\x1b*s20113r0V" );		// 失敗応答 
			char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
			if( pc_RspData == NULL ){
				errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
				netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
				return;
			}
			memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
			netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
			if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// RREQを受けている 
				netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
			}
			// デタッチする 
			if ( netc_TwainClientMan.getImageObserver( SocketFd ) != NULL ) {
				APIC_NetScanIfaxTxImage* pc_NetScanIfaxTxImage = NULL;
				pc_NetScanIfaxTxImage = APIC_NetScanIfaxTxImage::newInstance();
				// >>デッドロック問題対応.
				netc_TwainClientMan.semUnLock();
				pc_NetScanIfaxTxImage->detachObserver( netc_TwainClientMan.getImageObserver( SocketFd ) );
				netc_TwainClientMan.semLock();
				// <<デッドロック問題対応.
				char temp[100];
				sprintf( temp, "pc_NetScanIfaxTxImage->detachObserver" );
				registNetTwainLog( temp );
				delete netc_TwainClientMan.getImageObserver( SocketFd );
				netc_TwainClientMan.setImageObserver( SocketFd, NULL );
			}
		}
	}
	netc_TwainClientMan.setScanWindowStartFlag( SocketFd, False );	// #54459対策 Scanwindowコマンドでのreq_Start後のコールバック待ち状態を解除する 
	netc_TwainClientMan.semUnLock();		// クライアント管理情報のセマフォをアンロックする 
}

