//==================================================================================================.
//[機能] ジョブチケット取得→ジョブ実行.
//[履歴] 2010/12/21 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証.
//==================================================================================================.
void _setJobTicketProc( NETS_KeyDeviceLogin* ps_KeyDeviceLogin )
{
NetTwainDebugTrace((char*)"#### _setJobTicketProc() start! ####\n",0,0,0,0,0,0);
	netc_TwainClientMan.semLock();			// クライアントテーブルを参照・変更するためセマフォをロックする.
	
	// 認証結果保持→開放.
	NETS_KeyDeviceLogin s_KeyDeviceLogin;
	memcpy( &s_KeyDeviceLogin, ps_KeyDeviceLogin, sizeof( NETS_KeyDeviceLogin ) );
	free( ps_KeyDeviceLogin );
	
	int SocketFd = netc_TwainClientMan.getSocketFd( s_KeyDeviceLogin.index );	// SocketFd取得.
	
	// ジョブチケット発行結果で分岐.
	APIC_Job* pc_Job = NULL;
	switch( s_KeyDeviceLogin.e_Result ) {
		case TYPE_UserResultAdminMachineKM_OK:					// 認証成功.
NetTwainDebugTrace((char*)"#### _setJobTicketProc() Authentication Success! ####\n",0,0,0,0,0,0);
			pc_Job = netc_TwainClientMan.getJobInstanceforJobTicket( SocketFd );								// ジョブチケット取得用に退避したジョブポインタの取得.
			pc_Job->getJobSpec()->pc_Common->c_UserAcount.setCardID( s_KeyDeviceLogin.sl_AuthLabel );			// 認証ラベルをセット.
			pc_Job->setJobSpec();																				// ジョブスペック確定.

			// WDATコマンドで分岐.
			switch ( netc_TwainClientMan.getCommandID( SocketFd ) ) {
				case SCL_PRINT_DOC:
NetTwainDebugTrace((char*)"### _setJobTicketProc() Auth_OK! ans_startPrintDocTbl call! ###\n",0,0,0,0,0,0);
					pc_Job->req_start( ans_startPrintDocTbl[ s_KeyDeviceLogin.index ] );					// ジョブ実行.
					break;
				case SCL_SCAN_WINDOW:
NetTwainDebugTrace((char*)"### _setJobTicketProc() Auth_OK! ans_startScanWindowTbl call! ###\n",0,0,0,0,0,0);
					pc_Job->req_start( ans_startScanWindowTbl[ s_KeyDeviceLogin.index ] );					// ジョブ実行.
					netc_TwainClientMan.setImageTransJobID( SocketFd, pc_Job->getJobStatus()->getJobID() );			// CU1対応時の問題対策のためScanWindowから移動.
					break;
				case SCL_GET_PAGE_SIZE:
				case SCL_SET_HDD_TWAIN_PARAM_4:
				case SCL_SET_HDD_TWAIN_PARAM_5:
				case SCL_SET_HDD_TWAIN_PARAM_6:	//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start.
				case SCL_GET_SCAN_PAGE_DATA:
NetTwainDebugTrace((char*)"### _setJobTicketProc() Auth_OK! ans_startGetImageJobTbl call! ###\n",0,0,0,0,0,0);
					pc_Job->req_start( ans_startGetImageJobTbl[ s_KeyDeviceLogin.index ] );					// ジョブ実行.
					break;
				default:
NetTwainDebugTrace((char*)"### _setJobTicketProc() Auth_OK! Impossible! ###\n",0,0,0,0,0,0);
					break;
			}
			break;

		// 認証失敗.
		case TYPE_UserResultAdminMachineKM_NG: 					// 認証失敗⇒アプリに失敗を返答.
		case TYPE_UserResultAdminMachineKM_ParamError:			// パラメーター不正.
		case TYPE_UserResultAdminMachineKM_TimeOut:				// タイムアウトによる認証NG.
		case TYPE_UserResultAdminMachineKM_Other:				// その他エラー.
		default:
NetTwainDebugTrace((char*)"#### _setJobTicketProc()_Authentication Error s_KeyDeviceLogin.e_Result = %d Login Error ####\n", s_KeyDeviceLogin.e_Result,0,0,0,0,0);
			// WDATコマンドで分岐.
			switch ( netc_TwainClientMan.getCommandID( SocketFd ) ) {
				case SCL_PRINT_DOC:
NetTwainDebugTrace((char*)"### _setJobTicketProc() Auth_NG! ans_startPrintDocTbl call! ###\n",0,0,0,0,0,0);
					ans_startPrintDocTbl[ s_KeyDeviceLogin.index ]( NULL );					// ジョブ実行結果NG処理へ.
					break;
				case SCL_SCAN_WINDOW:
NetTwainDebugTrace((char*)"### _setJobTicketProc() Auth_NG! ans_startScanWindowTbl call! ###\n",0,0,0,0,0,0);
					ans_startScanWindowTbl[ s_KeyDeviceLogin.index ]( NULL );				// ジョブ実行結果NG処理へ.
					break;
				case SCL_GET_PAGE_SIZE:
				case SCL_SET_HDD_TWAIN_PARAM_4:
				case SCL_SET_HDD_TWAIN_PARAM_5:
				case SCL_SET_HDD_TWAIN_PARAM_6:	//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start.
				case SCL_GET_SCAN_PAGE_DATA:
NetTwainDebugTrace((char*)"### _setJobTicketProc() Auth_NG! ans_startGetImageJobTbl call! ###\n",0,0,0,0,0,0);
					ans_startGetImageJobTbl[ s_KeyDeviceLogin.index ]( NULL );				// ジョブ実行結果NG処理へ.
					break;
				default:
NetTwainDebugTrace((char*)"### _setJobTicketProc() Auth_NG! Impossible! ###\n",0,0,0,0,0,0);
					break;
			}
			break;
	}
	
	// ジョブチケット取得用に退避したジョブポインタのクリア.
	netc_TwainClientMan.setJobInstanceforJobTicket( SocketFd, NULL );
	
	// クライアント管理情報のセマフォをアンロックする.
	netc_TwainClientMan.semUnLock();
}
