//==================================================================================================
//[クラス]NETC_TwainJobOvserver 
//[内容]TCPSocketモジュールでのTwainジョブのステータス変化を取得するクラス 
//[履歴] 2004.01.14 Matsumoto
//==================================================================================================
class NETC_TwainJobOvserver : public APIC_JobObserver
{
public:
	//概要　　：コンストラクタ
	NETC_TwainJobOvserver() {}
	~NETC_TwainJobOvserver() {}

	//概要　　：終了通知 
	void end( APIC_Job* pc_Job ); 
	//概要　　：停止完了通知 
	void stopComplete( APIC_Job* pc_Job ); 
	//概要　　：ジョブスペック変化通知 
	void JobSpecChanged( APIC_Job* pc_Job ); 
	//概要　　：ジョブステータス変化通知　
	void JobStatusChanged( APIC_Job* pc_Job ); 
	//概要　　：ジョブ履歴変化通知 
	void JobHistoryChanged( APIC_Job* pc_Job ); 
	//概要　　：登録許可通知
	void JobRegistPermission( APIC_Job* pc_Job );
	//概要　　：１ページ排紙完了通知 
	void ejectOnePaper( APIC_Job* pc_Job, uint32_t ul_EjectNum, Bool b_FinalPaper ) { pc_Job = 0; ul_EjectNum = 0; b_FinalPaper = False; }
};

NETC_TwainJobOvserver netc_TwainJobOvserver;

void NETC_TwainJobOvserver::end( APIC_Job * pc_Job )
{
NetTwainDebugTrace((char*)"\n\n\n[%d]TWAIN Job End!\n\n\n",SYSF_tickGet(),0,0,0,0,0);

	signed int si_SocketFd = netc_TwainClientMan.getImageTransSocketFd( pc_Job->getJobStatus()->getJobID() );	// 自分を管理しているテーブルのSocketFdを取得する 
	NetTwainDebugTrace((char*)"### Job End %d %d 0x%lx %d\n",pc_Job->getJobStatus()->getJobID(),pc_Job->getJobHistory()->getJobResult(),reinterpret_cast<intptr_t>(pc_Job),si_SocketFd,0,0);
	Bool bl_RealTwain = False;

	// 2014/11/27 [ZeusS][CQ507082]OPS1前田(Sky) Start.
	// 下記処理はこの関数内から移動しないこと。 .
	// 接続タイムアウトが発生した場合は自タスク(_JobResultProc)まで処理が行かないためオブザーバー通知ないでフラグをセットする必要がある。 .
	// (オブザーバー通知内にあまり処理は入れたくはないが、接続タイムアウト時はgetTwainReceiverSlaveがNULLとなっており、 .
	//  setPacketDataにてNULLチェックに引っかかり自タスクまで処理が行かない) .
	if( True == isbizhubRACheck( si_SocketFd ) ) {
NetTwainDebugTrace((char*)"###  NETC_TwainJobOvserver::end setDuringScanToAndroid = False ###\n",0,0,0,0,0,0);
		APIC_AndroidPanel* pc_AndroidPanel = APIC_AndroidPanel::newInstance();
		pc_AndroidPanel->setDuringScanToAndroid( False );
	}
	// 2014/11/27 [ZeusS][CQ507082]OPS1前田(Sky) End.
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_JobResult* pc_JobResult = (NETS_JobResult*)malloc( sizeof(NETS_JobResult) );
	if( pc_JobResult == NULL ){
		errorLog_TwainService("pc_JobResult_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	pc_JobResult->pc_Job = pc_Job;
	si_SocketFd = netc_TwainClientMan.getSocketFd( pc_Job->getJobStatus()->getJobID(), &bl_RealTwain );
	NetTwainDebugTrace((char*)"[%d]JobOvserver::end sS 0x%lx %d\n",SYSF_tickGet(),reinterpret_cast<intptr_t>(pc_JobResult),si_SocketFd,0,0,0);
	if( si_SocketFd != -1 ) {

		netc_TwainService->setPacketData( NETE_TWAIN_JOB_RESULT,
										  netc_TwainClientMan.getClientIndex( si_SocketFd ),
										  NULL,
										  0,
										  netc_TwainClientMan.getAppID( si_SocketFd ),
										  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
										  NULL,
										  (void*)pc_JobResult );
	} else {
		netc_TwainService->setObservertData( NETE_TWAIN_JOB_RESULT2,(void*)pc_JobResult);
	}
	NetTwainDebugTrace((char*)"[%d]JobOvserver::end sE\n",SYSF_tickGet(),0,0,0,0,0);

}

//==================================================================================================.
//[機能] ジョブ実行→ジョブの結果.
//[履歴] 2011/07/28 静的解析対応により、JOBのオブザーバー内で処理できなくなったので
//		 自タスクへメッセージを送信して対応
//==================================================================================================.
void _JobResultProc( NETS_JobResult* pc_JobResult )
{
NetTwainDebugTrace((char*)"[%d]_JobResultProc() start! 0x%lx 0x%lx\n",SYSF_tickGet(),reinterpret_cast<intptr_t>(pc_JobResult),reinterpret_cast<intptr_t>(pc_JobResult->pc_Job),0,0,0);

	NETS_JobResult s_JobResult;
	memcpy( &s_JobResult, pc_JobResult, sizeof( NETS_JobResult ) );
	free( pc_JobResult );
	
NetTwainDebugTrace((char*)"### bl_EmptyPacketSendWait = [%d]\n",(int)bl_EmptyPacketSendWait,0,0,0,0,0);
	signed int SocketFd = netc_TwainClientMan.getImageTransSocketFd( s_JobResult.pc_Job->getJobStatus()->getJobID() );	// 自分を管理しているテーブルのSocketFdを取得する 
NetTwainDebugTrace((char*)"### SocketFd = [%d]\n",SocketFd,0,0,0,0,0);
	if ( (netc_TwainClientMan.getImageTransJobStatus( SocketFd ) == NETE_IMAGETRANS_TRANS) || (netc_TwainClientMan.getImageTransJobStatus( SocketFd ) == NETE_IMAGETRANS_STARTING) ) {		// 転送中状態の場合 
		s_JobResult.pc_Job->lock();
		if ( s_JobResult.pc_Job->getJobHistory()->getJobResult() != TYPE_JobResult_End ) {
			if ( s_JobResult.pc_Job->getJobHistory()->getJobResult() == TYPE_JobResult_UserCancel ) {		// ユーザーキャンセル時 
NetTwainDebugTrace((char*)"### NETE_IMAGETRANS_CANCEL ###\n",0,0,0,0,0,0);
				netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_CANCEL );
				netc_TwainClientMan.setState_CancelSync( SocketFd, NETE_CANCELSYNC_NONE );		// キャンセル同期状態を初期化する.		// 2.1c CQ519136 OSP1八代 2015.10.23.
NetTwainDebugTrace((char*)"### User Cancel!!!!\n",0,0,0,0,0,0);
				if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SCAN_WINDOW ) {		// ScanWindowコマンド未応答状態(1ページ作成できていない場合) 
					// ScanWindowに対する応答を返す 
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_JOB_CANCEL , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					char pc_ReqData[32];
					strcpy( pc_ReqData, "\x1b*s20113r0V" );	// 失敗レスポンス応答 
					char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
					if( pc_RspData == NULL ){
						errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
						s_JobResult.pc_Job->unlock();  // セマフォアンロック		//2021/10/18 [MinervaSSBK][OP_BTS-36147] HIENG.
						return;
					}
					memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
					netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
					if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
						netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
					}
NetTwainDebugTrace((char*)"### ScanWindow Responsed!!!!\n",0,0,0,0,0,0);
				} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_SCAN_DATA ) {
					// GetScanDataに対する応答を返す 
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_JOB_CANCEL , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
						if ( netc_TwainClientMan.getImageTransJobType( SocketFd ) == TYPE_JobTypeTwain )
						{
							uint32_t ul_Result = 1;		// 1 : キャンセル 
							netc_TwainClientMan.setEOIDData( SocketFd, ul_Result );				// EOID(End Of Image Data)パケットを送信する 
						}
						else
						{
							netc_TwainClientMan.setRdatEmptySend( SocketFd );					// データフィールドなしのRDATを送信する 
					}
						netc_TwainClientMan.setImageTransEmptyRDATSend( SocketFd, False );	// データフィールドなしのRDAT送信待ち状態をクリアする 
					}
NetTwainDebugTrace((char*)"### GetScanData Responsed!!!!\n",0,0,0,0,0,0);
				} else {
					short ss_CommandID = netc_TwainClientMan.getCommandID( SocketFd );		// 受信しているコマンドIDを取得する 
					char pc_ReqData[32];
					Bool isRsp = True;
					if ( ss_CommandID == SCL_GET_SCAN_IMAGE_INFO ) {
						sprintf( pc_ReqData, "\x1b*s265tN" );
					} else {
						isRsp = False;
					}
					if ( isRsp == True ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_JOB_CANCEL , __FILE__ ,__LINE__);	// Error Client Error Info 
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
						char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
						if( pc_RspData == NULL ){
							errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
							s_JobResult.pc_Job->unlock();  // セマフォアンロック		//2021/10/18 [MinervaSSBK][OP_BTS-36147] HIENG.
							return;
						}
						memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
						netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
						if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
							netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
						}
					}
					netc_TwainClientMan.setErrorInfo( SocketFd, ERR_USER_JOB_CANCEL );		// Error Client Error Info 
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_JOB_CANCEL , __FILE__ ,__LINE__);
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );				// Error Client Error Status 
				}
			} else if ( s_JobResult.pc_Job->getJobHistory()->getJobResult() == TYPE_JobResult_Delete ) {	// ジョブ破棄時 
NetTwainDebugTrace((char*)"### NETE_IMAGETRANS_CANCEL ###\n",0,0,0,0,0,0);
				netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_CANCEL );
				netc_TwainClientMan.setState_CancelSync( SocketFd, NETE_CANCELSYNC_NONE );		// キャンセル同期状態を初期化する.		// 2.1c CQ519136 OSP1八代 2015.10.23.
NetTwainDebugTrace((char*)"### JobDeleted!!!! ErrorCause = [%d]\n",s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause(),0,0,0,0,0);
				if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SCAN_WINDOW ) {		// ScanWindowコマンド未応答状態(1ページ作成できていない場合) 
					// ScanWindowに対する応答を返す 
					if ( s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause() == TYPE_DeleteJobCause_MemOver ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_MEMORY_OVERFLOW , __FILE__ ,__LINE__);	// Error Client Error Info 
					} else if ( s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause() == TYPE_DeleteJobCause_CopyGuard ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info 
					} else if ( s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause() == TYPE_DeleteJobCause_JimonPasswordUnfeasible ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info 
					//2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28(WP1061) Start.
					} else if ( s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause() == TYPE_DeleteJobCause_UnsupportedResolution ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					//2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28(WP1061) End.
					} else {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);	// Error Client Error Info 
					}
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					char pc_ReqData[32];
					strcpy( pc_ReqData, "\x1b*s20113r0V" );	// 失敗レスポンス応答 
					char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
					if( pc_RspData == NULL ){
						errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
						s_JobResult.pc_Job->unlock();  // セマフォアンロック		//2021/10/18 [MinervaSSBK][OP_BTS-36147] HIENG.
						return;
					}
					memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
					netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
					if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
						netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
					}
NetTwainDebugTrace((char*)"### ScanWindow Responsed!!!!\n",0,0,0,0,0,0);
				} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_SCAN_DATA ) {
NetTwainDebugTrace((char*)"### NETE_IMAGETRANS_CANCEL ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_CANCEL );
					netc_TwainClientMan.setState_CancelSync( SocketFd, NETE_CANCELSYNC_NONE );		// キャンセル同期状態を初期化する.		// 2.1c CQ519136 OSP1八代 2015.10.23.
NetTwainDebugTrace((char*)"### JobDeleted!!!!\n",0,0,0,0,0,0);
					if ( s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause() == TYPE_DeleteJobCause_MemOver ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_MEMORY_OVERFLOW , __FILE__ ,__LINE__);	// Error Client Error Info 
					} else if ( s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause() == TYPE_DeleteJobCause_CopyGuard ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info 
					} else if ( s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause() == TYPE_DeleteJobCause_JimonPasswordUnfeasible ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info 
					//2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28(WP1061) Start.
					} else if ( s_JobResult.pc_Job->getJobHistory()->getDeleteJobCause() == TYPE_DeleteJobCause_UnsupportedResolution ) {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					//2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28(WP1061) End.
					} else {
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);	// Error Client Error Info 
					}
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					// GetScanDataに対する応答を返す 
					if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
						if ( netc_TwainClientMan.getImageTransJobType( SocketFd ) == TYPE_JobTypeTwain )
						{
							uint32_t ul_Result = 2;		// 2 : エラー発生 
							netc_TwainClientMan.setEOIDData( SocketFd, ul_Result );				// EOID(End Of Image Data)パケットを送信する 
						}
						else
						{
							netc_TwainClientMan.setRdatEmptySend( SocketFd );					// データフィールドなしのRDATを送信する 
						}
						netc_TwainClientMan.setImageTransEmptyRDATSend( SocketFd, False );	// データフィールドなしのRDAT送信待ち状態をクリアする 
					}
NetTwainDebugTrace((char*)"### GetScanData Responsed!!!!\n",0,0,0,0,0,0);
				}
			}
		}
		s_JobResult.pc_Job->unlock();
		// Twainロック状態解除 
		APIC_SystemStatus* pc_SystemStatus = NULL;
		pc_SystemStatus = APIC_SystemStatus::newInstance();
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 Start.
		// 連続読み込みがONの場合は、ジョブの終了でTwainロックを解除しない.
		if ( (NULL != pc_SystemStatus) && (TYPE_SeparateScanForTwain_On != pc_SystemStatus->getSeparateScanForTwain()) ) {
			// 2014/09/03 [ZeusS][RQ-232][WP973]OPS1前田 Start.
			if( False == isbizhubRACheck( SocketFd ) ) {
				pc_SystemStatus->lock();
				pc_SystemStatus->setSeparateScanForTwain( TYPE_SeparateScanForTwain_Off );
				pc_SystemStatus->setNextImageEnableForTwain( TYPE_NextImageEnableForTwain_NoExec );
				pc_SystemStatus->setTwainLock( TYPE_TwainLockNon, s_JobResult.pc_Job );
				pc_SystemStatus->unlock();
			}
			// 2014/09/03 [ZeusS][RQ-232][WP973]OPS1前田 End.
		}
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 End.
	}
	netc_TwainClientMan.setImageTransJobInstance( SocketFd, NULL );

	s_JobResult.pc_Job->lock();
	s_JobResult.pc_Job->detachObserver( &netc_TwainJobOvserver );		// オブザーバーから除外する.
	s_JobResult.pc_Job->unlock();
	NetTwainDebugTrace((char*)"#### _JobResultProc() end! ####\n",0,0,0,0,0,0);

}

void _JobResultProc2( NETS_JobResult* pc_JobResult )
{
	NetTwainDebugTrace((char*)"[%d]_JobResultProc2() start! 0x%lx 0x%lx\n",SYSF_tickGet(),reinterpret_cast<intptr_t>(pc_JobResult),reinterpret_cast<intptr_t>(pc_JobResult->pc_Job),0,0,0);
	NETS_JobResult s_JobResult;
	memcpy( &s_JobResult, pc_JobResult, sizeof( NETS_JobResult ) );
	free( pc_JobResult );
	
	s_JobResult.pc_Job->lock();
	s_JobResult.pc_Job->detachObserver( &netc_TwainJobOvserver );		// オブザーバーから除外する.
	s_JobResult.pc_Job->unlock();
	NetTwainDebugTrace((char*)"#### _JobResultProc2() end! ####\n",0,0,0,0,0,0);
}

