//[履歴]
//==================================================================================================
NETC_TwainCommandGetErrorStack::NETC_TwainCommandGetErrorStack( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
void NETC_TwainCommandGetErrorStack::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* ,				// パラメータへのポインタ 
	short 				// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetErrorStack::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];

	if ( (netc_TwainClientMan.getImageTransJobStatus( SocketFd ) == NETE_IMAGETRANS_TRANS) || (netc_TwainClientMan.getImageTransJobStatus( SocketFd ) == NETE_IMAGETRANS_STARTING) ) {		// 転送中状態の場合 
		if ( netc_TwainClientMan.getErrorInfo( SocketFd ) != -1 ) {
			strcpy( pc_ReqData, "\x1b*s257d1V" );	// エラーが１回以上発生している 
		} else {
			strcpy( pc_ReqData, "\x1b*s257d0V" );	// エラーが発生していない 
		}
	} else if ( netc_TwainClientMan.getClientErrorStatus( SocketFd ) == False ) { 
		strcpy( pc_ReqData, "\x1b*s257d0V" );	// エラーが発生していない 
	} else {
		strcpy( pc_ReqData, "\x1b*s257d1V" );	// エラーが１回以上発生している 
	}

	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

//		SCL_GET_ERROR_NUMBER			38		//Read Current Error Number 
//==================================================================================================
//[クラス]NETC_TwainCommandGetErrorNumber 
//[内容] SCL_GET_ERROR_NUMBERコマンドを処理するクラス 
//[履歴] 2003.12.27 Matsumoto
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetErrorNumberのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandGetErrorNumber::NETC_TwainCommandGetErrorNumber( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
void NETC_TwainCommandGetErrorNumber::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* ,				// パラメータへのポインタ 
	short 				// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetErrorNumber::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];

	if ( (netc_TwainClientMan.getImageTransJobStatus( SocketFd ) == NETE_IMAGETRANS_TRANS) || (netc_TwainClientMan.getImageTransJobStatus( SocketFd ) == NETE_IMAGETRANS_STARTING) ) {		// 転送中状態の場合 
		if ( netc_TwainClientMan.getErrorInfo( SocketFd ) != -1 ) {
			sprintf( pc_ReqData, "\x1b*s259d%ldV", netc_TwainClientMan.getErrorInfo( SocketFd ) );		// 応答データ 
		} else {
			strcpy( pc_ReqData, "\x1b*s259dN" );	// Null Response（エラーが発生していない） 
		}
	} else if ( netc_TwainClientMan.getClientErrorStatus( SocketFd ) == False ) { 
		strcpy( pc_ReqData, "\x1b*s259dN" );	// Null Response（エラーが発生していない） 
	} else {
		int ss_Errinfo = netc_TwainClientMan.getClientErrorInfo( SocketFd );
		sprintf( pc_ReqData, "\x1b*s259d%dV", ss_Errinfo );		// 応答データ 
	}
	
NetTwainDebugTrace((char*)"<<GetErrorNumber>> pc_ReqData = [%s]\n", reinterpret_cast<intptr_t>(pc_ReqData),0,0,0,0,0);

	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

//		SCL_GET_NEXT_PAGE			39		//Inquire Next Page Data Available 
//==================================================================================================
//[クラス]NETC_TwainCommandGetNextPage 
//[内容] SCL_GET_NEXT_PAGEコマンドを処理するクラス 
//[履歴] 2004.02.18 Matsumoto
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetNextPageのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandGetNextPage::NETC_TwainCommandGetNextPage( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
void NETC_TwainCommandGetNextPage::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* ,				// パラメータへのポインタ 
	short 				// パラメータの長さ 
)
{

NetTwainDebugTrace((char*)" NETC_TwainCommandGetNextPage::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 Start.
	memset( pc_ReqData, 0, sizeof(pc_ReqData) );
	APIC_SystemStatus* pc_SystemStatus = APIC_SystemStatus::newInstance();
	Bool b_Send = False;
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 End.
	if ( (netc_TwainClientMan.getImageTransJobInstance( SocketFd ) == NULL ) || (netc_TwainClientMan.getImageTransJobStatus( SocketFd ) == NETE_IMAGETRANS_NONE) || (netc_TwainClientMan.getImageTransJobStatus( SocketFd ) == NETE_IMAGETRANS_INSTANCE) )
	{
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 Start.
		//2014/03/10 OPS1前田(Sky) [Zeus4th] 静的解析対応 ID:10211.
		if ( NULL != pc_SystemStatus ) {
			if ( TYPE_SeparateScanForTwain_On == pc_SystemStatus->getSeparateScanForTwain() ) {
				// ソケットを次ジョブ待ち状態に設定.
				netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_WAIT_NEXT_JOB );
				// 次画像実行可能状態を「実行可能」に設定する.
				pc_SystemStatus->setNextImageEnableForTwain( TYPE_NextImageEnableForTwain_Enable );
				// 応答は定期起床でNYETを返す.
NetTwainDebugTrace("### NETC_TwainCommandGetNextPage NextPage is NYET ###\n",0,0,0,0,0,0);
			} else {
					strcpy( pc_ReqData, "\x1b*s20201d0V" );	// 次ページなし応答 
NetTwainDebugTrace((char*)"### NETC_TwainCommandGetNextPage ERR_NO_SCAN_WINDOW_COMMAND ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_NO_SCAN_WINDOW_COMMAND , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
					b_Send = True;
					pc_SystemStatus->setNextImageEnableForTwain( TYPE_NextImageEnableForTwain_NoExec );
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 End.
			}
		} else {
			errorLog_TwainService("pc_SystemStatus is NULL\n",0,0,0,0,0,0);
			return;
		}
	}
	else
	{
		if ( (netc_TwainClientMan.getTotalPages( SocketFd ) != 0) && (netc_TwainClientMan.getTotalPages( SocketFd ) <= netc_TwainClientMan.getSendedPages( SocketFd ) ) ) {		// 総ページ数が確定していて、送信済みページ数が総ページ数以上になった場合は、次ページなし！！ 
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 Start.
			// 全原稿済み.
			if ( (NULL != pc_SystemStatus) && (TYPE_SeparateScanForTwain_On == pc_SystemStatus->getSeparateScanForTwain()) ) {
NetTwainDebugTrace("#### NextPage is NYET ####\n",0,0,0,0,0,0);
				// ソケットを次ジョブ待ち状態に設定.
				netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_WAIT_NEXT_JOB );
				// 次画像実行可能状態を「実行可能」に設定する.
				pc_SystemStatus->setNextImageEnableForTwain( TYPE_NextImageEnableForTwain_Enable );
				printf("#### getTotalPages <= getSendedPages ####\n");
				// 応答は定期起床でNYETを返す.
			} else {
NetTwainDebugTrace((char*)"#### NextPage is Not Exist ####\n",0,0,0,0,0,0);
				strcpy( pc_ReqData, "\x1b*s20201d0V" );	// 次ページなし応答 
				b_Send = True;
			}
		} else {
NetTwainDebugTrace((char*)"#### NextPage is Exist ####\n",0,0,0,0,0,0);
			// ADFに原稿が残っている間は読み込み終了ボタンを表示しない.
// 2021/10/18 FPT-TrungHV7 [IT6_2.2][TAS000000010056] Start.
//			if(isPushScanTimeOutON)
//			{
//				twainWatchDogCancel( wdog_ID_PushTwain );
//				isPushScanTimeOutON = false;
//				printf("#### twainWatchDogCancel() isPushScanTimeOutON = false ####\n");
//			}
// 2021/10/18 FPT-TrungHV7 [IT6_2.2][TAS000000010056] End.
			pc_SystemStatus->setNextImageEnableForTwain( TYPE_NextImageEnableForTwain_Disable );
			strcpy( pc_ReqData, "\x1b*s20201d1V" );	// 次ページあり応答 
			b_Send = True;
		}
	}
	if ( True == b_Send )
	{
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
	else {
		//	すぐに送信しない場合は、タイマスタート.
		APIC_ScanJobSetting* pc_ScanJobSetting = APIC_ScanJobSetting::newInstance();
		short ss_TimeOut = pc_ScanJobSetting->getTwainLockCancelTimeSec();
		twainWatchDogStart( wdog_ID_PushTwain, (int32_t)( ss_TimeOut * 1000 ), (FUNCPTR)PushScanTimeOutProc, SocketFd ); 
//		isPushScanTimeOutON = true;													// 2021/10/18 FPT-TrungHV7 [IT6_2.2][TAS000000010056] Delete.
//		printf("#### twainWatchDogStart() isPushScanTimeOutON = true ####\n");		// 2021/10/18 FPT-TrungHV7 [IT6_2.2][TAS000000010056] Delete.
NetTwainDebugTrace("#### NETC_TwainCommandGetNextPage Timer Start %d ####\n",( ss_TimeOut * 1000 ),0,0,0,0,0);
	}
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 End.

}

//		SCL_GET_DEVICE_INFO			40		// Get Device Information 2.
//==================================================================================================
//[クラス]NETC_TwainCommandGetDeviceInfo 
//[内容] SCL_GET_DEVICE_INFOコマンドを処理するクラス 
//[履歴] 2004.03.18 Iesato
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetDeviceInfoのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandGetDeviceInfo::NETC_TwainCommandGetDeviceInfo( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
void NETC_TwainCommandGetDeviceInfo::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* ,				// パラメータへのポインタ 
	short 				// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetDeviceInfo::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char* pc_ReqData = NULL;
	int returnLength = 0;

	// 領域確保 
	NETS_DeviceInformation nets_DeviceInformation;
	// 領域を初期化する 
	memset( &nets_DeviceInformation, 0, sizeof(NETS_DeviceInformation) );

	// 製品情報を取得する 
	// MIBのOIDを取得する 
	// >> 2008.03.06 Tana [Donau] No.EE ObjectIDの取得方法を変更 MIB→CommonAPI.
	APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();
	pc_SystemInfo->lock();
	pc_SystemInfo->getSysObjectID( &nets_DeviceInformation.sc_SysObjectID[0] );
	pc_SystemInfo->unlock();
	// << 2008.03.06 Tana [Donau] No.EE ObjectIDの取得方法を変更 MIB→CommonAPI.

	// 仕向情報を取得する。
	APIC_MachineSetting* pc_MachineSetting = APIC_MachineSetting::newInstance();// マシン設定のインスタンスを取得する 
	TYPE_SystemType e_SystemType = pc_MachineSetting->getSystemType();
	switch( e_SystemType ) {
		case TYPE_SystemType_JP:							// 日本仕向 
			nets_DeviceInformation.uc_SystemType[1] = 0;
			nets_DeviceInformation.uc_SystemType[0] = 1;
			break;
		case TYPE_SystemType_US:							// ＵＳ仕向 
			nets_DeviceInformation.uc_SystemType[1] = 0;
			nets_DeviceInformation.uc_SystemType[0] = 2;
			break;
		case TYPE_SystemType_EU:							// ＥＵ仕向 
			nets_DeviceInformation.uc_SystemType[1] = 0;
			nets_DeviceInformation.uc_SystemType[0] = 4;
			 break;
		default:
			nets_DeviceInformation.uc_SystemType[1] = 0;
			nets_DeviceInformation.uc_SystemType[0] = 0;
			break;
	}

	// 装置名を設定する 
	pc_SystemInfo->lock();
	pc_SystemInfo->getSysDescr( &nets_DeviceInformation.sc_SysDeviceName[0] );		// 装置名 
	pc_SystemInfo->unlock();
	if ( nets_DeviceInformation.sc_SysDeviceName[0] == '\0' ) {	// 装置名がNULLの場合MIBのsysDescrを取得する 
		NETG_FixedValueDefine* pc_FixedValueDefine = NETG_FixedValueDefine::newInstance();
		if ( pc_FixedValueDefine != NULL ) {
			char mibSysDescr[256];
			memset( &mibSysDescr, 0, sizeof(mibSysDescr) );
			pc_FixedValueDefine->getSysDescr( mibSysDescr );
			memcpy( &nets_DeviceInformation.sc_SysDeviceName[0], &mibSysDescr[0], 80 );
		}
	}

	// ＭＡＣアドレスを取得する 
	char sc_getMacAddress[17+1];
	memset( &sc_getMacAddress, 0, sizeof(sc_getMacAddress) );
	APIC_TcpIpSetting* pc_TcpIpSetting = NULL;
	pc_TcpIpSetting = APIC_TcpIpSetting::newInstance();
	pc_TcpIpSetting->lock();
	pc_TcpIpSetting->getMacAddress( sc_getMacAddress );		// MACアドレス取得 
	pc_TcpIpSetting->unlock();

	char sc_MacAddressTmp[17+1];
	memset( &sc_MacAddressTmp, 0, sizeof(sc_MacAddressTmp) );
	int i = 0;
	int j = 0;
	for ( j=0; j < 17; j++){
		if ( sc_getMacAddress[j] != ':' ){
			sc_MacAddressTmp[i] = sc_getMacAddress[j];
			i++;
		}
	}

	char sc_AsciiToBin[12];
	for ( i =0; i < 12; i++){
		switch ( sc_MacAddressTmp[i] ) {
			case '0':
				sc_AsciiToBin[i] = 0x00;
				break;
			case '1':
				sc_AsciiToBin[i] = 0x01;
				break;
			case '2':
				sc_AsciiToBin[i] = 0x02;
				break;
			case '3':
				sc_AsciiToBin[i] = 0x03;
				break;
			case '4':
				sc_AsciiToBin[i] = 0x04;
				break;
			case '5':
				sc_AsciiToBin[i] = 0x05;
				break;
			case '6':
				sc_AsciiToBin[i] = 0x06;
				break;
			case '7':
				sc_AsciiToBin[i] = 0x07;
				break;
			case '8':
				sc_AsciiToBin[i] = 0x08;
				break;
			case '9':
				sc_AsciiToBin[i] = 0x09;
				break;
			case 'A':
				sc_AsciiToBin[i] = 0x0a;
				break;
			case 'B':
				sc_AsciiToBin[i] = 0x0b;
				break;
			case 'C':
				sc_AsciiToBin[i] = 0x0c;
				break;
			case 'D':
				sc_AsciiToBin[i] = 0x0d;
				break;
			case 'E':
				sc_AsciiToBin[i] = 0x0e;
				break;
			case 'F':
				sc_AsciiToBin[i] = 0x0f;
				break;
			default:
				sc_AsciiToBin[i] = 0x00;
				break; // Eagle AR1026431(静的解析) ID1108680 2017.11.27 Sky徳永. 
		}
	}

	char sc_MacAddress[6+1];
	j = 0;
	for ( i =0; i < 12; i++){
		sc_MacAddress[j] = (signed char)( ( ( sc_AsciiToBin[i] & 0x0f) << 4 ) | ( sc_AsciiToBin[i +1 ] & 0x0f) );
		i++;
		j++;
	}

	memcpy( &nets_DeviceInformation.sc_MacAddress[0], &sc_MacAddress[0], 6 );

	char tmpdata[128];
	sprintf( tmpdata, "\x1b*s264t%dW", sizeof(NETS_DeviceInformation) );		// 応答データ作成 
	pc_ReqData = (char*)malloc(strlen(tmpdata)+sizeof(NETS_DeviceInformation));
	if( pc_ReqData == NULL ){
		errorLog_TwainService("pc_ReqData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( &pc_ReqData[0], tmpdata, strlen(tmpdata) );
	memcpy( &pc_ReqData[strlen(tmpdata)], &nets_DeviceInformation, sizeof(NETS_DeviceInformation) );
	returnLength = strlen(tmpdata) + sizeof(NETS_DeviceInformation);
	netc_TwainClientMan.setSendData( SocketFd, pc_ReqData, returnLength );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

//		SCL_RENAME_DOC				41		// Rename Document 
//==================================================================================================
//[クラス]NETC_TwainCommandRenameDoc 
//[内容] SCL_RENAME_DOCコマンドを処理するクラス 
//[履歴] 2004.06.25 Iesato
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandRenameDocのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandRenameDoc::NETC_TwainCommandRenameDoc( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
void NETC_TwainCommandRenameDoc::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandRenameDoc::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	// HDD装着のチェックを行う 
	if( isCheckAvailableBox() == NETE_Function_Box_Disabled )				// BOX使用可能or一部使用可能のとき.	// 2011/03/31 amiya 【Minerva】管理No941 SSD削減対応（1GB⇒512MB）.
	{
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_HDD_NOT_INSTALLED , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35105r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30.
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	// 2008.08.05 Donau問題点対応 CC 307768 平谷 str.
	} else if ( ( NULL != netc_TwainClientMan.getApic_Admin( SocketFd ) )
		&& ( True == netc_TwainClientMan.getUserLogined( SocketFd ) ) ) {	// 管理者ログイン時は不可.
NetTwainDebugTrace((char*)"# NETC_TwainCommandRenameDoc_ERR_USER_BOX_NOT_SPECIFIED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35105r0V" );	// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	// 2008.08.05 Donau問題点対応 CC 307768 平谷 end.
	// 監査ログフルのため操作禁止か否かをチェックする 
	APIC_SystemStatus* pc_SystemStatus = NULL;
	pc_SystemStatus = APIC_SystemStatus::newInstance();
	pc_SystemStatus->lock();
	Bool bl_InspectLog = pc_SystemStatus->chkJobStarting( TYPE_JobEnableCheckStatusInspectLogCnt );
	pc_SystemStatus->unlock();
	if ( bl_InspectLog == False )
	{
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SURVEILLANT_LOG_FULL , __FILE__ ,__LINE__);	// 監視ログのサイズが上限のためにジョブの登録、デバイス操作が行えないエラー 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// エラー発生状態とする 
		strcpy( pc_ReqData, "\x1b*s35105r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	// Boxログイン状態のチェックを行う 
	if ( netc_TwainClientMan.getBoxLogined( SocketFd ) == False ) {		// Box未ログイン状態 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35105r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	// ユーザー認証時の操作許可チェックを行う 
	if ( getUserAuthenticationMode() != TYPE_UserAuthenticationOff ) {	// ユーザー認証モードがOFF以外(ONの場合) 
		if ( netc_TwainClientMan.getUserLogined(SocketFd) == True ) {		// ログイン済み 
			APIC_User* pc_User = netc_TwainClientMan.getApic_User( SocketFd );
			if(pc_User == NULL){
				errorLog_TwainService("pc_User NULL!!!\n",0,0,0,0,0,0);
				return;
			}
			pc_User->lock();
			TYPE_FuncLimit e_BoxOperation = pc_User->getFunctionLimitation().e_EnableBoxOperation;		// 2010/08/25 amiya 【Minerva】UV-00458 ユーザー毎のカラー白黒出力制限をコピーとプリントで別々に設定したい対応.
			pc_User->unlock();
			if ( e_BoxOperation == TYPE_FuncLimit_Disable ) {		// 蓄積文書操作不可の場合 
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				strcpy( pc_ReqData, "\x1b*s35105r0V" );		// 失敗応答 
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
				return;
			}
		}
	}

	// パラメータから、ドキュメントID（ユーザジョブ番号）、変更するドキュメント名を抜き出す 
	char sc_ParamTemp[101];								// 一時格納領域  DocID:6 , DataSize:2 , DocName:91 , "t" , "N" でmax101
	memset( sc_ParamTemp, 0, sizeof(sc_ParamTemp) );	// 格納領域クリア 
	int32_t sl_DocID = 0;									// ドキュメントID（ユーザジョブ番号） 
	short ss_DataLen = 0;								// [data]領域長 
	char sc_DocName[91];								// 変更するドキュメント名格納領域 
	memset( sc_DocName, 0, sizeof(sc_DocName) );		// 格納領域クリア 
	Bool bl_is_CheckFlag = False;						// チェックフラグ 

	int state = 0;
	int TempIndex = 0;
	for ( int index = 0; index < 101 && index < ParamLength; index++ ) {
		switch( state ){
			case 0:													// #1 : ドキュメントID（ユーザジョブ番号）の抜き出し 
				if ( Parameter[index] == 't' ){							// "t"を検出 
					sc_ParamTemp[TempIndex] = '\0';							// 終端設定 
					sl_DocID = atoi(sc_ParamTemp);							// #1 : ドキュメントID取得 
					memset( sc_ParamTemp, 0, sizeof(sc_ParamTemp) );		// 一時格納領域初期化 
					TempIndex = 0;											// カウンタ初期化 
					state = 1;												// 次の処理へ
				} else {												// "t"を未検出 
					sc_ParamTemp[TempIndex] = Parameter[index];				// パラメータからデータ抜き取り 
					TempIndex++;
				}
				break;
			case 1:													// #2 : [data]のサイズの抜き出し 
				if ( Parameter[index] == 'N' ){								// "N"を検出 
					sc_ParamTemp[TempIndex] = '\0';							// 終端設定 
					ss_DataLen = (signed short)atoi(sc_ParamTemp);			// #1 : [data]領域長取得 
					memset( sc_ParamTemp, 0, sizeof(sc_ParamTemp) );		// 一時格納領域初期化 
					TempIndex = 0;											// カウンタ初期化 
					state = 2;												// 次の処理へ
				} else {
					sc_ParamTemp[TempIndex] = Parameter[index];					// パラメータからデータ抜き取り 
					TempIndex++;
				}
				break;
			case 2:
				sc_ParamTemp[TempIndex] = Parameter[index];					// 変更後のドキュメント名を一時格納領域へ取得 
				TempIndex++;
				bl_is_CheckFlag = True;									// チェックフラグTrue 
				break;
			default:
				bl_is_CheckFlag = False;								// チェックフラグFalse 
				break;
		}
	}

	// パラメータのチェックをおこなう 
	if ( ( sl_DocID < DOCD_DocIdMin || DOCD_DocIdMax < sl_DocID )	// ドキュメントIDが１～999999以外 
	  || ( ss_DataLen < 1 || 91 < ss_DataLen )						// または、[data]領域長が1～91以外 
	  || ( bl_is_CheckFlag == False ) ) {							// または、チェックフラグFalse 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);			// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35105r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	memcpy( &sc_DocName[0], sc_ParamTemp, ss_DataLen);						// 変更するドキュメント名格納 

	// ドキュメント名を変更する。
	APIC_Doc* pc_Doc = NULL;
	pc_Doc = APIC_Doc::newInstance();										// APIC_Doc のインスタンスを取得する 
	pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );							// ログ用IF No 登録.

	pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );	// インスタンスに Box ID を登録(保持)する 
	pc_Doc->setDocId( sl_DocID );											// インスタンスに Doc ID を登録(保持)する 
	APIC_DocInfo pc_DocInfo;												// Docの基本情報クラス 
	int32_t sl_result = 0;
	Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
	APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
	Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
	APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
	(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
	sl_result =  pc_Doc->getDocInfo( pc_UserGet, netc_TwainClientMan.getLoginedBoxPassword( SocketFd ), &pc_DocInfo, (LIBE_CharSet)APID_DefaultCharSet, pc_TrackGet );	// Docの基本情報 (DocName)を取得する 

	if (sl_result != APID_DocapiMethodOk){													// 正常終了以外 
		pc_Doc->deleteInstance();															// APIC_Doc のインスタンスを削除する 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);			// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35105r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	memset( pc_DocInfo.sc_DocName, '\0', sizeof(pc_DocInfo.sc_DocName) );						// ドキュメント名の領域を初期化する。
	strcpy( pc_DocInfo.sc_DocName, &sc_DocName[0] );											// 変更するドキュメント名を設定する。
	sl_result =  pc_Doc->setDocInfo( pc_UserGet,
									 netc_TwainClientMan.getLoginedBoxPassword( SocketFd ),
									 &pc_DocInfo,											// Docの基本情報 (DocName)を設定する 
									 (LIBE_CharSet)APID_DefaultCharSet,
									 pc_TrackGet );
	pc_Doc->deleteInstance();																	// APIC_Doc のインスタンスを削除する 

	if (sl_result != APID_DocapiMethodOk){			// 正常終了以外 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);			// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35105r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// 成功応答を返す 
	strcpy( pc_ReqData, "\x1b*s35105r1V" );	// 成功応答 
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

//==================================================================================================
//[機能]コールバック関数からコールされる関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2006.05.11 Matsumoto
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_GetJobIDScanPara( int id, APIS_JobInfoDoc* pc_JobInfoDoc, void* ptr, int32_t ret )
{
NetTwainDebugTrace((char*)"#### ans_GetJobIDScanPara() start! ####\n",0,0,0,0,0,0);
	netc_TwainClientMan.semLock();		// クライアントテーブルを参照・変更するためセマフォをロックする 
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_DocJobID* pc_DocJobID = (NETS_DocJobID*)malloc( sizeof(NETS_DocJobID) );
	if( pc_DocJobID == NULL ){
		errorLog_TwainService("pc_DocJobID_malloc Error\n",0,0,0,0,0,0);
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
		return;
	}
	pc_DocJobID->index = id;
	pc_DocJobID->pc_JobInfoDoc = pc_JobInfoDoc;
	pc_DocJobID->ptr = ptr;
	pc_DocJobID->ret = ret;
	netc_TwainService->setPacketData( NETE_TWAIN_DOC_JOBID_SCAN,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
									  (void*)pc_DocJobID );
	netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
}
