//==================================================================================================
//[機能]JobID取得時の処理関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2006.05.11 Matsumoto
//==================================================================================================
void _GetJobIDScanPara( NETS_DocJobID* pc_DocJobID )
{
NetTwainDebugTrace((char*)"### _GetJobIDScanPara() START! ###\n", 0,0,0,0,0,0);
	NETS_DocJobID s_DocJobID;
	memcpy( &s_DocJobID, pc_DocJobID, sizeof(NETS_DocJobID) );
	free( pc_DocJobID );
	int SocketFd = netc_TwainClientMan.getSocketFd( s_DocJobID.index );
	if ( SocketFd != -1 )
	{
		Bool isRsp = True;
		char pc_ReqData[32];
		if ( ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4)	// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_4である.
		  || ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5 ) 	// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_5である. 	// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya START.
		  || ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6 ) )// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_6である. 	//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start.
		// << 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.
		{
			if ( (s_DocJobID.pc_JobInfoDoc == NULL) || (s_DocJobID.ret == -1) ) {		// 取得失敗 
NetTwainDebugTrace((char*)"# _GetJobIDScanPara_ERR_PARAMETER_ERROR1 #\n", 0,0,0,0,0,0);
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				
				if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4 ) {
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
				} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5 ) {					// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya. 		_GetJobIDScanPara
					strcpy( pc_ReqData, "\x1b*s21119r0V" );	// 設定失敗.
				}else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6 ) {					// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya. 		_GetJobIDScanPara
					strcpy( pc_ReqData, "\x1b*s21121r0V" );	// 設定失敗.
				}
			} else {
				isRsp = False;
				short ss_DocPages = s_DocJobID.pc_JobInfoDoc->pJobStatus->getNumOfOriginals();
				// 指定ページのチェック 
				if ( netc_TwainClientMan.getPageNumber( SocketFd ) > ss_DocPages )
				{
NetTwainDebugTrace((char*)"# _GetJobIDScanPara_ERR_PARAMETER_ERROR2 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 

					if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4 ) {
						strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5 ) {			// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
						strcpy( pc_ReqData, "\x1b*s21119r0V" );	// 設定失敗. 
					} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6 ) {			//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start.
						strcpy( pc_ReqData, "\x1b*s21121r0V" );	// 設定失敗. 
					}

					isRsp = True;
				}
				if ( netc_TwainClientMan.getEndPageNumber( SocketFd ) > ss_DocPages )
				{
NetTwainDebugTrace((char*)"# _GetJobIDScanPara_ERR_PARAMETER_ERROR2 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					
					if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4 ) {
						strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5 ) {			// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
						strcpy( pc_ReqData, "\x1b*s21119r0V" );	// 設定失敗. 
					} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6 ) {			//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start..
						strcpy( pc_ReqData, "\x1b*s21121r0V" );	// 設定失敗. 
					}
					isRsp = True;
				}
				// エラーなしの場合 
				if ( isRsp == False )
				{
					// ジョブの起動をかける 
					netc_TwainClientMan.setHDDPageDataSize( SocketFd, 0 );							// HDD Twain ページデータサイズ 
					netc_TwainClientMan.setImageTransJobStatus( SocketFd, NETE_IMAGETRANS_NONE );	// HDD Twain ジョブ要求受付状態 
					netc_TwainClientMan.setImageTransJobID( SocketFd, 0 );							// HDD Twain ジョブ要求ジョブID 
					netc_TwainClientMan.setImageTransJobType( SocketFd, TYPE_JobTypeCopy );			// HDD Twain ジョブ要求ジョブタイプ 
					netc_TwainClientMan.setEndObserverNotified( SocketFd, False );					// Endオブザーバ通知済み状態.	// 2008.06.23 Harada BugNo.305231.
					netc_TwainClientMan.setState_CancelSync( SocketFd, NETE_CANCELSYNC_NONE );	// キャンセル同期状態を初期化する.		// 2.1c CQ519136 OSP1八代 2015.10.23.

					// 登録可否のチェックを行う 
					ERR_INFORMATION error_info = isHDDTwainAvailable( SocketFd );
					if ( error_info == ERR_NOT_EXIST_ERROR ) {		// 登録を妨げるエラー無し状態 
						// 取得の起動をかける 
						if ( _HDDDocumentAcquire( SocketFd ) == False ) {	// 2007.09.12 Harada チェック追加 
NetTwainDebugTrace((char*)"# _GetJobIDScanPara_ERR_SCAN_JOB_REGIST_ERROR #\n", 0,0,0,0,0,0);
							netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
							netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
							
							if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4 ) {
								strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
							} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5) {		// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya. 		_GetJobIDScanPara
								strcpy( pc_ReqData, "\x1b*s21119r0V" );	// 設定失敗. 
							} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6) {		//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start.
								strcpy( pc_ReqData, "\x1b*s21121r0V" );	// 設定失敗. 
							}
							isRsp = True;		// エラーあり 
						}
					} else {										// 登録を妨げるエラー有り状態 
						netc_TwainClientMan.setClientErrorInfo( SocketFd, error_info , __FILE__ ,__LINE__);			// Error Client Error Info 
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );				// Error Client Error Status.

						if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4 ) {
							strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
						} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5 ) {			// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya. 		_GetJobIDScanPara
							strcpy( pc_ReqData, "\x1b*s21119r0V" );	// 設定失敗. 
						} else if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6 ) {			//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start.
							strcpy( pc_ReqData, "\x1b*s21121r0V" );	// 設定失敗. 
						}
						isRsp = True;		// エラーあり 
					}
				}
			}
			if ( isRsp == True )
			{
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) 		// RREQを受けている 
				{
					if ( ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_4 )		// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_4である.
					  || ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_5 )	// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_5である.		// 2010/2/9 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
					  || ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_SET_HDD_TWAIN_PARAM_6 ) )	// WDATコマンドがSCL_SET_HDD_TWAIN_PARAM_6である.	//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata Start.
					{
						netc_TwainClientMan.setRdatSend( SocketFd , netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
					}
					else
					{
						free( pc_RspData );
					}
				}
			}
		}
	}
}

//==================================================================================================
//[機能]コールバック関数からコールされる関数( SCL_DELETE_BOX コマンド ) 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2005.04.26 Iesato
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_DeleteBox( int id ,int32_t BoxID, int32_t ret )
{
NetTwainDebugTrace((char*)"### ans_DeleteBox() START! ###\n", 0,0,0,0,0,0);
	netc_TwainClientMan.semLock();			// クライアントテーブルを参照・変更するためセマフォをロックする 
	int SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_DELETE_BOX ) {		// WDATコマンドがSCL_DELETE_BOXである
		char pc_ReqData[32];
		if ( ret == APID_DocapiMethodOk ){
			// 成功応答を返す 
			strcpy( pc_ReqData, "\x1b*s35103r1V" );	// 成功応答 
			// CQNo321236 2009/10/05 okabe START. 削除したボックスがTSI振り分け設定されている場合.
			short ss_BoxID = netc_TwainClientMan.getDeleteBoxNo( SocketFd );
			APIC_FaxJobSetting* pc_FaxJobSetting = APIC_FaxJobSetting::newInstance();
			//2013/11/05 [Zeus5BK]OPS1前田 CQ383567 DipSW25 0x00対応.
			TYPE_CommLine e_CommLine = TYPE_CommLineNotUsed;		// for分用.
			pc_FaxJobSetting->lock();
			for( e_CommLine = TYPE_CommLine1; e_CommLine <= TYPE_CommLine4; e_CommLine++ )
			{
				if( TYPE_TsiRoutingErrAct_SpecificBox == pc_FaxJobSetting->getTsiRoutingErrActAll( e_CommLine ) )	// TSI振分け設定:TSIルーティングエラー時の動作.
				{
NetTwainDebugTrace((char*)"### ans_DeleteBox e_CommLine = [%d] ###\n", e_CommLine,0,0,0,0,0);
					if( pc_FaxJobSetting->getTsiRoutingErrSpecificBoxAll( e_CommLine ) == ss_BoxID )			// TSI振分け設定:TSIルーティングエラー時の指定ボックスと一致する？.
					{
NetTwainDebugTrace((char*)"### ans_DeleteBox(Tsi) Match ###\n", 0,0,0,0,0,0);
						pc_FaxJobSetting->setTsiRoutingErrActAll( e_CommLine, TYPE_TsiRoutingErrAct_Print);		// 受信プリントへ変更.
						pc_FaxJobSetting->setTsiRoutingErrSpecificBoxAll( e_CommLine, 0 );						// 指定Boxの値を0へ変更.
					}
				}
			}
			pc_FaxJobSetting->unlock();
			// CQNo321236 2009/10/05 okabe END.
		} else {
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
			strcpy( pc_ReqData, "\x1b*s35103r0V" );	// 失敗応答 
		}
			char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
			if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
					return;
				}
			memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
			netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
			if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
				netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
			}
	}
	netc_TwainClientMan.semUnLock();		// クライアント管理情報のセマフォをアンロックする 
}


