//		SCL_DELETE_BOX					42		// Delete Box.
//==================================================================================================.
//[クラス]NETC_TwainCommandDeleteBox.
//[内容] SCL_DELETE_BOXコマンドを処理するクラス.
//==================================================================================================.
//==================================================================================================.
//[機能]NETC_TwainCommandDeleteBoxのコンストラクタ.
//==================================================================================================.
NETC_TwainCommandDeleteBox::NETC_TwainCommandDeleteBox( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================.
//[機能]コマンドを処理する.
//[履歴] 2005.04.25 Iesato.
//		 2005.09.01 Matsumoto Phase2対応.
//		 2005.06.12 yamahata 単体チェックによる細かい修正.
//		 2010/06/23 amiya 【Minerva】<UV-00939> パスワードの桁数を20~24桁まで増やす対応.
//==================================================================================================.
void NETC_TwainCommandDeleteBox::CommandProc(
	int SocketFd,		// ソケットディスクリプタ.
	char* Parameter,	// パラメータへのポインタ.
	short ParamLength	// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandDeleteBox::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];

	// *** HDD装着のチェックを行う ***.
	if( isCheckAvailableBox() == NETE_Function_Box_Disabled )				// BOX使用可能or一部使用可能のとき.	// 2011/03/31 amiya 【Minerva】管理No941 SSD削減対応（1GB⇒512MB）.
	{
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_HDD_NOT_INSTALLED , __FILE__ ,__LINE__);		// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35103r0V" );											// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	
// 2008.10.02 Donau問題点対応 CQ 309976 平谷 str.
	// 管理者ログイン時は ユーザ・ボックス操作(作成/編集/削除)禁止か否かをチェックしない.
	if ( NULL == netc_TwainClientMan.getApic_Admin( SocketFd ) ) {
NetTwainDebugTrace((char*)"### NETC_TwainCommandDeleteBox:User-BoxOperationCheck_Start!! ###\n", 0,0,0,0,0,0);
		// ユーザ・ボックス操作(作成/編集/削除)禁止か否かをチェックする.
		APIC_SystemSetting* pc_SystemSetting = NULL;
		pc_SystemSetting = APIC_SystemSetting::newInstance();
		pc_SystemSetting->lock();
		Bool bl_UserBoxOperation = pc_SystemSetting->getUserBoxOperation();
		pc_SystemSetting->unlock();
		if ( bl_UserBoxOperation == False )
		{
NetTwainDebugTrace((char*)" bl_UserBoxOperation = False \n",0,0,0,0,0,0);
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
			strcpy( pc_ReqData, "\x1b*s35103r0V" );										// 失敗応答.
			char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
			if( pc_RspData == NULL ){
				errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
				return;
			}
			memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
			netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
			if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
				netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
			}
			return;
		}
	}
// 2008.10.02 Donau問題点対応 CQ 309976 平谷 end.
	
	// ログイン状態のチェック.
	Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
	APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
	Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
	APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
	Bool bl_Result = getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
	if ( bl_Result == False )
	{
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);	// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );				// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35103r0V" );									// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// 監査ログフルのため操作禁止か否かをチェックする.
	APIC_SystemStatus* pc_SystemStatus = NULL;
	pc_SystemStatus = APIC_SystemStatus::newInstance();
	pc_SystemStatus->lock();
	Bool bl_InspectLog = pc_SystemStatus->chkJobStarting( TYPE_JobEnableCheckStatusInspectLogCnt );
	pc_SystemStatus->unlock();
	if ( bl_InspectLog == False )
	{
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SURVEILLANT_LOG_FULL , __FILE__ ,__LINE__);	// 監視ログのサイズが上限のためにジョブの登録、デバイス操作が行えないエラー.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// エラー発生状態とする.
		strcpy( pc_ReqData, "\x1b*s35103r0V" );											// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// *** パラメータからBoxID、パスワードを抜き出す ***.
	int32_t sl_BoxID = 0;								// ボックスID.
	char sc_BoxIDTemp[9+1];							// ボックスID文字列格納領域  boxID：1-999999999.
	memset( sc_BoxIDTemp, 0, sizeof(sc_BoxIDTemp) );
	short ss_BoxPswdLen = 0;						// ボックスパスワード長.
	char sc_BoxPswdLen[NETD_PASSWORD_CARA_SIZE + 1];	// ボックスパスワード長格納領域.	// 2010/06/23 amiya 【Minerva】<UV-00939> パスワードの桁数を20~24桁まで増やす対応.
	memset( sc_BoxPswdLen, 0, sizeof(sc_BoxPswdLen) );
	char sc_BoxPswd[NETD_PASSWORD_SIZE + 1];		// ボックスパスワード格納領域.		// 2010/06/23 amiya 【Minerva】<UV-00939> パスワードの桁数を20~24桁まで増やす対応.
	memset( sc_BoxPswd, 0, sizeof(sc_BoxPswd) );

	Bool bl_is_p_Detected = False;					// パラメータ内に"p"を発見したか否かのフラグ.
	Bool bl_is_X_Detected = False;					// パラメータ内に"X"を発見したか否かのフラグ.
//	Bool bl_isNonPswdDelete = False;				// パスワードなしでのBox削除要求か否かのフラグ.

	// BoxIDの抜き出し.
	int index = 0;
	for ( index = 0; index < 10; index++ ) {		// ボックスIDの抜き出しとパラメータに"p"が存在するか否かの確認.
		if ( Parameter[index] == 'p' ) {	// パラメータ内に"p"があるか否かを判断する.
			sc_BoxIDTemp[index] = '\0';
			index++;
			bl_is_p_Detected = True;		// "p"を発見！.
			break;
		} else if ( Parameter[index] == 'X' ) {	// パラメータ内に"X"が見つかった場合.
			// BoxパスワードなしでのBox削除要求である.
			sc_BoxIDTemp[index] = '\0';
			index++;
			bl_is_X_Detected = True;		// "X"を発見！.
			// break抜け対応 06/05/12 yamahata.
			break;
		}
		sc_BoxIDTemp[index] = Parameter[index];	// パラメータから抜き出し.
	}
	sc_BoxIDTemp[9] = '\0';	// プロテクト.
	sl_BoxID = atol((char*)sc_BoxIDTemp);

	// パスワード長の抜き出し 
	if ( (bl_is_p_Detected == True) && (bl_is_X_Detected == False) ) {			// パラメータに"p"があった場合（"p"フラグTrue、"X"フラグFalse）.
		for ( int pswdLenIndex = 0; pswdLenIndex < 9; pswdLenIndex++ ) {			// psw８byteまで.
			if ( Parameter[index] == 'X' ) {	// パラメータ内に"X"が見つかった場合.
				sc_BoxPswdLen[pswdLenIndex] = '\0';
				index++;
				bl_is_X_Detected = True;		// "X"を発見！.
				break;
			}
			sc_BoxPswdLen[pswdLenIndex] = Parameter[index];
			index++;
		}
		sc_BoxPswdLen[NETD_PASSWORD_CARA_SIZE] = '\0';			// プロテクト.
		ss_BoxPswdLen = (short)atoi((char*)sc_BoxPswdLen);
	} else if ( (bl_is_p_Detected == False) && (bl_is_X_Detected == True) ) {	// "p"がなし、"X"があり.
		ss_BoxPswdLen = 0;
	}

	short pswdLen = 0;
	// Boxパスワードの抜き出し.
	if ( ss_BoxPswdLen != 0 ) {			// Boxパスワード長が0でない場合.
		for ( int pswdIndex = 0; pswdIndex < (NETD_PASSWORD_SIZE + 1); pswdIndex++ ) {	// 2010/06/23 amiya 【Minerva】<UV-00939> パスワードの桁数を20~24桁まで増やす対応.
			// 上のfor文により、pswdIndexが129以上となることはないため、if文の第2条件は不要。条件修正 06/05/12 yamahata.
			if ( pswdIndex >= ss_BoxPswdLen ) {
				sc_BoxPswd[pswdIndex] = '\0';
				index++;
				break;
			}
			sc_BoxPswd[pswdIndex] = Parameter[index];
			index++;
			pswdLen++;
		}
	}

	sc_BoxPswd[NETD_PASSWORD_SIZE] = '\0';		// プロテクト.						// 2010/06/23 amiya 【Minerva】<UV-00939> パスワードの桁数を20~24桁まで増やす対応.
	char sc_Decryption[256];
	memset( sc_Decryption, 0, sizeof(sc_Decryption) );
	memcpy( sc_Decryption, sc_BoxPswd, pswdLen+1 );
	// ボックスID : sl_BoxID 、ボックスパスワード :  sc_BoxPswd にセット抜き出し完了.

	// *** パラメータのチェックをおこなう（ ボックスID : 1-999999999 ) ***.
	if ( ( sl_BoxID < 1 ) || ( 999999999 < sl_BoxID ) ) {
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35103r0V" );											// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	// パスワードデータを確定する。 
	char sc_FixedPassword[256];
	memset( &sc_FixedPassword[0], 0, sizeof(sc_FixedPassword) );
	// SSLの設定状況を確認する 
	APIC_TcpSocketSetting* pc_TcpSocketSetting = NULL;
	pc_TcpSocketSetting = APIC_TcpSocketSetting::newInstance();
	pc_TcpSocketSetting->lock();
	Bool bl_EnableSSL = pc_TcpSocketSetting->getEnableSSL();
	pc_TcpSocketSetting->unlock();
	if ( NetTwainDebugEnableSSLFlag == True )	// 2021/12/28 [IT6_2.2MR2] OP_BTS-37226 HIENG.
	{
		bl_EnableSSL = True;
	}
	if ( bl_EnableSSL == True )		// SSL有効時(パスワード情報が加工されずに送信される場合).
	{
		memcpy( sc_FixedPassword, sc_BoxPswd, pswdLen+1 );
	}
	else							// SSL無効時(パスワード情報が加工された状態で送信される場合).
	{
		if ( pswdLen != 0 )
		{
			APIC_Box* pc_Box = NULL;
			pc_Box = APIC_Box::newInstance();
			pc_Box->setLogIFNo( JLGE_InspectLogIfTCPSocket );
			APIC_BoxInfo pc_BoxInfo;
			pc_Box->setBoxId( sl_BoxID );
			Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
			APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
			Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
			APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
			(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
			int32_t ret = pc_Box->getBoxInfo( pc_UserGet, &pc_BoxInfo, (LIBE_CharSet)APID_DefaultCharSet, pc_TrackGet );
			if ( ret == APID_DocapiMethodOk )	// Box情報正常取得.
			{
				int length = strlen( pc_BoxInfo.sc_BoxPassword );
				char buf[256];
				memset( buf, 0, sizeof(buf) );
				if(netc_TwainClientMan.getChallengeValue( SocketFd ) == NULL){
					errorLog_TwainService("getChallengeValue NULL!!!\n",0,0,0,0,0,0);
					pc_Box->deleteInstance();	// MinervaBK2nd CQ379634(静的解析) ID12661 2013.05.28 OPS1八代.
					return;
				}
				memcpy( &buf[0], netc_TwainClientMan.getChallengeValue( SocketFd ), 16 );
				memcpy( &buf[16], pc_BoxInfo.sc_BoxPassword, length );
				char sc_md5[256];
				memset( sc_md5, 0, sizeof(sc_md5) );
				KM_MD5( (unsigned char*)&buf[0], 16+length, (unsigned char*)&sc_md5[0] );
				if ( memcmp( sc_BoxPswd, sc_md5, 16 ) == 0 )	// 一致した場合.
				{
					memcpy( sc_FixedPassword, pc_BoxInfo.sc_BoxPassword, (strlen(pc_BoxInfo.sc_BoxPassword)) + 1 );		// 20110506 amiya CQ343911 ボックスパスワードが64文字の場合にPSBOからのボックスログインができない対応.
				}
				else											// 一致しない場合.
				{
					sc_FixedPassword[0] = 0x01;		// 入力されないパスワード情報(つまり以降の処理で失敗するように情報を格納する).
				}
			}
			else								// Box情報取得失敗の場合.
			{
				sc_FixedPassword[0] = 0x01;			// 入力されないパスワード情報(つまり以降の処理で失敗するように情報を格納する).
			}
			pc_Box->deleteInstance();							// Boxインスタンスを削除する.
		}
	}
	// *** セキュリティペナルティ状態のチェックを行う ***.
	int32_t sl_ChkAns = 0;	// 2008.05.13 Harada Donau対応 Amur_GCC4.1対応.
	int32_t sl_ret = APIC_BoxRegistry::BoxLogIn_Chk_ErrDetail( pc_UserGet,					// Boxユーザー.
															sc_FixedPassword,			// Boxパスワード.
															sl_BoxID,					// Box番号.
															&sl_ChkAns,					// チェック結果.
															JLGE_InspectLogIfTCPSocket,	// アクセス元情報.
															pc_TrackGet );				// Box所属部門.

	if ( sl_ret != APID_DocapiMethodOk ){			// チェック処理正常終了でない場合 
		if ( sl_ret == APID_DocapiLoginCntErr ){			// ログイン回数失敗エラーの場合 
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_LOGIN_LOCK , __FILE__ ,__LINE__);			// Error Client Error Info.
		}
		else if ( sl_ret == APID_DocapiOwnerAccessErr )		// ユーザー番号不一致またはBox属性権限不一致エラー.
		{
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info.
		}
		else if ( sl_ret == APID_DocapiPasswordAccessErr )	// パスワード不一致エラー 
		{
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info.
		}
		// パスワード規約不正エラー追加により、処理追加 06/05/12 yamahata.
		else if ( sl_ret == APID_DocapiPasswordAgreeErr )	// パスワード規約不正エラー.
		{
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info.
		}
		else												// それ以外.
		{
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
		}
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35103r0V" );											// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	APIC_Box* pc_Box = NULL;
	pc_Box = APIC_Box::newInstance();					// Boxのインスタンスを取得する.
	pc_Box->setLogIFNo( JLGE_InspectLogIfTCPSocket );	// ログ用IF No 登録.
	pc_Box->setBoxId( sl_BoxID );						// インスタンスに Box ID を登録(保持)する.
	int32_t sl_accessState = 0;							// アクセス事象通知フラグ初期化	// 2008.05.13 Harada Donau対応 Amur_GCC4.1対応.
	sl_ret = 0;
	sl_ret = pc_Box->boxUsedChk( &sl_accessState );
	pc_Box->deleteInstance();							// Boxインスタンスを削除する.

	if ( ( sl_ret == APID_DocapiMethodOk) && ( sl_accessState == 1 )) {				// boxUsedChk()の戻り値が正常で、sl_accessStateが1: 設定変更中の場合.
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_BUSY , __FILE__ ,__LINE__);		// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35103r0V" );										// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// Boxを削除する.
	int clientindex = netc_TwainClientMan.getClientIndex( SocketFd );
	if ( clientindex == -1 ) {
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35103r0V" );											// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	
	APIC_BoxRegistry* pc_BoxRegistry = NULL;
	pc_BoxRegistry = APIC_BoxRegistry::newInstance();
	pc_BoxRegistry->setLogIFNo( JLGE_InspectLogIfTCPSocket );					// ログ用IF No 登録.
	sl_ret = 0;
	sl_ret = pc_BoxRegistry->req_deleteBox( pc_UserGet,							// ユーザーインスタンス.
											sc_FixedPassword,					// ボックスパスワード.
											sl_BoxID,							// 指定Ｂｏｘ番号.
											ans_BoxDeleteTable[clientindex],	// コールバックアドレス.
											0,									// ボックス種別.
											pc_TrackGet							// 部門インスタンス.
											);
	pc_BoxRegistry->deleteInstance();								// BoxRegistryインスタンスを削除する.
	netc_TwainClientMan.setDeleteBoxNo( SocketFd, (short)sl_BoxID );		// CQNo321236 2009/10/05 okabe 削除するBoxIDを保存.
	if ( sl_ret != APID_DocapiMethodOk ){							// 正常完了以外.
		if ( ( sl_ret == APID_DocapiOwnerAccessErr )						// オーナー名不正エラー.
		  || ( sl_ret == APID_DocapiPasswordAccessErr ) ){					// パスワード不正エラー.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);			// Error Client Error Info.
		} else {															// その他( 指定番号のBoxなしエラー , その他の処理失敗エラー ).
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info.
		}
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35103r0V" );												// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
}

//==================================================================================================
//[機能]コールバック関数からコールされる関数( SCL_MOVE_DOC コマンド ) 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2005.05.09 Iesato
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_MoveDoc( int id , int32_t ret)
{
NetTwainDebugTrace((char*)" ans_MoveDoc()_Start!! \n", 0,0,0,0,0,0);
	netc_TwainClientMan.semLock();			// クライアントテーブルを参照・変更するためセマフォをロックする 
	int SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_MOVE_DOC ) {		// WDATコマンドがSCL_MOVE_DOCである
		char pc_ReqData[32];
		// コールバックで返って来るエラーパラメータは、DOCC_Common.hの「概要:ReturnCode定義」に記載されている。 
		if ( ret == DOCD_RetOk ){
			// 成功応答を返す 
			strcpy( pc_ReqData, "\x1b*s35106r1V" );	// 成功応答 
		} else {
			// Docの下位で検出するエラーで特出すべきエラーは無いため、Parameter Errorとする。
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);			// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
			strcpy( pc_ReqData, "\x1b*s35106r0V" );	// 失敗応答 
		}
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
	netc_TwainClientMan.semUnLock();		// クライアント管理情報のセマフォをアンロックする 
}


