//		SCL_COPY_DOC				44		// Copy Document 
//==================================================================================================
//[クラス]NETC_TwainCommandCopyDoc 
//[内容] SCL_COPY_DOCコマンドを処理するクラス 
//[履歴] 2005.04.25 Iesato
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandCopyDocのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandCopyDoc::NETC_TwainCommandCopyDoc( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2006.05.22 yamahata コピー元/先のボックス種類チェック後、APIC_BoxRegistryのインスタンスを削除する処理抜け追加 
//==================================================================================================
void NETC_TwainCommandCopyDoc::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandCopyDoc::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	
	// *** HDD装着のチェックを行う ***.
	if( isCheckAvailableBox() == NETE_Function_Box_Disabled )				// BOX使用可能or一部使用可能のとき.	// 2011/03/31 amiya 【Minerva】管理No941 SSD削減対応（1GB⇒512MB）.
	{
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_HDD_NOT_INSTALLED , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	// 2008.08.05 Donau問題点対応 CC 307768 平谷 str.
	} else if ( ( NULL != netc_TwainClientMan.getApic_Admin( SocketFd ) )
		&& ( True == netc_TwainClientMan.getUserLogined( SocketFd ) ) ) {	// 管理者ログイン時は不可.
NetTwainDebugTrace((char*)"# NETC_TwainCommandCopyDoc_ERR_USER_BOX_NOT_SPECIFIED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );	// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	// 2008.08.05 Donau問題点対応 CC 307768 平谷 end.
	
	// 監査ログフルのため操作禁止か否かをチェックする 
	APIC_SystemStatus* pc_SystemStatus = NULL;
	pc_SystemStatus = APIC_SystemStatus::newInstance();
	pc_SystemStatus->lock();
	Bool bl_InspectLog = pc_SystemStatus->chkJobStarting( TYPE_JobEnableCheckStatusInspectLogCnt );
	pc_SystemStatus->unlock();
	if ( bl_InspectLog == False )
	{
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SURVEILLANT_LOG_FULL , __FILE__ ,__LINE__);	// 監視ログのサイズが上限のためにジョブの登録、デバイス操作が行えないエラー 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// エラー発生状態とする 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// Boxログイン状態のチェックを行う 
	if ( netc_TwainClientMan.getBoxLogined( SocketFd ) == False ) {		// Box未ログイン状態 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// ユーザー認証時の操作許可チェックを行う 
	if ( getUserAuthenticationMode() != TYPE_UserAuthenticationOff ) {	// ユーザー認証モードがOFF以外(ONの場合) 
		if ( netc_TwainClientMan.getUserLogined(SocketFd) == True ) {		// ログイン済み 
			APIC_User* pc_User = netc_TwainClientMan.getApic_User( SocketFd );
			if( pc_User == NULL ){
				errorLog_TwainService("pc_User Error\n",0,0,0,0,0,0);
				return;
			}
			pc_User->lock();
			TYPE_FuncLimit e_BoxOperation = pc_User->getFunctionLimitation().e_EnableBoxOperation;		// 2010/08/25 amiya 【Minerva】UV-00458 ユーザー毎のカラー白黒出力制限をコピーとプリントで別々に設定したい対応.
			pc_User->unlock();
			if ( e_BoxOperation == TYPE_FuncLimit_Disable ) {		// 蓄積文書操作不可の場合 
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
				return;
			}
		}
	}

	int32_t sl_DocID = 0;									// コピーするドキュメントID（ユーザジョブ番号） 
	char sc_DocIDTemp[6+1];								// ドキュメントID文字列格納領域  DocID：1-999999
	memset( sc_DocIDTemp, 0, sizeof(sc_DocIDTemp) );
	char sc_DataSize[1+1];								// # : data領域のバイナリデータのバイトサイズ（1Byte) 
	memset( sc_DataSize, 0, sizeof(sc_DataSize) );
	int32_t	sl_CopyBoxID = 0;								// コピー先のBox番号 1-999999999 

	// コピーするDocIDの抜き出し 
	int index = 0;
	// #1 t #2 Y [data] の#1（区切り記号のtまで）を抜き出し、BoxIDを取得する 
	Bool b_CheckFlag = False;								// True：OK , False：NG 
	for ( index = 0; index < 7; index++ ) {
		if ( Parameter[index] == 't' ) {
			sc_DocIDTemp[index] = '\0';							// 't'は抜き出さないで、終端文字セット 
			index++;
			b_CheckFlag = True;									// 't'が発見されたのでTrue 
			break;
		}
		sc_DocIDTemp[index] = Parameter[index];
	}
	sc_DocIDTemp[6] = '\0';										// プロテクト 
	sl_DocID = atoi((char*)sc_DocIDTemp);						// 文字列 → 整数値 

	// 't'発見のチェックをおこなう 
	if ( b_CheckFlag == False ) { 								// 't'が無し 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// #1 t #2 Y [data] の#2（区切り記号のYまで）を抜き出し、[data]領域のサイズを取得する 
	int effectLength = 0;			// #2のデータ長 
	int si_ByteCnt;
	for ( si_ByteCnt = 0; si_ByteCnt < 2; si_ByteCnt++ ) {
		if ( Parameter[index] == 'Y' ) {
			sc_DataSize[si_ByteCnt] = '\0';							// 'Y'は抜き出さないで、終端文字セット 
			index++;
			break;
		}
		sc_DataSize[si_ByteCnt] = Parameter[index];					// パラメータから抜き出し 
		index++;
	}
	effectLength = atoi((char*)sc_DataSize);						// #2のデータ長を数値に変換 

	// #2のデータ長のチェックをおこなう 
	if ( ( ParamLength != short( effectLength + index ) )			// [data]領域のバイトサイズと[data]領域サイズの不一致 
		|| ( effectLength != 4 ) ) {								// #2のデータ長が４以外 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// コピー先のBoxIDの抜き出し 
	int32_t sl_data1 = (Parameter[index]&0xff);
	index++;
	int32_t sl_data2 = (Parameter[index]&0xff) << 8;
	index++;
	int32_t sl_data3 = (Parameter[index]&0xff) << 16;
	index++;
	int32_t sl_data4 = (Parameter[index]&0xff) << 24;
	sl_CopyBoxID = sl_data1 + sl_data2 + sl_data3 + sl_data4;

	// コピー先BoxIDのチェックをおこなう 
	if ( ( sl_CopyBoxID < 1 ) || ( sl_CopyBoxID > 999999999 ) ) {	// Box番号が1～999999999以外 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// ログイン中のBox番号（ コピー元Box）とコマンドのBox番号（コピー先）が同じ場合のチェック 
	if ( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) == sl_CopyBoxID ) {			// コピー元Boxとコピー先Boxが同じ場合 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	} 

	APIC_Box* pc_Box = NULL;
	pc_Box = APIC_Box::newInstance();					// Boxのインスタンスを取得する 
	pc_Box->setLogIFNo( JLGE_InspectLogIfTCPSocket );						// ログ用IF No 登録.
	pc_Box->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );	// インスタンスに コピー元BoxID を登録(保持)する 
	int32_t sl_accessState = 0;							// アクセス事象通知フラグ初期化	// 2008.05.13 Harada Donau対応 Amur_GCC4.1対応.
	int32_t sl_ret = 0;	// 2008.05.13 Harada Donau対応 Amur_GCC4.1対応.
	sl_ret = pc_Box->boxUsedChk( &sl_accessState );

	if ( ( sl_ret == APID_DocapiMethodOk) && ( sl_accessState == 1 )) {		// boxUsedChk()の戻り値が正常で、sl_accessStateが1: 設定変更中の場合 
		pc_Box->deleteInstance();							// Boxインスタンスを削除する
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_BUSY , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// コピー先のBox、Docのチェックをおこなう 
	pc_Box->setBoxId( sl_CopyBoxID );										// コピー先のBoxID を指定する 
	sl_accessState = 0;													// アクセス事象通知フラグ初期化
	sl_ret = 0;
	sl_ret = pc_Box->boxUsedChk( &sl_accessState );

	if ( ( sl_ret == APID_DocapiMethodOk) && ( sl_accessState == 1 )) {		// boxUsedChk()の戻り値が正常で、sl_accessStateが1: 設定変更中の場合 
		pc_Box->deleteInstance();							// Boxインスタンスを削除する
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_BUSY , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// コピー先Boxの情報(BoxInfo)を取得する 
	pc_Box->setBoxId( sl_CopyBoxID );	// コピー先のBoxID を指定する 
	APIC_BoxInfo pc_BoxInfo;
	sl_ret = 0;
	Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
	APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
	Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
	APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
	(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
	sl_ret = pc_Box->getBoxInfo( pc_UserGet, &pc_BoxInfo, (LIBE_CharSet)APID_DefaultCharSet, pc_TrackGet );	// BoxのBoxInfoを取得する 
	if ( sl_ret != APID_DocapiMethodOk) {											// 取得失敗 
		pc_Box->deleteInstance();														// Boxインスタンスを削除する
		if ( sl_ret == APID_DocapiOwnerAccessErr ) {									// オーナー名不正エラー  
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);			// Error Client Error Info 
		} else {																		// その他( 指定番号のBoxなしエラー , その他の処理失敗エラー ) 
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info 
		}
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// コピー先Boxのドキュメント数上限チェックをおこなう 
	pc_Box->setBoxId( sl_CopyBoxID );											// コピー先のBoxID を指定する 
	int32_t sl_count = 0;
	sl_ret = 0;

	APIC_User* pc_CopyUser = NULL;
	if ( ( getUserAuthenticationMode() != TYPE_UserAuthenticationOff ) 			// ユーザー認証モードがONで 
	 	&&  ( netc_TwainClientMan.getUserLogined(SocketFd) == True ) ) {		// ログイン済み 
		pc_CopyUser = netc_TwainClientMan.getApic_User( SocketFd );
	} else {																	// ユーザー認証モードがOFFまたは未ログインの場合 
		pc_CopyUser = APIC_User::newInstance(TYPD_IndexUserPublic);
	}
	sl_ret = pc_Box->getMaxDocCnt( pc_UserGet,									// 既存ユーザー /*  pc_BoxInfo.us_OwnUserID  か */ 
								   pc_BoxInfo.sc_BoxPassword,					// 既存パスワード 
								   &sl_count,									// Docの個数 
								   APID_DocFunc_Non,
								   APID_User_non,
								   pc_TrackGet
								 );

	if ( sl_ret != APID_DocapiMethodOk ) {												// ドキュメント数取得失敗 
		pc_Box->deleteInstance();														// Boxインスタンスを削除する
		if ( ( sl_ret == APID_DocapiOwnerAccessErr )									// オーナー名不正エラー 
		  || ( sl_ret == APID_DocapiPasswordAccessErr ) ) {								// パスワード不正エラー 
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info 
		} else {																		// その他( 指定番号のBoxなしエラー , その他の処理失敗エラー ) 
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
		}
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}
	// 2019/6/21 RQ-560 SSD_1TB 日立 佐藤菜 Start.
	int32_t i32_BoxSaveMaxNum = DOCD_DocFileCntBoxMax;
	APIC_BoxRegistry* pc_BoxRegistry = APIC_BoxRegistry::newInstance();
	if ( NULL != pc_BoxRegistry ){
		i32_BoxSaveMaxNum = pc_BoxRegistry->getBoxSaveMaximumNumber( sl_CopyBoxID );
	}
	// 2019/6/21 RQ-560 SSD_1TB 日立 佐藤菜 End.
	if ( ( sl_count >= i32_BoxSaveMaxNum )											// ドキュメント数が最大値以上である // 2019/6/21 RQ-560 SSD_1TB 日立 佐藤菜.
	  || ( APIC_BoxRegistry::isWarning( APIE_BoxDocumentOver , sl_CopyBoxID ) )		// Box内ドキュメント数Overの警報が発生している 
	  || ( APIC_BoxRegistry::isWarning( APIE_DocumentPageCountOver , -1 ) ) ){		// デバイス内ドキュメント数Overの警報が発生している 
		pc_Box->deleteInstance();													// Boxインスタンスを削除する
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_LIMIT_OF_DOCUMENT , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	// 移動可能かチェックを行う 
	int32_t sl_SearchAns = 0;
	int32_t result = 0;
	if ( NULL != pc_BoxRegistry ){						// OP_BTS-25518 IT6_2.0MR3 静的解析.
		result = pc_BoxRegistry->chkFaxBoxKind( netc_TwainClientMan.getLoginedBoxNo( SocketFd ), &sl_SearchAns );
		if ( result == APID_DocapiMethodOk )
		{
			if ( sl_SearchAns == TYPD_FilingBox )
			{
				pc_Box->deleteInstance();															// Boxインスタンスを削除する
				pc_BoxRegistry->deleteInstance();													// BoxRegistryインスタンスを削除する
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_MOVE_DOC_FROM_SYSTEMBOX , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// Error Client Error Status 
				strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
				return;
			}
		}
		result = pc_BoxRegistry->chkFaxBoxKind( sl_CopyBoxID, &sl_SearchAns );
		if ( result == APID_DocapiMethodOk )
		{
			if ( sl_SearchAns == TYPD_FilingBox )
			{
				pc_Box->deleteInstance();															// Boxインスタンスを削除する
				pc_BoxRegistry->deleteInstance();													// BoxRegistryインスタンスを削除する
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_MOVE_DOC_TO_SYSTEMBOX , __FILE__ ,__LINE__);		// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// Error Client Error Status 
				strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
				return;
			}
		}
		// APIC_BoxRegistryのdeleteInstance()抜けのため、処理追加 06/05/22 yamahata 
		pc_BoxRegistry->deleteInstance();													// BoxRegistryインスタンスを削除する
	}

	// ドキュメントのコピーをおこなう 
	int clientindex = netc_TwainClientMan.getClientIndex( SocketFd );
	if ( clientindex == -1 ) {
		pc_Box->deleteInstance();															// Boxインスタンスを削除する
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
		return;
	}

	int32_t sl_DstDocId = 0;				// コピー先のDocID 	// 2008.05.13 Harada Donau対応 Amur_GCC4.1対応.
	sl_ret = 0;	// 2008.05.13 Harada Donau対応 Amur_GCC4.1対応.
	sl_ret = pc_Box->cpyDoc( netc_TwainClientMan.getApic_User( SocketFd ),					// コピー元Boxユーザー（ログインユーザー） 
							 netc_TwainClientMan.getLoginedBoxPassword( SocketFd ),			// コピー元Boxパスワード（ログインしているBoxのパスワード） 
							 netc_TwainClientMan.getLoginedBoxNo( SocketFd ),				// コピー元DocのBoxID（ログインしているBoxの番号） 
							 sl_DocID,														// コピー元DocID（コマンドパラメータの#1） 
							 pc_CopyUser,													// コピー先Boxユーザー
							 pc_BoxInfo.sc_BoxPassword,										// コピー先Boxパスワード
							 sl_CopyBoxID,													// コピー先のBoxID 
							 &sl_DstDocId,													// 生成したコピー先のDocID (Out) 
							 ans_DocCopyTable[clientindex],									// 上位コールバック関数 
							 pc_TrackGet,
							 pc_TrackGet
							);

	pc_Box->deleteInstance();																// Boxインスタンスを削除する
	if ( sl_ret != APID_DocapiMethodOk ) {													// コピー失敗 
		if ( ( sl_ret == APID_DocapiOwnerAccessErr )										// オーナー名不正エラー 
		  || ( sl_ret == APID_DocapiPasswordAccessErr ) ) {									// パスワード不正エラー 
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);			// Error Client Error Info 
		} else if ( sl_ret == APID_DocapiDocOverErr ){										// Doc数オーバーエラー
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_LIMIT_OF_DOCUMENT , __FILE__ ,__LINE__);		// Error Client Error Info 
		} else {																			// その他( 指定番号のBoxなしエラー , その他の処理失敗エラー ) 
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info 
		}
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );							// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35107r0V" );	// 失敗応答 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
}

//		SCL_DESTROY_BACKUP_TICKET_INFO	45		// Destroy Backup Ticket Information 
//==================================================================================================
//[クラス]NETC_TwainCommandDestroyBackupTicketInfo 
//[内容] SCL_DESTROY_BACKUP_TICKET_INFOコマンドを処理するクラス 
//[履歴]  
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandDestroyBackupTicketInfoのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandDestroyBackupTicketInfo::NETC_TwainCommandDestroyBackupTicketInfo( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2006.05.26 Harada 単体チェックによる細かい修正 
//       2006.09.13 Harada ドキュメント自動削除停止対応 
//                         Backup/Restore中に、ドキュメント自動削除処理によってHDDにアクセスさせない 
//                         ようにする。ここではセマフォを解放する 
//       2007.02.16 Harada バックアップ中状態クリア処理削除 
//                         バックアップ/リストア直後の監査ログ書き込みによりHDDのデータが破壊されて 
//                         しまうので、このタイミングでバックアップ中状態を解除し、HDDアクセスを許可 
//                         するのではなく、リブートまでバックアップ中状態にするため、バックアップ中 
//                         状態クリア処理を削除 
//==================================================================================================
void NETC_TwainCommandDestroyBackupTicketInfo::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandDestroyBackupTicketInfo::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	memset( &pc_ReqData[0], 0, sizeof(pc_ReqData) );
	// 管理者ログイン状態かどうかチェックする 
	// 管理者モードにログインした状態か否かを確認する。 
	APIC_User* pc_User = netc_TwainClientMan.getApic_Admin( SocketFd );					// ログインユーザーインスタンス 
// >> 2008.04.09 Harada Donau対応 No.22 分割バックアップ対応.
	int32_t sl_UserNo = TYPD_IndexUserPublic;	//2013/10/11 【スケーラブルFUM】[CQ383174] 20万人対応. 
	if ( pc_User != NULL ) {
		pc_User->lock();
		sl_UserNo = pc_User->getUserNo();	// ユーザＩＤ取得.
		pc_User->unlock();
	}
// << 2008.04.09 Harada Donau対応 No.22 分割バックアップ対応.
	
//>> 2009/06/15 hiratani Taiga 制御構成変更11対応.
	// Backup可能状態か確認する.
	if ( False == isBackupEnable() )	// 使用不可の場合.
	{
		netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_HDD_NOT_INSTALLED , __FILE__ ,__LINE__);	// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandDestroyBackupTicketInfo::ERR_HDD_NOT_INSTALLED #\n", 0,0,0,0,0,0);
		strcpy( pc_ReqData, "\x1b*s35108r0V" );										// 失敗応答.
	}
//<< 2009/06/15 hiratani Taiga 制御構成変更11対応.
	else if ( (pc_User == NULL) || (sl_UserNo != TYPD_IndexUserAdmin) )				// ログインユーザーインスタンスが無い場合 
	{
		netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s35108r0V" );	// 失敗応答 
	}
	else						// ログインユーザーインスタンスが存在する場合 
	{
		// パラメータ抜き出し 
		char sc_DataSize[20];
		memset( &sc_DataSize[0], 0, sizeof(sc_DataSize) );
		short ss_DataSize = 0;
		char sc_BackupTicket[20];
		memset( &sc_BackupTicket[0], 0, sizeof(sc_BackupTicket) );
		Bool bl_DataSizeFixed = False;
		Bool bl_BackupTicketFixed = False;
		int index = 0;
		for ( int i = 0; i < ParamLength; i++ )
		{
			if ( bl_DataSizeFixed == False )
			{
				if ( Parameter[i] != 'D' )
				{
					sc_DataSize[index] = Parameter[i];
					index++;
					if ( index >= (int)sizeof(sc_DataSize) )
					{
						break;
					}
				}
				else
				{
					sc_DataSize[index] = '\0';
					index = 0;
					bl_DataSizeFixed = True;
					ss_DataSize = (short)atoi((char*)sc_DataSize);
				}
			}
			else
			{
				if ( index < ss_DataSize )
				{
					sc_BackupTicket[index] = Parameter[i];
					index++;
					if ( index >= (int)sizeof(sc_BackupTicket) )
					{
						break;
					}
					if ( i == (ParamLength-1) )
					{
						sc_BackupTicket[index] = '\0';
						index = 0;
						bl_BackupTicketFixed = True;
					}
				}
				else
				{
					break;
				}
			}
		}
		// パラメータチェック 
		if ( ss_DataSize == 0 )
		{
			netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
			strcpy( pc_ReqData, "\x1b*s35108r0V" );	// 失敗応答 
		}
		else if ( bl_BackupTicketFixed == False )		// データ確定しなかった場合 
		{
			netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
			strcpy( pc_ReqData, "\x1b*s35108r0V" );	// 失敗応答 
		}
		else
		{
			if ( memcmp( netc_TwainClientMan.getBackupTicketID(), &sc_BackupTicket[0], BACKUP_TICKET_SIZE ) != 0 )
			{
				netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				strcpy( pc_ReqData, "\x1b*s35108r0V" );	// 失敗応答 
			}
			else
			{
				// OKの場合 
				// 2006.05.26 Harada バックアップ識別ID(チケット)クリア処理追加 
				char sc_tmp[BACKUP_TICKET_SIZE];
				memset( &sc_tmp[0], 0, BACKUP_TICKET_SIZE );
				netc_TwainClientMan.setBackupTicketID( &sc_tmp[0] );	// バックアップ識別ID(チケット) MACアドレス付きの設定 
				strcpy( pc_ReqData, "\x1b*s35108r1V" );	// 成功応答 
				netc_TwainClientMan.setBackupProcessing( False );	// バックアップ中状態の設定 
				// 2007.02.16 Harada バックアップ中状態クリア処理削除 
				// 2007.04.27 Harada HDDバックアップ中断後アプリ接続できない問題対策 
				// リブート設定ONでない場合バックアップ中状態クリア処理追加 
				if ( netc_TwainClientMan.getReboot() == False )		// リブート設定の取得 
				{
					APIC_SystemStatus* pc_SystemStatus = NULL;
					pc_SystemStatus = APIC_SystemStatus::newInstance();
					pc_SystemStatus->lock();
					pc_SystemStatus->setDoBackup( False );
					pc_SystemStatus->unlock();
					// 2006.09.13 Harada ドキュメント自動削除停止対応 
					FILF_HddUnlock();		// HDDの全てのパーティションに対してUnLock処理を行う 
					FILF_SsdUnlock();		// SSDの全てのパーティションに対してUnLock処理を行う.
					// >> 2008.09.19 Harada BugNo.309088 省電力中の分割バックアップ/リストアでFATALとなる問題対策.
					// HDDAccessEndウェイト登録処理追加.

					netc_TwainClientMan.setHddAccessEndWait( SocketFd );

					// << 2008.09.19 Harada BugNo.309088.
				}
			}
		}
	}
	
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

