//==================================================================================================
//[機能]HDDリストアコールバック関数からコールされる関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2005.09.12 Matsumoto 
//      2005.11.17 Tsukiji 引数追加 
//      2006.05.31 Harada メッセージパラメタ変更 リストア結果追加 
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_RestoreHDD( int id, Bool bl_OK )
{
NetTwainDebugTrace((char*)" ans_RestoreHDD()_Start!! \n", 0,0,0,0,0,0);
	netc_TwainClientMan.semLock();		// クライアントテーブルを参照・変更するためセマフォをロックする 
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	// 2006.05.31 Harada メッセージパラメタ変更 リストア結果追加 
	NETS_RestoreHdd* pc_RestoreHdd = (NETS_RestoreHdd*)malloc( sizeof(NETS_RestoreHdd) );
	if( pc_RestoreHdd == NULL ){
		errorLog_TwainService("pc_RestoreHdd_malloc Error\n",0,0,0,0,0,0);
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
		return;
	}
	pc_RestoreHdd->index = id;
	pc_RestoreHdd->ret = bl_OK;
	netc_TwainService->setPacketData( NETE_TWAIN_RESTORE_HDD,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
//									  (void*)pl_Data );
									  (void*)pc_RestoreHdd );
	netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
}

