//==================================================================================================
//[機能]HDDリストアコールバック関数からコールされる関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2005.09.12 Matsumoto 
//      2006.05.31 Harada 結果判断、結果失敗時処理追加 
//==================================================================================================
void _ReqRestoreHDD(
	NETS_RestoreHdd* pc_RestoreHdd
)
{
NetTwainDebugTrace((char*)" _ReqRestoreHDD()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	memset( &pc_ReqData[0], 0, sizeof(pc_ReqData) );

	if ( pc_RestoreHdd != NULL )
	{
		NETS_RestoreHdd s_RestoreHdd;
		memcpy( &s_RestoreHdd, pc_RestoreHdd, sizeof(NETS_RestoreHdd) );
		free( pc_RestoreHdd );
		int SocketFd = netc_TwainClientMan.getSocketFd( s_RestoreHdd.index );	// ソケットFDの取得(管理インデックスを指定して取得) 
		if ( SocketFd != -1 )
		{
			if ( s_RestoreHdd.ret == True )		// 成功 
			{
				strcpy( pc_ReqData, "\x1b*s35130r1V" );	// 成功応答 
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
				// bl_UsedBuf：バッファのデータをリストア先に書き込み終えたらFalseにする。 
				netsDataBuf.bl_UsedBuf = False;										// バッファ未使用に設定する
				netc_TwainClientMan.setRestoreStartSectorNum( netc_TwainClientMan.getRestoreEndSectorNum() + 1 );
// >> 2008.02.24 Harada Donau対応 No.22 分割バックアップ対応.
				// リストアデータ番号の更新.
				netc_TwainClientMan.setRestoreDataNum( netc_TwainClientMan.getRestoreDataNum()+1 );
// << 2008.02.24 Harada Donau対応 No.22 分割バックアップ対応.
			}
			else								// 失敗 
			{
				// 2006.05.31 Harada 結果失敗時処理追加 
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );				// Error Client Error Status 

				strcpy( pc_ReqData, "\x1b*s35130r0V" );	// 失敗応答 
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
				// bl_UsedBuf：バッファのデータをリストア先に書き込み終えたらFalseにする。 
				netsDataBuf.bl_UsedBuf = False;										// バッファ未使用に設定する
				netc_TwainClientMan.setRestoreEnd( SocketFd , True );				// リストア全回数終了 
			}
		}
	}
}

