			for ( i = 0; i < 10; i++ )
			{
				if ( pc_BackupMediaManageData->sl_HDDStartSector[i] != -1 )
				{
					// 2006.05.25 Harada 「終了セクタ－開始セクタ」では 1足りないので +1 するように修正 
NetTwainDebugTrace((char*)"### pc_BackupMediaManageData->sl_HDDStartSector[ %d ] = %d ###\n",i,pc_BackupMediaManageData->sl_HDDStartSector[i],0,0,0,0);
NetTwainDebugTrace((char*)"### pc_BackupMediaManageData->sl_HDDEndSector[ %d ]   = %d ###\n",i,pc_BackupMediaManageData->sl_HDDEndSector[i],0,0,0,0);
					int32_t sl_HDDSector = (pc_BackupMediaManageData->sl_HDDEndSector[i] - pc_BackupMediaManageData->sl_HDDStartSector[i]) + 1;
NetTwainDebugTrace((char*)"### sl_HDDSector = %d ###\n",sl_HDDSector,0,0,0,0,0);
					sl_TotalHDDSector += sl_HDDSector;
NetTwainDebugTrace((char*)"### sl_TotalHDDSector = %d ###\n",sl_TotalHDDSector,0,0,0,0,0);
					int32_t sl_SendSector = (sl_HDDSector / 2048) * 2048;
NetTwainDebugTrace((char*)"### sl_SendSector = %d ###\n",sl_SendSector,0,0,0,0,0);
					if ( (sl_HDDSector % 2048) != 0 )
					{
NetTwainDebugTrace((char*)"### (sl_HDDSector% 2048) != 0 ###\n",0,0,0,0,0,0);
						sl_SendSector += 2048;
					}
NetTwainDebugTrace((char*)"### sl_SendSector = %d ###\n",sl_SendSector,0,0,0,0,0);
					sl_TotalSendSector += sl_SendSector;
				}
			}
NetTwainDebugTrace((char*)"### sl_TotalHDDSector = %d ###\n",sl_TotalHDDSector,0,0,0,0,0);
NetTwainDebugTrace((char*)"### sl_TotalSendSector = %d ###\n",sl_TotalSendSector,0,0,0,0,0);

// >> 2008.02.24 Harada Donau対応 No.22 分割バックアップ対応.
			// 領域確保 
			NETS_BackupMediaInfo nets_BackupMediaInfo[2];	// ALL / BOXデータ.
			// 領域を初期化する 
