NetTwainDebugTrace((char*)"### Full Backup ###\n",0,0,0,0,0,0);
			// 全体バックアップ.
			nets_BackupMediaInfo[0].sc_BackupMediaID = 1;										// Backup Media 番号.
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupMediaID = %d ###\n",nets_BackupMediaInfo[0].sc_BackupMediaID,0,0,0,0,0);
			nets_BackupMediaInfo[0].uc_BackupMediaKind = 0xFF;									// Backup Media 種類.
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].uc_BackupMediaKind = %02x ###\n",nets_BackupMediaInfo[0].uc_BackupMediaKind,0,0,0,0,0);
			if ( bl_HDDExist == True )
			{	// HDD装着時 
				strcpy( &nets_BackupMediaInfo[0].sc_BackupMediaName[0], "NVRAM, FLASH, HDD" );	// Backup Media 名.
			}
			else
			{	// HDD非装着時 
				strcpy( &nets_BackupMediaInfo[0].sc_BackupMediaName[0], "NVRAM, FLASH" );		// Backup Media 名.
			}
if ( nets_BackupMediaInfo[0].sc_BackupMediaName[0] == '\0' ) {
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupMediaName[] = NULL ###\n",0,0,0,0,0,0);
} else {
	for ( uint32_t j=0; j < strlen(nets_BackupMediaInfo[0].sc_BackupMediaName); j++ ) {
		char tmpID = nets_BackupMediaInfo[0].sc_BackupMediaName[j];
		if ( tmpID == 0x00 ) { break; }
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupMediaName[%d] = [%c][%02x] ###\n",
		j,( (('0' <= tmpID) && (tmpID <= '9')) || (('A' <= tmpID) && (tmpID <= 'Z')) || (('a' <= tmpID) && (tmpID <= 'z')) ? tmpID : '?' ),(tmpID & 0x000000ff),0,0,0);
	}
}
			int32_t sl_StorageSize = 0;
			sl_StorageSize = (sl_TotalNVSize / 1024) + (sl_TotalFlashSize / 1024)				// 2006.11.20 Harada 中間認証対応.
						   + (sl_TotalSendSector / 2);											// 単位：キロバイト(KByte) 1セクタ=512バイト->セクタ数×512/1024->セクタ数/2->キロバイトに変換.
			sl_StorageSize = sl_StorageSize + 1*(1024*1024/1024);								// 初回 チェックデータ 1MB分を加算 単位：キロバイト(KByte) // 2006.07.14 Harada.
			nets_BackupMediaInfo[0].sc_BackupMediaSize[0] =  (char)(sl_StorageSize        & 0xFF);		// Backup Media Size (KByte).
			nets_BackupMediaInfo[0].sc_BackupMediaSize[1] = (char)((sl_StorageSize >>  8) & 0xFF);		// Backup Media Size (KByte).
			nets_BackupMediaInfo[0].sc_BackupMediaSize[2] = (char)((sl_StorageSize >> 16) & 0xFF);		// Backup Media Size (KByte).
			nets_BackupMediaInfo[0].sc_BackupMediaSize[3] = (char)((sl_StorageSize >> 24) & 0xFF);		// Backup Media Size (KByte).
NetTwainDebugTrace((char*)"### sl_StorageSize = %d ###\n",sl_StorageSize,0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupMediaSize[0] = %02x ###\n",nets_BackupMediaInfo[0].sc_BackupMediaSize[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupMediaSize[1] = %02x ###\n",nets_BackupMediaInfo[0].sc_BackupMediaSize[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupMediaSize[2] = %02x ###\n",nets_BackupMediaInfo[0].sc_BackupMediaSize[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupMediaSize[3] = %02x ###\n",nets_BackupMediaInfo[0].sc_BackupMediaSize[3],0,0,0,0,0);
			int32_t sl_TransferSize = 1049088;														// 1MByte(1024*1024=1048576) + 512Byte = 1049088.
			nets_BackupMediaInfo[0].sc_BackupTransferSize[0] = (char)( sl_TransferSize        & 0xFF);	// Backup Transfer Size (Byte).
			nets_BackupMediaInfo[0].sc_BackupTransferSize[1] = (char)((sl_TransferSize >>  8) & 0xFF);	// Backup Transfer Size (Byte).
			nets_BackupMediaInfo[0].sc_BackupTransferSize[2] = (char)((sl_TransferSize >> 16) & 0xFF);	// Backup Transfer Size (Byte).
			nets_BackupMediaInfo[0].sc_BackupTransferSize[3] = (char)((sl_TransferSize >> 24) & 0xFF);	// Backup Transfer Size (Byte).
NetTwainDebugTrace((char*)"### sl_TransferSize = %d ###\n",sl_TransferSize,0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupTransferSize[0] = %02x ###\n",nets_BackupMediaInfo[0].sc_BackupTransferSize[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupTransferSize[1] = %02x ###\n",nets_BackupMediaInfo[0].sc_BackupTransferSize[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupTransferSize[2] = %02x ###\n",nets_BackupMediaInfo[0].sc_BackupTransferSize[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_BackupTransferSize[3] = %02x ###\n",nets_BackupMediaInfo[0].sc_BackupTransferSize[3],0,0,0,0,0);
			// 2006.05.25 Harada 転送回数算出方法変更 
			int32_t sl_TransferNumber = sl_StorageSize / ((sl_TransferSize - 512) / 1024);			// 1MBずつ転送するので、転送回数は1MB単位化した場合の回数(切り上げ).
NetTwainDebugTrace((char*)"### sl_TransferNumber = %d ###\n",sl_TransferNumber,0,0,0,0,0);
			int32_t sl_rem = sl_StorageSize % ((sl_TransferSize - 512) / 1024);					// Backup Media Size / 転送回数 の余り.
NetTwainDebugTrace((char*)"### sl_rem = %d ###\n",sl_rem,0,0,0,0,0);
			if (sl_rem != 0) {																	// Backup Media Size / 転送回数 の余りがある場合、転送回数+1.
NetTwainDebugTrace((char*)"### sl_rem != 0 ###\n",0,0,0,0,0,0);
				sl_TransferNumber++;
			}
			nets_BackupMediaInfo[0].sc_TransferNum[0] =  (char)(sl_TransferNumber        & 0xFF);		// Transfer Number of Times (転送回数).
			nets_BackupMediaInfo[0].sc_TransferNum[1] = (char)((sl_TransferNumber >>  8) & 0xFF);		// Transfer Number of Times (転送回数).
			nets_BackupMediaInfo[0].sc_TransferNum[2] = (char)((sl_TransferNumber >> 16) & 0xFF);		// Transfer Number of Times (転送回数).
NetTwainDebugTrace((char*)"### sl_TransferNumber = %d ###\n",sl_TransferNumber,0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_TransferNum[0] = %02x ###\n",nets_BackupMediaInfo[0].sc_TransferNum[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_TransferNum[1] = %02x ###\n",nets_BackupMediaInfo[0].sc_TransferNum[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupMediaInfo[0].sc_TransferNum[2] = %02x ###\n",nets_BackupMediaInfo[0].sc_TransferNum[2],0,0,0,0,0);
			// 2006.05.25 Harada Backup Data Size算出方法変更 
			int32_t sl_BackupDataSize = (sl_TransferNumber * ((sl_TransferSize-512) / 1024)) + ((sl_TransferNumber * 512) / 1024);
			sl_rem = ((sl_TransferNumber * 512) % 1024);
