//==================================================================================================
//[機能]HDDバックアップコールバック関数からコールされる関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2005.09.12 Matsumoto 
//      2006.05.31 Harada 結果判断、結果失敗時処理追加 
//==================================================================================================
void _ReqBackupHDD(
//	int32_t* pl_Data	// クライアント管理インデックス番号 
	NETS_BackupHdd* pc_BackupHdd
)
{
NetTwainDebugTrace((char*)"### _ReqBackupHDD() START! ###\n",0,0,0,0,0,0);
	char pc_ReqData[32];
	memset( &pc_ReqData[0], 0, sizeof(pc_ReqData) );

//	if ( pl_Data != NULL )
	if ( pc_BackupHdd != NULL )
	{
		NETS_BackupHdd s_BackupHdd;
		memcpy( &s_BackupHdd, pc_BackupHdd, sizeof(NETS_BackupHdd) );
		free( pc_BackupHdd );
		int SocketFd = netc_TwainClientMan.getSocketFd( s_BackupHdd.index );	// ソケットFDの取得(管理インデックスを指定して取得) 
		if ( SocketFd != -1 )
		{
			if ( s_BackupHdd.ret == True )		// 成功 
			{
				// 応答データのバックアップデータ構造体のヘッダ情報を作成する 
				NETS_BackupDataInfo s_BackupDataInfo;
				memset( &s_BackupDataInfo, 0, sizeof(NETS_BackupDataInfo) );
				int32_t sl_BackupDataNum = netc_TwainClientMan.getBackupDataNum();
NetTwainDebugTrace((char*)"### # sl_BackupDataNum = %d # ###\n",sl_BackupDataNum,0,0,0,0,0);
				s_BackupDataInfo.uc_BackupDataNumber[0] = (unsigned char)( sl_BackupDataNum        & 0xFF);
				s_BackupDataInfo.uc_BackupDataNumber[1] = (unsigned char)((sl_BackupDataNum >>  8) & 0xFF);
				s_BackupDataInfo.uc_BackupDataNumber[2] = (unsigned char)((sl_BackupDataNum >> 16) & 0xFF);
				s_BackupDataInfo.uc_BackupDataNumber[3] = (unsigned char)((sl_BackupDataNum >> 24) & 0xFF);
				int32_t sl_BakupDataSize = 1024*1024;	// 1MB 
				s_BackupDataInfo.uc_BackupDataSize[0] = (unsigned char)( sl_BakupDataSize        & 0xFF);
				s_BackupDataInfo.uc_BackupDataSize[1] = (unsigned char)((sl_BakupDataSize >>  8) & 0xFF);
				s_BackupDataInfo.uc_BackupDataSize[2] = (unsigned char)((sl_BakupDataSize >> 16) & 0xFF);
				s_BackupDataInfo.uc_BackupDataSize[3] = (unsigned char)((sl_BakupDataSize >> 24) & 0xFF);

				char tmp[128];
				memset( &tmp[0], 0, sizeof(tmp) );
				sprintf( tmp, "\x1b*s35113t1049088W" );

				memcpy( &netsDataBuf.sc_Buf[strlen(tmp)], &s_BackupDataInfo, sizeof(NETS_BackupDataInfo) );

				// チェックサムを計算する 
				// 2006.09.14 Harada チェックサム計算修正 
				unsigned short us_CheckSum = 0;
				unsigned char  uc_CheckSum = 0;		// キャスト用変数.
				int32_t sl_DataSize = (int32_t)(strlen(tmp)+(int32_t)sizeof(NETS_BackupDataInfo)+1024*1024);
				int32_t index = strlen(tmp);
				while ( index < (int32_t)sl_DataSize )
				{
					uc_CheckSum = (unsigned char)netsDataBuf.sc_Buf[index];
					us_CheckSum = (unsigned short)(us_CheckSum + uc_CheckSum);
					index++;
				}
				netsDataBuf.sc_Buf[510+strlen(tmp)] = (char)( us_CheckSum       & 0xFF);
				netsDataBuf.sc_Buf[511+strlen(tmp)] = (char)((us_CheckSum >> 8) & 0xFF);
				netc_TwainClientMan.setBackupDataNum( sl_BackupDataNum + 1 );
				netc_TwainClientMan.setBackupStartSectorNum( netc_TwainClientMan.getBackupEndSectorNum() + 1 );
				netc_TwainClientMan.setBackupDataRspExist( True );
				netc_TwainClientMan.setBackupAllDataSize( strlen(tmp)+1049088 );		// 1回のWDATコマンド(GetBackupData)送信にて送信する総サイズの設定 
				netc_TwainClientMan.setSendData( SocketFd, &netsDataBuf.sc_Buf[0], (uint32_t)(strlen(tmp)+1049088), False );		// 送信データ保持領域に書き込む 
NetTwainDebugTrace((char*)"### # setSendData() # ###\n",0,0,0,0,0,0);
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True )
				{
NetTwainDebugTrace((char*)"### # setSendBackupData() # ###\n",0,0,0,0,0,0);
					netc_TwainClientMan.setSendBackupData( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ) );
				}
			}
			else								// 失敗 
			{
				// 2006.05.31 Harada 結果失敗時処理追加 
				netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );				// Error Client Error Status 
				netc_TwainClientMan.setBackupDataRspExist( False );

				strcpy( pc_ReqData, "\x1b*s35113tN" );	// 失敗応答 
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
			}
		}
	}
}

//		SCL_GET_BACKUP_DATA				53		// Get Backup Data 2.
//==================================================================================================.
//[クラス]NETC_TwainCommandGetBackupData.
//[内容] SCL_GET_BACKUP_DATAコマンドを処理するクラス.
