// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋 Start.
//==================================================================================================
//[機能]サムネイル画像生成によるBOXアクセスログ追加関数.
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2016.07.08 Sky大嶋.
//==================================================================================================
void addOpeLogThumbnailImage(int si_SocketFd, TYPE_ThumbnailResult e_Result, uint32_t ul_AcceptNum)
{
	JLGS_OpeLogCom s_OpeLogCom;
	JLGS_OpeLogFileAccess s_OpeLogFileAccess;
	
	memset(&s_OpeLogCom, 0x00, sizeof(s_OpeLogCom));

	APIC_JLG* p_Jlg = APIC_JLG::newInstance();
	
	p_Jlg->getNowTime(&s_OpeLogCom.s_Time);
	s_OpeLogCom.ul_Code			= JLGE_InspectLogReadBoxDoc;
	s_OpeLogCom.uc_IF			= JLGE_InspectLogIfTCPSocket;
	s_OpeLogCom.us_Result		= (TYPE_ThumbnailResult_OK == e_Result) ? JLGE_InspectLogResultOK : JLGE_InspectLogResultNG;
	s_OpeLogCom.us_EventType	= getEventTypeByResultCode( s_OpeLogCom.us_Result );
	
	// ユーザログイン状態時のみ、ユーザ情報を設定.
	if(netc_TwainClientMan.getUserLogined(si_SocketFd)){
		APIC_User* pc_LogInUser = netc_TwainClientMan.getApic_User(si_SocketFd);
		if(pc_LogInUser){
			pc_LogInUser->lock();
			s_OpeLogCom.ul_OpeCode = pc_LogInUser->getUserNo();
			pc_LogInUser->getUserNameUTF8(s_OpeLogCom.sc_Name);
			pc_LogInUser->getServerName(s_OpeLogCom.sc_ExtServerName);
			pc_LogInUser->unlock();
		}
	}
	
	// 部門ログイン状態時のみ、部門情報を設定.
	if(netc_TwainClientMan.getAccountLogined(si_SocketFd)){
		APIC_Track* pc_LogInTrack = netc_TwainClientMan.getApic_Track(si_SocketFd);
		if(pc_LogInTrack){
			pc_LogInTrack->lock();
			s_OpeLogCom.ul_TrackCode = pc_LogInTrack->getTrackLogNo();
			pc_LogInTrack->getTrackName(s_OpeLogCom.sc_TrackName);
			pc_LogInTrack->unlock();
		}
	}

	s_OpeLogFileAccess.sl_BoxNo = netc_TwainClientMan.getLoginedBoxNo(si_SocketFd);
// 2016/08/23 SCD2-Sky Kawanishi [SecV2]Warning除去対応.
	const NETS_TwainClientThumbnailInfo* p_Info = netc_TwainClientMan.getThumbnailInfo(si_SocketFd);
	if( p_Info && 
		ul_AcceptNum == p_Info->ul_ReqId ){
		s_OpeLogFileAccess.sl_DocNo = p_Info->sl_DocId;
		APIC_Doc::newInstance()->getDocName(s_OpeLogFileAccess.sl_DocNo, s_OpeLogFileAccess.sl_BoxNo, reinterpret_cast<char*>(s_OpeLogFileAccess.uc_DocName), sizeof(s_OpeLogFileAccess.uc_DocName), LIBE_CharSet(-1));
	}else{
		// ドキュメントID不明の場合、無効値（ULONG_MAX）を指定し、ドキュメント名は未取得とする.
		s_OpeLogFileAccess.sl_DocNo = (int32_t)ULONG_MAX;
	}
	
	p_Jlg->addOpeLogFileAccess(&s_OpeLogCom, &s_OpeLogFileAccess);
}
// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋 End.

//==================================================================================================
//[機能]サムネイルコールバック関数からコールされる関数 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2005.09.01 Matsumoto 
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================
void ans_getThumbnailData( int id, uint32_t ul_AcceptNum, TYPE_ThumbnailResult e_Result, TYPS_ActualThumbnailPara s_ActualThumbnailPara )
{
NetTwainDebugTrace((char*)" ans_getThumbnailData()_Start!! \n", 0,0,0,0,0,0);
	netc_TwainClientMan.semLock();		// クライアントテーブルを参照・変更するためセマフォをロックする 
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();

// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋 Start.
	addOpeLogThumbnailImage(si_SocketFd, e_Result, ul_AcceptNum);
// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋 End.

	NETS_GetThumbnail* pc_GetThumbnail = (NETS_GetThumbnail*)malloc( sizeof(NETS_GetThumbnail) );
	if( pc_GetThumbnail == NULL ){
		errorLog_TwainService("pc_GetThumbnail_malloc Error\n",0,0,0,0,0,0);
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
		return;
	}
	pc_GetThumbnail->index = id;
	pc_GetThumbnail->ul_AcceptNum = ul_AcceptNum;
	pc_GetThumbnail->e_Result = e_Result;
	memcpy( (void*)&pc_GetThumbnail->s_ActualThumbnailPara, &s_ActualThumbnailPara, sizeof(TYPS_ActualThumbnailPara) );
	netc_TwainService->setPacketData( NETE_TWAIN_GET_THUMBNAIL,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
									  (void*)pc_GetThumbnail );
	netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする 
}

