//==================================================================================================
//[機能]Thumbnail取得用のコールバック関数を処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2006.02.10 Matsumoto 
//		2006.07.18 yamahata 正常系の応答内容修正 
//==================================================================================================
void _GetThumbnailData( NETS_GetThumbnail* pc_GetThumbnail )
{
NetTwainDebugTrace((char*)"### _GetThumbnailData() START! ###\n", 0,0,0,0,0,0);
	if ( pc_GetThumbnail != NULL )		// メッセージデータがNULLで無い場合 
	{
		NETS_GetThumbnail s_GetThumbnail;
		memcpy( &s_GetThumbnail, pc_GetThumbnail, sizeof(NETS_GetThumbnail ) );
		free( pc_GetThumbnail );
		int SocketFd = netc_TwainClientMan.getSocketFd( s_GetThumbnail.index );

NetTwainDebugTrace((char*)"### index        = %d ####\n",s_GetThumbnail.index,0,0,0,0,0);
NetTwainDebugTrace((char*)"### ul_AcceptNum = %d ####\n",s_GetThumbnail.ul_AcceptNum,0,0,0,0,0);
NetTwainDebugTrace((char*)"### e_Result     = %d ####\n",s_GetThumbnail.e_Result,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_ActualThumbnailPara.e_ImageTone               = %d ####\n",s_GetThumbnail.s_ActualThumbnailPara.e_ImageTone,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_ActualThumbnailPara.ss_ImageDotSizeWidth      = %d ####\n",s_GetThumbnail.s_ActualThumbnailPara.ss_ImageDotSizeWidth,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_ActualThumbnailPara.ss_ImageTransDotSizeWidth = %d ####\n",s_GetThumbnail.s_ActualThumbnailPara.ss_ImageTransDotSizeWidth,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_ActualThumbnailPara.ss_ImageDotSizeHight      = %d ####\n",s_GetThumbnail.s_ActualThumbnailPara.ss_ImageDotSizeHight,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_ActualThumbnailPara.psc_ImageDataPointer      = 0x%p ####\n",reinterpret_cast<intptr_t>(s_GetThumbnail.s_ActualThumbnailPara.psc_ImageDataPointer),0,0,0,0,0);			
NetTwainDebugTrace((char*)"### s_ActualThumbnailPara.pImageFile                = 0x%p ####\n",reinterpret_cast<intptr_t>(s_GetThumbnail.s_ActualThumbnailPara.pImageFile),0,0,0,0,0);					
NetTwainDebugTrace((char*)"### s_ActualThumbnailPara.ul_ImageDataPointerOffset = %d ####\n",s_GetThumbnail.s_ActualThumbnailPara.ul_ImageDataPointerOffset,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_ActualThumbnailPara.ul_TotalDataSize          = %d ####\n",s_GetThumbnail.s_ActualThumbnailPara.ul_TotalDataSize,0,0,0,0,0);

		if ( s_GetThumbnail.e_Result == TYPE_ThumbnailResult_OK )		// 正常終了 
		{
			// 正常終了時の処理(クライアントへの応答データを設定する) 
			// >>正常系の応答内容修正(サムネイルデータのみ→Esc * s 21111 t <size of data> W [Thumnail Image Data]) 06/07/18 yamahata
			char tmp[64];
			memset( &tmp[0], 0, sizeof(tmp) );
			uint32_t ul_TotalDataSize = s_GetThumbnail.s_ActualThumbnailPara.ul_TotalDataSize;
			char* psc_ImageDataPointer = s_GetThumbnail.s_ActualThumbnailPara.psc_ImageDataPointer;
			sprintf( tmp, "\x1b*s21111t%ldW", ul_TotalDataSize );
			char* pc_RspData = (char*)malloc( strlen(tmp)+ul_TotalDataSize );
			if( pc_RspData == NULL ) {
				// 領域解放 
				free(psc_ImageDataPointer);
NetTwainDebugTrace((char*)"### _GetThumbnailData_ERR_MEMORY_OVERFLOW ###\n", 0,0,0,0,0,0);
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_MEMORY_OVERFLOW , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				char pc_ReqData[32];
				memset( &pc_ReqData[0], 0, sizeof(pc_ReqData) );
				strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
				pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
			} else {
				memcpy( pc_RspData, tmp, strlen(tmp) );
				memcpy( &pc_RspData[strlen(tmp)], psc_ImageDataPointer, ul_TotalDataSize );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(tmp)+ul_TotalDataSize );		// 送信データ保持領域に書き込む 
				// 領域解放 
				free(psc_ImageDataPointer);

				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
			}
			// <<正常系の応答内容修正(サムネイルデータのみ→Esc * s 21111 t <size of data> W [Thumnail Image Data]) 06/07/18 yamahata
		}
		else											// 正常終了以外の場合 
		{
			switch ( s_GetThumbnail.e_Result )
			{
				case TYPE_ThumbnailResult_NG:				// 失敗 
NetTwainDebugTrace((char*)"### _GetThumbnailData_ERR_PARAMETER_ERROR1 ###\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					break;
				case TYPE_ThumbnailResult_MemoryOver:		// メモリオーバー 
NetTwainDebugTrace((char*)"### _GetThumbnailData_ERR_PARAMETER_ERROR2 ###\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					break;
				case TYPE_ThumbnailResult_Nothing:			// ドキュメントが存在しない 
NetTwainDebugTrace((char*)"### _GetThumbnailData_ERR_PARAMETER_ERROR3 ###\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					break;
				case TYPE_ThumbnailResult_OutOfSupport:		// サポート外 
NetTwainDebugTrace((char*)"### _GetThumbnailData_ERR_PARAMETER_ERROR4 ###\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					break;
				default:
NetTwainDebugTrace((char*)"### _GetThumbnailData_ERR_PARAMETER_ERROR5 ###\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					break;
			}
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
			char pc_ReqData[32];
			memset( &pc_ReqData[0], 0, sizeof(pc_ReqData) );
			strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
			char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
			if( pc_RspData == NULL ){
				errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
				// 2016/10/07 第2システム深谷 1002990 静的解析対応（指摘ID：25884/25885） START.
				if( s_GetThumbnail.s_ActualThumbnailPara.psc_ImageDataPointer != NULL ){
					free( s_GetThumbnail.s_ActualThumbnailPara.psc_ImageDataPointer );
					s_GetThumbnail.s_ActualThumbnailPara.psc_ImageDataPointer = NULL;
				}
				// 2016/10/07 第2システム深谷 1002990 静的解析対応（指摘ID：25884/25885） END.
				return;
			}
			memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
			netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
			if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
				netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
			}
			// 2016/10/07 第2システム深谷 1002990 静的解析対応（指摘ID：25884/25885） START.
			if( s_GetThumbnail.s_ActualThumbnailPara.psc_ImageDataPointer != NULL ){
				free( s_GetThumbnail.s_ActualThumbnailPara.psc_ImageDataPointer );
				s_GetThumbnail.s_ActualThumbnailPara.psc_ImageDataPointer = NULL;
			}
			// 2016/10/07 第2システム深谷 1002990 静的解析対応（指摘ID：25884/25885） END.
		}
	}
	else								// メッセージデータがNULLの場合 
	{
NetTwainDebugTrace((char*)"### [ERR]_GetThumbnailData()_Message Data is NULL ###\n", 0,0,0,0,0,0);

	}
}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2006.02.10 Matsumoto 
//==================================================================================================
void NETC_TwainCommandGetThumbnail::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetThumbnail::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	// パラメータを一時的に構造体へコピーする 
	NETS_GetThumbnailParam s_GetThumbnailParam;
	memset( &s_GetThumbnailParam, 0, sizeof(NETS_GetThumbnailParam) );
	memcpy( &s_GetThumbnailParam, &Parameter[0], sizeof(NETS_GetThumbnailParam) );

	// 設定パラメータをローカルに保持 
	int32_t DocID = 0;			// ドキュメントID 
	short PageData = 1;		// 指定ページ 
	short DotSizeX = 0;		// ドットサイズ(X) 
	short DotSizeY = 0;		// ドットサイズ(Y) 
	short Format = 0;		// フォーマット 

	memcpy( &DocID, &s_GetThumbnailParam.sc_DocumentNo[0], 4 );
	DocID = (int32_t)ULtoLE( DocID );
NetTwainDebugTrace((char*)"### DocID = [%d] ####\n",DocID,0,0,0,0,0);

	memcpy( &PageData, &s_GetThumbnailParam.sc_PageNo[0], 2 );
	PageData = SStoLE( PageData );
NetTwainDebugTrace((char*)"### PageData = [%d] ####\n",PageData,0,0,0,0,0);

	memcpy( &DotSizeX, &s_GetThumbnailParam.sc_SizeX[0], 2 );
	DotSizeX = SStoLE( DotSizeX );
NetTwainDebugTrace((char*)"### DotSizeX = [%d] ####\n",DotSizeX,0,0,0,0,0);

	memcpy( &DotSizeY, &s_GetThumbnailParam.sc_SizeY[0], 2 );
	DotSizeY = SStoLE( DotSizeY );
NetTwainDebugTrace((char*)"### DotSizeY = [%d] ####\n",DotSizeY,0,0,0,0,0);

	memcpy( &Format, &s_GetThumbnailParam.FileType[0], 2 );
	Format = SStoLE( Format );
NetTwainDebugTrace((char*)"### Format = [%d] ####\n",Format,0,0,0,0,0);

	// 設定データのチェック 
	Bool isError = False;		// エラー状態(初期値エラーなし：False) 

	// HDD装着のチェックを行う 
	char pc_ReqData[32];
	
	// *** HDDとSSDの装着のチェックを行う ***.
	if( isCheckAvailableBox() != NETE_Function_Box_Available )				// BOX使用可能or一部使用可能のとき.	// 2011/03/31 amiya 【Minerva】管理No941 SSD削減対応（1GB⇒512MB）.
	{
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_HDD_NOT_INSTALLED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_HDD_NOT_INSTALLED , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
		isError = True;		// エラーあり 
	}
	// 2008.08.05 Donau問題点対応 CC 307768 平谷 str.
	else if ( ( NULL != netc_TwainClientMan.getApic_Admin( SocketFd ) )
		   && ( True == netc_TwainClientMan.getUserLogined( SocketFd ) ) ) {	// 管理者ログイン時は不可.
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_USER_BOX_NOT_SPECIFIED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗.
		isError = True;	// エラーあり.
	}
	// 2008.08.05 Donau問題点対応 CC 307768 平谷 end.
	else 											// HDDありの場合 
	{
		if ( netc_TwainClientMan.getBoxLogined( SocketFd ) == True )	// Boxログイン状態 
		{
			Bool isAuthCheck = True;
			if ( getUserAuthenticationMode() != TYPE_UserAuthenticationOff ) {	// ユーザー認証モードがOFF以外(ONの場合) 
				if ( netc_TwainClientMan.getUserLogined(SocketFd) == True ) {		// ログイン済み 
					APIC_User* pc_User = netc_TwainClientMan.getApic_User( SocketFd );
					if(pc_User == NULL){
						errorLog_TwainService("APIC_User::newInstance Error\n",0,0,0,0,0,0);
						return;
					}
					pc_User->lock();
					if ( pc_User->getFunctionLimitation().e_EnableBoxOperation == TYPE_FuncLimit_Disable )	// 蓄積文書操作不可の場合. // 2010/08/25 amiya 【Minerva】UV-00458 ユーザー毎のカラー白黒出力制限をコピーとプリントで別々に設定したい対応.
					{
						isAuthCheck = False;			// 許可機能プロテクト 
					}
					if ( pc_User->getFunctionLimitation().e_EnableScan == TYPE_FuncLimit_Disable ) 			// スキャン画像操作不可の場合. // 2010/08/25 amiya 【Minerva】UV-00458 ユーザー毎のカラー白黒出力制限をコピーとプリントで別々に設定したい対応.
					{
						isAuthCheck = False;			// 許可機能プロテクト 
					}
					pc_User->unlock();
				}
			}
			if ( isAuthCheck == True ) {
				// ドキュメントIDのチェック 
				if ( DocID < 0 ) {			// DocIDが負数 
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_PARAMETER_ERROR1 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
					isError = True;		// エラーあり 
				}
				// PageDataのチェック 
				if ( PageData != 1 ) {		// PageDataが1以外(先頭ページ指定以外) 
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_PARAMETER_ERROR2 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
					isError = True;		// エラーあり 
				}
				// DotSizeXのチェック 
				// サムネイルサイズを取得する.
				short ss_ThumbnailSize = 114;
				APIC_PanelSetting* pc_PanelSetting = APIC_PanelSetting::newInstance();
				if ( NULL != pc_PanelSetting ) {
					ss_ThumbnailSize = pc_PanelSetting->getThumbnailLength();
				}
				
				if ( DotSizeX < 80 || 160 < DotSizeX ) {		// DotSizeXが仕様範囲外 
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_PARAMETER_ERROR3 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
					isError = True;		// エラーあり 
				}
				else if(DotSizeX > ss_ThumbnailSize)
				{
					DotSizeX = ss_ThumbnailSize;
				}
				// DotSizeYのチェック 
				if ( DotSizeY < 80 || 160 < DotSizeY ) {		// DotSizeYが仕様範囲外 
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_PARAMETER_ERROR4 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
					isError = True;		// エラーあり 
				}
				// Formatのチェック 
				if ( Format < 0 || 1 < Format ) {				// Formatが仕様範囲外 
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_PARAMETER_ERROR5 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
					isError = True;		// エラーあり 
				}
				// 領域確保 
				char* psc_ThumbnailData = (char*)malloc( THUMBNAIL_DATA_SIZE );
				if ( psc_ThumbnailData == NULL )
				{
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_MEMORY_OVERFLOW #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_MEMORY_OVERFLOW , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
					isError = True;		// エラーあり 
				}
				if ( isError == False )		// エラーが無い場合(サムネイル画像取得起動をかけることができる場合) 
				{
					APIC_ThumbnailConverter* pc_ThumbnailConverter = NULL;
					pc_ThumbnailConverter = APIC_ThumbnailConverter::newInstance();
					if ( pc_ThumbnailConverter != NULL )	// サムネイル画像クラスインスタンス取得成功の場合 
					{
						TYPS_ReqThumbnailPara s_ReqThumbnailPara;
						// サムネイル画像要求パラメータ設定 
						s_ReqThumbnailPara.sl_BoxID = netc_TwainClientMan.getLoginedBoxNo( SocketFd );
						s_ReqThumbnailPara.sl_DocID = DocID;
						s_ReqThumbnailPara.sl_PageNum = PageData;
						if ( Format == 0 )
						{
							s_ReqThumbnailPara.e_ThumbnailFormat = TYPE_FileFormatJpeg;
						}
						else
						{
							s_ReqThumbnailPara.e_ThumbnailFormat = TYPE_FileFormatRAW;
						}
						s_ReqThumbnailPara.ss_ReqImageDotSizeWidth = DotSizeX;
						s_ReqThumbnailPara.ss_ReqImageDotSizeHight = DotSizeY;
						s_ReqThumbnailPara.psc_ImageDataPointer = psc_ThumbnailData;
						s_ReqThumbnailPara.ul_ImageDataPointerSize = THUMBNAIL_DATA_SIZE;
						s_ReqThumbnailPara.e_Priority = TYPE_ThumbnailPriority1;
// CQ309219 サムネイル再作成フラグを追加 : 2008.09.30 : hira <START>.
						s_ReqThumbnailPara.b_Recreate = True;
// CQ309219 サムネイル再作成フラグを追加 : 2008.09.30 : hira <END>.
						// サムネイル取得の起動をかける 
						int index = netc_TwainClientMan.getClientIndex( SocketFd );
						if ( index != -1 )
						{
// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋 Start.
							NETS_TwainClientThumbnailInfo s_Info;
							memset(&s_Info, 0x00, sizeof(s_Info));

							s_Info.sl_DocId = DocID;
							s_Info.ul_ReqId = pc_ThumbnailConverter->req_getThumbnailData( s_ReqThumbnailPara, ans_getThumbnailDataTbl[index] );
							// アクセスログ出力用に、サムネイル変換対象の情報を保存.
							netc_TwainClientMan.setThumbnailInfo(SocketFd, s_Info);
// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋 End.
						}
					}
					else									// サムネイル画像クラスインスタンス取得失敗の場合 
					{
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_PARAMETER_ERROR6 #\n", 0,0,0,0,0,0);
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
						strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
						isError = True;		// エラーあり 
					}
				}
				// 2016/10/07 第2システム深谷 1002990 静的解析対応 START.
				else
				{
					if( psc_ThumbnailData != NULL ){
						free( psc_ThumbnailData );
						psc_ThumbnailData = NULL;
					}
				}
				// 2016/10/07 第2システム深谷 1002990 静的解析対応 END.
			}
			else 		// 認証状態で禁止機能に関する画像取得の場合(アプリでプロテクトされるのでデバイス側の最低限のプロテクトとして入れる) 
			{
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_PARAMETER_ERROR7 #\n", 0,0,0,0,0,0);
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
				strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
				isError = True;		// エラーあり 
			}
		}
		else														// Boxログアウト状態 
		{
NetTwainDebugTrace((char*)"# NETC_TwainCommandGetThumbnail_ERR_USER_BOX_NOT_SPECIFIED #\n", 0,0,0,0,0,0);
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
			strcpy( pc_ReqData, "\x1b*s21111tN" );	// 設定失敗 
			isError = True;		// エラーあり 
		}
	}
	// エラーがあった場合、エラー応答を返す 
	if ( isError == True )
	{
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True )
		{
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
}

//		SCL_GET_EXT_SERVER_INFO		60		// 60: Get External Auth Server Info 
//==================================================================================================
//[クラス]NETC_TwainCommandGetExtServerInfo 
//[内容] SCL_GET_EXT_SERVER_INFOコマンドを処理するクラス 
//[履歴] 2006.02.20 Matsumoto
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetExtServerInfoのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandGetExtServerInfo::NETC_TwainCommandGetExtServerInfo( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

// Server Type 
#define ACTIVE_DIRECTORY	1
#define NTLM_V1				2
#define NTLM_V2				3
#define NDS					4
#define LDAP				5
#define NDS_over_TCPIP		6

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2006.02.22 Matsumoto 
//		2006.07.20 yamahata 外部サーバー情報は登録数分返すよう修正 
//		2006.07.22 yamahata 外部サーバー情報を登録の際、配列要素の指定方法を修正 
//		2008.03.04 Tana 外部サーバー種類に「NDS over TCP/IP」を追加.
//		2016.04.11 日立 森田 【RQ-523】認証拡張FUM 外部サーバーグループ認証対応
//==================================================================================================
void NETC_TwainCommandGetExtServerInfo::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetExtServerInfo::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	if( ( getUserAuthenticationMode() != TYPE_UserAuthenticationServer )			// 外部サーバー認証状態で無い場合 
	 && ( getUserAuthenticationMode() != TYPE_UserAuthenticationDeviceAndServer )	// デバイス本体認証 + 外部サーバ認証の場合	// 2012/11/14 amiya CQ374933 認証：本体＋中間サーバー認証の場合は装置がら、カスタマイズログイン情報の取得が失敗します.
	){
		char pc_ReqData[32];
		strcpy( pc_ReqData, "\x1b*s267tN" );	// 設定失敗 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True )
		{
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
	else																	// 外部サーバー認証の場合 
	{
		NETS_ExternalServer s_ExternalServer[APID_MaxNumberOfAuthenticationSever];
		memset( &s_ExternalServer[0], 0, sizeof(NETS_ExternalServer)*APID_MaxNumberOfAuthenticationSever );

		// [2016/04/11] 認証拡張FUM 森田(日立) [St.]
		APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();
		int si_ExtAuthServerNum = 0;	//登録済み外部認証サーバー数 
		if( NULL != pc_SystemInfo ){
			APIC_AuthenticationSeverSetting* pc_AuthenticationSeverSetting = NULL;
			pc_AuthenticationSeverSetting = APIC_AuthenticationSeverSetting::newInstance();
			// 外部サーバー情報を登録の際、配列要素の指定方法を修正 06/07/22 yamahata 

			if( True == pc_AuthenticationSeverSetting->checkServerGroup() )
			{
				NETS_ServerGroupInfo s_ServerGroupInfo[APID_AuthServerGroupIndexExtServerMax] = {};
				Bool b_Result = False;
				// サーバーグループ情報取得.
				for ( APID_AuthServerGroupIndex index = APID_AuthServerGroupIndexExtServerMin; index <= APID_AuthServerGroupIndexExtServerMax; index++ )
				{
					b_Result = getAuthServerGroupInfoParam( &s_ServerGroupInfo[index - APID_AuthServerGroupIndexExtServerMin], index );
					if( True == b_Result)
					{
						s_ExternalServer[si_ExtAuthServerNum].uc_DefaultServer = s_ServerGroupInfo[index - APID_AuthServerGroupIndexExtServerMin].uc_DefaultServerGroup;
						s_ExternalServer[si_ExtAuthServerNum].uc_ServerType = s_ServerGroupInfo[index - APID_AuthServerGroupIndexExtServerMin].uc_ServerType;
						memcpy( &s_ExternalServer[si_ExtAuthServerNum].uc_ServerName[0], &s_ServerGroupInfo[index - APID_AuthServerGroupIndexExtServerMin].uc_ServerGroupName[0], APID_MaxLengthOfServerName+1 );
						si_ExtAuthServerNum++;
					}
				}
			}else{
				APIS_AuthenticationServerInfo s_AuthenticationServerInfo[APID_MaxNumberOfAuthenticationSever];
				memset( &s_AuthenticationServerInfo[0], 0, sizeof(APIS_AuthenticationServerInfo)*APID_MaxNumberOfAuthenticationSever );

				// サーバー情報取得 
				pc_AuthenticationSeverSetting->lock();

				// 2014/07/24 [ZeusS] UV-00986 OPS1前田 Start.
				APID_AuthenticationServerIndex SecondaryServerIndex = 0;										//代替サーバーに設定さたサーバーIndex.
				
				if( True == pc_AuthenticationSeverSetting->getSecondaryAuth() )								//代替サーバー使用設定取得.
				{
					SecondaryServerIndex = pc_AuthenticationSeverSetting->getSecondaryServerIndex();		//代替サーバーIndex取得.
NetTwainDebugTrace((char*)"### NETC_TwainCommandGetExtServerInfo SecondaryServerIndex = %d ###\n", SecondaryServerIndex,0,0,0,0,0);
				}
				// 2014/07/24 [ZeusS] UV-00986 OPS1前田 End.

				for ( APID_AuthenticationServerIndex index = 1; index <= APID_MaxNumberOfAuthenticationSever; index++ )
				{
					pc_AuthenticationSeverSetting->getServerInfo( index, &s_AuthenticationServerInfo[index-1] );
				}
				APID_AuthenticationServerIndex defIndex = pc_AuthenticationSeverSetting->getDefaultServerIndex();
				pc_AuthenticationSeverSetting->unlock();
				// サーバー情報を内部情報へ展開 
				for ( int i = 0; i < APID_MaxNumberOfAuthenticationSever; i++ )
				{
					// 2014/07/24 [ZeusS] UV-00986 OPS1前田 Start.
					if ( ( s_AuthenticationServerInfo[i].e_ServerType != TYPE_AuthenticationServerTypeNone ) 
					   &&( i+1 != SecondaryServerIndex ) )													//Indexが一致した場合は、代替サーバーに設定されたサーバーの情報は付加しない.
					// 2014/07/24 [ZeusS] UV-00986 OPS1前田 End.
					{
						if ( i == (defIndex-1) )
						{
							s_ExternalServer[si_ExtAuthServerNum].uc_DefaultServer = 1;
						}
						
						switch ( s_AuthenticationServerInfo[i].e_ServerType )
						{
							case TYPE_AuthenticationServerTypeActiveDirectory:		// Active Directory	
								s_ExternalServer[si_ExtAuthServerNum].uc_ServerType = ACTIVE_DIRECTORY;
								break;
							case TYPE_AuthenticationServerTypeSMB:					// SMB(NTLM) --> NTLM v1 
								s_ExternalServer[si_ExtAuthServerNum].uc_ServerType = NTLM_V1;
								break;
							case TYPE_AuthenticationServerTypeNTLMv2:				// NTLM v2 
								s_ExternalServer[si_ExtAuthServerNum].uc_ServerType = NTLM_V2;
								break;
							case TYPE_AuthenticationServerTypeNDS:					// NDS over IPX.
								s_ExternalServer[si_ExtAuthServerNum].uc_ServerType = NDS;
								break;
							case TYPE_AuthenticationServerTypeLDAP:					// LDAP 
								s_ExternalServer[si_ExtAuthServerNum].uc_ServerType = LDAP;
								break;
							// >> 2008.03.04 Tana [Donau] No.69 NDS over TCP/IPを追加.
							case TYPE_AuthenticationServerTypeNDSOverTCPIP:			// NDS over TCP/IP.
								s_ExternalServer[si_ExtAuthServerNum].uc_ServerType = NDS_over_TCPIP;
								break;
							// << 2008.03.04 Tana [Donau] No.69 NDS over TCP/IPを追加.
						}
						memcpy( &s_ExternalServer[si_ExtAuthServerNum].uc_ServerName[0], &s_AuthenticationServerInfo[i].sc_ServerName[0], APID_MaxLengthOfServerName+1 );
						si_ExtAuthServerNum++;
					}
				}
			}
		}
		// [2016/04/11] 認証拡張FUM 森田(日立) [Ed.]
		char tmp[32];
		// 外部サーバー情報は登録数分返すよう修正 06/07/20 yamahata 
		sprintf( tmp, "\x1b*s267t%dW", sizeof(NETS_ExternalServer)*si_ExtAuthServerNum );
		char* pc_RspData = (char*)malloc( strlen(tmp)+sizeof(NETS_ExternalServer)*si_ExtAuthServerNum );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, tmp, strlen(tmp) );
		memcpy( &pc_RspData[strlen(tmp)], &s_ExternalServer[0], sizeof(NETS_ExternalServer)*si_ExtAuthServerNum );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(tmp)+sizeof(NETS_ExternalServer)*si_ExtAuthServerNum );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
}

//		SCL_GET_BOX_CAPABILITY		61		// 61: Get Box Capability 
//==================================================================================================
//[クラス]NETC_TwainCommandGetBoxCapability 
//[内容] SCL_GET_BOX_CAPABILITYコマンドを処理するクラス 
//[履歴] 2006.05.08 yamahata
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetBoxCapabilityのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandGetBoxCapability::NETC_TwainCommandGetBoxCapability( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]2006.05.08 yamahata
//==================================================================================================
void NETC_TwainCommandGetBoxCapability::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetBoxCapability::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	// 領域確保 
	NETS_BoxCapability nets_BoxCapability;
	// 領域を初期化する 
	memset( &nets_BoxCapability, 0, sizeof(NETS_BoxCapability) );

	Bool bl_isHDDExist;
	bl_isHDDExist = isHDDExist();
	// デバイスが保持できるBox数の上限値(HDDなしの場合0) 
	if ( bl_isHDDExist == True ) {	// HDDありの場合 
		nets_BoxCapability.uc_MaxBoxNum[1] = static_cast<uchar>((DOCD_BoxCntMax & 0xff00) >> 8);
		nets_BoxCapability.uc_MaxBoxNum[0] = static_cast<uchar>((DOCD_BoxCntMax & 0x00ff));
	}
	// 2019/6/21 RQ-560 SSD_1TB 日立 佐藤菜 Start.
	int32_t i32_AllBoxSaveMaxNum	= DOCD_MaxDocFile;							// 全ボックスの文書最大数(10000).
	int32_t i32_BoxSaveMaxNum		= DOCD_DocFileCntBoxMax;					// 1ボックス当りの文書最大数.
	int32_t i32_PagesSaveMaxNum		= DOCD_MaxBoxPage;							// 全Box内の総ページ数.
	APIC_BoxRegistry* pc_BoxRegistry = APIC_BoxRegistry::newInstance();
	if ( NULL != pc_BoxRegistry ){
		i32_BoxSaveMaxNum = pc_BoxRegistry->getBoxSaveMaximumNumber( 1 );		// ユーザーBoxとして文書の最大数を取得.
		i32_PagesSaveMaxNum = pc_BoxRegistry->getPagesSaveMaximumNumber();
	}
	if ( DOCD_DocFileCntBoxMax_1T == i32_BoxSaveMaxNum ) {
		i32_AllBoxSaveMaxNum = DOCD_MaxDocFile_1T;								// 全ボックスの文書最大数(50000).
	}
	// 2019/6/21 RQ-560 SSD_1TB 日立 佐藤菜 End.
	
	// デバイスが保持できる文書数の上限値(HDDなしの場合0) 
	if ( bl_isHDDExist == True ) {	// HDDありの場合 
		nets_BoxCapability.uc_MaxDocNumPerDevice[3] = static_cast<uchar>((i32_AllBoxSaveMaxNum & 0xff000000) >> 24);
		nets_BoxCapability.uc_MaxDocNumPerDevice[2] = static_cast<uchar>((i32_AllBoxSaveMaxNum & 0x00ff0000) >> 16);
		nets_BoxCapability.uc_MaxDocNumPerDevice[1] = static_cast<uchar>((i32_AllBoxSaveMaxNum & 0x0000ff00) >> 8);
		nets_BoxCapability.uc_MaxDocNumPerDevice[0] = static_cast<uchar>((i32_AllBoxSaveMaxNum & 0x000000ff));
	}
	// 1ボックスに保持できる文書数の上限値(HDDなしの場合0) 
	if ( bl_isHDDExist == True ) {	// HDDありの場合 
		nets_BoxCapability.uc_MaxDocNumPerBox[3] = static_cast<uchar>((i32_BoxSaveMaxNum & 0xff000000) >> 24);
		nets_BoxCapability.uc_MaxDocNumPerBox[2] = static_cast<uchar>((i32_BoxSaveMaxNum & 0x00ff0000) >> 16);
		nets_BoxCapability.uc_MaxDocNumPerBox[1] = static_cast<uchar>((i32_BoxSaveMaxNum & 0x0000ff00) >> 8);
		nets_BoxCapability.uc_MaxDocNumPerBox[0] = static_cast<uchar>((i32_BoxSaveMaxNum & 0x000000ff));
	}
	// デバイスが保持できる総ページ数の上限値(HDDなしの場合0) 
	if ( bl_isHDDExist == True ) {	// HDDありの場合 
		nets_BoxCapability.uc_MaxPageNumPerDevice[3] = static_cast<uchar>((i32_PagesSaveMaxNum & 0xff000000) >> 24);
		nets_BoxCapability.uc_MaxPageNumPerDevice[2] = static_cast<uchar>((i32_PagesSaveMaxNum & 0x00ff0000) >> 16);
		nets_BoxCapability.uc_MaxPageNumPerDevice[1] = static_cast<uchar>((i32_PagesSaveMaxNum & 0x0000ff00) >> 8);
		nets_BoxCapability.uc_MaxPageNumPerDevice[0] = static_cast<uchar>((i32_PagesSaveMaxNum & 0x000000ff));
	}
	// 1ボックスに保持できる総ページ数の上限値(1BOX辺りのページ上限は無いので、デバイスで保持できるページ上限の値を返す)
	if ( bl_isHDDExist == True ) {	// HDDありの場合 
		nets_BoxCapability.uc_MaxPageNumPerBox[3] = static_cast<uchar>((i32_PagesSaveMaxNum & 0xff000000) >> 24);
		nets_BoxCapability.uc_MaxPageNumPerBox[2] = static_cast<uchar>((i32_PagesSaveMaxNum & 0x00ff0000) >> 16);
		nets_BoxCapability.uc_MaxPageNumPerBox[1] = static_cast<uchar>((i32_PagesSaveMaxNum & 0x0000ff00) >> 8);
		nets_BoxCapability.uc_MaxPageNumPerBox[0] = static_cast<uchar>((i32_PagesSaveMaxNum & 0x000000ff));
	}
	// 1ジョブあたりで処理可能なページ数の上限値(HDDなしの場合0) 
	if ( bl_isHDDExist == True ) {	// HDDありの場合 
		nets_BoxCapability.uc_MaxPageNumPerJob[3] = static_cast<uchar>((DOCD_MaxPage & 0xff000000) >> 24);
		nets_BoxCapability.uc_MaxPageNumPerJob[2] = static_cast<uchar>((DOCD_MaxPage & 0x00ff0000) >> 16);
		nets_BoxCapability.uc_MaxPageNumPerJob[1] = static_cast<uchar>((DOCD_MaxPage & 0x0000ff00) >> 8);
		nets_BoxCapability.uc_MaxPageNumPerJob[0] = static_cast<uchar>((DOCD_MaxPage & 0x000000ff));
	}
	// デバイスが保持できる掲示板Box数の上限値 
	nets_BoxCapability.uc_MaxBulletinBoxNum[1] = static_cast<uchar>((DOCD_BulletinBoardCnt & 0xff00) >> 8);
	nets_BoxCapability.uc_MaxBulletinBoxNum[0] = static_cast<uchar>((DOCD_BulletinBoardCnt & 0x00ff));
	// 1掲示板Boxに保持できる文書数の上限値(define値がないため、1をベタ書) 
	nets_BoxCapability.uc_MaxDocNumOfBulletinBox[1] = static_cast<uchar>((i32_BoxSaveMaxNum & 0xff00) >> 8);
	nets_BoxCapability.uc_MaxDocNumOfBulletinBox[0] = static_cast<uchar>((i32_BoxSaveMaxNum & 0x00ff));
	// デバイスが保持できる親展Box数の上限値 
	nets_BoxCapability.uc_MaxConfidentialBoxNum[1] = static_cast<uchar>((DOCD_ConfidentialCnt & 0xff00) >> 8);
	nets_BoxCapability.uc_MaxConfidentialBoxNum[0] = static_cast<uchar>((DOCD_ConfidentialCnt & 0x00ff));
	// 1親展Boxに保持できる文書数の上限値(define値がないため、100をベタ書) 
	nets_BoxCapability.uc_MaxDocNumOfConfidentialBox[1] = static_cast<uchar>((i32_BoxSaveMaxNum & 0xff00) >> 8);
	nets_BoxCapability.uc_MaxDocNumOfConfidentialBox[0] = static_cast<uchar>((i32_BoxSaveMaxNum & 0x00ff));
	// デバイスが保持できる中継Box数の上限値 
	nets_BoxCapability.uc_MaxRelayBoxNum[1] = static_cast<uchar>((DOCD_RelayCnt & 0xff00) >> 8);
	nets_BoxCapability.uc_MaxRelayBoxNum[0] = static_cast<uchar>((DOCD_RelayCnt & 0x00ff));
	// 1中継Boxに保持できる文書数の上限値(define値がないため、1をベタ書) 
	nets_BoxCapability.uc_MaxDocNumOfRelayBox[1] = static_cast<uchar>((i32_BoxSaveMaxNum & 0xff00) >> 8);
	nets_BoxCapability.uc_MaxDocNumOfRelayBox[0] = static_cast<uchar>((i32_BoxSaveMaxNum & 0x00ff));
	// デバイスに保持できる機密文書数の上限値(define値がないため、200をベタ書 HDDなしの場合0) 
	if ( bl_isHDDExist == True ) {	// HDDありの場合 
		if ( NULL != pc_BoxRegistry ){
			i32_BoxSaveMaxNum = pc_BoxRegistry->getBoxSaveMaximumNumber( DOCD_SecretDocumentsBox );
		}
		nets_BoxCapability.uc_MaxSecretDocNum[1] = static_cast<uchar>((i32_BoxSaveMaxNum & 0xff00) >> 8);
		nets_BoxCapability.uc_MaxSecretDocNum[0] = static_cast<uchar>((i32_BoxSaveMaxNum & 0x00ff));
	}
	if ( NULL != pc_BoxRegistry ){
		pc_BoxRegistry->deleteInstance();
	}
	char tmpd[64];
	short ss_dsize = sizeof(NETS_BoxCapability);
	int tmpLen = sprintf( tmpd, "\x1b*s309t%dW", ss_dsize );
	char* pc_ReqData = (char*)malloc(ss_dsize+tmpLen);
	if( pc_ReqData == NULL ){
		errorLog_TwainService("pc_ReqData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_ReqData, tmpd, tmpLen );
	memcpy( &pc_ReqData[tmpLen], (char*)&nets_BoxCapability, ss_dsize );
	netc_TwainClientMan.setSendData( SocketFd, pc_ReqData, (uint32_t)(tmpLen+ss_dsize) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
	
}

//		SCL_GET_ACCOUNT_LOGIN_TYPE_2	62		//Inquire Account Login Type 2.
//==================================================================================================
//[クラス]NETC_TwainCommandGetAccLoginType2 
//[内容] SCL_GET_ACCOUNT_LOGIN_TYPE_2コマンドを処理するクラス 
//[履歴] 2006.07.07 Harada 
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetAccLoginType2のコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainCommandGetAccLoginType2::NETC_TwainCommandGetAccLoginType2( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2010/03/18 amiya <UV-00651> 認証と部門のユーザー別連動設定対応.
//==================================================================================================
void NETC_TwainCommandGetAccLoginType2::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* ,				// パラメータへのポインタ 
	short 				// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetAccLoginType2::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	// 認証モードを解析し応答データを作成する 
	switch( getTrackMode() ){
		case TYPE_TrackModeOff:							// 部門認証ＯＦＦ 
			strcpy( pc_ReqData, "\x1b*s20003d0V" );
			break;
		case TYPE_TrackModeNoAndPassword:				// 部門ＩＤと部門パスワードが必要 
			strcpy( pc_ReqData, "\x1b*s20003d1V" );
			break;
		case TYPE_TrackModeOnlyPassword:				// 部門パスワードのみが必要 
			strcpy( pc_ReqData, "\x1b*s20003d2V" );
			break;
		case TYPE_TrackModeOnWithUserAuthentication:	// ユーザー認証と連動して部門認証 
			strcpy( pc_ReqData, "\x1b*s20003d4V" );
			break;
		case TYPE_TrackModeUserSelect:					// 部門認証 ON (ユーザ認証と連動をユーザが設定).	// 2010/03/18 <UV-00651> 認証と部門のユーザー別連動設定対応 amiya.
			strcpy( pc_ReqData, "\x1b*s20003d5V" );
			break;
		default:
			break;
	}
	// 中間認証サーバーでのプロジェクト管理(費用コード管理)が行われているかどうかを判断する 
	if( ( getUserAuthenticationMode() == TYPE_UserAuthenticationIntermeddiateServer )
	 || ( getUserAuthenticationMode() == TYPE_UserAuthenticationDeviceAndMidAuth ) )	// デバイス本体認証 + 拡張サーバ認証の場合	// 2012/11/14 amiya CQ374933 認証：本体＋中間サーバー認証の場合は装置がら、カスタマイズログイン情報の取得が失敗します.
	{
		if ( getTrackMode() == TYPE_TrackModeNoAndPassword )
		{
			strcpy( pc_ReqData, "\x1b*s20003d3V" );
		}
	}

	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );			// 送信データセット 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// 2004.11.30  
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

//		SCL_GET_HDD_NUMBER				63		//Inquire Numbers of Installed HDD.
