//[履歴] 2007.06.12 Harada コマンドの"n"を"d"に修正 
//==================================================================================================
void NETC_TwainCommandGetHddNumber::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* ,				// パラメータへのポインタ 
	short 				// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetHddNumber::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	if ( isHDDExist() == False ) {						// HDD非装着 
		strcpy( pc_ReqData, "\x1b*s30030d0V" );
	} else {											// HDD装着 
		strcpy( pc_ReqData, "\x1b*s30030d1V" );
	}
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True )
	{
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

//==================================================================================================
//[クラス]NETC_CustomizedLoginResultNotifier 
//[内容]中間認証サーバーログイン結果を取得するためのクラス 
//[履歴] 2006.10.17 Harada 
//==================================================================================================
//==================================================================================================
//[機能]ログイン結果通知 
//[戻り値]void 
//[コメント]
//[レビュー]
//[履歴] 2006.10.17 Harada 
//		 2012.05.10 Sky mori. CQ364908 【TCPSocket】リファイン オブザーバ通知処理改善.
//==================================================================================================
void NETC_CustomizedLoginResultNotifier::notifyLoginResult(
	TYPE_UserResult	e_UserResult, 	// ログイン結果 
	APIC_User* 		pc_User			// ユーザオブジェクト 
)
{
NetTwainDebugTrace((char*)"#### NETC_CustomizedLoginResultNotifier::notifyLoginResult() START! ####\n",0,0,0,0,0,0);

	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( index );	// 自分を管理しているテーブルのSocketFdを取得する 
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_CustomizedLogin* pc_CustomizedLogin = (NETS_CustomizedLogin*)malloc( sizeof(NETS_CustomizedLogin) );
	if( pc_CustomizedLogin == NULL ){
		errorLog_TwainService("pc_CustomizedLogin_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memset( pc_CustomizedLogin, 0, sizeof(NETS_CustomizedLogin) );
	pc_CustomizedLogin->index = index;
	index = -1;
	pc_CustomizedLogin->pc_User = pc_User;
	pc_CustomizedLogin->e_Result = e_UserResult;
	pc_CustomizedLogin->ps_Param = NULL;
	NETS_CustomizedLoginParam* ps_Param = (NETS_CustomizedLoginParam*)malloc( sizeof(NETS_CustomizedLoginParam) );
	if ( ps_Param != NULL ) {
		memset( ps_Param, 0, sizeof(NETS_CustomizedLoginParam) );
		if ( e_UserResult == TYPE_UserResultOk ) {
			// メッセージ 
			TYPS_ExtMessage* ps_ResParam = (TYPS_ExtMessage*)getResParameter();
			if ( ps_ResParam != NULL) {
				strcpy( ps_Param->sc_Message, ps_ResParam->sc_Value );
			}

			// >>i-Op SROM対応.
			TYPS_ResExtParameter* ps_ResExtParameter = NULL;
			ps_ResExtParameter = getResExtParameter();
			if( ps_ResExtParameter != NULL ) {
				ps_Param->ps_ResExtParameter = (TYPS_ResExtParameter*)malloc( sizeof(TYPS_ResExtParameter) );
				if( ps_Param->ps_ResExtParameter != NULL ) {
					memcpy( ps_Param->ps_ResExtParameter, ps_ResExtParameter, sizeof(TYPS_ResExtParameter) );
				} else {
					errorLog_TwainService("ps_Param->ps_ResExtParameter_malloc Error\n",0,0,0,0,0,0);
					ps_Param->ps_ResExtParameter = NULL;
				}
			} else {
				ps_Param->ps_ResExtParameter = NULL;
			}
			// <<i-Op SROM対応.

		} else {
			TYPS_ExtError* ps_ResParam = (TYPS_ExtError*)getResParameter();
			if ( ps_ResParam != NULL) {
				strcpy( ps_Param->sc_Message, ps_ResParam->sc_Description );
			}
		}
		pc_CustomizedLogin->ps_Param = ps_Param;
	}
	else
	{
		errorLog_TwainService("ps_Param_malloc Error\n",0,0,0,0,0,0);
	}

	netc_TwainService->setPacketData( NETE_TWAIN_CUSTOMIZED_LOGIN,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
									  (void*)pc_CustomizedLogin );
	
}
