NETC_TwainCommandSetBackupMediaFileNumber::NETC_TwainCommandSetBackupMediaFileNumber( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================.
//[機能]コマンドを処理する.
//[戻り値].
//[コメント].
//[レビュー].
//[履歴].
//==================================================================================================.
void NETC_TwainCommandSetBackupMediaFileNumber::CommandProc(
	int SocketFd,		// ソケットディスクリプタ.
	char* Parameter,	// パラメータへのポインタ.
	short ParamLength	// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandSetBackupMediaFileNumber::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	memset( &pc_ReqData[0], 0, sizeof(pc_ReqData) );
	// 管理者ログイン状態かどうかチェックする.
	// 管理者モードにログインした状態か否かを確認する。.
	APIC_User* pc_User = netc_TwainClientMan.getApic_Admin( SocketFd );					// ログインユーザーインスタンス.
// >> 2008.04.09 Harada Donau対応 No.22 分割バックアップ対応.
	int32_t sl_UserNo = TYPD_IndexUserPublic;	//2013/10/11 【スケーラブルFUM】[CQ383174] 20万人対応. 
	if ( pc_User != NULL ) {
		pc_User->lock();
		sl_UserNo = pc_User->getUserNo();	// ユーザＩＤ取得.
		pc_User->unlock();
	}
// << 2008.04.09 Harada Donau対応 No.22 分割バックアップ対応.
	
//>> 2009/06/15 hiratani Taiga 制御構成変更11対応.
	if ( False == isBackupEnable() )	// Backup可能状態か確認する.
	{
	netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber::ERR_HDD_NOT_INSTALLED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_HDD_NOT_INSTALLED , __FILE__ ,__LINE__);	// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s35121r0V" );										// 失敗応答.
	}
//<< 2009/06/15 hiratani Taiga 制御構成変更11対応.
	else if ( (pc_User == NULL) || (sl_UserNo != TYPD_IndexUserAdmin) )		// ログインユーザーインスタンスが無い場合 
	{
		netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber_ERR_ACCESS_DENIED #\n", 0,0,0,0,0,0);
		strcpy( pc_ReqData, "\x1b*s35121r0V" );	// 失敗応答.
	}
	else if ( netc_TwainClientMan.getBackupMediaID() == 0 )		// メディアIDの指定が無い場合.
	{
		netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_MEDIAID_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber_ERR_MEDIAID_NOT_SPECIFIED #\n", 0,0,0,0,0,0);
		strcpy( pc_ReqData, "\x1b*s35121r0V" );	// 失敗応答.
	}
	else if ( netc_TwainClientMan.getBackupMediaID() != 2 )		// 分割バックアップ指定で無い場合.
	{
		netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber_ERR_ACCESS_DENIED2 #\n", 0,0,0,0,0,0);
		strcpy( pc_ReqData, "\x1b*s35121r0V" );	// 失敗応答.
	}
	else
	{
		char sc_BackupMediaFileNum[20];
		memset( &sc_BackupMediaFileNum[0], 0, sizeof(sc_BackupMediaFileNum) );
		int32_t sl_BackupMediaFileNum = 0;
		char sc_DataSize[20];
		memset( &sc_DataSize[0], 0, sizeof(sc_DataSize) );
		short ss_DataSize = 0;
		char sc_BackupTicket[20];
		memset( &sc_BackupTicket[0], 0, sizeof(sc_BackupTicket) );
		Bool bl_BackupMediaFileNumFixed = False;
		Bool bl_DataSizeFixed = False;
		Bool bl_BackupTicketFixed = False;
		int index = 0;
		for ( int i = 0; i < ParamLength; i++ )
		{
			if ( bl_BackupMediaFileNumFixed == False )
			{
				if ( Parameter[i] != 't' )
				{
					sc_BackupMediaFileNum[index] = Parameter[i];
					index++;
					if ( index >= (int)sizeof(sc_BackupMediaFileNum) )
					{
NetTwainDebugTrace((char*)"### (BUG)Not enough size! Size Error ###\n",0,0,0,0,0,0);
						break;
					}
				}
				else
				{
					sc_BackupMediaFileNum[index] = '\0';
					index = 0;
					bl_BackupMediaFileNumFixed = True;
					sl_BackupMediaFileNum = atoi((char*)sc_BackupMediaFileNum);
				}
			}
			else if ( bl_DataSizeFixed == False )
			{
				if ( Parameter[i] != 'F' )
				{
					sc_DataSize[index] = Parameter[i];
					index++;
					if ( index >= (int)sizeof(sc_DataSize) )
					{
NetTwainDebugTrace((char*)"### (BUG)Not enough size! Size Error ###\n",0,0,0,0,0,0);
						break;
					}
				}
				else
				{
					sc_DataSize[index] = '\0';
					index = 0;
					bl_DataSizeFixed = True;
					ss_DataSize = (short)atoi((char*)sc_DataSize);
				}
			}
			else
			{
				if ( index < ss_DataSize )
				{
					sc_BackupTicket[index] = Parameter[i];
					index++;
					if ( index >= (int)sizeof(sc_BackupTicket) )
					{
NetTwainDebugTrace((char*)"### (BUG)Not enough size! Size Error ###\n",0,0,0,0,0,0);
						break;
					}
					if ( i == (ParamLength-1) )
					{
						sc_BackupTicket[index] = '\0';
						index = 0;
						bl_BackupTicketFixed = True;
					}
				}
				else
				{
NetTwainDebugTrace((char*)"### Unusual size! Size Error  ###\n",0,0,0,0,0,0);
					bl_BackupTicketFixed = False;
					break;
				}
			}
		}
NetTwainDebugTrace((char*)"### sl_BackupMediaFileNum = %d ###\n",sl_BackupMediaFileNum,0,0,0,0,0);
NetTwainDebugTrace((char*)"### bl_BackupMediaFileNumFixed = %d ###\n",bl_BackupMediaFileNumFixed,0,0,0,0,0);
NetTwainDebugTrace((char*)"### ss_DataSize = %d ###\n",ss_DataSize,0,0,0,0,0);
NetTwainDebugTrace((char*)"### bl_DataSizeFixed = %d ###\n",bl_DataSizeFixed,0,0,0,0,0);
NetTwainDebugTrace((char*)"### bl_BackupTicketFixed = %d ###\n",bl_BackupTicketFixed,0,0,0,0,0);

		NETS_BackupInfoData s_BackupInfoData = netc_TwainClientMan.getBackupInfoData();
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_MediaFileNum[0] = %02x ###\n",s_BackupInfoData.sc_MediaFileNum[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_MediaFileNum[1] = %02x ###\n",s_BackupInfoData.sc_MediaFileNum[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_MediaFileNum[2] = %02x ###\n",s_BackupInfoData.sc_MediaFileNum[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_MediaFileNum[3] = %02x ###\n",s_BackupInfoData.sc_MediaFileNum[3],0,0,0,0,0);
		int32_t sl_MediaFileNum = 0;		// メディアファイル数.
		sl_MediaFileNum = C4LEtoSL( s_BackupInfoData.sc_MediaFileNum );
NetTwainDebugTrace((char*)"### sl_MediaFileNum = %d ###\n",sl_MediaFileNum,0,0,0,0,0);
		if ( ss_DataSize == 0 )		// データサイズが0の場合.
		{
			netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber_ERR_PARAMETER_ERROR1 #\n", 0,0,0,0,0,0);
			strcpy( pc_ReqData, "\x1b*s35121r0V" );	// 失敗応答.
		}
		else if ( bl_BackupTicketFixed == False )		// データ確定しなかった場合.
		{
			netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber_ERR_PARAMETER_ERROR2 #\n", 0,0,0,0,0,0);
			strcpy( pc_ReqData, "\x1b*s35121r0V" );	// 失敗応答.
		}
		else if ( sl_BackupMediaFileNum == -1 )		// メディアファイル指定解除の指定.
		{
NetTwainDebugTrace((char*)"###Designation of file designation release of media ###\n",0,0,0,0,0,0);
			netc_TwainClientMan.setBackupMediaFileNum( -1 );			// バックアップメディアファイル番号の設定.
			strcpy( pc_ReqData, "\x1b*s35121r1V" );	// 成功応答.
		}
		else if ( !((1 <= sl_BackupMediaFileNum) && (sl_BackupMediaFileNum <= sl_MediaFileNum)) )		// メディアファイル番号が範囲外であった場合.
		{
			netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber_ERR_PARAMETER_ERROR3 #\n", 0,0,0,0,0,0);
			strcpy( pc_ReqData, "\x1b*s35121r0V" );	// 失敗応答.
		}
		else if ( sl_BackupMediaFileNum != netc_TwainClientMan.getBackupCheckMediaFileNum() )		// メディアファイル番号がチェック用番号と一致しない場合.
		{
			netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber_ERR_PARAMETER_ERROR4 #\n", 0,0,0,0,0,0);
			strcpy( pc_ReqData, "\x1b*s35121r0V" );	// 失敗応答.
		}
		else
		{
			if ( memcmp( netc_TwainClientMan.getBackupTicketID(), &sc_BackupTicket[0], BACKUP_TICKET_SIZE ) != 0 )
			{
				netc_TwainClientMan.setBackUpExistError( SocketFd, True );	// BackUp/Restoreエラーセット.	// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetBackupMediaFileNumber_ERR_PARAMETER_ERROR5 #\n", 0,0,0,0,0,0);
				strcpy( pc_ReqData, "\x1b*s35121r0V" );	// 失敗応答.
			}
			else		// 発行したバックアップIDと設定されたバックアップIDが同一の場合.
			{
NetTwainDebugTrace((char*)"### Set Backup Media File Number ###\n",0,0,0,0,0,0);
				netc_TwainClientMan.setBackupMediaFileNum( sl_BackupMediaFileNum );			// バックアップメディアファイル番号の設定.
				strcpy( pc_ReqData, "\x1b*s35121r1V" );	// 成功応答.
			}
		}
	}
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

