//==================================================================================================.
//[機能]ファイルデータ初期化処理関数からコールされる関数.
//[戻り値].
//[コメント].
//[レビュー].
//[履歴] 2008.03.03 Harada Donau対応 No.22 分割バックアップ対応.
//==================================================================================================.
void _ReqInitRestoreFile(
	NETS_InitRestoreFile* pc_InitRestoreFile
)
{
NetTwainDebugTrace((char*)"### _ReqInitRestoreFile()! ###\n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	memset( &pc_ReqData[0], 0, sizeof(pc_ReqData) );

	if ( pc_InitRestoreFile != NULL )
	{
		NETS_InitRestoreFile s_InitRestoreFile;
		memcpy( &s_InitRestoreFile, pc_InitRestoreFile, sizeof(NETS_InitRestoreFile) );
		free( pc_InitRestoreFile );
		int SocketFd = netc_TwainClientMan.getSocketFd( s_InitRestoreFile.index );	// ソケットFDの取得(管理インデックスを指定して取得).
		if ( SocketFd != -1 )
		{
			if ( s_InitRestoreFile.ret == True )		// 成功.
			{
NetTwainDebugTrace((char*)"### Success ###\n",0,0,0,0,0,0);
				strcpy( pc_ReqData, "\x1b*s35123r1V" );	// 成功応答.
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
				// bl_UsedBuf：バッファのデータをリストア先に書き込み終えたらFalseにする。.
				netsDataBuf.bl_UsedBuf = False;										// バッファ未使用に設定する.
				// リストアデータ番号の更新.
				netc_TwainClientMan.setRestoreDataNum( netc_TwainClientMan.getRestoreDataNum()+1 );
NetTwainDebugTrace((char*)"### RestoreDataNum = %d ###\n",netc_TwainClientMan.getRestoreDataNum(),0,0,0,0,0);
			}
			else
			{
NetTwainDebugTrace((char*)"### Error  ###\n",0,0,0,0,0,0);
NetTwainDebugTrace((char*)"# _ReqInitRestoreFile_ERR_DEVICE_ERROR1 #\n", 0,0,0,0,0,0);
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);	// Error Client Error Info.
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );				// Error Client Error Status.
				strcpy( pc_ReqData, "\x1b*s35123r0V" );	// 失敗応答.
				char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
				}
				// bl_UsedBuf：バッファのデータをリストア先に書き込み終えたらFalseにする。.
				netsDataBuf.bl_UsedBuf = False;										// バッファ未使用に設定する.
				netc_TwainClientMan.setRestoreEnd( SocketFd , True );				// リストア全回数終了.
			}
		}
	}
}

//==================================================================================================.
//[機能]分割バックアップコールバック関数からコールされる関数.
//[戻り値].
//[コメント].
//[レビュー].
//[履歴] 2008.03.03 Harada Donau対応 No.22 分割バックアップ対応.
//		2017/01/06 SCD2-2G前田 No1008849 デッドロック対応.
//==================================================================================================.
void ans_RestoreMediaFileData( int id, Bool bl_OK )
{
	netc_TwainClientMan.semLock();		// クライアントテーブルを参照・変更するためセマフォをロックする.
	signed int si_SocketFd = netc_TwainClientMan.getSocketFd( id );	// 自分を管理しているテーブルのSocketFdを取得する.
	NETC_TwainService* netc_TwainService = NULL;
	netc_TwainService = NETC_TwainService::newInstance();
	NETS_RestoreMediaFileData* pc_RestoreMediaFileData = (NETS_RestoreMediaFileData*)malloc( sizeof(NETS_RestoreMediaFileData) );
	if( pc_RestoreMediaFileData == NULL ){
		errorLog_TwainService("pc_RestoreMediaFileData_malloc Error\n",0,0,0,0,0,0);
		netc_TwainClientMan.semUnLock();		// No1008849 デッドロック対応.
		return;
	}
	pc_RestoreMediaFileData->index = id;
	pc_RestoreMediaFileData->ret = bl_OK;
	netc_TwainService->setPacketData( NETE_TWAIN_RESTORE_MEDIA_FILE_DATA,
									  netc_TwainClientMan.getClientIndex( si_SocketFd ),
									  NULL,
									  0,
									  netc_TwainClientMan.getAppID( si_SocketFd ),
									  netc_TwainClientMan.getTwainReceiverSlave( si_SocketFd ),
									  NULL,
									  (void*)pc_RestoreMediaFileData );
	netc_TwainClientMan.semUnLock();			// クライアント管理情報のセマフォをアンロックする.
}

