NetTwainDebugTrace((char*)"### s_RestoreMediaFileInfoData.sc_ClusterNum[0] = %02x ###\n",s_RestoreMediaFileInfoData.sc_ClusterNum[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_RestoreMediaFileInfoData.sc_ClusterNum[1] = %02x ###\n",s_RestoreMediaFileInfoData.sc_ClusterNum[1],0,0,0,0,0);
