//[戻り値].
//[コメント].
//[レビュー].
//[履歴] 2008.03.03 Harada Donau対応 No.22 分割バックアップ対応.
//==================================================================================================.
void _ReqGetBackupFileNum(
	NETS_GetBackupFileNum* pc_GetBackupFileNum
)
{
	char* pc_RspData = NULL;
	char pc_ReqData[32];
	memset( &pc_ReqData[0], 0, sizeof(pc_ReqData) );
	int si_RspLength = 0;
	Bool bl_ErrorDetect = False;

	netc_TwainClientMan.setBackupFileNumStatus( False );		// ファイル数取得状態の解除.
	if ( pc_GetBackupFileNum != NULL )
	{
		NETS_GetBackupFileNum s_GetBackupFileNum;
		memcpy( &s_GetBackupFileNum, pc_GetBackupFileNum, sizeof(NETS_GetBackupFileNum) );
		free( pc_GetBackupFileNum );
		int SocketFd = netc_TwainClientMan.getSocketFd( s_GetBackupFileNum.index );	// ソケットFDの取得(管理インデックスを指定して取得).
		if ( SocketFd != -1 )
		{
			if ( s_GetBackupFileNum.ret == True )		// 成功.
			{
NetTwainDebugTrace((char*)"### The file number acquisition result Success ###\n",0,0,0,0,0,0);
				// 対象メディア領域を取得する.
				APIC_Backup* pc_Backup = NULL;
				pc_Backup = APIC_Backup::newInstance();
				if ( pc_Backup != NULL )
				{
NetTwainDebugTrace((char*)"### pc_Backup != NULL ###\n",0,0,0,0,0,0);
					// 応答データの分割バックアップ管理情報構造体のヘッダ情報を作成する.
					NETS_BackupPartitionedInfo nets_BackupPartitionedInfo;
					memset( &nets_BackupPartitionedInfo, 0, sizeof(NETS_BackupPartitionedInfo) );

					// Backup Media Manage Data.
					NETS_BackupMediaManageData* pc_BackupMediaManageData = netc_TwainClientMan.get_BackupMediaManageData();
					for ( short i = 1; i <= 10; i++ )
					{
						pc_Backup->lock();
						pc_Backup->getBackupAdressNVRAM( i, (void**)&(pc_BackupMediaManageData->vp_NVRAMAddress[i-1]), pc_BackupMediaManageData->sl_NVRAMSize[i-1] );
						pc_Backup->getBackupAddressFlash( i, (void**)&(pc_BackupMediaManageData->vp_FLASHAddress[i-1]), pc_BackupMediaManageData->sl_FLASHSize[i-1] );
						pc_Backup->unlock();
NetTwainDebugTrace((char*)"### NVRAMAddress[%d] = %p ###\n",i-1,reinterpret_cast<intptr_t>(pc_BackupMediaManageData->vp_NVRAMAddress[i-1]),0,0,0,0);		
NetTwainDebugTrace((char*)"### NVRAMSize[%d]    = %d ###\n",i-1,pc_BackupMediaManageData->sl_NVRAMSize[i-1],0,0,0,0);
NetTwainDebugTrace((char*)"### FLASHAddress[%d] = %p ###\n",i-1,reinterpret_cast<intptr_t>(pc_BackupMediaManageData->vp_FLASHAddress[i-1]),0,0,0,0);		
NetTwainDebugTrace((char*)"### FLASHSize[%d]    = %d ###\n",i-1,pc_BackupMediaManageData->sl_FLASHSize[i-1],0,0,0,0);
					}
					// NVRAM ---------------------------------------------------------------------------.
					uint32_t ul_NVSize = 0;			// 単位：バイト.
					uint32_t ul_TotalNVSize = 0;		// 単位：Kバイト.
					// Donauでは先頭の領域にのみ設定される.
					if ( pc_BackupMediaManageData->vp_NVRAMAddress[0] != NULL )
					{
						ul_NVSize += pc_BackupMediaManageData->sl_NVRAMSize[0];
					}
NetTwainDebugTrace((char*)"### ul_NVSize = %d ###\n",ul_NVSize,0,0,0,0,0);
					// 1M単位化.
					if ( (ul_NVSize != 0) 							// サイズが 0でなく.
					  && ((ul_NVSize % (1024*1024)) != 0) )			// 1Mで割った余りがある(1M未満のデータがある).
					{
						ul_NVSize = ((ul_NVSize / (1024*1024)) * (1024*1024)) + (1024*1024);
					}
NetTwainDebugTrace((char*)"### ul_NVSize (1M unit) = %d ###\n",ul_NVSize,0,0,0,0,0);
					// メディアファイルヘッダ付加分加算.
					ul_NVSize = ul_NVSize + (1024*1024);
NetTwainDebugTrace((char*)"### ul_NVSize (+Header) = %d ###\n",ul_NVSize,0,0,0,0,0);
					// 単位：Kバイト.
					ul_TotalNVSize = ul_NVSize / 1024;
NetTwainDebugTrace((char*)"### ul_TotalNVSize (+Header) (KB) = %d ###\n",ul_TotalNVSize,0,0,0,0,0);
					// FLASH ---------------------------------------------------------------------------.
					uint32_t ul_FlashSize = 0;				// 単位：バイト.
					uint32_t ul_TotalFlashSize = 0;		// 単位：Kバイト.
// >> 2008.05.15 Harada Donau対応 FLASHサイズ変更.
					// FLASHのサイズは実データサイズでなく1Mとする.
					// FLASHにデータがない場合は、アドレスはNULL、サイズは0となっておりデータバックアップしない.
					// 0のデータであっても強制的に1M分のデータをバックアップするようサイズを1Mとしておく.
					ul_FlashSize = 1024 * 1024;
// << 2008.05.15 Harada Donau対応 FLASHサイズ変更.
NetTwainDebugTrace((char*)"### ul_FlashSize = %d ###\n",ul_FlashSize,0,0,0,0,0);
					// メディアファイルヘッダ付加分加算.
					ul_FlashSize = ul_FlashSize + (1024*1024);
NetTwainDebugTrace((char*)"### ul_FlashSize (+Header) = %d ###\n",ul_FlashSize,0,0,0,0,0);
					// 単位：Kバイト.
					ul_TotalFlashSize = ul_FlashSize / 1024;
NetTwainDebugTrace((char*)"### ul_TotalFlashSize (+Header) (KB) = %d ###\n",ul_TotalFlashSize,0,0,0,0,0);
					// DOS領域のファイル ---------------------------------------------------------------.
					int32_t sl_FileNum = 0;
					sl_FileNum = (int32_t)s_GetBackupFileNum.ul_FileNum;		// バックアップ対象ファイル数を設定.
NetTwainDebugTrace((char*)"### sl_FileNum = %d ###\n",sl_FileNum,0,0,0,0,0);
					char tmp[256];
					memset( &tmp[0], 0, sizeof(tmp) );
					uint32_t ul_FileSize = 0;
					uint32_t ul_TotalFileSize = 0;		// 単位：Kバイト.
					STATUS status_DosFile = OK;		// システムアクセス結果 
					for ( int32_t i=0; i<sl_FileNum; i++ ) {
						pc_Backup->lock();
						status_DosFile = pc_Backup->getBackupFileInfo( i, &tmp[0], ul_FileSize );
						pc_Backup->unlock();
						if ( status_DosFile == ERROR ) {
							break;
						}
NetTwainDebugTrace((char*)"### ul_FileSize = %d ###\n",ul_FileSize,0,0,0,0,0);
						// 1M単位化.
						if ( (ul_FileSize != 0) 						// サイズが 0でなく.
						  && ((ul_FileSize % (1024*1024)) != 0) )		// 1Mで割った余りがある(1M未満のデータがある).
						{
							ul_FileSize = ((ul_FileSize / (1024*1024)) * (1024*1024)) + (1024*1024);
						}
NetTwainDebugTrace((char*)"### ul_FileSize (1M unit) = %d ###\n",ul_FileSize,0,0,0,0,0);
						// メディアファイルヘッダ付加分加算.
						ul_FileSize = ul_FileSize + (1024*1024);
NetTwainDebugTrace((char*)"### ul_FileSize (+Header) = %d ###\n",ul_FileSize,0,0,0,0,0);
						// 単位：Kバイト.
						ul_TotalFileSize = ul_TotalFileSize + (ul_FileSize / 1024);
NetTwainDebugTrace((char*)"### ul_TotalFileSize (KB) = %d ###\n",ul_TotalFileSize,0,0,0,0,0);
						ul_FileSize = 0;	// クリア.
					}
					// スレッド領域のFAT(画像情報) -----------------------------------------------------.
					// スレッド領域のFAT(管理情報) -----------------------------------------------------.
					uint32_t ul_FatSizeImage = 0;			// 単位：バイト.
					uint32_t ul_TotalFatSizeImage = 0;		// 単位：Kバイト.
					uint32_t ul_FatSizeInfo = 0;			// 単位：バイト.
					uint32_t ul_TotalFatSizeInfo = 0;		// 単位：Kバイト.
					pc_Backup->lock();
					pc_Backup->getThrtFatSize( ul_FatSizeImage, ul_FatSizeInfo );
					pc_Backup->unlock();
NetTwainDebugTrace((char*)"### ul_FatSizeImage = %d ###\n",ul_FatSizeImage,0,0,0,0,0);
					// 1M単位化.
					if ( (ul_FatSizeImage != 0) 						// サイズが 0でなく.
					  && ((ul_FatSizeImage % (1024*1024)) != 0) )		// 1Mで割った余りがある(1M未満のデータがある).
					{
						ul_FatSizeImage = ((ul_FatSizeImage / (1024*1024)) * (1024*1024)) + (1024*1024);
					}
NetTwainDebugTrace((char*)"### ul_FatSizeImage (1M unit) = %d ###\n",ul_FatSizeImage,0,0,0,0,0);
					// メディアファイルヘッダ付加分加算.
					ul_FatSizeImage = ul_FatSizeImage + (1024*1024);
NetTwainDebugTrace((char*)"### ul_FatSizeImage (+Header) = %d ###\n",ul_FatSizeImage,0,0,0,0,0);
					// 単位：Kバイト.
					ul_TotalFatSizeImage = ul_FatSizeImage / 1024;
NetTwainDebugTrace((char*)"### ul_TotalFatSizeImage (+Header) (KB) = %d ###\n",ul_TotalFatSizeImage,0,0,0,0,0);

NetTwainDebugTrace((char*)"### ul_FatSizeInfo = %d ###\n",ul_FatSizeInfo,0,0,0,0,0);
					// 1M単位化.
					if ( (ul_FatSizeInfo != 0) 						// サイズが 0でなく.
					  && ((ul_FatSizeInfo % (1024*1024)) != 0) )		// 1Mで割った余りがある(1M未満のデータがある).
					{
						ul_FatSizeInfo = ((ul_FatSizeInfo / (1024*1024)) * (1024*1024)) + (1024*1024);
					}
NetTwainDebugTrace((char*)"### ul_FatSizeInfo (1M unit) = %d ###\n",ul_FatSizeInfo,0,0,0,0,0);
					// メディアファイルヘッダ付加分加算.
					ul_FatSizeInfo = ul_FatSizeInfo + (1024*1024);
NetTwainDebugTrace((char*)"### ul_FatSizeInfo (+Header) = %d ###\n",ul_FatSizeInfo,0,0,0,0,0);
					// 単位：Kバイト.
					ul_TotalFatSizeInfo = ul_FatSizeInfo / 1024;
NetTwainDebugTrace((char*)"### ul_TotalFatSizeInfo (+Header) (KB) = %d ###\n",ul_TotalFatSizeInfo,0,0,0,0,0);
					// スレッド領域のクラスタ(画像情報) ------------------------------------------------.
					uint32_t ul_ClusterSize = 0;
					uint32_t ul_ClusterNum = 0;
					uint32_t ul_ClusterNumOf1M = 0;			// クラスタサイズでの1MB中のクラスタ数.
					uint32_t ul_TransferNum = 0;				// 1MB単位での転送回数.
					uint32_t ul_TotalClusterSizeImage = 0;		// 単位：Kバイト.
					STATUS status_ClusterImage = OK;		// システムアクセス結果 
					pc_Backup->lock();
					status_ClusterImage = pc_Backup->getThrClusterInfo( TYPE_BackupTypeImage, ul_ClusterSize, ul_ClusterNum );
					pc_Backup->unlock();
NetTwainDebugTrace((char*)"### ul_ClusterSize = %d ###\n",ul_ClusterSize,0,0,0,0,0);
NetTwainDebugTrace((char*)"### ul_ClusterNum = %d ###\n",ul_ClusterNum,0,0,0,0,0);
					if ( ul_ClusterSize != 0 ) {		// サイズが 0でない.
						ul_ClusterNumOf1M = (1024*1024) / ul_ClusterSize;		// クラスタサイズでの1MB中のクラスタ数.
					}
NetTwainDebugTrace((char*)"### ul_ClusterNumOf1M = %d ###\n",ul_ClusterNumOf1M,0,0,0,0,0);
					if ( ul_ClusterNumOf1M != 0) {		// サイズが 0でない.
						ul_TransferNum = ul_ClusterNum / ul_ClusterNumOf1M;		// 1MB単位での転送回数.
					}
NetTwainDebugTrace((char*)"### ul_TransferNum = %d ###\n",ul_TransferNum,0,0,0,0,0);
					// 1M単位化.
					if ( ((ul_ClusterNum != 0) && (ul_ClusterNumOf1M != 0))		// サイズが 0でなく.
					  && ((ul_ClusterNum % ul_ClusterNumOf1M) != 0) )			// 1Mで割った余りがある(1M未満のデータがある).
					{
						// 1M単位化で余り分の1Mを加算.
						ul_TransferNum = (ul_ClusterNum / ul_ClusterNumOf1M) + 1;
NetTwainDebugTrace((char*)"### ul_TransferNum = %d ###\n",ul_TransferNum,0,0,0,0,0);
					}
					// Kバイト単位化.
					ul_TotalClusterSizeImage = ul_TransferNum * 1024;
NetTwainDebugTrace((char*)"### ul_TotalClusterSizeImage (1M unit) (KB) = %d ###\n",ul_TotalClusterSizeImage,0,0,0,0,0);
					// メディアファイルヘッダ付加分加算.
					ul_TotalClusterSizeImage = ul_TotalClusterSizeImage + 1024;
NetTwainDebugTrace((char*)"### ul_TotalClusterSizeImage (+Header) (KB) = %d ###\n",ul_TotalClusterSizeImage,0,0,0,0,0);
					// スレッド領域のクラスタ(管理情報) ------------------------------------------------.
					ul_ClusterSize = 0;
					ul_ClusterNum = 0;
					ul_ClusterNumOf1M = 0;							// クラスタサイズでの1MB中のクラスタ数.
					ul_TransferNum = 0;								// 1MB単位での転送回数.
					uint32_t ul_TotalClusterSizeInfo = 0;		// 単位：Kバイト.
					STATUS status_ClusterInfo = OK;		// システムアクセス結果 
					pc_Backup->lock();
					status_ClusterInfo = pc_Backup->getThrClusterInfo( TYPE_BackupTypeInfo, ul_ClusterSize, ul_ClusterNum );
					pc_Backup->unlock();
NetTwainDebugTrace((char*)"### ul_ClusterSize = %d ###\n",ul_ClusterSize,0,0,0,0,0);
NetTwainDebugTrace((char*)"### ul_ClusterNum = %d ###\n",ul_ClusterNum,0,0,0,0,0);
					if ( ul_ClusterSize != 0 ) {		// サイズが 0でない.
						ul_ClusterNumOf1M = (1024*1024) / ul_ClusterSize;		// クラスタサイズでの1MB中のクラスタ数.
					}
NetTwainDebugTrace((char*)"### ul_ClusterNumOf1M = %d ###\n",ul_ClusterNumOf1M,0,0,0,0,0);
					if ( ul_ClusterNumOf1M != 0) {		// サイズが 0でない.
						ul_TransferNum = ul_ClusterNum / ul_ClusterNumOf1M;		// 1MB単位での転送回数.
					}
NetTwainDebugTrace((char*)"### ul_TransferNum = %d ###\n",ul_TransferNum,0,0,0,0,0);
					// 1M単位化.
					if ( ((ul_ClusterNum != 0) && (ul_ClusterNumOf1M != 0))		// サイズが 0でなく.
					  && ((ul_ClusterNum % ul_ClusterNumOf1M) != 0) )			// 1Mで割った余りがある(1M未満のデータがある).
					{
						// 1M単位化で余り分の1Mを加算.
						ul_TransferNum = (ul_ClusterNum / ul_ClusterNumOf1M) + 1;
NetTwainDebugTrace((char*)"### ul_TransferNum = %d ###\n",ul_TransferNum,0,0,0,0,0);
					}
					// Kバイト単位化.
					ul_TotalClusterSizeInfo = ul_TransferNum * 1024;
NetTwainDebugTrace((char*)"### ul_TotalClusterSizeInfo (1M unit) (KB) = %d ###\n",ul_TotalClusterSizeInfo,0,0,0,0,0);
					// メディアファイルヘッダ付加分加算.
					ul_TotalClusterSizeInfo = ul_TotalClusterSizeInfo + 1024;
NetTwainDebugTrace((char*)"### ul_TotalClusterSizeInfo (+Header) (KB) = %d ###\n",ul_TotalClusterSizeInfo,0,0,0,0,0);

					if ( (status_DosFile == OK) && (status_ClusterImage == OK) && (status_ClusterInfo == OK) )		// システムアクセス成功 
					{
NetTwainDebugTrace((char*)"### System Access Success ###\n",0,0,0,0,0,0);
						// Data Size.
						uint32_t ul_DataSize = 0;
						ul_DataSize = ( ul_TotalNVSize
									  + ul_TotalFlashSize
									  + ul_TotalFileSize
									  + ul_TotalFatSizeImage
									  + ul_TotalFatSizeInfo
									  + ul_TotalClusterSizeImage
									  + ul_TotalClusterSizeInfo );	// 単位：KB.
NetTwainDebugTrace((char*)"### ul_DataSize = %d ###\n",ul_DataSize,0,0,0,0,0);
						// 分割バックアップ管理情報分も加算.
						uint32_t ul_BackupInfoDataSize = 0;
						ul_BackupInfoDataSize = sizeof( NETS_BackupInfoData );
NetTwainDebugTrace((char*)"### ul_BackupInfoDataSize = %d ###\n",ul_BackupInfoDataSize,0,0,0,0,0);
						// 1K単位化.
						if ( (ul_BackupInfoDataSize != 0) 					// サイズが 0でなく.
						  && ((ul_BackupInfoDataSize % 1024) != 0) )		// 1Kで割った余りがある(1K未満のデータがある).
						{
							ul_BackupInfoDataSize = ((ul_BackupInfoDataSize / 1024) * 1024) + 1024;
						}
NetTwainDebugTrace((char*)"### ul_BackupInfoDataSize (1K unit) = %d ###\n",ul_BackupInfoDataSize,0,0,0,0,0);
						ul_DataSize = ul_DataSize + ul_BackupInfoDataSize;
NetTwainDebugTrace((char*)"### ul_DataSize = %d ###\n",ul_DataSize,0,0,0,0,0);
						nets_BackupPartitionedInfo.uc_DataSize[0] = (unsigned char)( ul_DataSize        & 0xFF);				// Data Size (KByte).
						nets_BackupPartitionedInfo.uc_DataSize[1] = (unsigned char)((ul_DataSize >>  8) & 0xFF);				// Data Size (KByte).
						nets_BackupPartitionedInfo.uc_DataSize[2] = (unsigned char)((ul_DataSize >> 16) & 0xFF);				// Data Size (KByte).
						nets_BackupPartitionedInfo.uc_DataSize[3] = (unsigned char)((ul_DataSize >> 24) & 0xFF);				// Data Size (KByte).
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_DataSize[0] = %02x ###\n",nets_BackupPartitionedInfo.uc_DataSize[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_DataSize[1] = %02x ###\n",nets_BackupPartitionedInfo.uc_DataSize[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_DataSize[2] = %02x ###\n",nets_BackupPartitionedInfo.uc_DataSize[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_DataSize[3] = %02x ###\n",nets_BackupPartitionedInfo.uc_DataSize[3],0,0,0,0,0);
						// Media File Num.
						int32_t sl_MediaFileNum = 0;
						sl_MediaFileNum = 6 + (int32_t)s_GetBackupFileNum.ul_FileNum;
NetTwainDebugTrace((char*)"### sl_MediaFileNum = %d ###\n",sl_MediaFileNum,0,0,0,0,0);
						nets_BackupPartitionedInfo.uc_MediaFileNum[0] = (unsigned char)( sl_MediaFileNum        & 0xFF);		// Media Files Number.
						nets_BackupPartitionedInfo.uc_MediaFileNum[1] = (unsigned char)((sl_MediaFileNum >>  8) & 0xFF);		// Media Files Number.
						nets_BackupPartitionedInfo.uc_MediaFileNum[2] = (unsigned char)((sl_MediaFileNum >> 16) & 0xFF);		// Media Files Number.
						nets_BackupPartitionedInfo.uc_MediaFileNum[3] = (unsigned char)((sl_MediaFileNum >> 24) & 0xFF);		// Media Files Number.
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_MediaFileNum[0] = %02x ###\n",nets_BackupPartitionedInfo.uc_MediaFileNum[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_MediaFileNum[1] = %02x ###\n",nets_BackupPartitionedInfo.uc_MediaFileNum[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_MediaFileNum[2] = %02x ###\n",nets_BackupPartitionedInfo.uc_MediaFileNum[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_MediaFileNum[3] = %02x ###\n",nets_BackupPartitionedInfo.uc_MediaFileNum[3],0,0,0,0,0);
						// Information Data Size.
						int32_t sl_InfoDataSize = 0;
						sl_InfoDataSize = sizeof(NETS_BackupInfoData);
NetTwainDebugTrace((char*)"### sl_InfoDataSize = %d ###\n",sl_InfoDataSize,0,0,0,0,0);
						nets_BackupPartitionedInfo.uc_InfoDataSize[0] = (unsigned char)( sl_InfoDataSize        & 0xFF);		// Information Data Size.
						nets_BackupPartitionedInfo.uc_InfoDataSize[1] = (unsigned char)((sl_InfoDataSize >>  8) & 0xFF);		// Information Data Size.
						nets_BackupPartitionedInfo.uc_InfoDataSize[2] = (unsigned char)((sl_InfoDataSize >> 16) & 0xFF);		// Information Data Size.
						nets_BackupPartitionedInfo.uc_InfoDataSize[3] = (unsigned char)((sl_InfoDataSize >> 24) & 0xFF);		// Information Data Size.
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_InfoDataSize[0] = %02x ###\n",nets_BackupPartitionedInfo.uc_InfoDataSize[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_InfoDataSize[1] = %02x ###\n",nets_BackupPartitionedInfo.uc_InfoDataSize[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_InfoDataSize[2] = %02x ###\n",nets_BackupPartitionedInfo.uc_InfoDataSize[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### nets_BackupPartitionedInfo.uc_InfoDataSize[3] = %02x ###\n",nets_BackupPartitionedInfo.uc_InfoDataSize[3],0,0,0,0,0);

						// 分割バックアップ管理情報作成.
						NETS_BackupInfoData s_BackupInfoData;
						memset( &s_BackupInfoData, 0, sizeof(NETS_BackupInfoData) );
						// キーワード(識別子).
						strcpy( s_BackupInfoData.sc_KeyWord, NETD_INFODATA_KEYWORD );
if ( s_BackupInfoData.sc_KeyWord[0] == '\0' ) {
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_KeyWord = NULL ###\n",0,0,0,0,0,0);
} else {
	for ( uint32_t j=0; j < strlen(s_BackupInfoData.sc_KeyWord); j++ ) {
		char tmp = s_BackupInfoData.sc_KeyWord[j];
		if ( tmp == 0x00 ) { break; }
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_KeyWord[%d] = [%c][%02x] ###\n",
		j,( (('0' <= tmp) && (tmp <= '9')) || (('A' <= tmp) && (tmp <= 'Z')) || (('a' <= tmp) && (tmp <= 'z')) ? tmp : '?' ),(tmp & 0x000000ff),0,0,0);
	}
}
						// バージョン.
						UStoC2LE( s_BackupInfoData.sc_Version, NETD_INFODATA_VERSION );
NetTwainDebugTrace((char*)"### us_Version = %d ###\n",NETD_INFODATA_VERSION,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_Version[0] = %02x ###\n",s_BackupInfoData.sc_Version[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_Version[1] = %02x ###\n",s_BackupInfoData.sc_Version[1],0,0,0,0,0);
						// メディアファイル数.
						SLtoC4LE( s_BackupInfoData.sc_MediaFileNum, sl_MediaFileNum );
NetTwainDebugTrace((char*)"### sl_MediaFileNum = %d ###\n",sl_MediaFileNum,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_MediaFileNum[0] = %02x ###\n",s_BackupInfoData.sc_MediaFileNum[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_MediaFileNum[1] = %02x ###\n",s_BackupInfoData.sc_MediaFileNum[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_MediaFileNum[2] = %02x ###\n",s_BackupInfoData.sc_MediaFileNum[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_MediaFileNum[3] = %02x ###\n",s_BackupInfoData.sc_MediaFileNum[3],0,0,0,0,0);
						// MIB SysObjectID.
						APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();
						if ( pc_SystemInfo != NULL ) {
							pc_SystemInfo->lock();
							pc_SystemInfo->getSysObjectID( &s_BackupInfoData.sc_SysObjectID[0] );
							pc_SystemInfo->unlock();
						}
// << 2008.03.03 Harada Donau対応 No.EE ObjectIDの取得方法を変更 MIB→CommonAPI.
if ( s_BackupInfoData.sc_SysObjectID[0] == '\0' ) {
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_SysObjectID = NULL ###\n",0,0,0,0,0,0);
} else {
	for ( uint32_t j=0; j < strlen(s_BackupInfoData.sc_SysObjectID); j++ ) {
		char tmp = s_BackupInfoData.sc_SysObjectID[j];
		if ( tmp == 0x00 ) { break; }
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_SysObjectID[%d] = [%c][%02x] ###\n",
		j,( (('0' <= tmp) && (tmp <= '9')) || (('A' <= tmp) && (tmp <= 'Z')) || (('a' <= tmp) && (tmp <= 'z')) ? tmp : '?' ),(tmp & 0x000000ff),0,0,0);
	}
}
						// Serial Number.
						if ( pc_SystemInfo == NULL ) {
							errorLog_TwainService("sp NULL!!!\n",0,0,0,0,0,0);
							return;
						}
						pc_SystemInfo->lock();
						pc_SystemInfo->getSerialNoPrinter( &s_BackupInfoData.sc_SerialNumber[0] );
						pc_SystemInfo->unlock();
if ( s_BackupInfoData.sc_SerialNumber[0] == '\0' ) {
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_SerialNumber = NULL ###\n",0,0,0,0,0,0);
} else {
	for ( uint32_t j=0; j < strlen(s_BackupInfoData.sc_SerialNumber); j++ ) {
		char tmp = s_BackupInfoData.sc_SerialNumber[j];
		if ( tmp == 0x00 ) { break; }
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_SerialNumber[%d] = [%c][%02x] ###\n",
		j,( (('0' <= tmp) && (tmp <= '9')) || (('A' <= tmp) && (tmp <= 'Z')) || (('a' <= tmp) && (tmp <= 'z')) ? tmp : '?' ),(tmp & 0x000000ff),0,0,0);
	}
}
						// データ領域サイズ.
						uint32_t ul_SubDataSize = 0;
						ul_SubDataSize = sizeof( s_BackupInfoData.sc_InternalVersion )
									   + sizeof( s_BackupInfoData.sc_DocDBVersion )
									   + sizeof( s_BackupInfoData.sc_DeviceComposition );
						ULtoC4LE( s_BackupInfoData.sc_SubDataSize, ul_SubDataSize );
NetTwainDebugTrace((char*)"### ul_SubDataSize = %d ###\n",ul_SubDataSize,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_SubDataSize[0] = %02x ###\n",s_BackupInfoData.sc_SubDataSize[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_SubDataSize[1] = %02x ###\n",s_BackupInfoData.sc_SubDataSize[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_SubDataSize[2] = %02x ###\n",s_BackupInfoData.sc_SubDataSize[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_SubDataSize[3] = %02x ###\n",s_BackupInfoData.sc_SubDataSize[3],0,0,0,0,0);
						// 内部管理バージョン.
						s_BackupInfoData.sc_InternalVersion = NETD_INTERNAL_VERSION;
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_InternalVersion = %d ###\n",s_BackupInfoData.sc_InternalVersion,0,0,0,0,0);
						// DOC DB Version.
						APIC_BoxRegistry* pc_BoxRegistry = NULL;
						pc_BoxRegistry = APIC_BoxRegistry::newInstance();
						int32_t sl_DocDBVersion = 0;
						sl_DocDBVersion = pc_BoxRegistry->getDocVersion();
						pc_BoxRegistry->deleteInstance();
						SLtoC4LE( s_BackupInfoData.sc_DocDBVersion, sl_DocDBVersion );
NetTwainDebugTrace((char*)"### sl_DocDBVersion = %d ###\n",sl_DocDBVersion,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_DocDBVersion[0] = %02x ###\n",s_BackupInfoData.sc_DocDBVersion[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_DocDBVersion[1] = %02x ###\n",s_BackupInfoData.sc_DocDBVersion[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_DocDBVersion[2] = %02x ###\n",s_BackupInfoData.sc_DocDBVersion[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_DocDBVersion[3] = %02x ###\n",s_BackupInfoData.sc_DocDBVersion[3],0,0,0,0,0);
						// Device Composition (デバイス構成).
						int32_t sl_DeviceComposition = 0x01;
						if ( isHDDExist() == True )	// HDDありの場合.
						{
							sl_DeviceComposition += 0x02;
						}
						SLtoC4LE( s_BackupInfoData.sc_DeviceComposition, sl_DeviceComposition );
NetTwainDebugTrace((char*)"### sl_DeviceComposition = %02x ###\n",sl_DeviceComposition,0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_DeviceComposition[0] = %02x ###\n",s_BackupInfoData.sc_DeviceComposition[0],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_DeviceComposition[1] = %02x ###\n",s_BackupInfoData.sc_DeviceComposition[1],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_DeviceComposition[2] = %02x ###\n",s_BackupInfoData.sc_DeviceComposition[2],0,0,0,0,0);
NetTwainDebugTrace((char*)"### s_BackupInfoData.sc_DeviceComposition[3] = %02x ###\n",s_BackupInfoData.sc_DeviceComposition[3],0,0,0,0,0);
						// 分割バックアップ管理情報の設定.
						netc_TwainClientMan.setBackupInfoData( s_BackupInfoData );

						// 応答データ生成.
						char tmpdata[128];
						sprintf( tmpdata, "\x1b*s35125t%dW", sizeof(NETS_BackupPartitionedInfo) + sizeof(NETS_BackupInfoData) );		// 応答データ作成.
						pc_RspData = (char*)malloc(strlen(tmpdata) + sizeof(NETS_BackupPartitionedInfo) + sizeof(NETS_BackupInfoData));
						if ( pc_RspData == NULL )	// 領域確保できない場合.
						{
							netc_TwainClientMan.setBackUpExistError( SocketFd, True );				// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
							netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_MEMORY_OVERFLOW , __FILE__ ,__LINE__);		// Error Client Error Info.
							netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
NetTwainDebugTrace((char*)"# _ReqGetBackupFileNum_ERR_MEMORY_OVERFLOW #\n", 0,0,0,0,0,0);
							strcpy( pc_ReqData, "\x1b*s35125tN" );	// 失敗応答.
							bl_ErrorDetect = True;
						}
						else						// 領域確保できた場合.
						{
							int length = 0;
							memcpy( &pc_RspData[0], tmpdata, strlen(tmpdata) );
							length = strlen(tmpdata);
							memcpy( &pc_RspData[length], &nets_BackupPartitionedInfo, sizeof(NETS_BackupPartitionedInfo) );
							length = length + sizeof(NETS_BackupPartitionedInfo);
							memcpy( &pc_RspData[length], &s_BackupInfoData, sizeof(NETS_BackupInfoData) );
							length = length + sizeof(NETS_BackupInfoData);
							si_RspLength = length;
						}
					}
					else					// システムアクセス失敗.
					{
NetTwainDebugTrace((char*)"### System Access Failed ###\n",0,0,0,0,0,0);
						netc_TwainClientMan.setBackUpExistError( SocketFd, True );				// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);		// Error Client Error Info.
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# _ReqGetBackupFileNum_ERR_DEVICE_ERROR1_1 #\n", 0,0,0,0,0,0);
						strcpy( pc_ReqData, "\x1b*s35125tN" );	// 失敗応答.
						bl_ErrorDetect = True;
					}
				}
			}
			else									// 失敗.
			{
NetTwainDebugTrace((char*)"### The file number acquisition result Error ###\n",0,0,0,0,0,0);
				netc_TwainClientMan.setBackUpExistError( SocketFd, True );				// 2012/03/15 amiya【ZeusMLK】UV-01212 ISO15408：監査ログ機能のPP（IEEE2600.1）要件への対応.
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_DEVICE_ERROR1 , __FILE__ ,__LINE__);		// Error Client Error Info.
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
NetTwainDebugTrace((char*)"# _ReqGetBackupFileNum_ERR_DEVICE_ERROR1_2 #\n", 0,0,0,0,0,0);
				strcpy( pc_ReqData, "\x1b*s35125tN" );	// 失敗応答.
				bl_ErrorDetect = True;
			}

			if ( bl_ErrorDetect == True )	// エラー系の場合.
			{
NetTwainDebugTrace((char*)"### Error Response Size Error ###\n",0,0,0,0,0,0);
				pc_RspData = (char*)malloc( strlen(pc_ReqData) );
				if( pc_RspData == NULL ){
					errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {		// RREQを受けている.
					if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_BACKUP_PARTITIONED_INFO ) {	// WDATコマンドがSCL_GET_BACKUP_PARTITIONED_INFOである.
						netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
					} else {
						free( pc_RspData );
					}
				}
			}
			else if ( pc_RspData != NULL )		// 応答データがある場合.
			{
NetTwainDebugTrace((char*)"### Success Response ###\n",0,0,0,0,0,0);
				netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)si_RspLength );		// 送信データ保持領域に書き込む.
				if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
					if ( netc_TwainClientMan.getCommandID( SocketFd ) == SCL_GET_BACKUP_PARTITIONED_INFO ) {	// WDATコマンドがSCL_GET_BACKUP_PARTITIONED_INFOである.
						netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
					} else {
						free( pc_RspData );
					}
				}
			}
		}
	}
}

//		SCL_GET_BACKUP_PARTITIONED_INFO			84		// Get Backup Partitioned Info.
//==================================================================================================.
//[クラス]NETC_TwainCommandGetBackupPartitionedInfo.
//[内容] SCL_GET_BACKUP_PARTITIONED_INFOコマンドを処理するクラス.
