NETC_TwainCommandGetSpdfSupportInfo::NETC_TwainCommandGetSpdfSupportInfo( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================.
//[機能]コマンドを処理する.
//[戻り値].
//[コメント].
//[レビュー].
//[履歴] 2008.09.26 hiratani Amur_WBS No. 8 261 UV案件 新規実装.
//==================================================================================================.
void NETC_TwainCommandGetSpdfSupportInfo::CommandProc(
	int SocketFd,		// ソケットディスクリプタ.
	char* Parameter,	// パラメータへのポインタ.
	short ParamLength	// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetSpdfSupportInfo::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	
	NETS_GetSpdfSupportInfo nets_GetSpdfSupportInfo;								// 領域確保.
	memset( &nets_GetSpdfSupportInfo, 0x00, sizeof( nets_GetSpdfSupportInfo ) );	// 領域を初期化する.
	
	// NULLチェック.
	APIC_SearchablePDFSetting* pc_SearchablePDFSetting = NULL;
	pc_SearchablePDFSetting = APIC_SearchablePDFSetting::newInstance();
	if ( NULL != pc_SearchablePDFSetting ) {
NetTwainDebugTrace((char*)"### NETC_TwainCommandGetSpdfSupportInfo::NULL != pc_SearchablePDFSetting ###\n", 0,0,0,0,0,0);
		
		// SPDF辞書データ展開完了判定.
		pc_SearchablePDFSetting->lock();
		Bool b_SpdfDictionaryDataExpandFlg = pc_SearchablePDFSetting->getSearchablePDFDictionaryDataExpandFlg();
		pc_SearchablePDFSetting->unlock();
		if ( True == b_SpdfDictionaryDataExpandFlg ) {	// SPDF生成機能サポートON.
NetTwainDebugTrace((char*)"### NETC_TwainCommandGetSpdfSupportInfo::True == b_SpdfDictionaryDataExpandFlg ###\n", 0,0,0,0,0,0);
			
			// ★SPDF生成機能サポートON格納.
			nets_GetSpdfSupportInfo.sc_SpdfSupport = 0x01;
			
			// 言語一覧（サーチャブルPDF選択可能言語）取得処理.
			TYPE_LanguageOcr e_TempLanguageOcr[ TYPD_LanguageListNum ];							// 領域確保.
			memset( e_TempLanguageOcr, 0x00, sizeof( e_TempLanguageOcr ) );						// 領域を初期化する.
			pc_SearchablePDFSetting->lock();
			pc_SearchablePDFSetting->getSearchablePDFChoiceAbleLangList( e_TempLanguageOcr );	// 言語一覧取得.
			pc_SearchablePDFSetting->unlock();
			
			// 言語情報格納&言語数のカウント処理.
			int si_Num = 0;	// サポート言語数.
			for ( int i = 0; i < TYPD_LanguageListNum; i++ ) {
				
				// SPDF 設定言語.
				NETE_LanguageOcr nete_LanguageOcr = TYPE_LanguageOcrNone;
				switch (  e_TempLanguageOcr[i] ) {
					case TYPE_LanguageOcrJapanese:		// 日本語.
						nete_LanguageOcr =  NETE_LanguageOcrJapanese;
						break;
					case TYPE_LanguageOcrEnglish:		// 英語.
						nete_LanguageOcr =  NETE_LanguageOcrEnglish;
						break;
					case TYPE_LanguageOcrFrench:		// フランス語.
						nete_LanguageOcr =  NETE_LanguageOcrFrench;
						break;
					case TYPE_LanguageOcrItalian:		// イタリア語.
						nete_LanguageOcr =  NETE_LanguageOcrItalian;
						break;
					case TYPE_LanguageOcrGerman:		// ドイツ語.
						nete_LanguageOcr =  NETE_LanguageOcrGerman;
						break;
					case TYPE_LanguageOcrSpanish:		// スペイン語.
						nete_LanguageOcr =  NETE_LanguageOcrSpanish;
						break;
					case TYPE_LanguageOcrChinese1:		// 中国語（簡体字）.
						nete_LanguageOcr =  NETE_LanguageOcrChinese1;
						break;
					case TYPE_LanguageOcrChinese2:		// 台湾語（繁体字）.
						nete_LanguageOcr =  NETE_LanguageOcrChinese2;
						break;
					case TYPE_LanguageOcrKorean:		// 韓国語.
						nete_LanguageOcr =  NETE_LanguageOcrKorean;
						break;
					case TYPE_LanguageOcrDutch:			// オランダ語.
						nete_LanguageOcr =  NETE_LanguageOcrDutch;
						break;
					case TYPE_LanguageOcrDanish:		// デンマーク語.
						nete_LanguageOcr =  NETE_LanguageOcrDanish;
						break;
					case TYPE_LanguageOcrNorwegian:		// ノルウェー語.
						nete_LanguageOcr =  NETE_LanguageOcrNorwegian;
						break;
					case TYPE_LanguageOcrSwedish:		// スウェーデン語.
						nete_LanguageOcr =  NETE_LanguageOcrSwedish;
						break;
					case TYPE_LanguageOcrFinnish:		// フィンランド語.
						nete_LanguageOcr =  NETE_LanguageOcrFinnish;
						break;
					case TYPE_LanguageOcrPortuguese:	// ポルトガル語.
						nete_LanguageOcr =  NETE_LanguageOcrPortuguese;
						break;
					case TYPE_LanguageOcrTurkish:		// トルコ語.
						nete_LanguageOcr =  NETE_LanguageOcrTurkish;
						break;
					case TYPE_LanguageOcrGreek:			// ギリシャ語.
						nete_LanguageOcr =  NETE_LanguageOcrGreek;
						break;
					case TYPE_LanguageOcrCzech:			// チェコ語.
						nete_LanguageOcr =  NETE_LanguageOcrCzech;
						break;
					case TYPE_LanguageOcrPolish:		// ポーランド語.
						nete_LanguageOcr =  NETE_LanguageOcrPolish;
						break;
					case TYPE_LanguageOcrHungarian:		// ハンガリー語.
						nete_LanguageOcr =  NETE_LanguageOcrHungarian;
						break;
					case TYPE_LanguageOcrSlovak:		// スロバキア語.
						nete_LanguageOcr =  NETE_LanguageOcrSlovak;
						break;
					case TYPE_LanguageOcrRussian:		// ロシア語.
						nete_LanguageOcr =  NETE_LanguageOcrRussian;
						break;
					case TYPE_LanguageOcrCatalan:		// カタロニア語.
						nete_LanguageOcr =  NETE_LanguageOcrCatalan;
						break;
					case TYPE_LanguageOcrLithuanian:	// リトアニア語.
						nete_LanguageOcr =  NETE_LanguageOcrLithuanian;
						break;
					case TYPE_LanguageOcrEstonian:		// エストニア語.
						nete_LanguageOcr =  NETE_LanguageOcrEstonian;
						break;
					case TYPE_LanguageOcrLatvian:		// ラトビア語.
						nete_LanguageOcr =  NETE_LanguageOcrLatvian;
						break;
					case TYPE_LanguageOcrSlovenia:		// スロベニア語.
						nete_LanguageOcr =  NETE_LanguageOcrSlovenia;
						break;
					case TYPE_LanguageOcrRomanian:		// ルーマニア語.
						nete_LanguageOcr =  NETE_LanguageOcrRomanian;
						break;
					case TYPE_LanguageOcrUkrainian:		// ウクライナ語.
						nete_LanguageOcr =  NETE_LanguageOcrUkrainian;
						break;
					case TYPE_LanguageOcrBulgarian:		// ブルガリア語.
						nete_LanguageOcr =  NETE_LanguageOcrBulgarian;
						break;
					case TYPE_LanguageOcrCroatian:		// クロアチア語.
						nete_LanguageOcr =  NETE_LanguageOcrCroatian;
						break;
					case TYPE_LanguageOcrNone:			// 未設定.
					default:
						nete_LanguageOcr =  NETE_LanguageOcrNone;
						break;
				}
NetTwainDebugTrace((char*)"### NETC_TwainCommandGetSpdfSupportInfo::nete_LanguageOcr == [%d] ###\n", nete_LanguageOcr,0,0,0,0,0);
				// サポート言語情報判定.
				if ( TYPE_LanguageOcrNone != nete_LanguageOcr ) {
					// ★サポート言語情報格納.
					nets_GetSpdfSupportInfo.sc_Lang[ si_Num ] = nete_LanguageOcr;
					si_Num++;
				}
			}
			// ★サポート言語数格納.
			nets_GetSpdfSupportInfo.sc_LangNum = (char)si_Num;
		} else {										// SPDF生成機能サポートOFF.
NetTwainDebugTrace((char*)"### NETC_TwainCommandGetSpdfSupportInfo::True != b_SpdfDictionaryDataExpandFlg ###\n", 0,0,0,0,0,0);
			// ★SPDF生成機能サポートOFF格納.
			nets_GetSpdfSupportInfo.sc_SpdfSupport = 0x02;
		}
	} else {
NetTwainDebugTrace((char*)"### NETC_TwainCommandGetSpdfSupportInfo::NULL == pc_SearchablePDFSetting ###\n", 0,0,0,0,0,0);
		// ★SPDF生成機能サポートOFF格納.
		nets_GetSpdfSupportInfo.sc_SpdfSupport = 0x02;
	}
	
	char tmpd[32];
	short ss_dsize = (short)( sizeof( nets_GetSpdfSupportInfo.sc_SpdfSupport ) 
		+ sizeof( nets_GetSpdfSupportInfo.sc_LangNum ) + sizeof( char ) * nets_GetSpdfSupportInfo.sc_LangNum );
	int tmpLen = sprintf( tmpd, "\x1b*s314t%dW", ss_dsize );
	char* pc_ReqData = (char*)malloc(ss_dsize+tmpLen);
	if( pc_ReqData == NULL ){
		errorLog_TwainService("pc_ReqData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_ReqData, tmpd, tmpLen );
	memcpy( &pc_ReqData[tmpLen], (char*)&nets_GetSpdfSupportInfo, ss_dsize );
	netc_TwainClientMan.setSendData( SocketFd, pc_ReqData, (uint32_t)(tmpLen+ss_dsize) );	// 送信データ保存領域に書き込む.
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

// SCL_SET_HDD_TWAIN_PARAM_4			88 //: Set HDD Scan Parameter 4.
//==================================================================================================.
//[クラス]NETC_TwainCommandSetHDDTwainPara4.
//[内容] SCL_SET_HDD_TWAIN_PARAM_4コマンドを処理するクラス.
//[履歴] 2008.09.26 hiratani Amur_WBS No. 8 261 UV案件 新規実装.
//==================================================================================================.
//==================================================================================================.
//[機能]NETC_TwainCommandSetHDDTwainPara4のコンストラクタ.
//[戻り値].
//[コメント].
//[レビュー].
//[履歴] 2008.09.26 hiratani Amur_WBS No. 8 261 UV案件 新規実装.
//==================================================================================================.
NETC_TwainCommandSetHDDTwainPara4::NETC_TwainCommandSetHDDTwainPara4( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================.
//[機能]コマンドを処理する.
//[戻り値].
//[コメント].
//[レビュー].
//[履歴] 2008.09.26 hiratani Amur_WBS No. 8 261 UV案件 新規実装.
//==================================================================================================.
void NETC_TwainCommandSetHDDTwainPara4::CommandProc(
	int SocketFd,		// ソケットディスクリプタ.
	char* Parameter,	// パラメータへのポインタ.
	short ParamLen		// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandSetHDDTwainPara4::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	// 設定パラメータをローカルに保持.
	int32_t	NumOfDocs = 0;
	int32_t	_sl_DocID[10];		// ドキュメントID.
	memset( &_sl_DocID[0], 0, sizeof(int32_t)*10 );
	short	StartPage = 0;		// 開始ページ.
	short	EndPage = 0;		// 終了ページ.
	short	FileFormat = 0;		// ファイルフォーマット.
	short	offset = 0;
	int32_t	HDDXResolution = 0;	// 解像度 X.
	int32_t	HDDYResolution = 0;	// 解像度 Y.
	uchar	HDDColorMode = 0;	// カラーモード.
	char				sc_SpdfOnOff = 0;		// SPDF ON/OFF 設定.
	NETE_LanguageOcr	nete_LanguageOcr = 0;	// SPDF 設定言語.
	char				sc_SpdfRotate = 0;		// SPDF 回転補正.
	char				sc_OpdfOnOff = 0;		// OPDF ON/OFF 設定.
	// 設定データのチェック.
	Bool isError = False;		// エラー状態(初期値エラーなし：False).
	
	// ①コマンドが実行可能かチェック.
	char pc_ReqData[32];
	if( isCheckAvailableBox() == NETE_Function_Box_Disabled )				// BOX使用可能or一部使用可能のとき.	// 2011/03/31 amiya 【Minerva】管理No941 SSD削減対応（1GB⇒512MB）.
	{
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_HDD_NOT_INSTALLED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_HDD_NOT_INSTALLED , __FILE__ ,__LINE__);
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
		strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
		isError = True;		// エラーあり.
	} else if ( ( NULL != netc_TwainClientMan.getApic_Admin( SocketFd ) )
		&& ( True == netc_TwainClientMan.getUserLogined( SocketFd ) ) ) {	// ①管理者ログイン時.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_USER_BOX_NOT_SPECIFIED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
		strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.

		isError = True;		// エラーあり.
	} else {																// ①コマンド実行可能.
		if ( netc_TwainClientMan.getBoxLogined( SocketFd ) == True ) {	// Boxログイン状態.
			char _sc_BinarySize[4];
			memset( &_sc_BinarySize[0], 0, 4 );
			// #I[data]の#は25～61、memcpyサイズ 2.
			memcpy( _sc_BinarySize, Parameter, 2 );
			int32_t _si_BinarySize = atol( _sc_BinarySize );
			char _sc_BinaryData[64];
			memset( &_sc_BinaryData[0], 0, 64 );
			if ( Parameter[2] != 'L' )
			{
				isError = True;
			}
			else if ( _si_BinarySize < 25 )
			{
				isError = True;
			}
			else
			{
				if ( _si_BinarySize > 61 )
				{
					isError = True;
				}
				else if ( ParamLen < (3 + _si_BinarySize) )
				{
					isError = True;
				}
				else
				{
					memcpy( &_sc_BinaryData[0], &Parameter[3], _si_BinarySize );
					// ↓ の計算式.
					// ドキュメント数のサイズ(2) +.
					// DocumentNo.のサイズ(4) * ドキュメント数 +.
					// StartPageのサイズ(2) + EndPageのサイズ(2) + FileFormat/CompressionModeのサイズ(2) +.
					// SetScanXResolutionのサイズ(4) + SetScanYResolutionのサイズ(4) + ColorModeのサイズ(1) +.
					// SPDF ON/OFF(1) + SPDF展開言語(1) + SPDF回転補正(1) + OPDF(1).
					if ( 2+(_sc_BinaryData[0]+(_sc_BinaryData[1]<<8))*4 +6 +9 +4 != _si_BinarySize )
					{
						isError = True;
					}
				}
			}
			if ( isError == False )
			{
				NumOfDocs = _sc_BinaryData[0]+(_sc_BinaryData[1]<<8);
				if ( ( NumOfDocs > 10 ) || ( ( isAuthDeviceType2Available() ==True ) && ( NumOfDocs > 1 ) ) )		// 2010/12/21 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証.
				{
					isError = True;
				}
				else
				{
					int i = 0;
					for ( i = 0; i < NumOfDocs; i++ )
					{
						int32_t tmp = (unsigned char)(_sc_BinaryData[2+i*4])
								+ ((unsigned char)(_sc_BinaryData[2+i*4 + 1])<<8)
								+ ((unsigned char)(_sc_BinaryData[2+i*4 + 2])<<16)
								+ ((unsigned char)(_sc_BinaryData[2+i*4 + 3])<<24);
						memcpy( &_sl_DocID[i], &tmp, 4 );
					}
					StartPage  = (short)((unsigned char)(_sc_BinaryData[2+i*4])   + ((unsigned char)(_sc_BinaryData[2+i*4 + 1])<<8));		// 開始ページ.
					EndPage    = (short)((unsigned char)(_sc_BinaryData[2+i*4+2]) + ((unsigned char)(_sc_BinaryData[2+i*4 + 1 + 2])<<8));	// 終了ページ.
					FileFormat = (short)((unsigned char)(_sc_BinaryData[2+i*4+4]) + ((unsigned char)(_sc_BinaryData[2+i*4 + 1 + 4])<<8));	// ファイルフォーマット.
					
					offset = (short)((2+i*4) + 2 + 2 + 2);
					HDDXResolution = (unsigned char)(_sc_BinaryData[offset   ])
								  + ((unsigned char)(_sc_BinaryData[offset +1])<<8)
								  + ((unsigned char)(_sc_BinaryData[offset +2])<<16)
								  + ((unsigned char)(_sc_BinaryData[offset +3])<<24);												// 解像度 X.
					offset = (short)(offset + 4);
					HDDYResolution = (unsigned char)(_sc_BinaryData[offset   ])
								  + ((unsigned char)(_sc_BinaryData[offset +1])<<8)
								  + ((unsigned char)(_sc_BinaryData[offset +2])<<16)
								  + ((unsigned char)(_sc_BinaryData[offset +3])<<24);												// 解像度 Y.
					offset = (short)(offset + 4);
					HDDColorMode = (unsigned char)(_sc_BinaryData[offset]);															// カラーモード.
					offset = (short)(offset + 1);
					sc_SpdfOnOff = (unsigned char)(_sc_BinaryData[offset]);															// SPDF ON/OFF.
					offset = (short)(offset + 1);
					nete_LanguageOcr = (unsigned char)(_sc_BinaryData[offset]);														// SPDF 設定言語.
					offset = (short)(offset + 1);
					sc_SpdfRotate = (unsigned char)(_sc_BinaryData[offset]);														// SPDF 回転補正.
					offset = (short)(offset + 1);
					sc_OpdfOnOff = (unsigned char)(_sc_BinaryData[offset]);															// OPDF ON/OFF.
					
				}
			}

			if( isError == False ) {
				// StartPageのチェック.
				if ( StartPage < 0 ) {			// StartPageが負数.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR1 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					
					isError = True;		// エラーあり.
				}
				// EndPageのチェック.
				if ( EndPage < 0 ) {			// EndPageが負数.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR2 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					isError = True;		// エラーあり.
				}
				if ( EndPage < StartPage ) {	// EndPageがStartPageより小さい.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR3 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					isError = True;		// エラーあり.
				}
				Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
				APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
				Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
				APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
				(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
				// DocumentNoのチェック.
				for ( int32_t dc = 0; dc < NumOfDocs; dc++ )
				{
					APIC_Doc* pc_Doc = NULL;
					pc_Doc = APIC_Doc::newInstance();
// >> 2008.04.17 Tana [Donau] No.86 監査ログの追加.
					pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );
// << 2008.04.17 Tana [Donau] No.86 監査ログの追加.
					pc_Doc->setDocId( _sl_DocID[dc] );
					pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );
					APIC_DocInfo c_DocInfo;
					int32_t ret = pc_Doc->getDocInfo( pc_UserGet, netc_TwainClientMan.getLoginedBoxPassword( SocketFd ), &c_DocInfo, (LIBE_CharSet)APID_DefaultCharSet, pc_TrackGet );
					pc_Doc->deleteInstance();
					if ( ret != APID_DocapiMethodOk )
					{
NetTwainDebugTrace((char*)"# [Err]NETC_TwainCommandSetHDDTwainPara4_getDocInfo() Error #\n", 0,0,0,0,0,0);
						isError = True;		// エラーあり.
						break;
					}
				}
				// HDDXResolutionのチェック.
				if ( !((HDDXResolution == 0) || ( HDDXResolution == 200 ) || (HDDXResolution == 300) || (HDDXResolution == 400) || (HDDXResolution == 600)) ) {	// 設定データが範囲外の場合.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR4 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					isError = True;		// エラーあり.
				}
				// HDDYResolutionのチェック.
				if ( !((HDDYResolution == 0) || (HDDYResolution == 100) || (HDDYResolution == 200) || (HDDYResolution == 300) || (HDDYResolution == 400) || (HDDYResolution == 600)) ) {	// 設定データが範囲外の場合.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR5 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.

					isError = True;		// エラーあり.
				}
				if ( !( ( HDDXResolution == HDDYResolution )							// HDDXResolutionとHDDYResolutionが異なる場合.
					 || (( HDDXResolution == 200 ) && ( HDDYResolution == 100 )) ) ) {	// HDDXResolution == 200 && HDDXResolution == 100 の場合はエラー対象から外す.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR6 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					isError = True;		// エラーあり.
				}
				// HDDColorModeのチェック.
				Bool bl_ColorSystem = NETC_Twain_isColorSystem();
				if ( bl_ColorSystem == True ) {											// カラー機.
					if ( !((HDDColorMode == 0) || (HDDColorMode == 1) || (HDDColorMode == 4) || (HDDColorMode == 5)) ) {		// 設定データが範囲外の場合.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR7 #\n", 0,0,0,0,0,0);
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
						strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
						isError = True;		// エラーあり.
					}
				} else {																// モノクロ機.
					if ( !((HDDColorMode == 0) || (HDDColorMode == 1)) ) {														// 設定データが範囲外の場合.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR8 #\n", 0,0,0,0,0,0);
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
						strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
						isError = True;		// エラーあり.
					}
				}
				// 2010/12/21 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証 START.
				if ( ( isAuthDeviceType2Available() == True ) && ( HDDColorMode != 1 ) ) {		// 統合管理装置2が装着かつネットワーク認証有効で、Boxに保存時の設定を使用以外の場合.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4 Vendor & (HDDColorMode != 1) #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );										// 設定失敗.
					isError = True;																// エラーあり.
				} else{}
				// 2010/12/21 amiya 【Minerva】UV-00675 管理装置ベンダー装置利用時におけるネットワーク経由での認証 END.
				
				// ①SPDFのON/OFF設定チェック.
				if ( 1 == sc_SpdfOnOff ) {			// ①SPDF設定ONの場合.
					
					// ②ファイルフォーマットチェック.
					// 2008.12.16 msato CQ312774 str.
NetTwainDebugTrace((char*)"#NETC_TwainCommandSetHDDTwainPara4 StartPage = %d, FileFormat = %d#\n", StartPage,FileFormat,0,0,0,0);
					if ( ( ( StartPage == 0 ) && ( FileFormat == 0 ) )		// ②全ページ取得 + PDF.
					  || ( ( StartPage == 0 ) && ( FileFormat == 2 ) )		// ②全ページ取得 + CompactPDF.
					  || ( ( StartPage != 0 ) && ( FileFormat == 131 ) )		// ②所定ページ取得 + PDF.
					  || ( ( StartPage != 0 ) && ( FileFormat == 132 ) ) ) {	// ②所定ページ取得 + CompactPDF.
					// 2008.12.16 msato CQ312774 end.
						
						// ③NETE_LanguageOcr->TYPE_LanguageOcr変換し、パラメーターが範囲内かチェック.
						Bool bl_RangeChk = True;
						TYPE_LanguageOcr e_LanguageOcr = TYPE_LanguageOcrNone;
						switch ( nete_LanguageOcr ) {
							case NETE_LanguageOcrJapanese:		// 日本語.
								e_LanguageOcr = TYPE_LanguageOcrJapanese;
								break;
							case NETE_LanguageOcrEnglish:		// 英語.
								e_LanguageOcr = TYPE_LanguageOcrEnglish;
								break;
							case NETE_LanguageOcrFrench:		// フランス語.
								e_LanguageOcr = TYPE_LanguageOcrFrench;
								break;
							case NETE_LanguageOcrItalian:		// イタリア語.
								e_LanguageOcr = TYPE_LanguageOcrItalian;
								break;
							case NETE_LanguageOcrGerman:		// ドイツ語.
								e_LanguageOcr = TYPE_LanguageOcrGerman;
								break;
							case NETE_LanguageOcrSpanish:		// スペイン語.
								e_LanguageOcr = TYPE_LanguageOcrSpanish;
								break;
							case NETE_LanguageOcrChinese1:		// 中国語（簡体字）.
								e_LanguageOcr = TYPE_LanguageOcrChinese1;
								break;
							case NETE_LanguageOcrChinese2:		// 台湾語（繁体字）.
								e_LanguageOcr = TYPE_LanguageOcrChinese2;
								break;
							case NETE_LanguageOcrKorean:		// 韓国語.
								e_LanguageOcr = TYPE_LanguageOcrKorean;
								break;
							case NETE_LanguageOcrDutch:			// オランダ語.
								e_LanguageOcr = TYPE_LanguageOcrDutch;
								break;
							case NETE_LanguageOcrDanish:		// デンマーク語.
								e_LanguageOcr = TYPE_LanguageOcrDanish;
								break;
							case NETE_LanguageOcrNorwegian:		// ノルウェー語.
								e_LanguageOcr = TYPE_LanguageOcrNorwegian;
								break;
							case NETE_LanguageOcrSwedish:		// スウェーデン語.
								e_LanguageOcr = TYPE_LanguageOcrSwedish;
								break;
							case NETE_LanguageOcrFinnish:		// フィンランド語.
								e_LanguageOcr = TYPE_LanguageOcrFinnish;
								break;
							case NETE_LanguageOcrPortuguese:	// ポルトガル語.
								e_LanguageOcr = TYPE_LanguageOcrPortuguese;
								break;
							case NETE_LanguageOcrTurkish:		// トルコ語.
								e_LanguageOcr = TYPE_LanguageOcrTurkish;
								break;
							case NETE_LanguageOcrGreek:			// ギリシャ語.
								e_LanguageOcr = TYPE_LanguageOcrGreek;
								break;
							case NETE_LanguageOcrCzech:			// チェコ語.
								e_LanguageOcr = TYPE_LanguageOcrCzech;
								break;
							case NETE_LanguageOcrPolish:		// ポーランド語.
								e_LanguageOcr = TYPE_LanguageOcrPolish;
								break;
							case NETE_LanguageOcrHungarian:		// ハンガリー語.
								e_LanguageOcr = TYPE_LanguageOcrHungarian;
								break;
							case NETE_LanguageOcrSlovak:		// スロバキア語.
								e_LanguageOcr = TYPE_LanguageOcrSlovak;
								break;
							case NETE_LanguageOcrRussian:		// ロシア語.
								e_LanguageOcr = TYPE_LanguageOcrRussian;
								break;
							case NETE_LanguageOcrCatalan:		// カタロニア語.
								e_LanguageOcr = TYPE_LanguageOcrCatalan;
								break;
							case NETE_LanguageOcrLithuanian:	// リトアニア語.
								e_LanguageOcr = TYPE_LanguageOcrLithuanian;
								break;
							case NETE_LanguageOcrEstonian:		// エストニア語.
								e_LanguageOcr = TYPE_LanguageOcrEstonian;
								break;
							case NETE_LanguageOcrLatvian:		// ラトビア語.
								e_LanguageOcr = TYPE_LanguageOcrLatvian;
								break;
							case NETE_LanguageOcrSlovenia:		// スロベニア語.
								e_LanguageOcr = TYPE_LanguageOcrSlovenia;
								break;
							case NETE_LanguageOcrRomanian:		// ルーマニア語.
								e_LanguageOcr = TYPE_LanguageOcrRomanian;
								break;
							case NETE_LanguageOcrUkrainian:		// ウクライナ語.
								e_LanguageOcr = TYPE_LanguageOcrUkrainian;
								break;
							case NETE_LanguageOcrBulgarian:		// ブルガリア語.
								e_LanguageOcr = TYPE_LanguageOcrBulgarian;
								break;
							case NETE_LanguageOcrCroatian:		// クロアチア語.
								e_LanguageOcr = TYPE_LanguageOcrCroatian;
								break;
							case NETE_LanguageOcrNone:			// 未設定.
							default:
								bl_RangeChk = False;
								break;
						}
						if ( True == bl_RangeChk ) {	// ③パラメーターが範囲内.
							// ④NULLチェック.
							APIC_SearchablePDFSetting* pc_SearchablePDFSetting = NULL;
							pc_SearchablePDFSetting = APIC_SearchablePDFSetting::newInstance();
							if ( NULL != pc_SearchablePDFSetting ) {	// ④インスタンス取得成功.
								// 言語一覧（サーチャブルPDF選択可能言語）取得処理.	
								TYPE_LanguageOcr e_TempLanguageOcr[ TYPD_LanguageListNum ];
								memset( e_TempLanguageOcr, 0x00, sizeof( e_TempLanguageOcr ) );
								pc_SearchablePDFSetting->lock();
								pc_SearchablePDFSetting->getSearchablePDFChoiceAbleLangList( e_TempLanguageOcr );	// 言語一覧取得.
								pc_SearchablePDFSetting->unlock();
								// ⑤設定する言語がRAMに展開済みかチェック.
								Bool bl_LangChk = False;
								for ( int i = 0; i < TYPD_LanguageListNum; i++ ) {
									if ( e_LanguageOcr == e_TempLanguageOcr[ i ] ) {
										bl_LangChk = True;
										break;
									}
								}
								if ( True == bl_LangChk  ) {	// ⑤言語一覧に設定する言語が含まれる.
									// SPDFパラメーター設定可能.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_SPDF Parameter Normal Error #\n",0,0,0,0,0,0);
								} else {						// ⑤言語一覧に設定する言語が含まれない.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR9 #\n", 0,0,0,0,0,0);
									netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);
									netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
									strcpy( pc_ReqData, "\x1b*s21118r0V" );	// 設定失敗.
									isError = True;
								}
							} else {									// ④インスタンス取得失敗.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR10 #\n", 0,0,0,0,0,0);
								netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);
								netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
								strcpy( pc_ReqData, "\x1b*s21118r0V" );	// 設定失敗.
								isError = True;
							}
						} else {						// ③パラメーターが範囲外.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR11 #\n", 0,0,0,0,0,0);
							netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);
							netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
							strcpy( pc_ReqData, "\x1b*s21118r0V" );	// 設定失敗.
							isError = True;
						}
					} else {																							// ②ファイルフォーマットがサポート外.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR12 #\n", 0,0,0,0,0,0);
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
						strcpy( pc_ReqData, "\x1b*s21118r0V" );	// 設定失敗.
						isError = True;
					}
				} else if ( 0 == sc_SpdfOnOff ) {	// ①SPDF設定OFFの場合.
					// SPDF設定OFFの場合は処理なし.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_No deal if SPDF setting is OFF #\n", 0,0,0,0,0,0);
				} else {							// ①SPDF設定異常値の場合.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR13 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
					strcpy( pc_ReqData, "\x1b*s21118r0V" );	// 設定失敗.
					isError = True;
				}
				
				// ①OPDFのON/OFF設定チェック.
				// 2008.12.16 msato CQ312774 str.
				if ( 1 == sc_OpdfOnOff) {			// ①OPDF設定ONの場合.
NetTwainDebugTrace((char*)"#NETC_TwainCommandSetHDDTwainPara4 StartPage = %d, FileFormat = %d#\n", StartPage,FileFormat,0,0,0,0);
NetTwainDebugTrace((char*)"NETC_TwainCommandSetHDDTwainPara4_1_OPDF Settings On Case \n",0,0,0,0,0,0);
					// ②ファイルフォーマットチェック.
					if ( ( ( StartPage == 0 ) && ( FileFormat == 2 ) )		// ②全ページ取得 + CompactPDF.
					  || ( ( StartPage != 0 ) && ( FileFormat == 132 ) ) ) {	// ②所定ページ取得 + CompactPDF.
NetTwainDebugTrace((char*)"NETC_TwainCommandSetHDDTwainPara4_2_File Format is Compact PDF. \n",0,0,0,0,0,0);
					 } else {																							// ②ファイルフォーマットがCompactPDF以外.
NetTwainDebugTrace((char*)"NETC_TwainCommandSetHDDTwainPara4_2_File format is except for Compact PDF \n",0,0,0,0,0,0);
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR20 #\n", 0,0,0,0,0,0);
						netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);
						netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
						strcpy( pc_ReqData, "\x1b*s21118r0V" );	// 設定失敗.
						isError = True;
					 }
				} else if ( 0 == sc_OpdfOnOff ) {	// ①OPDF設定OFFの場合.
				// 2008.12.16 msato CQ312774 end.
					// OPDFパラメーター設定可能.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_OPDF Parameter Normal #\n", 0,0,0,0,0,0);
				} else {						// ①パラメーターが範囲外.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR14 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );
					strcpy( pc_ReqData, "\x1b*s21118r0V" );	// 設定失敗.
					isError = True;
				}

				if ( isError == False )		// エラーなし状態.
				{
					netc_TwainClientMan.setTempDocumentID( SocketFd, &_sl_DocID[0] );		// ドキュメントID仮登録.
					netc_TwainClientMan.setTempHDDFileFormat( SocketFd, FileFormat );		// 仮ファイルフォーマット.

					// ページ指定がある場合.
					if ( StartPage != 0 )
					{
						// Compressionのエラーチェック.
						if ( FileFormat == 0 )		// RAW指定の場合.
						{
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR15 #\n", 0,0,0,0,0,0);
							netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
							netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
							strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
							isError = True;		// エラーあり.
						}
						// >> 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.
						else if ( ((FileFormat == COMPRESSION_JPEG) && !bl_ColorSystem) 			// JPEG(only for Color System).
							   || ((FileFormat == COMPRESSION_CPDF) && !bl_ColorSystem) 			// CPDF(only for Color System).
							   || ((FileFormat == COMPRESSION_CXPS) && !bl_ColorSystem) 			// CXPS(only for Color System).
							   || ((FileFormat == COMPRESSION_JPEG) && (HDDColorMode == 0))			// JPEG指定で B/W Threshold.
							   || ((FileFormat == COMPRESSION_CPDF) && (HDDColorMode == 0))			// CPDF指定で B/W Threshold.
							   || ((FileFormat == COMPRESSION_CXPS) && (HDDColorMode == 0))			// CXPS指定で B/W Threshold.
						) {
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR16 #\n", 0,0,0,0,0,0);
							netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
							netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
							strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗. 
							isError = True;		// エラーあり.
						}
						// << 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.
						else
						{
							// 指定ページ番号を保持する.
							netc_TwainClientMan.setPageNumber( SocketFd, StartPage );	// 開始ページを指定する.
							netc_TwainClientMan.setEndPageNumber( SocketFd, EndPage );	// 終了ページを指定する.
							// フォーマット等を保持する.
							netc_TwainClientMan.setHDDCompression( SocketFd, FileFormat );	// Compressionを指定する.
							netc_TwainClientMan.setDocumentID( SocketFd, &_sl_DocID[0] );				// ドキュメント番号を指定する.
							// >> 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.
							netc_TwainClientMan.setHDDXResolution( SocketFd, (short)HDDXResolution );			// 解像度 Xを指定する.
							netc_TwainClientMan.setHDDYResolution( SocketFd, (short)HDDYResolution );			// 解像度 Yを指定する.
							netc_TwainClientMan.setHDDColorMode( SocketFd, HDDColorMode );				// カラーモードを指定する.
							// << 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.
							// ページ数のチェック 及び 内部で管理するページ数(取得時の最終を判断するための情報)を確定する.

							netc_TwainClientMan.setSpdfOnOff( SocketFd, sc_SpdfOnOff );			// SPDF ON/OFF セット.
							netc_TwainClientMan.setSpdfLang( SocketFd, nete_LanguageOcr );		// SPDF 設定言語 セット.
							netc_TwainClientMan.setSpdfRotate( SocketFd, sc_SpdfRotate );		// SPDF 回転補正 セット.
							netc_TwainClientMan.setOpdfOnOff( SocketFd, sc_OpdfOnOff );			// OPDF ON/OFF セット.
							
							APIC_Doc* pc_Doc = NULL;
							pc_Doc = APIC_Doc::newInstance();
// >> 2008.04.17 Tana [Donau] No.86 監査ログの追加.
							pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );
// << 2008.04.17 Tana [Donau] No.86 監査ログの追加.
							pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );
							pc_Doc->setDocId( _sl_DocID[0] );
							int clientindex = netc_TwainClientMan.getClientIndex( SocketFd );
							if ( clientindex != -1 )
							{
								(void)pc_Doc->req_GetJobID( netc_TwainClientMan.getJobInfoDoc( SocketFd ), ans_GetJobIDScanParaTbl[clientindex] );
							}
							pc_Doc->deleteInstance();
						}
					}
					// 全ページ取得の場合.
					else
					{
						// >> 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.
						if ( ((FileFormat == FILEFORMAT_CPDF) && !bl_ColorSystem) 			// CPDF(only for Color System).
						  || ((FileFormat == FILEFORMAT_CXPS) && !bl_ColorSystem) 			// CXPS(only for Color System).
						  || ((FileFormat == FILEFORMAT_CPDF) && (HDDColorMode == 0))		// CPDF指定で B/W Threshold.
						  || ((FileFormat == FILEFORMAT_CXPS) && (HDDColorMode == 0))		// CXPS指定で B/W Threshold.
						) {
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR17 #\n", 0,0,0,0,0,0);
							netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
							netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
							strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
							isError = True;		// エラーあり.
						}
						else
						{
						// << 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.

							netc_TwainClientMan.InitializationClientMan( SocketFd );						// 転送関連のクライアント情報の初期化.		// 2010/3/12 DonauLast <UV-00657 UV-00158 PDF関連> amiya.
							// 登録可否のチェックを行う.
							ERR_INFORMATION error_info = isHDDTwainAvailable( SocketFd );
							if ( error_info == ERR_NOT_EXIST_ERROR ) {		// 登録を妨げるエラー無し状態.
								// 設定パラメータを内部データに展開.
								netc_TwainClientMan.setDocumentID( SocketFd, &_sl_DocID[0] );				// ドキュメント番号を指定する.
								netc_TwainClientMan.setPageNumber( SocketFd, StartPage );				// 開始ページを指定する.
								netc_TwainClientMan.setHDDFileFormat( SocketFd, FileFormat );	// ファイルフォーマットを指定する.
								// >> 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.
								netc_TwainClientMan.setHDDXResolution( SocketFd, (short)HDDXResolution );			// 解像度 Xを指定する.
								netc_TwainClientMan.setHDDYResolution( SocketFd, (short)HDDYResolution );			// 解像度 Yを指定する.
								netc_TwainClientMan.setHDDColorMode( SocketFd, HDDColorMode );				// カラーモードを指定する.
								// << 2008.02.05 Harada Donau対応 No.64 BOXからのデータ送信時に解像度/カラー変更対応.
								netc_TwainClientMan.setSpdfOnOff( SocketFd, sc_SpdfOnOff );			// SPDF ON/OFF セット.
								netc_TwainClientMan.setSpdfLang( SocketFd, nete_LanguageOcr );		// SPDF 設定言語 セット.
								netc_TwainClientMan.setSpdfRotate( SocketFd, sc_SpdfRotate );		// SPDF 回転補正 セット.
								netc_TwainClientMan.setOpdfOnOff( SocketFd, sc_OpdfOnOff );			// OPDF ON/OFF セット.
								// 取得の起動をかける.
								if ( _HDDDocumentAcquire( SocketFd ) == False ) {	// 2007.09.12 Harada チェック追加.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_SCAN_JOB_REGIST_ERROR #\n", 0,0,0,0,0,0);
									netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SCAN_JOB_REGIST_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
									netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
									strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
									isError = True;		// エラーあり.
								}
							} else {										// 登録を妨げるエラー有り状態.
								netc_TwainClientMan.setClientErrorInfo( SocketFd, error_info , __FILE__ ,__LINE__);			// Error Client Error Info.
								netc_TwainClientMan.setClientErrorStatus( SocketFd, True );				// Error Client Error Status.
								strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
								isError = True;		// エラーあり.
							}
						}
					}
				}
				else		// エラー有り状態の場合.
				{
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR18 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					isError = True;		// エラーあり.
				}
			} else {
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_PARAMETER_ERROR19 #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
					strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
					isError = True;		// エラーあり.
			}
		} else {														// Boxログアウト状態.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetHDDTwainPara4_ERR_USER_BOX_NOT_SPECIFIED #\n", 0,0,0,0,0,0);
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
			strcpy( pc_ReqData, "\x1b*s21116r0V" );	// 設定失敗.
			isError = True;		// エラーあり.
		}
	}
	// エラーがあった場合、エラー応答を返す.
	if ( isError == True ) {
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
}

