// SCL_SET_USERNAME_PUBLIC				// 96: Set User Name during Public Login.
//==================================================================================================
//[クラス]NETC_TwainCommandSetUserNamePublic.
//[内容] SCL_SET_USERNAME_PUBLICコマンドを処理するクラス.
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandSetUserNamePublicのコンストラクタ.
//==================================================================================================
NETC_TwainCommandSetUserNamePublic::NETC_TwainCommandSetUserNamePublic( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}
//==================================================================================================
//[機能]コマンドを処理する.
//[戻り値]なし.
//[履歴]2010/03/23 okabe.
//		Gaia先取り対応 <UV00970>対応により強制メモリ操作時の任意の文字列を追加するコマンド.
//==================================================================================================
void NETC_TwainCommandSetUserNamePublic::CommandProc(
	int SocketFd,		// ソケットディスクリプタ.
	char* Parameter,	// パラメータへのポインタ.
	short ParamLength	// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandSetUserNamePublic::CommandProc()_Start!! \n", 0,0,0,0,0,0);

	char sc_Size[32+1];
	memset( sc_Size, 0, sizeof(sc_Size) );	// バイナリデータのサイズを抜き出す.
	short ss_effectLength = 0;			// サイズ長データと区切り記号を抜いた分の実際のパラメータ長.
	char pc_ReqData[32];				// 応答データの領域を確保する.

	short ss_index;
	for ( ss_index = 0; ss_index < 32; ss_index++ ){
		if ( Parameter[ss_index] == 'Q' ){ break;}
		sc_Size[ss_index] = Parameter[ss_index];
	}
	sc_Size[ss_index] = '\0';	// プロテクト.
	ss_index++;
	ss_effectLength = (short)atoi((char*)sc_Size);

	char sc_LoginID[NETD_DURING_PUBLIC_LENGTH];
	memset( sc_LoginID, 0, sizeof(sc_LoginID) );

	// ユーザーID情報を抜き出す 
	for( short ss_prmIndex = 0 ; ss_prmIndex < ParamLength && ss_prmIndex < NETD_DURING_PUBLIC_LENGTH ; ss_prmIndex++ , ss_index++){
		sc_LoginID[ss_prmIndex] = Parameter[ss_index];
	}

	if( ss_effectLength  < 1 || 60 < ss_effectLength ){							// 1～60Byte以内か?
		strcpy( pc_ReqData, "\x1b*s21120r0V" );									// 失敗応答.
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);	// Access to the specified object is denied.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );				// エラー発生状態とする.
	} else {
		APIC_User* pc_User = netc_TwainClientMan.getApic_User( SocketFd );					// ログインユーザーインスタンス取得.
		int32_t sl_UserNo = 0;	//2013/10/11 【スケーラブルFUM】[CQ383174] 20万人対応. 
		if( pc_User != NULL ) {
			pc_User->lock();
			sl_UserNo = pc_User->getUserNo();
			pc_User->unlock();
		}
		if( ( sl_UserNo == TYPD_IndexUserPublic ) && isForceMemoryReceiveBoxJournal( SocketFd ) ){	// ログインしているユーザーがPublicの場合かつ機能が有効.
			netc_TwainClientMan.setForceMemoryName( SocketFd , sc_LoginID );				// 文字列確保.
			strcpy( pc_ReqData, "\x1b*s21120r1V" );											// 成功応答.
		} else {
			strcpy( pc_ReqData, "\x1b*s21120r0V" );											// 失敗応答.
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PUBLICUSER_NOT_LOGINED , __FILE__ ,__LINE__);	// Public User Not Logined.
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// エラー発生状態とする.
		}
	}

	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
	if( netc_TwainClientMan.getRREQReceived( SocketFd ) == True )
	{
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

// SCL_GET_SUPPORT_PUBLIC				// 97: Inquire Support of Setting User Name.
//==================================================================================================
//[クラス]NETC_TwainCommandGetSupportPublic.
//[内容] SCL_GET_SUPPORT_PUBLICコマンドを処理するクラス.
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetSupportPublicのコンストラクタ.
//==================================================================================================
NETC_TwainCommandGetSupportPublic::NETC_TwainCommandGetSupportPublic( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}
//==================================================================================================
//[機能]コマンドを処理する.
//[戻り値]なし.
//[履歴]2010/03/23 okabe.
//		Gaia先取り対応 <UV00970>対応により強制メモリ操作時の任意の文字列を残すのかを取得するコマンド.
//==================================================================================================
void NETC_TwainCommandGetSupportPublic::CommandProc(
	int SocketFd,		// ソケットディスクリプタ.
	char* Parameter,	// パラメータへのポインタ.
	short ParamLength	// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetSupportPublic::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];

	// ユーザID取得.
	APIC_User* pc_User = netc_TwainClientMan.getApic_User( SocketFd );					// ログインユーザーインスタンス.
	int32_t sl_UserNo = 0;	//2013/10/11 【スケーラブルFUM】[CQ383174] 20万人対応. 
	if ( pc_User != NULL ) {
		pc_User->lock();
		sl_UserNo = pc_User->getUserNo();
		pc_User->unlock();
	}

	Bool bl_SW7704 = False;
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	if ( pc_SoftDipSw != NULL ){
		pc_SoftDipSw->lock();
		bl_SW7704 = pc_SoftDipSw->getSoftDipSwBit( 38, 8 );					// SoftSW No77.0x04の値を取得.
		pc_SoftDipSw->unlock();
	}

	if( ( sl_UserNo == TYPD_IndexUserPublic ) && bl_SW7704 ){				// ログインしているユーザーがPublicの場合かつ機能が有効 CQNo327801 2010/05/24 okabe 変更.
		strcpy( pc_ReqData, "\x1b*s21028d1V" );
	} else {
		strcpy( pc_ReqData, "\x1b*s21028d0V" );
	}
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
	if( netc_TwainClientMan.getRREQReceived( SocketFd ) == True )
	{
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}
