// SCL_GET_CURRENT_USER_INFO2	98		// Get Current User Info 2.
//==================================================================================================
//[クラス]NETC_TwainCommandGetCurrentUserInfo2.
//[内容] SCL_GET_CURRENT_USER_INFO2コマンドを処理するクラス.
//[履歴] 2010/03/18 amiya <UV-00651> 認証と部門のユーザー別連動設定対応.
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetCurrentUserInfo2のコンストラクタ.
//==================================================================================================
NETC_TwainCommandGetCurrentUserInfo2::NETC_TwainCommandGetCurrentUserInfo2( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する.
//[履歴] 2010/03/18 amiya 新規 <UV-00651> 認証と部門のユーザー別連動設定対応.
//==================================================================================================
void NETC_TwainCommandGetCurrentUserInfo2::CommandProc(
	int si_SocketFd,				// ソケットディスクリプタ.
	char* ,							// パラメータへのポインタ.
	short 							// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetCurrentUserInfo2::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	NETS_CurrentUserInfo2 nets_CurrentUserInfo2;
	memset( &nets_CurrentUserInfo2, 0, sizeof(NETS_CurrentUserInfo2) );
	APIC_User* pc_User = NULL;
	char* sc_RspData = NULL;
	char sc_tmp[32];
	int si_tmpLen = 0;
	memset( &sc_tmp[0], 0, sizeof(sc_tmp) );
	if ( netc_TwainClientMan.getUserLogined( si_SocketFd ) == False ) {								// ログイン状態でない場合.
		strcpy( sc_tmp, "\x1b*s282tN" );															// Null応答.
		netc_TwainClientMan.setClientErrorInfo( si_SocketFd, ERR_USER_NOT_LOGINED , __FILE__ ,__LINE__);				// User not logined in device.
		netc_TwainClientMan.setClientErrorStatus( si_SocketFd, True );								// エラー発生状態とする.
		sc_RspData = (char*)malloc( strlen(sc_tmp) );
		if( sc_RspData == NULL ){
			errorLog_TwainService("sc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( sc_RspData, sc_tmp, strlen(sc_tmp) );
		netc_TwainClientMan.setSendData( si_SocketFd, sc_RspData, (uint32_t)strlen(sc_tmp) );			// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( si_SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( si_SocketFd, netc_TwainClientMan.getRREQRequestSize( si_SocketFd ), 4 );
		}
		return;
	} else {
		if ( getUserAuthenticationMode() != TYPE_UserAuthenticationOff ) {							// ユーザー認証モードがOFF以外(ON)の場合.
NetTwainDebugTrace((char*)"### <GetCurrentUserInfo2> User Auth ON ###\n",0,0,0,0,0,0);
			pc_User = netc_TwainClientMan.getApic_User( si_SocketFd );								// ユーザーインスタンスを取得.
			if ( pc_User != NULL ) {
NetTwainDebugTrace((char*)"### <GetCurrentUserInfo2> pc_User exist ###\n",0,0,0,0,0,0);
				pc_User->lock();
				pc_User->getUserNameUTF8( nets_CurrentUserInfo2.sc_UserName );						// ユーザ名.
				pc_User->getLoginServerName( nets_CurrentUserInfo2.sc_ServerName );					// 外部サーバ名.

				TYPE_UserTrackMode e_UserTrackMode = pc_User->getUserTrackMode();
				pc_User->unlock();
				// 部門認証のユーザ認証連動設定.
				if( e_UserTrackMode == TYPE_UserTrackMode_UnLink ) {								// ユーザー認証と連動しない場合.
NetTwainDebugTrace((char*)"### <GetCurrentUserInfo2>No synchronize with User Authentication ###\n",0,0,0,0,0,0);
					nets_CurrentUserInfo2.sc_UserTrackModeOnOff = 0x00;
				} else if( e_UserTrackMode == TYPE_UserTrackMode_Link ) {							// ユーザー認証と連動する場合.
NetTwainDebugTrace((char*)"### <GetCurrentUserInfo2> Synchronize with User Authentication ###\n",0,0,0,0,0,0);
					nets_CurrentUserInfo2.sc_UserTrackModeOnOff = 0x01;
				}
			}
		}
NetTwainDebugTraceUserInfo((char*)"### <GetCurrentUserInfo2> UserName   = %s ###\n",reinterpret_cast<intptr_t>(&nets_CurrentUserInfo2.sc_UserName[0]),0,0,0,0,0);		// 2022/2/7 [IT6_2.2MR2] OP_BTS-37530 HIENG.	
NetTwainDebugTrace((char*)"### <GetCurrentUserInfo2> ServerName = %s ###\n",reinterpret_cast<intptr_t>(&nets_CurrentUserInfo2.sc_ServerName[0]),0,0,0,0,0);
		si_tmpLen = sprintf( sc_tmp, "\x1b*s282t%dW", sizeof(NETS_CurrentUserInfo2) );
		sc_RspData = (char*)malloc( si_tmpLen + sizeof(NETS_CurrentUserInfo2) );
		if( sc_RspData == NULL ){
			errorLog_TwainService("sc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memset( sc_RspData, 0, si_tmpLen + sizeof(NETS_CurrentUserInfo2) );
		memcpy( sc_RspData, sc_tmp, si_tmpLen );
		memcpy( &sc_RspData[si_tmpLen], (char*)&nets_CurrentUserInfo2, sizeof(NETS_CurrentUserInfo2) );
	}
	netc_TwainClientMan.setSendData( si_SocketFd, sc_RspData, (uint32_t)( si_tmpLen + sizeof(NETS_CurrentUserInfo2) ) );		// 送信データ保持領域に書き込む.
	if ( netc_TwainClientMan.getRREQReceived( si_SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( si_SocketFd, netc_TwainClientMan.getRREQRequestSize( si_SocketFd ), 4 );
	}
}

