//==================================================================================================
//[機能]ドキュメント情報の送信処理.
//[履歴] //2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata .
//==================================================================================================
void _documentInfo6(
	void* p_MsgData
)
{
NetTwainDebugTrace((char*)"#### _documentInfo6() START!! ####\n",0,0,0,0,0,0);
	APIC_DocListInfo* pc_DocListInfo = (APIC_DocListInfo*)p_MsgData;
	netc_TwainClientMan.setDocListInfoList( pc_DocListInfo->index, pc_DocListInfo );		// APIC_DocListInfoへのポインタを設定.
	char* pc_RspData = NULL;
	Bool bl_isRsp = True;
	if ( pc_DocListInfo->pList == NULL ) {										// リスト情報なし(エラー). 
		char sc_ReqData[32];
		strcpy( sc_ReqData, "\x1b*s283t0:0/0W" );
		pc_RspData = (char*)malloc( strlen(sc_ReqData) );
		if(pc_RspData == NULL){
			errorLog_TwainService("pc_RspData NULL!!!\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, sc_ReqData, strlen(sc_ReqData) );
		netc_TwainClientMan.setSendData( pc_DocListInfo->index, pc_RspData, (uint32_t)strlen(sc_ReqData) );	// 送信データ保持領域に書き込む. 
		DocListCreateSocketFd = 0;																			// DocumentList作成中のクライアントのsi_SocketFd. 
	} else {																								// ●リスト情報あり(通常). 
		APIC_DocListTbl *pc_DocListTbl = pc_DocListInfo->pList->findFirst();								// 先頭データを取得.
		short ss_index = 0;
		while(pc_DocListTbl != NULL){
			ss_index++;
			pc_DocListTbl = pc_DocListInfo->pList->findNext();												// 次データを取得.
		}
		short ss_getNum = ss_index;
NetTwainDebugTrace((char*)"### _documentInfo6() ss_getNum = [%d] ###\n", ss_getNum,0,0,0,0,0);
		if ( ss_index == 0 ) {															// ドキュメント数が0の場合(エラー). 
NetTwainDebugTrace((char*)"#### _documentInfo6() ERROR!!(Documents aren't) ####\n",0,0,0,0,0,0);
			pc_DocListTbl = pc_DocListInfo->pList->findFirst();
			char sc_ReqData[32];
			sprintf( sc_ReqData, "\x1b*s283t0:0/%ldW", sl_AllList );
			pc_RspData = (char*)malloc( strlen(sc_ReqData) );
			if(pc_RspData == NULL){
				errorLog_TwainService("pc_RspData NULL!!!\n",0,0,0,0,0,0);
				return;
			}
			memcpy( pc_RspData, sc_ReqData, strlen(sc_ReqData) );
			netc_TwainClientMan.setSendData( pc_DocListInfo->index, pc_RspData, (uint32_t)strlen(sc_ReqData) );		// 送信データ保持領域に書き込む. 
			DocListCreateSocketFd = 0;																				// DocumentList作成中のクライアントのsi_SocketFd. 
		} else {																									// ●ドキュメント数が0以外の場合(通常). 
NetTwainDebugTrace((char*)"#### _documentInfo6() Documents are! ####\n",0,0,0,0,0,0);
			netc_TwainClientMan.setDocumentCnt( pc_DocListInfo->index, ss_getNum );															// ドキュメント個数をクライアント管理情報として保持する.
			NETS_TwainDocumentInfo6* pc_TwainDocumentInfo6 = (NETS_TwainDocumentInfo6*)malloc(sizeof(NETS_TwainDocumentInfo6)*ss_index);	// ドキュメント数分の領域を確保.
			pc_DocListTbl = pc_DocListInfo->pList->findFirst();
			if ( pc_TwainDocumentInfo6 != NULL ) {																	// ●領域確保成功(通常).
NetTwainDebugTrace((char*)"#### _documentInfo6() Memory sector OK! ####\n",0,0,0,0,0,0);
				memset( pc_TwainDocumentInfo6, 0, sizeof(NETS_TwainDocumentInfo6)*ss_index );
				netc_TwainClientMan.setTwainDocumentInfo6( pc_DocListInfo->index, pc_TwainDocumentInfo6 );
				APIC_Doc* pc_Doc = NULL;
				pc_Doc = APIC_Doc::newInstance();
				pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );													// ログ用IF No 登録.
				pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( pc_DocListInfo->index ) );					// BoxID設定.
				pc_Doc->setDocId( pc_DocListTbl->docID );															// Doc ID を登録(保持).

				int si_clientindex = netc_TwainClientMan.getClientIndex( pc_DocListInfo->index );					// クライアントインデックス情報を取得.
				if ( si_clientindex != -1 ) {																		// ●インデックスが-1以外(通常).
NetTwainDebugTrace((char*)"#### _documentInfo6() Index OK! ####\n",0,0,0,0,0,0);
					netc_TwainClientMan.setDocumentIDForList( pc_DocListInfo->index, pc_DocListTbl->docID );		// ドキュメントリスト作成時のドキュメントIDを設定.
					netc_TwainClientMan.setDocListTbl( pc_DocListInfo->index, pc_DocListTbl );						// APIC_DocListTblへのポインタを設定.
					netc_TwainClientMan.setDocumentCreateCnt( pc_DocListInfo->index, 0 );							// ボックス内ドキュメント数(作成完了ドキュメント数)を設定.

					// setBoxId()、setDocId()で指示されたBox内Docが保持するJobID、JobStatusを取得するコールバック関数req_GetJobIDをコールする.
NetTwainDebugTrace((char*)"### _documentInfo6() req_GetJobID ###\n", 0,0,0,0,0,0);
					int32_t sl_ret = pc_Doc->req_GetJobID( netc_TwainClientMan.getJobInfoDoc( pc_DocListInfo->index ), ans_GetJobIDTbl[si_clientindex] );
					if ( sl_ret != APID_DocapiMethodOk ) {											// コールに失敗(エラー)
NetTwainDebugTrace((char*)"### _documentInfo6() ERROR!!(You couldn't call req_GetJobID) ###\n", 0,0,0,0,0,0);
						char sc_ReqData[32];
						sprintf( sc_ReqData, "\x1b*s283t0:0/%ldW", sl_AllList );
						pc_RspData = (char*)malloc( strlen(sc_ReqData) );
						if(pc_RspData == NULL){
							errorLog_TwainService("pc_RspData NULL!!!\n",0,0,0,0,0,0);
							return;
						}
						memcpy( pc_RspData, sc_ReqData, strlen(sc_ReqData) );
						netc_TwainClientMan.setSendData( pc_DocListInfo->index, pc_RspData, (uint32_t)strlen(sc_ReqData) );		// 送信データ保持領域に書き込む 
						pc_DocListTbl = pc_DocListInfo->pList->findFirst();
						while (pc_DocListTbl != NULL) {
							pc_DocListInfo->pList->del(pc_DocListTbl);
							free( pc_DocListTbl );
							pc_DocListTbl = pc_DocListInfo->pList->findFirst();
						}
						free( netc_TwainClientMan.getTwainDocumentInfo6( pc_DocListInfo->index ) );
						DocListCreateSocketFd = 0;																		// DocumentList作成中のクライアントのsi_SocketFd 
					} else {																	// ●コールに成功(通常)
						bl_isRsp = False;
					}
				} else {																	// インデックスが-1(エラー).
NetTwainDebugTrace((char*)"#### _documentInfo6() ERROR!!(Index NG) ####\n",0,0,0,0,0,0);
					char sc_ReqData[32];
					sprintf( sc_ReqData, "\x1b*s283t0:0/%ldW", sl_AllList );
					pc_RspData = (char*)malloc( strlen(sc_ReqData) );
					if(pc_RspData == NULL){
						errorLog_TwainService("pc_RspData NULL!!!\n",0,0,0,0,0,0);
						return;
					}
					memcpy( pc_RspData, sc_ReqData, strlen(sc_ReqData) );
					netc_TwainClientMan.setSendData( pc_DocListInfo->index, pc_RspData, (uint32_t)strlen(sc_ReqData) );		// 送信データ保持領域に書き込む 
					pc_DocListTbl = pc_DocListInfo->pList->findFirst();
					while (pc_DocListTbl != NULL) {
						pc_DocListInfo->pList->del(pc_DocListTbl);
						free( pc_DocListTbl );
						pc_DocListTbl = pc_DocListInfo->pList->findFirst();
					}
					free( netc_TwainClientMan.getTwainDocumentInfo6( pc_DocListInfo->index ) );
					DocListCreateSocketFd = 0;																				// DocumentList作成中のクライアントのsi_SocketFd 
				}
				pc_Doc->deleteInstance();
			} else {																	// 領域確保失敗(エラー).
NetTwainDebugTrace((char*)"#### _documentInfo6() ERROR!!(Memory sector NG) ####\n",0,0,0,0,0,0);
				char sc_ReqData[32];
				sprintf( sc_ReqData, "\x1b*s283t0:0/%ldW", sl_AllList );
				pc_RspData = (char*)malloc( strlen(sc_ReqData) );
				if(pc_RspData == NULL){
					errorLog_TwainService("pc_RspData NULL!!!\n",0,0,0,0,0,0);
					return;
				}
				memcpy( pc_RspData, sc_ReqData, strlen(sc_ReqData) );
				netc_TwainClientMan.setSendData( pc_DocListInfo->index, pc_RspData, (uint32_t)strlen(sc_ReqData) );		// 送信データ保持領域に書き込む 
				pc_DocListTbl = pc_DocListInfo->pList->findFirst();
				while (pc_DocListTbl != NULL) {
					pc_DocListInfo->pList->del(pc_DocListTbl);
					free( pc_DocListTbl );
					pc_DocListTbl = pc_DocListInfo->pList->findFirst();
				}
				free( netc_TwainClientMan.getTwainDocumentInfo6( pc_DocListInfo->index ) );
				DocListCreateSocketFd = 0;																				// DocumentList作成中のクライアントのsi_SocketFd 
			}
		}
	}
	if ( bl_isRsp == True ) {
		if ( netc_TwainClientMan.getRREQReceived( pc_DocListInfo->index ) == True ) {							// RREQを受けている.
			if ( netc_TwainClientMan.getCommandID( pc_DocListInfo->index ) == SCL_GET_DOC_INFO_6 ) {			// WDATコマンドがSCL_GET_DOC_INFO_6である.
				netc_TwainClientMan.setRdatSend( pc_DocListInfo->index , netc_TwainClientMan.getRREQRequestSize( pc_DocListInfo->index ), 4 );
			} else {
				if ( pc_RspData != NULL ) {
					free ( pc_RspData );
				}
			}
		}
		netc_TwainClientMan.setHddAccessEndWait( pc_DocListInfo->index );
	}
}
//==================================================================================================
//[機能] JobID取得時の処理関数.
//[履歴] 2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata .
//==================================================================================================
void _GetJobID6( NETS_DocJobID* pc_DocJobID )
{
NetTwainDebugTrace((char*)"#### _GetJobID6() START!! ####\n",0,0,0,0,0,0);
	NETS_DocJobID s_DocJobID;
	memcpy( &s_DocJobID, pc_DocJobID, sizeof(NETS_DocJobID) );
	free( pc_DocJobID );
	int si_SocketFd = netc_TwainClientMan.getSocketFd( s_DocJobID.index );							// ソケットFDを取得.
	if ( si_SocketFd != -1 ) {															// ●ソケットFDが-1でない(通常).
NetTwainDebugTrace((char*)"#### _GetJobID6() SocketFD OK! ####\n", 0,0,0,0,0,0);
		Bool bl_isRsp = True;
		char sc_ReqData[32];
		if ( netc_TwainClientMan.getCommandID( si_SocketFd ) == SCL_GET_DOC_INFO_6 ){ 		// ●WDATコマンドがSCL_GET_DOC_INFO_6(通常).
NetTwainDebugTrace((char*)"#### _GetJobID6() COMMAND is SCL_GET_DOC_INFO_6! ####\n", 0,0,0,0,0,0);
			if ( (s_DocJobID.pc_JobInfoDoc == NULL) || (s_DocJobID.ret == -1) ) {			// pc_JobInfoDoc取得失敗(エラー). 
NetTwainDebugTrace((char*)"# _GetJobID6_ERR_PARAMETER_ERROR1 #\n", 0,0,0,0,0,0);
				netc_TwainClientMan.setClientErrorInfo( si_SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info. 
				netc_TwainClientMan.setClientErrorStatus( si_SocketFd, True );						// Error Client Error Status.
				strcpy( sc_ReqData, "\x1b*s283tN" );											// 設定失敗.
				free( netc_TwainClientMan.getTwainDocumentInfo6( si_SocketFd ) );
				DocListCreateSocketFd = 0;														// DocumentList作成中のクライアントのsi_SocketFd. 
			} else {																		// ●pc_JobInfoDoc取得成功(通常).
NetTwainDebugTrace((char*)"#### _GetJobID6() pc_JobInfoDoc OK!(Normal) ####\n", 0,0,0,0,0,0);
				bl_isRsp = False;
				uint32_t ul_getJobID = s_DocJobID.pc_JobInfoDoc->pJobStatus->getJobID();											// ジョブIDを取得. 
				TYPE_OriginalsColorType e_OriginalsColorType = s_DocJobID.pc_JobInfoDoc->pJobStatus->getOriginalsColorType();	// カラーモード情報(カラー混載を含む)を取得. 
				short ss_index = netc_TwainClientMan.getDocumentCreateCnt( si_SocketFd );
				//2012/01/12 Iwata UV-01188FAX転送時のファイル名変更対応 Start.
				// 回線取得及び相手先送信回線番号取得.
				char sc_RemoteID[TYPD_StatRemoteIDLen+1];
				memset( &sc_RemoteID, 0, sizeof(sc_RemoteID) );
				TYPE_CommLine e_CommLine = s_DocJobID.pc_JobInfoDoc->pJobStatus->getCurrentLine();
				s_DocJobID.pc_JobInfoDoc->pJobStatus->getRemoteID(sc_RemoteID,e_CommLine);
				netc_TwainClientMan.setTsiRemoteID( si_SocketFd, &sc_RemoteID[0] );					// 送信してきた相手先回線番号をClientManへ保存.

				char sc_tmpFaxID[TYPD_StatRemoteIDLen+1];
				memset( sc_tmpFaxID, 0, sizeof( sc_tmpFaxID ));
				strncpy( sc_tmpFaxID, APIC_FaxGfpSetting::newInstance()-> getNumericIdAll(e_CommLine), ( sizeof(sc_tmpFaxID) - 1 ));
				netc_TwainClientMan.setReceiveTsiRemoteID( si_SocketFd, &sc_tmpFaxID[0] );				// 受信回線番号をClientManへ保存.
				// FAX受信文書のファイル名変更要望(DA-172) end.
				//2012/01/12 Iwata UV-01188FAX転送時のファイル名変更対応 End.

				NETS_TwainDocumentInfo6* pc_TwainDocumentInfo6 = NULL;
				pc_TwainDocumentInfo6 = netc_TwainClientMan.getTwainDocumentInfo6( si_SocketFd );									// NETS_TwainDocumentInfo6へのポインタを取得.
				if ( pc_TwainDocumentInfo6 != NULL ) {											// pc_TwainDocumentInfo6ポインタ取得成功.
					// ユーザージョブ番号(本当のジョブ番号). 
					pc_TwainDocumentInfo6[ss_index].sc_UserJobJobID[3] = (char)((ul_getJobID & 0xff000000) >> 24);
					pc_TwainDocumentInfo6[ss_index].sc_UserJobJobID[2] = (char)((ul_getJobID & 0x00ff0000) >> 16);
					pc_TwainDocumentInfo6[ss_index].sc_UserJobJobID[1] = (char)((ul_getJobID & 0x0000ff00) >> 8);
					pc_TwainDocumentInfo6[ss_index].sc_UserJobJobID[0] = (char)(ul_getJobID & 0x000000ff);
					// 原稿カラー情報. 
					switch ( e_OriginalsColorType ) {
						case TYPE_OriginalsColorTypeColor:
							pc_TwainDocumentInfo6[ss_index].sc_ColorType[0] = 0x02;
NetTwainDebugTrace((char*)"#### _GetJobID6() COLOR TYPE JobStatus->getOriginalsColorType() = TYPE_OriginalsColorTypeColor ####\n", 0,0,0,0,0,0);
							break;
						case TYPE_OriginalsColorTypeMono:
							pc_TwainDocumentInfo6[ss_index].sc_ColorType[0] = 0x01;
NetTwainDebugTrace((char*)"#### _GetJobID6() COLOR TYPE JobStatus->getOriginalsColorType() = TYPE_OriginalsColorTypeMono ####\n", 0,0,0,0,0,0);
							break;
						case TYPE_OriginalsColorTypePageMix:
							pc_TwainDocumentInfo6[ss_index].sc_ColorType[0] = 0x03;
NetTwainDebugTrace((char*)"#### _GetJobID6() COLOR TYPE JobStatus->getOriginalsColorType() = TYPE_OriginalsColorTypePageMix ####\n", 0,0,0,0,0,0);
							break;
						default:
							pc_TwainDocumentInfo6[ss_index].sc_ColorType[0] = 0x01;
							break;
					}
					// 原稿枚数(NumOfDocument). 
					pc_TwainDocumentInfo6[ss_index].sc_NumOfDocument[1] = (char)((s_DocJobID.pc_JobInfoDoc->pJobStatus->getNumOfOriginals() & 0xff00) >> 8);
					pc_TwainDocumentInfo6[ss_index].sc_NumOfDocument[0] = (char)( s_DocJobID.pc_JobInfoDoc->pJobStatus->getNumOfOriginals() & 0x00ff);
				}
				
NetTwainDebugTrace((char*)"### _GetJobID6() req_getInstance ###\n", 0,0,0,0,0,0);
				// DocIDからCompositedDocインスタンスのアドレスを取得するコールバック関数req_getInstanceをコールする.
//				int32_t sl_result = DOCC_CompositeDoc::req_getInstance( netc_TwainClientMan.getDocumentIDForList( si_SocketFd ), netc_TwainClientMan.getLoginedBoxNo( si_SocketFd ), ans_GetDocInstanceTbl[s_DocJobID.index] );
				// 2012/11/15 amiya CQ375074 【市場問題(FQ-ISDP-1200313)】PSBOでBOXにアクセスするとジョブの自動削除機能が動作しない.
				// req_getInstance()の第7引数をFalseにすると、最終アクセス時刻を変更しなくなる.
				// 第4-6引数は、デフォルト引数と同じ値をセットする.
				int32_t sl_result = DOCC_CompositeDoc::req_getInstance( netc_TwainClientMan.getDocumentIDForList( si_SocketFd ), netc_TwainClientMan.getLoginedBoxNo( si_SocketFd ), ans_GetDocInstanceTbl[s_DocJobID.index], NULL, False, 0, False );
				if ( sl_result == DOCD_RetRamExist || sl_result == DOCD_RetFileExist ) {		// ●コール成功(getInstance時→RAM上に存在/File上に存在)(通常).
				} else {																// コール失敗(エラー).
					bl_isRsp = True;
NetTwainDebugTrace((char*)"### _GetJobID6() ERROR!!(You couldn't call req_getInstance) ###\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( si_SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info. 
					netc_TwainClientMan.setClientErrorStatus( si_SocketFd, True );					// Error Client Error Status.
					strcpy( sc_ReqData, "\x1b*s283tN" );										// 設定失敗.
					free( netc_TwainClientMan.getTwainDocumentInfo6( si_SocketFd ) );
					DocListCreateSocketFd = 0;													// DocumentList作成中のクライアントのsi_SocketFd. 
				}
			}
		} else {																		// WDATコマンドがSCL_GET_DOC_INFO_6でない(エラー).
NetTwainDebugTrace((char*)"# _GetJobID6() COMMAND is not SCL_GET_DOC_INFO_6! #\n", 0,0,0,0,0,0);
			return;
		}
		if ( bl_isRsp == True ) {
			char* pc_RspData = (char*)malloc( strlen(sc_ReqData) );
			if( pc_RspData == NULL ){
				errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
				return;
			}
			memcpy( pc_RspData, sc_ReqData, strlen(sc_ReqData) );
			netc_TwainClientMan.setSendData( si_SocketFd, pc_RspData, (uint32_t)strlen(sc_ReqData) );		// 送信データ保持領域に書き込む. 
			if ( netc_TwainClientMan.getRREQReceived( si_SocketFd ) == True ) {						// RREQを受けている.
				if ( netc_TwainClientMan.getCommandID( si_SocketFd ) == SCL_GET_DOC_INFO_6 ) { 		// WDATコマンドがSCL_GET_DOC_INFO_6.
					netc_TwainClientMan.setRdatSend( si_SocketFd , netc_TwainClientMan.getRREQRequestSize( si_SocketFd ), 4 );
				} else {
					free( pc_RspData );
				}
			}
			netc_TwainClientMan.setHddAccessEndWait( si_SocketFd );
		}
	}
}
//2012/01/26 ZeusMLK <UV-00973 OfficeOpenXML形式ファイル生成機能> Iwata End.

