		ss_SetLowDensityAdjustment = SStoLE( ss_SetLowDensityAdjustment );
		short ss_SetFeedDirection = 0;	//	Set Feed Direction 
		memcpy( &ss_SetFeedDirection, &s_SetScanParameter3.uc_SetFeedDirection[0], 2 );
