//		SCL_SET_SESSION_TIMEOUT				105		// Set Session Timeout.
//==================================================================================================.
//[クラス] NETC_TwainCommandSetSessionTimeout.
//[内容] SCL_SET_SESSION_TIMEOUTコマンドを処理するクラス.
//[履歴] 2012/11/14 S12-r_mori CQ373974 [ZeusBK][開発提起][UV-01233] タイムアウト(60分)経過まで次ジョブが投入できない.
//==================================================================================================.
//==================================================================================================.
//[機能] NETC_TwainCommandSetSessionTimeoutのコンストラクタ.
//==================================================================================================.
NETC_TwainCommandSetSessionTimeout::NETC_TwainCommandSetSessionTimeout( int si_CommandID ) : NETC_TwainCommandMan( si_CommandID ) {}

//==================================================================================================.
//[機能] コマンドを処理する.
//==================================================================================================.
void NETC_TwainCommandSetSessionTimeout::CommandProc(
	int si_SocketFd,		// ソケットディスクリプタ.
	char* psc_Parameter,	// パラメータへのポインタ.
	short ss_ParamLength	// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandSetSessionTimeout::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	// ログイン要求パラメータを分析する.
	char sc_Size[32];											// コマンドの‘D’までの格納用.
	memset( sc_Size, 0, sizeof(sc_Size) );						// 初期化.
	int si_index = 0;											// For文で使用用.
	int32_t sl_timeout = 0;											// 30D←といったサイズ長データと区切り記号を抜いた分の実際のtimeout指定値.
	// 30D←といったパラメータ長と区切り記号のDまでを抜き出し、サイズを取得する.
	Bool bl_Rsp = False;
	for ( si_index = 0; si_index < 32; si_index++ )
	{
		if ( psc_Parameter[si_index] == 'D' )
		{
			sc_Size[si_index] = '\0';
			si_index++;
			break;
		}
		sc_Size[si_index] = psc_Parameter[si_index];
	}
	sc_Size[31] = '\0';							// プロテクト.
	sl_timeout = atol((char*)sc_Size);
	
	// 応答データの領域を確保する.
	char sc_ReqData[32];
	
	// 指定されたタイムアウト値が０以下の場合は設定失敗とする.
	if(sl_timeout < 1){
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetSessionTimeout::CommandProc Error!! [%d] #\n", (int)sl_timeout,0,0,0,0,0);
		strcpy( sc_ReqData, "\x1b*s20125r0V" );					// 失敗応答.
		bl_Rsp = True;
	}else{
NetTwainDebugTrace((char*)"### session timeout         = [%d] ###\n",(int)sl_timeout,0,0,0,0,0);
		// 現在のWatchDogTimerをリセットする.
		WDOG_ID wdog_ID_Device = netc_TwainClientMan.getwdogID_Device( si_SocketFd );
		twainWatchDogCancel( wdog_ID_Device );
		// 指定されたTimeout値をSocketFdに紐付けて保持する(IF仕様は秒数で指定されるが内部はmsecで保存する).
		netc_TwainClientMan.setSessionTimeout( si_SocketFd, (sl_timeout * 1000) );
		// 指定されたTimeout値でWatchDogをRestartする.
		twainWatchDogStart( wdog_ID_Device, netc_TwainClientMan.getSessionTimeout( si_SocketFd ), (FUNCPTR)DevicePacketRecieveTimeOutProc, si_SocketFd ); 

		strcpy( sc_ReqData, "\x1b*s20125r1V" );					// 成功応答.
		bl_Rsp = True;
	}

	if ( bl_Rsp == True ) {
		char* psc_RspData = (char*)malloc( strlen(sc_ReqData) );
		if( psc_RspData == NULL ){
			errorLog_TwainService("psc_RspData malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( psc_RspData, sc_ReqData, strlen(sc_ReqData) );
		netc_TwainClientMan.setSendData( si_SocketFd, psc_RspData, (uint32_t)strlen(sc_ReqData) );		// 送信データ保持領域に書き込む.
		if ( netc_TwainClientMan.getRREQReceived( si_SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( si_SocketFd, netc_TwainClientMan.getRREQRequestSize( si_SocketFd ), 4 );
		}
	}
}
