// ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応 2013/03/07 OPS1八代 START.
// SCL_GET_SECURITY_RXDATA				// 106: Inquire Security Setting of RX Data.
//==================================================================================================
//[クラス]NETC_TwainCommandGetSecurityRxData.
//[内容] SCL_GET_SECURITY_RXDATAコマンドを処理するクラス.
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetSecurityRxDataのコンストラクタ.
//==================================================================================================
NETC_TwainCommandGetSecurityRxData::NETC_TwainCommandGetSecurityRxData( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}
//==================================================================================================
//[機能]コマンドを処理する.
//[戻り値]なし.
//[履歴]2013/03/07 OPS1八代.
//		ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応.
//==================================================================================================
void NETC_TwainCommandGetSecurityRxData::CommandProc(
	int SocketFd,		// ソケットディスクリプタ.
	char* Parameter,	// パラメータへのポインタ.
	short ParamLength	// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetSecurityRxData::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	memset( pc_ReqData, 0x00, sizeof(pc_ReqData) );

	APIC_FaxPanelSetting* pc_FaxPanelSetting  = APIC_FaxPanelSetting::newInstance();
	TYPE_FaxRxDataGuard   e_FaxRxDataGuard    = TYPE_FaxRxDataGuardOFF;

	uchar uc_FaxRxDataGuardPassword[16+1];		// パスワードは必要としないが、コンパイルエラー回避の為、宣言及び取得する.
	memset(uc_FaxRxDataGuardPassword, 0, sizeof(uc_FaxRxDataGuardPassword));

	if( NULL != pc_FaxPanelSetting ) {
		pc_FaxPanelSetting->lock();
		e_FaxRxDataGuard = pc_FaxPanelSetting->getFaxRxDataGuard( uc_FaxRxDataGuardPassword );
		pc_FaxPanelSetting->unlock();
	} else {
NetTwainDebugTrace((char*)" NETC_TwainCommandGetSecurityRxData::CommandProc() pc_FaxPanelSetting is NULL \n", 0,0,0,0,0,0);
		return;
	}

	switch( e_FaxRxDataGuard ) {
		case 	TYPE_FaxRxDataGuardOFF: 	 strcpy( pc_ReqData, "\x1b*s21029d0V" );	break; // しない.
		case 	TYPE_FaxRxDataGuardPassword: strcpy( pc_ReqData, "\x1b*s21029d1V" );	break; // する(パスワード).
		case 	TYPE_FaxRxDataGuardBoxAdmin: strcpy( pc_ReqData, "\x1b*s21029d2V" );	break; // する(ボックス管理者で削除).
		default:
NetTwainDebugTrace((char*)" NETC_TwainCommandGetSecurityRxData::CommandProc() e_FaxRxDataGuard  is undefined[%d] \n", (int)e_FaxRxDataGuard,0,0,0,0,0);
		break; // 例外.
	}

	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
// MinervaZeus3rd CQ381661(静的解析) ID12127 2013.07.11 OPS1前田.
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error \n", 0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
	if( netc_TwainClientMan.getRREQReceived( SocketFd ) == True )
	{
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
NetTwainDebugTrace((char*)" NETC_TwainCommandGetSecurityRxData::CommandProc()_End!! \n", 0,0,0,0,0,0);
}

//		SCL_DELETE_DOC2				107		// Delete Document2.
//==================================================================================================
//[クラス]NETC_TwainCommandDeleteDoc2 
//[内容] SCL_DELETE_DOC2コマンドを処理するクラス 
//[履歴] 2013/03/07 OPS1八代 新規作成 : ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応.
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandDeleteDoc2のコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2013/03/07 OPS1八代 新規作成 : ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応.
//==================================================================================================
NETC_TwainCommandDeleteDoc2::NETC_TwainCommandDeleteDoc2( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2013/03/07 OPS1八代 新規作成 : ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応.
//==================================================================================================
void NETC_TwainCommandDeleteDoc2::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandDeleteDoc2::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	// HDD装着のチェックを行う 
	char pc_ReqData[32];
	Bool isRsp = False;	// 2007.02.20 Harada 追加 
	if( isCheckAvailableBox() == NETE_Function_Box_Disabled )				// BOX使用可能or一部使用可能のとき.	// 2011/03/31 amiya 【Minerva】管理No941 SSD削減対応（1GB⇒512MB）.
	{
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_HDD_NOT_INSTALLED , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s21115r0V" );	// 失敗応答 
		isRsp = True;	// 2007.02.20 Harada 追加 
	// 2008.08.05 Donau問題点対応 CC 307768 平谷 str.
	} else if ( ( NULL != netc_TwainClientMan.getApic_Admin( SocketFd ) )
		&& ( True == netc_TwainClientMan.getUserLogined( SocketFd ) ) ) {	// 管理者ログイン時は不可.
NetTwainDebugTrace((char*)"# NETC_TwainCommandDeleteDoc2_ERR_USER_BOX_NOT_SPECIFIED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__ );	// Error Client Error Info.
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
		strcpy( pc_ReqData, "\x1b*s21115r0V" );	// 失敗応答.
		isRsp = True;	// 2007.02.20 Harada 追加 
	// 2008.08.05 Donau問題点対応 CC 307768 平谷 end.
	} else {											// HDDありの場合 
		// 監査ログフルのため操作禁止か否かをチェックする 
		APIC_SystemStatus* pc_SystemStatus = NULL;
		pc_SystemStatus = APIC_SystemStatus::newInstance();
		pc_SystemStatus->lock();
		Bool bl_InspectLog = pc_SystemStatus->chkJobStarting( TYPE_JobEnableCheckStatusInspectLogCnt );
		pc_SystemStatus->unlock();
		if ( bl_InspectLog == False )
		{
			strcpy( pc_ReqData, "\x1b*s21115r0V" );		// 失敗応答 
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_SURVEILLANT_LOG_FULL , __FILE__ ,__LINE__);	// 監視ログのサイズが上限のためにジョブの登録、デバイス操作が行えないエラー 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// エラー発生状態とする 
			isRsp = True;	// 2007.02.20 Harada 追加 
		}
		else
		{
			if ( netc_TwainClientMan.getBoxLogined( SocketFd ) == True ) {	// Boxログイン状態 
				// ユーザー認証時の操作許可チェックを行う 
				if ( getUserAuthenticationMode() != TYPE_UserAuthenticationOff ) {	// ユーザー認証モードがOFF以外(ONの場合) 
					if ( netc_TwainClientMan.getUserLogined(SocketFd) == True ) {		// ログイン済み 
						APIC_User* pc_User = netc_TwainClientMan.getApic_User( SocketFd );
						if(pc_User == NULL){
							errorLog_TwainService("pc_User NULL!!!\n",0,0,0,0,0,0);
							return;
						}
						pc_User->lock();
						TYPE_FuncLimit e_BoxOperation = pc_User->getFunctionLimitation().e_EnableBoxOperation;	// 2010/08/25 amiya 【Minerva】UV-00458 ユーザー毎のカラー白黒出力制限をコピーとプリントで別々に設定したい対応.
						pc_User->unlock();
						if ( e_BoxOperation == TYPE_FuncLimit_Disable ) {		// 蓄積文書操作不可の場合 
							netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
							netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
							strcpy( pc_ReqData, "\x1b*s21115r0V" );		// 失敗応答 
							char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
							if( pc_RspData == NULL ){
								errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
								return;
							}
							memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
							netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
							if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
								netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
							}
							return;
						}
					}
				}
				// ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応 2013/03/07 OPS1八代 START.
				// ZM3rd CQ380700 2013/06/11 OPS1八代 START.
				for(short ii=0; ii < ParamLength; ii++) {
NetTwainDebugTrace((char*)"# NETC_TwainCommandDeleteDoc2::CommandProc() Parameter[%d] =  %d #\n", (int)ii, (int)Parameter[ii],0,0,0,0);
				}

				// パスワードが間違っていた場合、削除失敗となる.
				// 不揮発からパスワードを取得する.
				APIC_FaxPanelSetting* pc_FaxPanelSetting  = APIC_FaxPanelSetting::newInstance();
				TYPE_FaxRxDataGuard   e_FaxRxDataGuard    = TYPE_FaxRxDataGuardOFF;

				// MinervaZeus3rd CQ381661(静的解析) ID32254 2013.07.11 OPS1前田.
				uchar uc_FaxRxDataGuardPasswordNVRAM[16+1];
				memset(uc_FaxRxDataGuardPasswordNVRAM, 0, sizeof(uc_FaxRxDataGuardPasswordNVRAM));

				if( NULL != pc_FaxPanelSetting ) {
					pc_FaxPanelSetting->lock();
					e_FaxRxDataGuard = pc_FaxPanelSetting->getFaxRxDataGuard( uc_FaxRxDataGuardPasswordNVRAM );
					pc_FaxPanelSetting->unlock();
				} else {
NetTwainDebugTrace((char*)"# NETC_TwainCommandDeleteDoc2::CommandProc() pc_FaxPanelSetting is NULL #\n", 0,0,0,0,0,0);
					return;
				}
NetTwainDebugTrace((char*)"# NETC_TwainCommandDeleteDoc2::CommandProc() e_FaxRxDataGuard =  %d #\n", (int)e_FaxRxDataGuard,0,0,0,0,0);
NetTwainDebugTraceUserInfo((char*)"# NETC_TwainCommandDeleteDoc2::CommandProc() uc_FaxRxDataGuardPasswordNVRAM =  %s #\n", reinterpret_cast<intptr_t>(uc_FaxRxDataGuardPasswordNVRAM),0,0,0,0,0);		// 2022/2/7 [IT6_2.2MR2] OP_BTS-37530 HIENG.
				// コマンドから、item情報(パスワード)を抜き出す.
				// Parameterには、# + X + [data]が入っている.
				// #はバイナリデータサイズ。
				// 'X'は、データサイズと[data]の区切り検知文字.
				// [data]は実データ(ドキュメント識別番号(4byte)+パスワード(16byte)).
				// 以下例の@がドキュメント識別番号の先頭、?がパスワードの先頭となる.
				// 例) #X@***?***************

				// 区切り検知文字'X'の位置を検出する.
				short s_PosDetectChar = 0;
				for ( s_PosDetectChar = 0; s_PosDetectChar < ParamLength; s_PosDetectChar++ ) {
					if ( Parameter[s_PosDetectChar] == 'X' ) break;
				}
NetTwainDebugTrace((char*)"# NETC_TwainCommandDeleteDoc2::CommandProc() s_PosDetectChar =  %d #\n", (int)s_PosDetectChar,0,0,0,0,0);

				// 区切り検知文字'X'から、+5するとパスワードの先頭配列番号となる.
				//        12345
				// 例t) #X@***?***************
				char c_FaxRxPassword[16+1];
				memset( c_FaxRxPassword, 0, 16+1 );
				memcpy( c_FaxRxPassword, &Parameter[s_PosDetectChar+5], 16 );

				// SSL OFFの場合、MD5で暗号化されているため、同アルゴリズムで復号化する.
				APIC_TcpSocketSetting* pc_TcpSocketSetting = APIC_TcpSocketSetting::newInstance();
				pc_TcpSocketSetting->lock();
				Bool bl_EnableSSL = pc_TcpSocketSetting->getEnableSSL();
				pc_TcpSocketSetting->unlock();

				if( False == bl_EnableSSL ) {
					int length = strlen( (char*)uc_FaxRxDataGuardPasswordNVRAM );
					char buf[256];
					memset( buf, 0, sizeof(buf) );
					if(netc_TwainClientMan.getChallengeValue( SocketFd ) == NULL){
						errorLog_TwainService("getChallengeValue NULL!!!\n",0,0,0,0,0,0);
						return;
					}
					memcpy( &buf[0], netc_TwainClientMan.getChallengeValue( SocketFd ), 16 );
					memcpy( &buf[16], uc_FaxRxDataGuardPasswordNVRAM, length );
					char sc_md5[256];
					memset( sc_md5, 0, sizeof(sc_md5) );
					KM_MD5( (unsigned char*)&buf[0], 16+length, (unsigned char*)&sc_md5[0] );

					memset( uc_FaxRxDataGuardPasswordNVRAM, 0, 16+1 );				// 一度、クリアして...
					memcpy( uc_FaxRxDataGuardPasswordNVRAM, &sc_md5[0], 16 );		// MD5ハッシュ後のデータをコピーする.
//2013/09/10 OPS1前田(Sky)【ZM3rd】コンパイルワーニング除去対応 CQ378083 コンパイルワーニング除去対応 Start.
					for(unsigned short jj=0; jj < strlen( (char*)uc_FaxRxDataGuardPasswordNVRAM ); jj++) {
//2013/09/10 OPS1前田(Sky)【ZM3rd】コンパイルワーニング除去対応 CQ378083 コンパイルワーニング除去対応 End.
NetTwainDebugTraceUserInfo((char*)"# NETC_TwainCommandDeleteDoc2::CommandProc() uc_FaxRxDataGuardPasswordNVRAM[%d] =  %d #\n", (int)jj, (int)uc_FaxRxDataGuardPasswordNVRAM[jj],0,0,0,0);		// 2022/2/7 [IT6_2.2MR2] OP_BTS-37530 HIENG.
					}
				}
				// パスワードを比較する.
				if(  ( TYPE_FaxRxDataGuardPassword != e_FaxRxDataGuard )
				  || ( memcmp( uc_FaxRxDataGuardPasswordNVRAM, c_FaxRxPassword, strlen( (char*)uc_FaxRxDataGuardPasswordNVRAM ) ) != 0 ) ) {
NetTwainDebugTrace((char*)"# NETC_TwainCommandDeleteDoc2::CommandProc() Password Unmath #\n", 0,0,0,0,0,0);
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );										// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21115r0V" );		// 失敗応答 
					char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
					if( pc_RspData == NULL ){
						errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
						return;
					}
					memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
					netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
					if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
						netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
					}
					return;
				}
				// パラメータからドキュメント識別番号を取得する 
				// 区切り検知文字'X'から、+1するとパスワードの先頭配列番号となる.
				//        1
				// 例) #X@***?***************
				// また、DeleteDocumetとは異なり、DeleteDocumet2のドキュメント識別番号は、
				// バイナリデータで送付されてくるため、1Byteずつシフト変換を行う.
				int32_t sl_DocID = (unsigned char)(Parameter[(s_PosDetectChar+1)])
						     + ((unsigned char)(Parameter[(s_PosDetectChar+1)+1])<<8)
        					 + ((unsigned char)(Parameter[(s_PosDetectChar+1)+2])<<16)
						     + ((unsigned char)(Parameter[(s_PosDetectChar+1)+3])<<24);
NetTwainDebugTrace((char*)"# NETC_TwainCommandDeleteDoc2::CommandProc() sl_DocID =  %d #\n", (int)sl_DocID,0,0,0,0,0);
				// ZM3rd CQ380700 2013/06/11 OPS1八代 END.
				// ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応 2013/03/07 OPS1八代 END.

				// ログインしている状態のBoxのIDとパスワードを取得しBox情報を参照する 
				APIC_Box* pc_Box = NULL;
				pc_Box = APIC_Box::newInstance();
				pc_Box->setLogIFNo( JLGE_InspectLogIfTCPSocket );							// ログ用IF No 登録.
				pc_Box->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );
				// ジョブの破棄を要求する
				int32_t ret = 0;
				Bool bl_UserLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
				APIC_User* pc_UserGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
				Bool bl_TrackLogined = False;		// 2011/02/14 Coverity対応 変数初期化.
				APIC_Track* pc_TrackGet = NULL;		// 2011/02/14 Coverity対応 変数初期化.
				(void)getLoginStatusCheck( &bl_UserLogined, &pc_UserGet, &bl_TrackLogined, &pc_TrackGet, SocketFd );
				// 2007.01.30 Harada I/F変更 コールバック関数対応 deleteDoc() → req_deleteDoc() 
				int index = netc_TwainClientMan.getClientIndex( SocketFd );
				if ( index != -1 )
				{
					// 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴 START.
					if( isForceMemoryReceiveBoxJournal( SocketFd ) ){
NetTwainDebugTrace((char*)"### ForceMemoryReceiveBox && SoftSw No77 0x04 ###\n",0,0,0,0,0,0);
						APIC_User* pc_User = netc_TwainClientMan.getApic_User( SocketFd );					// ログインユーザーインスタンス取得.
						int32_t sl_UserNo = 0;		//2014/02/07 【スケーラブルFUM】[CQ385789] 20万人対応. 
						if ( pc_User != NULL ){
							pc_User->lock();
							sl_UserNo = pc_User->getUserNo();
							pc_User->unlock();
						}
						// ログインユーザーがパブリックかつ任意の文字列が設定されていない場合はエラー.
						if( netc_TwainClientMan.getForceMemoryName( SocketFd ) == NULL ){
							errorLog_TwainService("getForceMemoryName Error\n",0,0,0,0,0,0);
							return;
						}
						if( sl_UserNo == TYPD_IndexUserPublic && *netc_TwainClientMan.getForceMemoryName( SocketFd ) == '\0' ){
							NetTwainDebugTrace((char*)"### ForceMemoryName NULL!!! ###\n",0,0,0,0,0,0);			// パブリック指定時のユーザー名が設定されていない.
							netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);		// Error Client Error Info.
							netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status.
							strcpy( pc_ReqData, "\x1b*s21115r0V" );	// 失敗応答.
							isRsp = True;
						} else {
							netc_TwainClientMan.setTransactionID( SocketFd, 0 , -1);						// トランザクションIDを初期化.
							netc_TwainClientMan.setTransactionIndex( SocketFd, 0 );							// トランザクション管理インデックス.
							netc_TwainClientMan.setDeleteDocumentID( SocketFd , sl_DocID);					// ドキュメントIDを保存.
							APIC_Doc* pc_Doc  = APIC_Doc::newInstance();
							pc_Doc->setLogIFNo( JLGE_InspectLogIfTCPSocket );								// ログ用IF No 登録.
							pc_Doc->setBoxId( netc_TwainClientMan.getLoginedBoxNo( SocketFd ) );
							pc_Doc->setDocId( sl_DocID );
							ret = pc_Doc->req_GetJobStatus( netc_TwainClientMan.getJobStatusDoc( SocketFd ) , ans_GetJobStatusTbl[index] );
							pc_Doc->deleteInstance();
NetTwainDebugTrace((char*)" NETC_TwainCommandDeleteDoc2::CommandProc() req_GetJobStatus call \n", 0,0,0,0,0,0);
							if( ret != APID_DocapiMethodOk ){
	NetTwainDebugTrace((char*)"###req_GetJobStatus Error!!! return = [%d] ###\n",(int)ret,0,0,0,0,0);
								netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info.
								netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status.
								strcpy( pc_ReqData, "\x1b*s21115r0V" );	// 失敗応答.
								isRsp = True;
							}
						}
					} else {
// 2010/03/23 okabe Gaia <UV-00970> FAX受信ボックスの出力ユーザ履歴 END.
						ret = pc_Box->req_deleteDoc( pc_UserGet,												// 既存ユーザー 
													 netc_TwainClientMan.getLoginedBoxPassword( SocketFd ),		// 既存パスワード 
													 sl_DocID,													// 削除対象DocID 
													 ans_DeleteDocTable[index],									// コールバックアドレス 
													 APID_DefaultWatchDocID,									// 削除対象WatchDocID 
													 pc_TrackGet );												// 部門管理情報 

NetTwainDebugTrace((char*)" NETC_TwainCommandDeleteDoc2::CommandProc() req_deleteDoc call \n", 0,0,0,0,0,0);
					}
				}
				pc_Box->deleteInstance();
				if( ret != APID_DocapiMethodOk ) {		// 正常終了以外 	// 2007.01.30 Harada 
					netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
					netc_TwainClientMan.setClientErrorStatus( SocketFd, True );					// Error Client Error Status 
					strcpy( pc_ReqData, "\x1b*s21115r0V" );	// 失敗応答 
					isRsp = True;	// 2007.02.20 Harada 追加 
				}
			} else {														// Boxログアウト状態 
				netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_BOX_NOT_SPECIFIED , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( SocketFd, True );						// Error Client Error Status 
				strcpy( pc_ReqData, "\x1b*s21115r0V" );	// 失敗応答 
				isRsp = True;	// 2007.02.20 Harada 追加 
			}
		}
	}
	if ( isRsp == True ) {	// 2007.02.20 Harada 追加 
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
		}
	}
}
// ZM3rd UV-01227_ファックスJOBを管理者権限がないと削除不可とする対応 2013/03/07 OPS1八代 END.

//2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28 Start.
//		SCL_GET_OPTION_FUNCTION				109		// Get Device Function Option.
//==================================================================================================
//[クラス]NETC_TwainCommandGetOptionFunction 
//[内容] SCL_GET_OPTION_FUNCTIONコマンドを処理するクラス 
//[履歴] 2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28.
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetOptionFunctionのコンストラクタ 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28.
//==================================================================================================
NETC_TwainCommandGetOptionFunction::NETC_TwainCommandGetOptionFunction( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28.
//==================================================================================================
void NETC_TwainCommandGetOptionFunction::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetOptionFunction::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];

	APIC_EnablerSetting* pc_EnablerSetting = APIC_EnablerSetting::newInstance();

	NETS_GetDeviceFunctionOption s_GetDeviceFunctionOption;
	memset( &s_GetDeviceFunctionOption, 0, sizeof(NETS_GetDeviceFunctionOption) );
	NETE_FileFormat e_FileFormat = NETE_FileFormat_None;

	e_FileFormat = ( e_FileFormat | NETE_FileFormat_PDF );
	e_FileFormat = ( e_FileFormat | NETE_FileFormat_TIFF );
	e_FileFormat = ( e_FileFormat | NETE_FileFormat_JPEG );

	// 機器構成にてファイル形式が有効(ファイル形式の送信に制限がない)であればビットを有効にする.
	if( True == SYSF_getAppOptionStatus( TYPE_AppOptionFileNoLicence ) ) {
NetTwainDebugTrace((char*)"### getAppOptionStatus(TYPE_AppOptionFileNoLicence) is True ###\n", 0,0,0,0,0,0);
		e_FileFormat = ( e_FileFormat | NETE_FileFormat_CPDF );
		e_FileFormat = ( e_FileFormat | NETE_FileFormat_XPS );
		e_FileFormat = ( e_FileFormat | NETE_FileFormat_CXPS );
		e_FileFormat = ( e_FileFormat | NETE_FileFormat_PPTX );
	}

	// I-Option(ファイル形式拡張パッケージ)が有効であればDOCX,XLSXのビットを有効にする.
	if( TYPE_CategoryState_ENABLE == pc_EnablerSetting->getFEK_CotegoryState( TYPE_FEKType21 ) ) {
NetTwainDebugTrace((char*)"### TYPE_FEKType21 TYPE_CategoryState_ENABLE ###\n", 0,0,0,0,0,0);
		e_FileFormat = ( e_FileFormat | NETE_FileFormat_DOCX );
		e_FileFormat = ( e_FileFormat | NETE_FileFormat_XLSX );
	}
NetTwainDebugTrace((char*)"### e_FileFormat :%lx ###\n", e_FileFormat,0,0,0,0,0);

	s_GetDeviceFunctionOption.sc_FileFormat[0] = ( e_FileFormat >>  0 &0xff );
	s_GetDeviceFunctionOption.sc_FileFormat[1] = ( e_FileFormat >>  8 &0xff );
	s_GetDeviceFunctionOption.sc_FileFormat[2] = ( e_FileFormat >> 16 &0xff );
	s_GetDeviceFunctionOption.sc_FileFormat[3] = ( e_FileFormat >> 24 &0xff );

	sprintf( pc_ReqData, "\x1b*s286t%dW", sizeof(NETS_GetDeviceFunctionOption) );
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData)+sizeof(NETS_GetDeviceFunctionOption) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	memcpy( &pc_RspData[strlen(pc_ReqData)], &s_GetDeviceFunctionOption, sizeof(NETS_GetDeviceFunctionOption) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData)+sizeof(NETS_GetDeviceFunctionOption) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}
//2014/03/26 OPS1前田[Zeus5BK] 制御構成変更No.28 End.

