//[履歴] [2015/03/16][MinervaSBK][RQ-189][OPS1前田]簡易認証対応.
//==================================================================================================
void NETC_TwainCommandSetSimpleAuth::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandSetSimpleAuth::CommandProc()_Start!! \n", 0,0,0,0,0,0);

	char sc_Data[32] = {0};
	memcpy( sc_Data, Parameter, ParamLength );
	sc_Data[ParamLength] = '\0';

	char pc_ReqData[32] = {0};

	char sc_SimpleAuthSetting = (char)atoi(sc_Data);

	if ( (0 <= sc_SimpleAuthSetting) && (sc_SimpleAuthSetting <= 1) ) {		// 設定範囲内の場合 
		netc_TwainClientMan.setSimpleAuth( SocketFd, sc_SimpleAuthSetting );
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetSimpleAuth sc_SimpleAuthSetting :%d #\n", sc_SimpleAuthSetting,0,0,0,0,0);
		strcpy( pc_ReqData, "\x1b*s20126r1V" );	// 設定成功 
	} else {										// 設定範囲外の場合 
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );										// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s20126r0V" );	// 設定失敗 
	}

	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

