//[履歴] 2015/12/1 GTaguchi 新規作成 : ZeusS_ZX0 MZV-74_RTMTwain速度改善要望.
//==================================================================================================
NETC_TwainCommandSetMixedOriginal::NETC_TwainCommandSetMixedOriginal( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}

//==================================================================================================
//[機能]コマンドを処理する 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2015/12/1 GTaguchi 新規作成 : ZeusS_ZX0 MZV-74_RTMTwain速度改善要望.
//==================================================================================================
void NETC_TwainCommandSetMixedOriginal::CommandProc(
	int SocketFd,		// ソケットディスクリプタ 
	char* Parameter,	// パラメータへのポインタ 
	short ParamLength	// パラメータの長さ 
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandSetMixedOriginal::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	if ( ( NULL != netc_TwainClientMan.getApic_Admin( SocketFd ) )
	  && ( True == netc_TwainClientMan.getUserLogined( SocketFd ) ) ) {	// 管理者ログイン時は不可.
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetMixedOriginal_ERR_ACCESS_DENIED #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_ACCESS_DENIED , __FILE__ ,__LINE__);		// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );										// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s90002r0V" );	// 設定失敗.
	} else if ( netc_TwainClientMan.getImageTransJobInstance( SocketFd ) == NULL ) {	// ジョブ未登録状態の場合 
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetMixedOriginal_ERR_USER_JOB_CANCEL #\n", 0,0,0,0,0,0);
		netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_USER_JOB_CANCEL , __FILE__ ,__LINE__);	// Error Client Error Info 
		netc_TwainClientMan.setClientErrorStatus( SocketFd, True );										// Error Client Error Status 
		strcpy( pc_ReqData, "\x1b*s90002r0V" );	// 設定失敗 
	} else {															// ジョブ登録済みの場合 
		char pc_tmpData[128];
		memset( &pc_tmpData, 0, sizeof(pc_tmpData) );
		memcpy( pc_tmpData, Parameter, ParamLength );
		pc_tmpData[ParamLength] = '\0';
		short ss_Data = (short)atoi(pc_tmpData);
		if ( (1 <= ss_Data) && (ss_Data <= 2) ) {		// 設定範囲内の場合 
			netc_TwainClientMan.setMixedOriginal( SocketFd, (char)ss_Data );			//  Mixed Original 
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetMixedOriginal ss_Data :%d #\n", (char)ss_Data,0,0,0,0,0);
			strcpy( pc_ReqData, "\x1b*s90002r1V" );	// 設定成功 
		} else {										// 設定範囲外の場合 
NetTwainDebugTrace((char*)"# NETC_TwainCommandSetMixedOriginal_ERR_PARAMETER_ERROR #\n", 0,0,0,0,0,0);
			netc_TwainClientMan.setClientErrorInfo( SocketFd, ERR_PARAMETER_ERROR , __FILE__ ,__LINE__);	// Error Client Error Info 
			netc_TwainClientMan.setClientErrorStatus( SocketFd, True );										// Error Client Error Status 
			strcpy( pc_ReqData, "\x1b*s90002r0V" );	// 設定失敗 
		}
	}
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
	if ( netc_TwainClientMan.getRREQReceived( SocketFd ) == True ) {
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
}

