// [2016/04/15][ZeusSBK][CQ527368] 第2システム深谷 Start.
// SCL_GET_ENHANCED_SECURITY_MODE				// 116: Inquire Enhanced Security Mode.
//==================================================================================================
//[クラス]NETC_TwainCommandGetEnhancedSecurityMode.
//[内容] SCL_GET_SECURITY_RXDATAコマンドを処理するクラス.
//==================================================================================================
//==================================================================================================
//[機能]NETC_TwainCommandGetEnhancedSecurityModeのコンストラクタ.
//==================================================================================================
NETC_TwainCommandGetEnhancedSecurityMode::NETC_TwainCommandGetEnhancedSecurityMode( int CommandID ) : NETC_TwainCommandMan( CommandID ) {}
//==================================================================================================
//[機能]コマンドを処理する.
//[戻り値]なし.
//[履歴]2016/04/15 第2システム深谷.
//		ZeusSBK 527368_セキュリティ強化モードのとき、PSBOのクイック印刷を制限する.
//==================================================================================================
void NETC_TwainCommandGetEnhancedSecurityMode::CommandProc(
	int SocketFd,		// ソケットディスクリプタ.
	char* Parameter,	// パラメータへのポインタ.
	short ParamLength	// パラメータの長さ.
)
{
NetTwainDebugTrace((char*)" NETC_TwainCommandGetEnhancedSecurityMode::CommandProc()_Start!! \n", 0,0,0,0,0,0);
	char pc_ReqData[32];
	memset( pc_ReqData, 0x00, sizeof(pc_ReqData) );
	
	APIC_SystemSetting* pc_SystemSetting  = APIC_SystemSetting::newInstance();
	
	if( NULL != pc_SystemSetting ) {
		pc_SystemSetting->lock();
		Bool bl_isEhdSecurityMode = pc_SystemSetting->getSecurityLevelUpOn();
		pc_SystemSetting->unlock();
		
		if( True == bl_isEhdSecurityMode ) {
			strcpy( pc_ReqData, "\x1b*s21030d1V" );	// 有効.
		} else {
			strcpy( pc_ReqData, "\x1b*s21030d0V" );	// 無効.
		}
	} else {
NetTwainDebugTrace((char*)" NETC_TwainCommandGetEnhancedSecurityMode::CommandProc() pc_SystemSetting is NULL \n", 0,0,0,0,0,0);
		return;
	}
	
	char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
	if( pc_RspData == NULL ){
		errorLog_TwainService("pc_RspData_malloc Error \n", 0,0,0,0,0,0);
		return;
	}
	memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
	netc_TwainClientMan.setSendData( SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む.
	if( netc_TwainClientMan.getRREQReceived( SocketFd ) == True )
	{
		netc_TwainClientMan.setRdatSend( SocketFd, netc_TwainClientMan.getRREQRequestSize( SocketFd ), 4 );
	}
NetTwainDebugTrace((char*)" NETC_TwainCommandGetEnhancedSecurityMode::CommandProc()_End!! \n", 0,0,0,0,0,0);
	return;
}
// [2016/04/15][ZeusSBK][CQ527368] 第2システム深谷 End.

