// --- 21532対応 ここから --- 
//==================================================================================================
//[機能]NETC_UserAuthenticationObserverの初期処理 
//==================================================================================================
void NETC_UserAuthenticationObserver::initSet()
{
	// ユーザー認証の初期化 
	APIC_UserAuthentication* pc_UserAuthentication = NULL;
	pc_UserAuthentication = APIC_UserAuthentication::newInstance();
	if ( pc_UserAuthentication != NULL ) {
		pc_UserAuthentication->lock();
		ne_UserAuthentication = pc_UserAuthentication->getUserAuthentication();		// ユーザー認証 
		ne_CertificationAction = pc_UserAuthentication->getCertificationAction();	// ユーザー認証動作方法 
		pc_UserAuthentication->unlock();
	}
}

//==================================================================================================
//[機能]NETC_UserAuthenticationObserverのデータ変化通知時の処理 
// 2004.04.27 yamahataユーザー認証の変更があった場合、接続しているすべての全クライアントとの切断を行う処理追加 
//==================================================================================================
void NETC_UserAuthenticationObserver::dataChanged()
{
	APIC_UserAuthentication* pc_UserAuthentication = NULL;
	pc_UserAuthentication = APIC_UserAuthentication::newInstance();
	pc_UserAuthentication->lock();
	TYPE_UserAuthentication e_UserAuthentication = pc_UserAuthentication->getUserAuthentication();
	TYPE_CertificationAction e_CertificationAction = pc_UserAuthentication->getCertificationAction();
	pc_UserAuthentication->unlock();
	if ( ( ne_UserAuthentication != e_UserAuthentication )
	  || ( ne_CertificationAction != e_CertificationAction ) ){
		// ユーザー認証の変更があった場合、接続しているすべての全クライアントとの切断を行う 
		NETC_TwainService* netc_TwainService = NULL;
		netc_TwainService = NETC_TwainService::newInstance();
		netc_TwainService->allConnSocketCloseProc();
		ne_UserAuthentication = e_UserAuthentication;
		ne_CertificationAction = e_CertificationAction;
	}
}

//==================================================================================================
//[機能]NETC_TrackManagerObserverの初期処理 
//==================================================================================================
void NETC_TrackManagerObserver::initSet()
{
	// 部門管理の初期化 
	APIC_TrackManager* pc_TrackManager = NULL;
	pc_TrackManager = APIC_TrackManager::newInstance();
	if ( pc_TrackManager != NULL ) {
		pc_TrackManager->lock();
		ne_TrackMode = pc_TrackManager->getTrackMode();
		pc_TrackManager->unlock();
	}
}

//==================================================================================================
//[機能]NETC_TrackManagerObserverのデータ変化通知時の処理 
// 2004.04.27 yamahataユーザー認証の変更があった場合、接続しているすべての全クライアントとの切断を行う処理追加 
//==================================================================================================
void NETC_TrackManagerObserver::dataChanged()
{
	APIC_TrackManager* pc_TrackManager = NULL;
	pc_TrackManager = APIC_TrackManager::newInstance();
	pc_TrackManager->lock();
	TYPE_TrackMode e_TrackMode = pc_TrackManager->getTrackMode();
	pc_TrackManager->unlock();
	if ( ne_TrackMode != e_TrackMode ){
	// 部門管理の変更があった場合、接続しているすべての全クライアントとの切断を行う 
		NETC_TwainService* netc_TwainService = NULL;
		netc_TwainService = NETC_TwainService::newInstance();
		netc_TwainService->allConnSocketCloseProc();
		ne_TrackMode = e_TrackMode;
	}
}

NETC_TrackManagerObserver netc_TrackManagerObserver;

NETC_UserAuthenticationObserver netc_UserAuthenticationObserver;

