						break;
					case TWNSERVICE_MSG_RREQ_PACKET:	// RREQコマンド 
							// パケット受信TimeOut(60min)監視用ウォッチドッグタイマーのキャンセル＆再スタート 
							// ログ管理者ログイン中は、パケット受信TimeOutが3分となる処理追加 06/07/25 yamahata
							twainWatchDogCancel( wdog_ID_Device );
//		2008.02.01 Harada Donau対応 No.86 監査ログの追加対応 
							twainWatchDogStart( wdog_ID_Device, netc_TwainClientMan.getSessionTimeout( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ), (FUNCPTR)DevicePacketRecieveTimeOutProc, netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ); // 2012/11/14 S12-r_mori CQ373974 [ZeusBK][開発提起][UV-01233] タイムアウト(60分)経過まで次ジョブが投入できない.
							// コマンドを判断する 
							ss_Cmd = netc_TwainClientMan.getCommandID( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() );	// WDATコマンドを取得する 
NetTwainDebugTrace((char*)"#### RREQ Receive CMD ID = [%d]####\n", ss_Cmd,0,0,0,0,0);
NetTwainDebugTrace((char*)"#### ScanDataFlag = [%d]####\n", netc_TwainClientMan.getScanDataFlag( netsTwainServiceMsgOption.pTwainSlave->getSocketFd()),0,0,0,0,0);
							if ( (ss_Cmd == -1) && (netc_TwainClientMan.getScanDataFlag( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ) == True ) ) {
								ss_Cmd = SCL_GET_SCAN_DATA;
								netc_TwainClientMan.setCommandID( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), ss_Cmd );
NetTwainDebugTrace((char*)"#### RREQ Receive CMD ID Changed = [%d]####\n", ss_Cmd,0,0,0,0,0);
							}

// >> 2008.03.03 Harada Donau対応 No.22 分割バックアップ対応.
							if ( ((ss_Cmd == SCL_GET_BACKUP_DATA) || (ss_Cmd == SCL_GET_BACKUP_MEDIA_FILE_DATA)) && (netc_TwainClientMan.getBackupDataRspExist() == True) ) {
// >> 2008.03.03 Harada Donau対応 No.22 分割バックアップ対応.
								netc_TwainClientMan.setRREQReceived( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), True );	// RREQ受信状態とする 
								netc_TwainClientMan.setRREQRequestSize( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netsTwainServiceMsgOption.pc_rreqData );	// RREQ要求サイズをセットする 
								netc_TwainClientMan.setSendBackupData( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netc_TwainClientMan.getRREQRequestSize( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ) );
							} else if ( ((ss_Cmd == SCL_GET_SCAN_DATA) || (ss_Cmd == SCL_GET_SCAN_PAGE_DATA)) && netc_TwainClientMan.getImageTransPreError( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ) == False ) {
								if ( netc_TwainClientMan.getRREQReceived( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ) == False ) {
									netc_TwainClientMan.setRREQReceived( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), True );	// RREQ受信状態とする 
									netc_TwainClientMan.setRREQRequestSize( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netsTwainServiceMsgOption.pc_rreqData );	// RREQ要求サイズをセットする 
									_ImageTransRequest( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() );
								} else {
									netc_TwainClientMan.setRREQRequestSize( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netsTwainServiceMsgOption.pc_rreqData );	// RREQ要求サイズをセットする 
								}
							} else if ( (ss_Cmd == SCL_GET_SCAN_DATA) && netc_TwainClientMan.getImageTransPreError( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ) == TRUE ) {
NetTwainDebugTrace((char*)"#### SCL_GET_SCANDATA & ImageTransPreError ####\n",0,0,0,0,0,0);
								if ( netc_TwainClientMan.getRREQReceived( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ) == FALSE ) {
									netc_TwainClientMan.setRREQReceived( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), TRUE );	// RREQ受信状態とする 
									netc_TwainClientMan.setRREQRequestSize( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netsTwainServiceMsgOption.pc_rreqData );	// RREQ要求サイズをセットする 
NetTwainDebugTrace((char*)"#### call _ImageTransRequest ####\n",0,0,0,0,0,0);
									_ImageTransRequest( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() );
								} else {
									// RDATの送信処理を行う 
									netc_TwainClientMan.setRREQReceived( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), TRUE );	// RREQ受信状態とする 
									netc_TwainClientMan.setRREQRequestSize( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netsTwainServiceMsgOption.pc_rreqData );	// RREQ要求サイズをセットする 
									netc_TwainClientMan.setRdatSend( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netsTwainServiceMsgOption.pc_rreqData, netsTwainServiceMsgOption.ss_rreqBytes );
								}
							} else {
								// RDATの送信処理を行う 
								netc_TwainClientMan.setRREQReceived( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), True );	// RREQ受信状態とする 
								netc_TwainClientMan.setRREQRequestSize( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netsTwainServiceMsgOption.pc_rreqData );	// RREQ要求サイズをセットする 
								netc_TwainClientMan.setRdatSend( netsTwainServiceMsgOption.pTwainSlave->getSocketFd(), netsTwainServiceMsgOption.pc_rreqData, netsTwainServiceMsgOption.ss_rreqBytes );
								// ↓Set Restore Data 対応 
								if ( netc_TwainClientMan.getRestoreDataStatus( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ) == True ) {				// 「Set Restore Data」実行中の場合  
									if ( netc_TwainClientMan.getRestoreEnd( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() ) == True ) {						// リストア全回数終了 
										netc_TwainClientMan.setRestoreDataStatus( netsTwainServiceMsgOption.pTwainSlave->getSocketFd() , False );					//  Restore実行中実行中を解除する 
									}
								}
								// ↑Set Restore Data 対応 
							}
						break;
					case TWNSERVICE_MSG_KCON_PACKET:	// KCONコマンド 
