//[機能]新規セッションの登録データベースのインデックス番号を返す 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
short NETC_TwainService::registNewClient(int)
{
	for(short i=0; i<MAX_TWAIN_CLIENTNUM; i++){
		if(!netsTwainService[i].bl_User){
			netsTwainService[i].bl_User = True;
NetTwainDebugTrace((char*)"NETC_TwainService::registNewClient called!! index=[%d]\n",i,0,0,0,0,0);
			return i;
		}
	}
	return 0;	//エラー	// 2011/2/21 amiya Coverity対応.
}

