//[機能]セッション終了時に登録データベースの仕様状態をクリアする 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
void NETC_TwainService::deleteClient(short index)
{
	if ( (index >= 0) && (index < MAX_TWAIN_CLIENTNUM) ) {
NetTwainDebugTrace((char*)"NETC_TwainService::deleteClient called!! index=[%d]\n",index,0,0,0,0,0);
		netsTwainService[index].bl_User = False;
	}
}

//==================================================================================================
//[機能]PUSH Twainジョブの開始 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
void NETC_TwainService::startPushTwain()
{
NetTwainDebugTrace((char*)" NETC_TwainService::startPushTwain()_Start!! \n", 0,0,0,0,0,0);
	// PUSH Twainジョブに対して、パネルにてStartボタンが押された。 
	// クライアントへの応答データを生成する 
	int si_SocketFd = netc_TwainClientMan.getTwainReqStatusFd();
	
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 Start.
	if ( 0 == si_SocketFd )
	{
		si_SocketFd = netc_TwainClientMan.getWaitNextJobFd();
	}
	
	char pc_ReqData[32];
	short ss_CommandID = netc_TwainClientMan.getCommandID( si_SocketFd );

	if ( (SCL_START_PUSH_SCAN == ss_CommandID) || (SCL_GET_NEXT_PAGE == ss_CommandID) )
	{
		// ウォッチドックタイマー動キャンセル＆削除 
		twainWatchDogCancel( wdog_ID_PushTwain );
		
		if ( SCL_START_PUSH_SCAN == ss_CommandID )
		{
			// ジョブ開始.
			strcpy( pc_ReqData, "\x1b*s20101r1V" );
NetTwainDebugTrace("### NETC_TwainService:startPushTwain Job Start [%d] !\n",(int)ss_CommandID,0,0,0,0,0);
		} else {
			// 読み込み再開のため、Inquire Next Page Data Availableの応答を返す.
			strcpy( pc_ReqData, "\x1b*s20201d2V" );
NetTwainDebugTrace("### NETC_TwainService:startPushTwain Next Page Start [%d] !\n",(int)ss_CommandID,0,0,0,0,0);
		}
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 End.
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( si_SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( si_SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( si_SocketFd, netc_TwainClientMan.getRREQRequestSize( si_SocketFd ), 4 );
NetTwainDebugTrace("### NETC_TwainService:startPushTwain Send To Driver !\n",0,0,0,0,0,0);
		}
	}
}

//==================================================================================================
//[機能]PUSH Twainパネルロック中のジョブのキャンセル 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
void NETC_TwainService::cancelTwainLock()
{
NetTwainDebugTrace((char*)" NETC_TwainService::cancelTwainLock()_Start!! \n", 0,0,0,0,0,0);
	// PUSH Twainジョブに対して、パネルにてStopボタンが押された。 
	// クライアントへの応答データを生成する 
	int si_SocketFd = netc_TwainClientMan.getTwainReqStatusFd();
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 Start.
	if ( 0 == si_SocketFd )
	{
		si_SocketFd = netc_TwainClientMan.getWaitNextJobFd();
	}
	
	short ss_CommandID = netc_TwainClientMan.getCommandID( si_SocketFd );
	if ( (SCL_START_PUSH_SCAN == ss_CommandID) || (SCL_GET_NEXT_PAGE == ss_CommandID) ) {
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 End.
		// ジョブに対してキャンセル処理を行う 
		APIC_Job* pc_Job = netc_TwainClientMan.getImageTransJobInstance( si_SocketFd );
		if ( SCL_START_PUSH_SCAN == ss_CommandID )
		{
			if ( pc_Job != NULL ) {
				pc_Job->lock();
				pc_Job->deleteInstance();
				pc_Job->unlock();
				netc_TwainClientMan.setImageTransJobInstance( si_SocketFd, NULL );
				netc_TwainClientMan.setScanDataFlag( si_SocketFd, False );
			}
		}
		APIC_SystemStatus* pc_SystemStatus = NULL;
		pc_SystemStatus = APIC_SystemStatus::newInstance();
		if ( pc_SystemStatus != NULL ) {
			pc_SystemStatus->lock();

// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 Start.
			pc_SystemStatus->setSeparateScanForTwain( TYPE_SeparateScanForTwain_Off );
			pc_SystemStatus->setNextImageEnableForTwain( TYPE_NextImageEnableForTwain_NoExec );
// comment 2014/1/15 OPS1-Sky南波 [特Rom対応][BK2ND-6][機種マージ]Reiffeisen過去対応のBK機種展開要望 End.

			pc_SystemStatus->setTwainLock( TYPE_TwainLockNon, pc_Job );		// ロック無し 
			pc_SystemStatus->unlock();
		}

		// ウォッチドックタイマー動キャンセル＆削除 
		twainWatchDogCancel( wdog_ID_PushTwain );
		netc_TwainClientMan.setPushTwain( si_SocketFd, False );		// PUSH Twain状態解除 

		char pc_ReqData[32];
		if ( SCL_START_PUSH_SCAN == ss_CommandID )
		{
			strcpy( pc_ReqData, "\x1b*s20101r2V" );
		}
		else
		{
			strcpy( pc_ReqData, "\x1b*s20201d0V" );
		}
		char* pc_RspData = (char*)malloc( strlen(pc_ReqData) );
		if( pc_RspData == NULL ){
			errorLog_TwainService("pc_RspData_malloc Error\n",0,0,0,0,0,0);
			return;
		}
		memcpy( pc_RspData, pc_ReqData, strlen(pc_ReqData) );
		netc_TwainClientMan.setSendData( si_SocketFd, pc_RspData, (uint32_t)strlen(pc_ReqData) );		// 送信データ保持領域に書き込む 
		if ( netc_TwainClientMan.getRREQReceived( si_SocketFd ) == True ) {
			netc_TwainClientMan.setRdatSend( si_SocketFd, netc_TwainClientMan.getRREQRequestSize( si_SocketFd ), 4 );
		}
	}
}

//==================================================================================================
//[機能]PUSH Twainジョブの開始 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴]
//==================================================================================================
NETC_TwainReceiverSlave* NETC_TwainService::getTwainSlave(
	short index
)
{
	int msgIndex = netc_TwainClientMan.getMsgIndexIndex( index );
	if ( (0 <= index) && (index < MAX_TWAIN_CLIENTNUM) ) {
		return netsTwainService[index].netsMsgOption[msgIndex].pTwainSlave;
	} else {
		return NULL;
	}
}

//==================================================================================================
//[機能]デバイスから６０分間以上、パケット(WDAT, RREQ, KCON)を受信しなかった場合タイムアウト処理を実行する 
//[戻り値]
//[コメント]タイムアウト処理(_closeSocket()を実行することにより、セッションの破棄＆wdTimerのキャンセル＆削除)を行う。
//[レビュー]
//[履歴] 2004.04.12 Yamahata
//		 2004.04.27 Yamahata ユーザー認証時、接続しているソケットをすべてクローズする処理と判別するため、bl_AllCloseをFalseとする処理追加(*1)
//		 2013.03.25 ADS坪井  CQ.378831(Act_63702) NETS_TwainServiceをNETS_TwainServiceMsgに変更.
//==================================================================================================
void NETC_TwainService::deviceTimeOutProc(
	int SocketFd		// ソケットディスクリプタ 
)
{
	// 2014/09/08 [ZeusS][RQ-232][WP959]OPS1前田 Start.
	if( True == isbizhubRACheck( SocketFd ) ) {
		setAuthResult( True , True , SocketFd , True );							//Lan切断時などは認証設定を初期化する. //2015/04/21 [ZeusS][CQ512658]OPS1前田 .
	}
	// 2014/09/08 [ZeusS][RQ-232][WP959]OPS1前田 End.

	// メッセージ送信がソケットクローズ要求処理によるもののため、ここではTrueを設定する 
	NETS_TwainServiceMsg netsMsg;
	memset( &netsMsg, 0, sizeof(netsMsg) );
	netsMsg.closeSocketInfo.bl_CloseSocketReq = True;
	netsMsg.closeSocketInfo.bl_AllClose = False;		// (*1)
	netsMsg.closeSocketInfo.si_SocketFd = SocketFd;
	SYSF_msgQSend(msg_Q_ID,(char*)&netsMsg,sizeof(NETS_TwainServiceMsg),NO_WAIT,MSG_PRI_NORMAL);
}

//==================================================================================================
//[機能]ユーザー認証モードが変更されたとき、接続しているクライアントをすべて切断する処理を実行する 
//[戻り値]
//[コメント]ユーザー認証モードが変更されたと通知を受けた場合、接続しているクライアントをすべて切断するようメッセージを送信する 
//[レビュー]
//[履歴] 2004.04.27 Yamahata
//		 2013.03.25 ADS坪井  CQ.378831(Act_63702) NETS_TwainServiceをNETS_TwainServiceMsgに変更.
//==================================================================================================
void NETC_TwainService::allConnSocketCloseProc()
{
	int SocketFd = 0;
	// #70490対策 バックアップ/リストア中は、認証モード変更通知を受けても切断しない 
NetTwainDebugTrace((char*)"getBackupProcessing()=[%d] getRestoreProcessing()=[%d]\n",netc_TwainClientMan.getBackupProcessing(),netc_TwainClientMan.getRestoreProcessing(),0,0,0,0);
	if ( ( netc_TwainClientMan.getBackupProcessing() == FALSE ) && ( netc_TwainClientMan.getRestoreProcessing() == FALSE ) ) {		// バックアップ/リストア中以外 
		for ( int i = 0; i < MAX_TWAIN_CLIENTNUM; i++ ) {
			SocketFd = netc_TwainClientMan.getSocketFd( i );
			if ( SocketFd > 0 ) {									// 接続していない場合は、メッセージを送信しない 
				// メッセージ送信がソケットクローズ要求処理によるもののため、ここではTrueを設定する 
				NETS_TwainServiceMsg netsMsg;
				memset( &netsMsg, 0, sizeof(netsMsg) );
				netsMsg.closeSocketInfo.bl_CloseSocketReq = True;
				netsMsg.closeSocketInfo.bl_AllClose = True;
				SYSF_msgQSend(msg_Q_ID,(char*)&netsMsg,sizeof(NETS_TwainServiceMsg),WAIT_FOREVER,MSG_PRI_NORMAL);
				break;
			}
		}
	}
}

