//==================================================================================================.
//[機能] ジョブ追加.
//[履歴] 2011/08/22 静的解析対応により、JOBのオブザーバー内で処理できなくなったので
//		 自タスクへメッセージを送信して対応(CQNo352955)
//==================================================================================================.
void _AddJobListProc( NETS_JobResult* ps_JobResult )
{
NetTwainDebugTrace((char*)"#### _AddJobListProc() start! ####\n",0,0,0,0,0,0);

// 2017/01/18 [IT5_3.4][市場問題]tTwnCyclicタスクでのE304問題対応.
	if( NULL != ps_JobResult ) {
		NETS_JobResult s_JobResult;
		memcpy( &s_JobResult, ps_JobResult, sizeof( NETS_JobResult ) );
		free( ps_JobResult );
		ps_JobResult = NULL;

// 2017/01/18 [IT5_3.4][市場問題]tTwnCyclicタスクでのE304問題対応.
		if( NULL != s_JobResult.pc_Job ) {
			s_JobResult.pc_Job->lock();
			int si_BitData = NETC_TwainDecideActJobListObserverTypeBit(s_JobResult.pc_Job->getJobSpec()->pc_Common->c_JobType.getJobType()
																	  ,s_JobResult.pc_Job->getJobStatus()->getSendMode()
																	  ,s_JobResult.pc_Job->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( 1 )
																	  ,s_JobResult.pc_Job );
			int si_BitData2 = checkActJobTypeBitSocket2( si_BitData , s_JobResult.pc_Job );
			s_JobResult.pc_Job->unlock();
			setActiveJobListObserverTypeBit( getActiveJobListObserverTypeBit() | si_BitData );
			setActiveJobListObserverTypeBit2( getActiveJobListObserverTypeBit2() | si_BitData2 );
			setActiveJobListStatus( True ); //20050216 arisawa - Fixed BugNo.27887.  Job追加時のDeviceStatus通知。PrintJob受信中にNETC_ActiveJobObserver::JobStatusChangedが呼ばれない.
			setDeviceProcessingInfoStatus( True );

			// 後でGetActJobInfoのタイプが変更されても検知できるようにするため、すべてのジョブのオブザーバーを登録する.
			s_JobResult.pc_Job->lock();
			s_JobResult.pc_Job->attachObserver( &netc_ActiveJobObserver );
			s_JobResult.pc_Job->unlock();
		}
	}
}
