//==================================================================================================.
//[機能] ジョブ実行.
//[履歴] 2011/07/28 静的解析対応により、JOBのオブザーバー内で処理できなくなったので
//		 自タスクへメッセージを送信して対応
//==================================================================================================.
void _DeleteJobListProc(NETS_DeleteJobListParam* ps_DeleteJobListParam)
{
NetTwainDebugTrace((char*)"[%d]_DeleteJobListProc() start! \n",SYSF_tickGet(),0,0,0,0,0);
	NETS_DeleteJobListParam s_DeleteJobListParam;
	memcpy( &s_DeleteJobListParam, ps_DeleteJobListParam, sizeof( NETS_DeleteJobListParam ) );
	free( ps_DeleteJobListParam );
	ps_DeleteJobListParam = NULL;	// 2012/11/05 amiya CQ372762 耐久試験にて片面カラーA4L、5枚コピーを繰り返し実行で「C-E301」発生.

	Bool bl_RealTwain = False;
	int si_SocketFd = netc_TwainClientMan.getSocketFd( s_DeleteJobListParam.index, &bl_RealTwain );
	if ( (s_DeleteJobListParam.e_JobType == TYPE_JobTypeTwain) && (si_SocketFd != -1) ) {		// RealModeTwainの時 
		if ( s_DeleteJobListParam.e_JobResult != TYPE_JobResult_End ) {
			if ( netc_TwainClientMan.getImageTransJobStatus( si_SocketFd ) != NETE_IMAGETRANS_NONE ) {
				bl_EmptyPacketSendWait = True;
				netc_TwainClientMan.setClientErrorInfo( si_SocketFd, ERR_USER_JOB_CANCEL , __FILE__ ,__LINE__);	// Error Client Error Info 
				netc_TwainClientMan.setClientErrorStatus( si_SocketFd, True );				// Error Client Error Status 
			}
		}
		if ( bl_EmptyPacketSendWait == False ) {
			netc_TwainClientMan.setImageTransJobInstance( si_SocketFd, NULL );
			netc_TwainClientMan.setScanDataFlag( si_SocketFd, False );
		} else {
			bl_TwainJobEnded = True;
		}
	} else if ( (s_DeleteJobListParam.e_JobType == TYPE_JobTypeScan) && (s_DeleteJobListParam.b_HddTwain == True) && (si_SocketFd != -1) ) {	// HDD Twainのとき 
		if ( s_DeleteJobListParam.e_JobResult != TYPE_JobResult_End ) {
			if ( netc_TwainClientMan.getImageTransJobStatus( si_SocketFd ) == NETE_IMAGETRANS_TRANS ) {		// 転送中状態の場合 
NetTwainDebugTrace((char*)"### NETE_IMAGETRANS_CANCEL ###\n",0,0,0,0,0,0);
				netc_TwainClientMan.setImageTransJobStatus( si_SocketFd, NETE_IMAGETRANS_CANCEL );
			}
		}
		if ( bl_EmptyPacketSendWait == False ) {
			netc_TwainClientMan.setImageTransJobInstance( si_SocketFd, NULL );
		} else {
			bl_TwainJobEnded = True;
		}
	}
	setActiveJobListObserverTypeBit( getActiveJobListObserverTypeBit() | s_DeleteJobListParam.si_BitData );
	setActiveJobListObserverTypeBit2( getActiveJobListObserverTypeBit2() | s_DeleteJobListParam.si_BitData2 );				// PSWC対応
	setActiveJobListStatus( True );
	setDeviceProcessingInfoStatus( True );
NetTwainDebugTrace((char*)"#### _DeleteJobListProc() end! ####\n",0,0,0,0,0,0);
}

