//==================================================================================================.
//[機能] ジョブ実行.
//[履歴] 2011/07/28 静的解析対応により、JOBのオブザーバー内で処理できなくなったので
//		 自タスクへメッセージを送信して対応
//==================================================================================================.
void _DeleteJobListProc(NETS_JobResult* ps_JobResult)
{
// 2017/01/18 [IT5_3.4][市場問題]tTwnCyclicタスクでのE304問題対応.
	if( NULL != ps_JobResult ) {
		NETS_JobResult s_JobResult;
		memcpy( &s_JobResult, ps_JobResult, sizeof( NETS_JobResult ) );
		free( ps_JobResult );
		ps_JobResult = NULL;	// 2012/11/05 amiya CQ372762 耐久試験にて片面カラーA4L、5枚コピーを繰り返し実行で「C-E301」発生.

// 2017/01/18 [IT5_3.4][市場問題]tTwnCyclicタスクでのE304問題対応.
		if( ( NULL != s_JobResult.pc_Job )
		  &&( NULL != s_JobResult.pc_Job->getJobSpec()->pc_Common ) ) {
			TYPE_JobType e_JobType = s_JobResult.pc_Job->getJobSpec()->pc_Common->c_JobType.getJobType();
			Bool bl_RealTwain = False;
			int si_SocketFd = netc_TwainClientMan.getSocketFd( s_JobResult.pc_Job->getJobStatus()->getJobID(), &bl_RealTwain );
			if ( (e_JobType == TYPE_JobTypeTwain) && (si_SocketFd != -1) ) {		// RealModeTwainの時 
				if ( s_JobResult.pc_Job->getJobHistory()->getJobResult() != TYPE_JobResult_End ) {
					if ( netc_TwainClientMan.getImageTransJobStatus( si_SocketFd ) != NETE_IMAGETRANS_NONE ) {
						bl_EmptyPacketSendWait = True;
						netc_TwainClientMan.setClientErrorInfo( si_SocketFd, ERR_USER_JOB_CANCEL , __FILE__ ,__LINE__);	// Error Client Error Info 
						netc_TwainClientMan.setClientErrorStatus( si_SocketFd, True );				// Error Client Error Status 
					}
				}
				if ( bl_EmptyPacketSendWait == False ) {
					netc_TwainClientMan.setImageTransJobInstance( si_SocketFd, NULL );
					netc_TwainClientMan.setScanDataFlag( si_SocketFd, False );
				} else {
					bl_TwainJobEnded = True;
				}
			} else if ( (e_JobType == TYPE_JobTypeScan) && (s_JobResult.pc_Job->getJobSpec()->pc_Send->c_Twain.getHddTwain() == True) && (si_SocketFd != -1) ) {	// HDD Twainのとき 
				if ( s_JobResult.pc_Job->getJobHistory()->getJobResult() != TYPE_JobResult_End ) {
					if ( netc_TwainClientMan.getImageTransJobStatus( si_SocketFd ) == NETE_IMAGETRANS_TRANS ) {		// 転送中状態の場合 
NetTwainDebugTrace((char*)"### NETE_IMAGETRANS_CANCEL ###\n",0,0,0,0,0,0);
						netc_TwainClientMan.setImageTransJobStatus( si_SocketFd, NETE_IMAGETRANS_CANCEL );
						netc_TwainClientMan.setState_CancelSync( si_SocketFd, NETE_CANCELSYNC_NONE );	// キャンセル同期状態を初期化する.		// 2.1c CQ519136 OSP1八代 2015.10.23.
					}
				}
				if ( bl_EmptyPacketSendWait == False ) {
					netc_TwainClientMan.setImageTransJobInstance( si_SocketFd, NULL );
				} else {
					bl_TwainJobEnded = True;
				}
			}
// 2017/01/18 [IT5_3.4][市場問題]tTwnCyclicタスクでのE304問題対応.
			s_JobResult.pc_Job->lock();
			int si_BitData = NETC_TwainDecideActJobListObserverTypeBit(s_JobResult.pc_Job->getJobSpec()->pc_Common->c_JobType.getJobType()
																	  ,s_JobResult.pc_Job->getJobStatus()->getSendMode()
																	  ,s_JobResult.pc_Job->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( 1 )
																	  ,s_JobResult.pc_Job );
			int si_BitData2 = checkActJobTypeBitSocket2( si_BitData , s_JobResult.pc_Job );			// PSWC対応 
			s_JobResult.pc_Job->unlock();
			setActiveJobListObserverTypeBit( getActiveJobListObserverTypeBit() | si_BitData );
			setActiveJobListObserverTypeBit2( getActiveJobListObserverTypeBit2() | si_BitData2 );				// PSWC対応
			setActiveJobListStatus( True );
			setDeviceProcessingInfoStatus( True );
			s_JobResult.pc_Job->lock();
			s_JobResult.pc_Job->detachObserver( &netc_ActiveJobObserver );
			s_JobResult.pc_Job->unlock();
		}
	}
}
