void NETC_ActiveJobListObserver::changedOrder( APIC_Job* pc_Job )
{
// 2017/01/18 [IT5_3.4][市場問題]tTwnCyclicタスクでのE304問題対応.
	if( NULL != pc_Job ) {
		pc_Job->lock();
		int si_BitData = NETC_TwainDecideActJobListObserverTypeBit(pc_Job->getJobSpec()->pc_Common->c_JobType.getJobType()
																  ,pc_Job->getJobStatus()->getSendMode()
																  ,pc_Job->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook.pageBoxAddress( 1 )
																  ,pc_Job );
		int si_BitData2 = checkActJobTypeBitSocket2( si_BitData , pc_Job );			// PSWC対応 
		pc_Job->unlock();
		setActiveJobListObserverTypeBit( getActiveJobListObserverTypeBit() | si_BitData );
		setActiveJobListObserverTypeBit2( getActiveJobListObserverTypeBit2() | si_BitData2 );				// PSWC対応
	}
}

