{
}
//==================================================================================================
//[機能]NETC_BoxInfoManの空ボックス全削除完了時の処理 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2005.03.25 Matsumoto 
//==================================================================================================
void NETC_BoxInfoMan::boxAllDel()
{
	// ボックス管理情報のクリア 
	memset( &netsTwainBoxInfoMan[0], 0, sizeof(NETS_TwainBoxInfoMan)*MAX_BOX_INFO );
	for ( int i = 0; i < MAX_BOX_INFO; i++ ) {
		netsTwainBoxInfoMan[i].sl_BoxID = -1;
		netsTwainBoxInfoMan[i].bl_DocExist = False;
	}
	// 存在しないボックス管理情報のクリア 
	memset( &netsTwainNotExistBoxInfo[0], 0, sizeof(NETS_TwainNotExistBoxInfo)*MAX_NOTEXIST_BOX_INFO );
	for ( int i = 0; i < MAX_NOTEXIST_BOX_INFO; i++ ) {
		netsTwainNotExistBoxInfo[i].sl_BoxID = -1;
	}
NetTwainDebugTrace2((char*)"#### boxAllDel\n", 0,0,0,0,0,0);
}
//==================================================================================================
//[機能]NETC_BoxInfoManのScanDirectにてアクセスされたときのチェック処理 
//[戻り値]True:ScanDirectアクセス不要(ドキュメントなし) / False:ScanDirectアクセス可(ドキュメントあり)
//[コメント]
//[レビュー]
//[履歴] 2005.03.25 Matsumoto 
//==================================================================================================
Bool NETC_BoxInfoMan::isCheckScanDirectAccess(
	int32_t boxID
)
{
	Bool ret = False;
	Bool isExist = False;
	Bool DocExist = True;
	// ドキュメントが追加されたボックス情報が、管理情報で管理していない場合は新たに管理対象とする 
	for ( int i = 0; i < MAX_BOX_INFO; i++ ) {
		if ( netsTwainBoxInfoMan[i].sl_BoxID == boxID ) {	// 合致するボックス番号を発見した 
			isExist = True;
			DocExist = netsTwainBoxInfoMan[i].bl_DocExist;
NetTwainDebugTrace2((char*)"#### isCheckScanDirectAccess boxInfo Exist boxID = [%d] DocExist = [%d]\n", boxID,DocExist,0,0,0,0);
			break;
		}
	}
	if ( isExist == True ) {		// 管理情報に該当のボックスがあった場合 
		if ( DocExist == False ) {
			ret = True;
NetTwainDebugTrace2((char*)"#### isCheckScanDirectAccess ret = True\n", 0,0,0,0,0,0);
		}
	}
	return ret;
}
//==================================================================================================
//[機能]NETC_BoxInfoManのScanDirectにてアクセスされたボックスのドキュメント一覧取得時の管理情報更新処理 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2005.03.25 Matsumoto 
//==================================================================================================
void NETC_BoxInfoMan::checkDocScanDirectAccessBox(
	int32_t boxID,
	Bool docExist
)
{
	short empty = -1;
	Bool isExist = False;
	// 追加されたボックス情報が、管理情報で管理していない場合は新たに管理対象とする 
	for ( int i = 0; i < MAX_BOX_INFO; i++ ) {
		if ( netsTwainBoxInfoMan[i].sl_BoxID == boxID ) {	// 合致するボックス番号を発見した 
			isExist = True;
			netsTwainBoxInfoMan[i].bl_DocExist = docExist;
NetTwainDebugTrace2((char*)"#### checkDocScanDirectAccessBox boxInfo Exist boxID = [%d]\n", boxID,0,0,0,0,0);
			break;
		}
		if ( (empty == -1) && (netsTwainBoxInfoMan[i].sl_BoxID == -1) ) {
			empty = (short)i;
		}
	}
	if ( isExist == False ) {		// 管理情報に該当のボックスが無かった場合 
		if ( empty != -1 ) {
NetTwainDebugTrace2((char*)"#### isCheckScanDirectAccess boxInfo Not Exist Create empty = [%d] boxID = [%d]\n", empty,boxID,0,0,0,0);
			netsTwainBoxInfoMan[empty].sl_BoxID = boxID;	// 管理情報に書き込む 
			netsTwainBoxInfoMan[empty].bl_DocExist = docExist;
		}
	}
}
//==================================================================================================
//[機能]NETC_BoxInfoManのボックス管理情報を表示する処理(デバッグ用関数) 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2005.03.25 Matsumoto 
//==================================================================================================
void NETC_BoxInfoMan::printBoxInfo()
{
	for ( int i = 0; i < MAX_BOX_INFO; i++ ) {
		if ( netsTwainBoxInfoMan[i].sl_BoxID != -1 ) {
			NetTwainDebugTrace("#### netsTwainBoxInfoMan[%03d].sl_BoxID = [%d], netsTwainBoxInfoMan[%03d].bl_DocExist = [%d]\n", i, netsTwainBoxInfoMan[i].sl_BoxID, i, netsTwainBoxInfoMan[i].bl_DocExist, 0,0);
		}
	}
}
//==================================================================================================
//[機能]NETC_BoxInfoManの存在しないボックス情報を表示する処理(デバッグ用関数) 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2005.03.25 Matsumoto 
//==================================================================================================
void NETC_BoxInfoMan::printNotExistBoxInfo()
{
	for ( int i = 0; i < MAX_NOTEXIST_BOX_INFO; i++ ) {
		if ( netsTwainNotExistBoxInfo[i].sl_BoxID != -1 ) {
			NetTwainDebugTrace("#### netsTwainNotExistBoxInfo[%03d].sl_BoxID = [%d]\n", i, netsTwainNotExistBoxInfo[i].sl_BoxID, 0, 0, 0,0);
		}
	}
}
//==================================================================================================
//[機能]ScanDirectにてアクセスされた際に存在しないボックスであったことを管理する情報の更新処理 
//[戻り値]
//[コメント]
//[レビュー]
//[履歴] 2005.03.25 Matsumoto 
//==================================================================================================
void NETC_BoxInfoMan::setNotExistBox(
	int32_t boxID
)
{
	for ( int i = 0; i < MAX_NOTEXIST_BOX_INFO; i++ ) {
		if ( netsTwainNotExistBoxInfo[i].sl_BoxID == -1 ) {
			netsTwainNotExistBoxInfo[i].sl_BoxID = boxID;
			break;
		}
	}
}
//==================================================================================================
//[機能]ScanDirectにてアクセスされた際に存在しないボックスへのアクセスか否かをチェックする処理 
//[戻り値]True:ScanDirectアクセス不要(ボックスなし) / False:ScanDirectアクセス可(ボックスあり)
//[コメント]
//[レビュー]
//[履歴] 2005.03.25 Matsumoto 
//==================================================================================================
Bool NETC_BoxInfoMan::checkNotExistBox(
	int32_t boxID
)
{
	Bool ret = False;
	for ( int i = 0; i < MAX_NOTEXIST_BOX_INFO; i++ ) {
		if ( netsTwainNotExistBoxInfo[i].sl_BoxID == boxID ) {
			ret = True;
			break;
		}
	}
	return ret;
}

